window.STORY_LIBRARY.push({"title": "GIẢ LÀM THẦN MINH", "subtitle": "Bản hiệu đính — Phiên ngoại", "chapters": [{"title": "Chương 104 – Phiên ngoại một (vai phụ xuất hiện nhiều)", "paragraphs": ["Trong đợt loạn lạc vừa qua, trận chiến ở Mạc Bắc là trận đánh dữ dội nhất, kéo dài lâu nhất. Chiến sự còn chưa hoàn toàn lắng xuống, tin Trung Nguyên đã dẹp yên phản loạn cũng chưa kịp truyền tới, lòng dân Mạc Bắc vẫn còn phấp phỏng lo sợ, nên dù đã cận kề năm hết Tết đến, không ai dám bày tiệc ăn mừng rầm rộ. Ai nấy đều đang chờ một tin thật sự khiến lòng mình yên ổn.", "Đúng lúc ấy, Giang Sóc Dã dẫn quân đánh phá vương đình Thát Đát, giết chết khả hãn Hi Đức cùng toàn bộ vương thất, chiếm trọn một dải sa mạc thảo nguyên.", "Đám tàn quân còn sót lại trốn sâu vào thảo nguyên, y không đích thân truy đuổi mà giao cho phó tướng dẫn quân tiến vào. Như vậy các tướng sĩ mới có thêm cơ hội lập công, sang năm y dâng tấu lên triều đình, mọi người cũng được thêm phần thưởng.", "Chỉ tiếc lần này y vẫn chưa lần ra được kẻ phản bội cài trong quân, cũng không rõ tên phản đồ ấy đã kịp báo tin cho Thát Đát hay chưa, hay là đã chết cùng vợ chồng Tần Cảnh Triệu từ trước đó rồi. Giang Sóc Dã nghĩ mãi không ra đáp án, đành gác lại, đợi hôm nào rảnh sẽ hỏi Đại Tư Tế một phen.", "Y dẫn quân tuần qua một vòng biên giới thảo nguyên vừa đánh hạ, sai người an bài ổn thỏa cho đám dân chăn nuôi hiền lành nơi đây. Xong xuôi mọi việc, y để phần lớn binh mã ở lại thảo nguyên, dặn các tướng sĩ chịu khó trấn giữ thêm một dạo, đề phòng có kẻ trong đám dân chăn nuôi nổi lên gây chuyện. Năm nay quân lính ai nấy đều có áo ấm mùa đông, lương thảo cũng dư dả, ở lại doanh trại cũng coi như được đón một cái Tết tươm tất.", "Thu xếp xong hết thảy, Giang Sóc Dã dẫn theo vài trăm quân sĩ, tối mùng hai tháng Giêng thì về tới đại doanh Mạc Bắc.", "Trong doanh còn hai vạn tướng sĩ trấn giữ, nghe tin thắng trận liền reo hò ăn mừng, cuộc vui kéo dài đến tận nửa đêm.", "Mười năm.", "Rốt cuộc họ cũng đánh cho đám man di kia khuất phục, rốt cuộc bình định trọn vẹn cả một dải biên cương phía Bắc.", "Tin thắng trận cũng dần dần lọt vào tai bách tính, người người vừa khóc vừa cười. Bao năm sống trên mảnh đất này, rốt cuộc cũng đến ngày binh lửa chấm dứt. Rốt cuộc họ được đón một cái Tết yên bình. Và từ nay về sau, họ không còn phải chịu cảnh loạn lạc quấy nhiễu nữa.", "Vì thế Mạc Bắc vốn quạnh quẽ bấy lâu, đêm mùng hai bỗng náo nhiệt khác thường.", "Giang Sóc Dã ở trong quân cùng tướng sĩ nâng chén chúc mừng, đến khi mặt trời khuất núi mới trở về phủ.", "Giang gia vốn đã sa sút từ lâu, mười năm ở Mạc Bắc, người trong nhà kẻ đi người tán, đến nay còn ở lại đây, ngoài chi trưởng ra thì chỉ có phụ thân của Giang Sóc Dã cùng vài người chú bác họ hàng gần. Gộp cả già trẻ lớn bé vụn vặt lại cũng chưa đầy hai mươi mấy người. Ngày thường Giang gia vẫn giữ lệ cả nhà quây quần dùng bữa chung ở nhà chính.", "Nhưng đêm nay Giang Sóc Dã đội gió tuyết trở về phủ, bước vào phòng ăn lại chỉ thấy một mình phụ thân Giang Hiến ngồi đó. Đừng nói tới người trong họ, ngay cả mẹ kế Dư thị cùng hai đứa em một trai một gái cũng không có mặt.", "Trên bàn bày tới tám món, hơi nóng còn bốc lên nghi ngút, nhưng nhìn kỹ thì chẳng món nào bị đụng đũa.", "Thấy y bước vào, Giang Hiến đang thất thần bỗng lấy lại tinh thần, nở nụ cười.", "“Về rồi đấy à.” Ông nói.", "Giang Sóc Dã đáp lại một tiếng, đi tới bên bàn ngồi xuống. Trên bàn chỉ bày hai bộ chén đũa, một phần cho phụ thân, một phần cho y.", "“Những người khác đâu cả rồi?” Giang Sóc Dã hỏi.", "Giang Hiến nói: “Dư thị người không được khỏe, đệ đệ muội muội con ở sau viện chăm nàng. Còn những người khác đều ở phòng riêng của mình. Giờ chiến loạn đã yên, cha con mình cũng nên ngồi nói chuyện tử tế với nhau, nên ta không gọi bọn họ ra đây làm phiền.”", "Giang Sóc Dã trong quân đã uống qua một vòng rượu, nhưng lúc này vẫn cầm lấy bầu rượu, rót cho phụ thân và cho chính mình mỗi người một chén.", "“Trì Phong à.” Giang Hiến cười, nâng chén hướng về y, “Con là đại anh hùng, để ta kính con một chén.”", "Giang Sóc Dã ngước mắt nhìn ông.", "Y không nhớ nổi đã bao lâu rồi mình chưa nghiêm túc nhìn kỹ phụ thân như thế này. Mẫu thân qua đời năm y sáu tuổi, sau đó y theo sư phụ rời nhà, từ ấy về sau cứ mãi lang bạt bên ngoài. Về sau y cũng nghe nói phụ thân tục huyền, cưới tiểu thư một sĩ tộc địa phương, chính là kế mẫu Dư thị. Rồi lại có lời đồn rằng Giang Hiến với Dư thị tình sâu nghĩa nặng, ông sủng ái người vợ kế này thế nào thế nào, nhưng Giang Sóc Dã chưa từng để tâm.", "Nói cho cùng, lúc mẫu thân còn sống, phụ thân cũng chưa từng thực sự phụ bạc bà, ngược lại còn rất mực tôn trọng. Chỉ là không có tình cảm. Họ, cũng như biết bao đôi vợ chồng thời ấy, ba lần mối sáu lần sính lễ mà thành thân, chẳng có nền tảng tình cảm gì, chỉ tôn trọng nhau như khách.", "Mẫu thân sinh y bị tổn thương thân thể, vì thế mới ra đi sớm. Cho nên sau này phụ thân tục huyền, sinh liên tiếp hai đứa con nữa, y cũng chẳng để bụng, thậm chí thỉnh thoảng tìm được món đồ chơi hay, thứ gì hợp với trẻ nhỏ, y còn nhờ người mang về tặng cho hai đứa em chưa từng gặp mặt kia.", "Y từng nghĩ cả đời mình sẽ cứ như vậy, mãi mãi cùng sư phụ ngao du giang hồ. Nhưng sư phụ tuổi đã cao, không thể cùng y ngày ngày ngắm núi xem sông mãi được nữa, bèn tìm một nơi phong thủy tốt, lập tông lập phái, dưỡng già. Giang Sóc Dã phần lớn thời gian vẫn ở bên ngoài, nhưng cứ đến lễ Tết lại về bên sư phụ.", "Vốn tưởng đời này cứ thế mà trôi qua, ai ngờ năm mười bảy tuổi, Giang gia gặp biến cố. Giang Hiến tính toán dẫn cả nhà đến Mạc Bắc, định đoạt lấy Tần gia quân từ tay Tần Cảnh Triệu. Giang Sóc Dã chạy tới nơi, mới hay Tần tướng quân cùng phu nhân đã qua đời, Mạc Bắc Quân như rắn mất đầu.", "Rồi sau đó, y dần dần trở thành “Mạc Bắc chiến thần”, trở thành “Trì Phong tướng quân” mà trong ngoài biên ải không ai không biết.", "Nay mười năm đã trôi qua, sư phụ cũng đã khuất núi từ lâu. Giang Sóc Dã gần như chẳng còn mấy dịp ở cùng người nhà, càng không có cơ hội trò chuyện với phụ thân. Giữa họ vốn chẳng có tình cảm gì, chỉ còn một sợi dây huyết mạch nối liền mà thôi.", "Nhưng nhìn người đàn ông tóc đã hoa râm trước mặt, trong lòng Giang Sóc Dã lại dấy lên một cảm xúc khác lạ. Gương mặt này đã chẳng còn giống hình bóng trong ký ức của y nữa, nhưng nhìn kỹ, lại thấy nó dần dần chồng khít lên hình bóng ấy.", "Y nhớ lại thuở nhỏ, khi mẫu thân còn chưa mất, phụ thân từng tự tay dạy dỗ đứa con trai duy nhất này, từng mua cho y những món điểm tâm mềm ngọt. Nhưng giờ đây, đệ đệ muội muội cũng đã trưởng thành, phụ thân không còn là phụ thân của riêng một mình y nữa. Trong ngôi nhà này, kỳ thực từ lâu đã chẳng còn chỗ nào thuộc về y. Đối với gia đình này, y giống một “gia chủ” độc lập, có quyền thế uy áp hơn là một người thân thích.", "Giang Hiến uống cạn chén rượu, Giang Sóc Dã nhìn theo, cũng ngửa cổ uống cạn theo.", "“Bao nhiêu năm rồi, ta vẫn có rất nhiều điều muốn nói với con.” Giang Hiến cười, khóe mắt hằn nếp nhăn sâu, gương mặt cũng già đi nhiều vì gió cát biên cương. Nhưng vẫn có thể nhận ra nét anh tuấn thuở trẻ còn sót lại.", "Ông nhìn Giang Sóc Dã thật sâu, ánh mắt lại chưa từng nghiêm túc nhìn thẳng vào y quá lâu.", "“Ngày trước còn là đứa trẻ nhỏ như vậy, giờ đã lớn thành một đại tướng quân lợi hại thế này.” Giang Hiến dường như cảm khái lắm, lại rót rượu, chạm chén cùng Giang Sóc Dã.", "Giang Sóc Dã cụp mắt nhìn chén rượu, rồi nâng lên uống cạn.", "Giang Hiến cứ lải nhải kể lại, những đoạn ký ức mơ hồ liên quan đến Giang Sóc Dã hồi còn rất nhỏ. Nhưng Giang Sóc Dã chẳng biết đáp lại thế nào, vì những chuyện đó, ngay cả bản thân y cũng không nhớ rõ. Có lẽ vài chuyện trong đó vốn không phải về y, mà là về hai đứa em kia, chỉ là Giang Hiến lẫn lộn mà thôi.", "Giang Hiến còn nhắc đến người vợ đầu đã khuất hai mươi năm trước. Ông nói bà là một vị tiểu thư khuê các dịu dàng xinh đẹp, nói tính cách bà nhu hòa thế nào, nói bà đối đãi với con cái kiên nhẫn ra sao, kể ra không biết bao nhiêu điều tốt đẹp về bà.", "Giang Sóc Dã nghiêm túc lắng nghe. Đây là những chuyện y chưa từng nghe ai kể qua. Theo lời kể của phụ thân, hình bóng mơ hồ trong đầu y về mẹ dần dần trở nên rõ nét. Từng chén rượu trôi xuống bụng, y bắt đầu thấy hơi choáng váng.", "Có lẽ là say rồi, y nghĩ.", "Trong lúc mơ màng, Giang Hiến lại nói đến Thát Đát, nói đến sự anh dũng của Mạc Bắc Quân. Rồi ông nhắc đến triều đình.", "“Một đời vua, một đời thần.” Giang Hiến khẽ nheo mắt, như đang hồi tưởng chuyện gì đó rất xa xôi, “Lòng dạ đế vương, tranh đoạt quyền thế, đâu phải thứ hạng người như chúng ta có thể xem hiểu.”", "“Giờ Thát Đát đã bình định, Mạc Bắc Quân cũng chẳng còn tác dụng lớn nữa.”", "Một đội quân đã hết chỗ dùng mà vẫn có tới hơn mười vạn tướng sĩ, nhìn kiểu gì cũng là mối uy hiếp không nhỏ. Nếu Giang Sóc Dã có lòng, y hoàn toàn có thể tự lập làm vương ngay tại đây, dựng nên một quốc gia mới.", "Đầu óc Giang Sóc Dã xoay chuyển chậm hơn thường lệ. Vốn tính cẩn trọng, nhưng trước mặt người thân thiết nhất, lại thêm men rượu, y không thể nghĩ thấu đáo như mọi khi. Nhưng y vẫn cảm nhận được, lời phụ thân nói dường như là để nhắc nhở, khuyên y sớm chia bớt binh quyền ra ngoài.", "Quả nhiên, y mơ hồ nghe Giang Hiến hỏi: “Binh phù cất kỹ chưa? Sang năm nếu trong kinh có chiếu triệu, con cứ đem binh phù trả lại cho bệ hạ, như vậy…”", "Người đàn ông chậm rãi nói. Mí mắt Giang Sóc Dã trĩu nặng, nhưng hình bóng phụ thân trước mặt lại không hề nhòe đi, thậm chí còn rõ ràng lạ thường, như thể y căn bản không hề say. Nhưng suy nghĩ trong đầu lại rối loạn vô cùng, thậm chí không xử lý kịp những lời Giang Hiến nói ra, cảm giác này thật kỳ lạ.", "“Cái thứ binh phù này, mang theo bên người cũng phải cẩn thận.” Giang Hiến nói tiếp, “Hay là con giấu nó trong phòng, tìm một ngăn bí mật mà người thường không tìm ra được…”", "Binh phù.", "Binh phù.", "Giang Sóc Dã cụp mắt, mí mắt trĩu xuống đến mức không nâng lên nổi nữa, cuối cùng khép hẳn lại.", "Giang Hiến vẫn nói tiếp, không biết qua bao lâu mới phát hiện con trai mình dường như đã ngủ mất rồi. Ông bật cười, đưa tay khẽ vỗ vai Giang Sóc Dã, gọi khẽ “Trì Phong, Trì Phong”.", "Giang Sóc Dã ngủ say thật sự.", "Giang Hiến đứng dậy, không gọi người hầu, mà tự mình đỡ Giang Sóc Dã dậy, đặt một cánh tay y lên vai mình, định dìu y ra ngoài. Một tay ông đỡ lấy eo Giang Sóc Dã, tay còn lại vô tình dừng lại trước ngực y, chạm phải một vật có góc cạnh cứng.", "Giang Hiến khựng lại, ngước mắt nhìn gương mặt nghiêng của Giang Sóc Dã, thấy y nhắm nghiền mắt, hơi thở nồng nặc mùi rượu. Vì thế bàn tay đang đỡ trước ngực y liền dời sang, định luồn vào vạt áo lấy ra vật kia.", "Nhưng đầu ngón tay vừa chạm tới lớp vải, cổ tay ông đã bị một bàn tay siết chặt lấy.", "Tim Giang Hiến giật thót, ngước mắt lên đã thấy Giang Sóc Dã, kẻ vừa nãy còn “say khướt”, từ từ mở mắt ra. Y quay đầu đối diện với ông, ánh mắt trong veo, còn đâu một chút hơi men?", "“Phụ thân.” Giang Sóc Dã đứng thẳng người, siết chặt cổ tay ông đến mức đối phương toát cả mồ hôi lạnh. “Ngài muốn dùng binh phù Mạc Bắc để làm gì?”", "Giang Hiến đối diện ánh mắt ấy, chợt có cảm giác như đang bị một con mãnh thú hung tợn nào đó rình rập. Trong ánh mắt kia là sự phẫn nộ và sát khí mãnh liệt, khiến ông rợn cả tóc gáy.", "“Trì Phong, con hiểu lầm rồi.” Giang Hiến cười gượng, “Ta dùng binh phù làm gì chứ? Chỉ là vừa nãy vô tình sờ thấy nó có góc cạnh, sợ cấn vào người con nên mới định lấy ra thôi.”", "Giang Sóc Dã sắc mặt lạnh lùng, chẳng buồn nghe lọt tai câu nào.", "“Ngài phục tùng ai?” Y hỏi, “Khâu gia, Lục gia, hay là Tiêu gia?”", "“Hay là, một vị phiên vương nào đó?”", "Tin tức mới nhất từ Trung Nguyên vẫn chưa truyền tới, nên cả Giang Hiến lẫn Giang Sóc Dã đều chưa rõ tình hình chiến sự bên đó ra sao. Chỉ có điều Giang Sóc Dã tin chắc triều đình rồi sẽ thắng, chỉ là chuyện sớm muộn. Nhưng Giang Hiến lại không có tầm nhìn ấy, cũng chẳng phân tích nổi đại thế thiên hạ.", "Tin tức mới nhất trong tay ông là do một phiên vương hay một thế gia nào đó truyền tới, báo cho ông biết Trung Nguyên đã bắt đầu hỗn loạn. Vì thế giờ đây ông muốn có binh phù Mạc Bắc, hoặc để tự mình cầm hơn mười vạn tướng sĩ làm một phương chư hầu, hoặc để dẫn quân vào Trung Nguyên gia nhập cuộc hỗn chiến, danh chính ngôn thuận đoạt lấy ngôi vị tối cao. Đương nhiên cũng không loại trừ khả năng bản thân ông chẳng có bản lĩnh ấy, chỉ muốn theo phò một chủ nhân khác để lập công.", "Nhưng dù là khả năng nào, cũng đều chứng minh một điều: lòng Giang Hiến chưa từng thực sự đặt ở Mạc Bắc. Trong lòng ông, đứa con trai ruột thịt của mình chẳng quan trọng bằng những kẻ ngoài kia, những kẻ có thể mang lại cho ông quyền thế địa vị lớn hơn.", "“Trì Phong, con uống say rồi, Khâu gia Lục gia gì đó, để ta đưa con về phòng nghỉ ngơi.” Giang Hiến làm như căn bản không hiểu Giang Sóc Dã đang nói gì.", "Giang Sóc Dã buông tay ông ra, lùi lại hai bước, nói: “Ngài đã làm gì cho bọn họ? Cái chết của Tần tướng quân có liên quan gì đến ngài không?”", "Điều Giang Sóc Dã biết chỉ là, năm xưa khi Giang gia dẫn quân đến Mạc Bắc, Tần Cảnh Triệu cùng Ngụy Linh Chứa đồng thời tử trận, Giang gia mới có cớ thuận lý thành chương tiếp quản phần còn lại của Tần gia quân. Nhưng khi ấy, kỳ thực Giang gia đã được lệnh của Anh Tông, đến để “đoạt lấy” Tần gia quân. Vậy nên cũng không loại trừ khả năng Giang gia cố ý bày mưu hại chết Tần Cảnh Triệu cùng Ngụy Linh Chứa.", "Chỉ là chưa bao giờ Giang Sóc Dã nghĩ tới điều này. Trong ấn tượng của y, hình ảnh phụ thân không đủ cao lớn, nhưng tuyệt đối chính trực. Bởi đối phương từng nhận lệnh của Anh Tông mà đến, Giang Sóc Dã chỉ cảm thấy đó là lòng trung quân của Giang Hiến, cảm thấy ông muốn giành cho Giang gia một tương lai tốt đẹp hơn. Nhưng sự thật dường như khác xa những gì y từng tưởng tượng, như trời với vực.", "Giang Hiến cúi mắt nhìn cổ tay mình đã bị siết đến bầm tím, phải cố kìm lắm mới không buột miệng chửi rủa. Chuyện đến nước này, ông biết Giang Sóc Dã sẽ không nguôi nghi ngờ với mình nữa, nên cũng chẳng cần giả vờ thêm.", "Ông ngước mắt nhìn Giang Sóc Dã, ánh mắt trầm đục: “Trì Phong, ta là cha con, sẽ không hại con đâu.”", "Giang Sóc Dã im lặng không nói.", "“Chúng ta trong tay có binh, có địa bàn, còn có lương thảo, mọi thứ đều đã sẵn sàng cả rồi.” Giọng Giang Hiến mang theo vẻ mê hoặc, lẫn cả một sự hưng phấn khó tả: “Trời cao hoàng đế xa, sao chúng ta không trực tiếp lập nên một vương triều mới?”", "Nếu là trước kia, hẳn ông đã nghĩ nhân cơ hội này đánh thẳng vào kinh thành mới là thượng sách, có thể quang minh chính đại lên ngôi hoàng đế. Nhưng bây giờ khác rồi, ông đã tận mắt chứng kiến những thủ đoạn thần kỳ của Sở Cửu Biện, nên nếu không đến bước đường cùng, ông không muốn dây dưa với triều đình.", "Chỉ có điều, những thủ đoạn thần kỳ ấy của Sở Cửu Biện chắc cũng chẳng thể vươn tới tận Mạc Bắc — nếu không, đối phương đã trực tiếp diệt sạch quân Thát Đát bằng cách nào đó tiện lợi hơn rồi, đâu cần để Giang Sóc Dã liều mạng ra trận đánh giết như thế. Cho nên ông muốn ở lại Mạc Bắc, cũng không còn muốn liên lạc với Tiêu gia nữa.", "Kế phu nhân Dư thị vốn là người của Tiêu gia, chỉ là đã thay tên đổi họ mới gả vào Giang gia. Bà xoay chuyển Giang Hiến trong lòng bàn tay, ông nói gì nghe nấy, chẳng dám trái lời. Lần này ông cũng từng định bụng, sau khi đoạt được binh phù sẽ nghe theo Dư thị, giúp Tiêu gia đoạt quyền.", "Nhưng ông vẫn chưa muốn chết, không muốn chọc vào Sở Cửu Biện. Vì thế lần đầu tiên ông trái ý Dư thị, dù bà van nài làm nũng thế nào ông cũng không lay chuyển. Bởi vậy mấy ngày nay Dư thị mang theo con cái ở mãi hậu viện, chẳng thèm để ý tới ông.", "Nhưng cũng chính vì thế mà hôm nay ông mới có dịp ở riêng cùng Giang Sóc Dã, chỉ cần chuốc say đối phương là có thể lấy được binh phù. Ở lại Mạc Bắc tự lập làm vương, việc này lại càng thuận tiện cho Giang Sóc Dã hành sự, các tướng sĩ cũng nghe lời y hơn.", "Nhưng Giang Hiến bị con trai mình đè đầu cưỡi cổ đã bao nhiêu năm nay, thực sự không chịu nổi cảnh cứ mãi nhìn ánh mắt của con trai mà sống nữa. Vì thế ông muốn đoạt lấy binh phù, trở thành “vương” lớn nhất Mạc Bắc.", "Nhưng Giang Sóc Dã lại quá đỗi cẩn trọng. Có lẽ ngay từ khoảnh khắc bước vào phòng ăn, y đã nhận ra điều bất thường, nên ngay từ đầu đã diễn kịch, giả vờ say để tạo cơ hội cho Giang Hiến ra tay.", "Đây là một phép thử. Và Giang Hiến đã thua.", "Con giết cha, thiên lý khó dung. Vì thế Giang Sóc Dã không ra tay với phụ thân, chỉ nhìn ông thật sâu, rồi xoay người bước về phía cửa chính, giọng bình thản như đang nói chuyện phiếm: “Ta sẽ không giết ngài. Nhưng từ nay về sau, đừng bao giờ tự xưng là cha ta nữa.”", "“Ân đoạn nghĩa tuyệt từ đây.”", "Giang Hiến nhìn theo bóng y rời đi, cất giọng: “Con tưởng con đi được sao?”", "Ngay sau đó, Giang Sóc Dã khựng bước.", "Ngước mắt lên, y thấy trong sân bỗng xuất hiện hơn chục ám vệ, ngoài sân còn có gần ngàn người mặc áo giáp mềm, đeo đao bên hông, vây kín xung quanh.", "Những người này đều có thực lực không tầm thường, một mình Giang Sóc Dã dù có tài giỏi cũng khó lòng địch nổi hàng ngàn tay đao ấy.", "“Binh phù đưa cho ta.” Giang Hiến đứng xa xa phía sau y, nói, “Chỉ cần con giao binh phù cho ta, ta cũng có thể bảo con cả đời vinh hoa phú quý.”", "Giang Sóc Dã không thèm quay đầu lại. Y siết chặt nắm đấm, đánh thẳng vào tên ám vệ gần nhất.", "Giang Sóc Dã phần lớn thời gian đóng quân ngoài doanh trại, nên đám phủ binh trong phủ này từ trên xuống dưới đều xa lạ với y, tất cả đều là thủ hạ của Giang Hiến. Bị bấy nhiêu người vây đánh, bản thân Giang Sóc Dã lại tay không tấc sắt, dù dũng mãnh đến đâu cũng khó tránh khỏi thương tích.", "Huống hồ chén rượu vừa nãy y uống đã bị pha thêm loại thuốc thường dùng để khống chế tù nhân, giờ y vận nội lực, thuốc lại càng phát tác nhanh hơn. Giang Sóc Dã khó lòng tập trung sức lực, chẳng mấy chốc đã đầy mình thương tích.", "Giang Hiến từ lúc ám vệ xuất hiện đã lui vào trong phòng ăn, sợ bị vạ lây. Ông ngồi bên bàn, tự rót cho mình một chén rượu. Qua cánh cửa mở rộng, ông có thể nhìn thấy cảnh chém giết đẫm máu ngoài sân, tự nhiên cũng thấy được vết thương trên người Giang Sóc Dã ngày một nhiều thêm.", "Nhưng ông chỉ lạnh lùng đứng nhìn, như đang xem một người xa lạ nào đó. Không đúng — nếu thật là người xa lạ, chứng kiến cảnh này hẳn còn thấy đau lòng, còn thấy căng thẳng. Nhưng là cha ruột của Giang Sóc Dã, Giang Hiến lại nhìn con trai mình như nhìn kẻ thù. Thậm chí trong lòng ông còn thấp thoáng chút hưng phấn, chút vui sướng. Bị chính con trai ruột đè đầu cưỡi cổ, ức hiếp bao nhiêu năm nay, ông già này rốt cuộc cũng có ngày ngẩng đầu thở phào.", "Lại thêm một đao chém trúng sau lưng, một tiếng “bụp” ướt nhẹp vang lên. Giang Sóc Dã loạng choạng một bước, xoay người dùng thanh đao vừa cướp được chém ngã liền mấy người. Rồi y sực nhớ trong người mình còn có một khẩu súng.", "Y liền rút súng ra, nhắm vào đám người vây quanh nổ liền mấy phát.", "Tiếng nổ chát chúa vang lên cùng tiếng người ngã xuống, khiến đám phủ binh sợ hãi không dám xông lên nữa. Giang Sóc Dã giơ súng trước ngực, gương mặt lạnh băng. Y biết trong súng còn bao nhiêu viên đạn, nhưng những kẻ kia thì không — và chính cái không biết ấy mới là điều đáng sợ nhất.", "Giang Hiến cũng chẳng phải người già yếu vô dụng, ông đứng dậy khóa cửa lại, rồi đến bên cửa sổ lặng lẽ nhìn ra ngoài.", "Giang Sóc Dã cả người tắm máu, giơ súng chậm rãi bước ra ngoài, đám phủ binh đều tự động nhường ra một lối đi, không ai dám tiến sát lại gần.", "Không được. Không thể để y thoát.", "Nếu Giang Sóc Dã đi thoát, Giang Hiến chắc chắn không tránh khỏi cái chết. Giang Sóc Dã đúng là không thể mang tội danh giết cha, nhưng y có bao nhiêu thủ hạ trung thành tận tụy, chỉ cần y hé một câu, ắt có kẻ thay y giải quyết mối phiền toái này.", "“Còn chờ gì nữa?! Xông lên!” Giang Hiến hét lớn, “Nghĩ đến gia đình các ngươi đi!”", "Lời uy hiếp rõ ràng khiến đám thị vệ không dám trái lệnh nữa, đành cắn răng xông lên.", "Giang Sóc Dã lại bắn thêm hai phát, nhưng người vây quá đông, y đành phải cướp lấy một thanh trường đao khác, một đường chém mở lối xông ra ngoài.", "Nhưng y không ngờ, ra khỏi sân trong lại còn một tiền viện rộng lớn hơn, cùng với càng nhiều người hầu chờ sẵn.", "Xong rồi, y nghĩ.", "Cơn choáng váng trước mắt, thuốc đã phát tác trọn vẹn. Y chỉ còn bản năng đánh trả những kẻ vây quanh, đầu óc rối loạn không thôi.", "Lúc này y chợt nhớ đến Đại Tư Tế, nhớ lời dặn rằng nếu gặp chuyện thực sự không thể giải quyết, cứ gọi tên thần minh. Vì thế trong lòng y thầm niệm: “Đại Tư Tế, thuộc hạ có việc cầu xin.”", "Cầu xong trong lòng, y còn buột miệng niệm thành tiếng.", "*", "Trong cung. Trong phòng ngủ.", "Ngọn đèn dầu le lói chập chờn, màn trướng khẽ lay động. Sở Cửu Biện ngồi tựa bên hông Tần Kiêu, ánh nến ấm áp phủ lên làn da y như tấm lụa quý nhất, những mảng da trắng ngần điểm xuyết sắc hồng phơn phớt, khiến người ta không rời mắt nổi. Thanh niên ngửa đầu ra sau, chiếc cổ phác nên đường cong mềm mại. Tần Kiêu tựa lưng vào đầu giường, một tay đặt nơi vòng eo y, ánh mắt thâm trầm chậm rãi lướt khắp người y. Ánh mắt ấy tựa hồ có thực chất, như một bàn tay vô hình, khiến Sở Cửu Biện khẽ run lên hết lần này đến lần khác.", "Không biết đã qua bao lâu, lượt ân ái đầu tiên đêm nay rốt cuộc cũng kết thúc. Sở Cửu Biện vòng tay ôm lấy cổ người đàn ông, mồ hôi ướt đẫm, tựa đầu vào vai y. Khắp người, từ trong ra ngoài, chỉ còn sót lại một chỗ khẽ run rẩy.", "Tần Kiêu hôn nhẹ lên gương mặt còn đẫm mồ hôi của y, tay vẫn chưa chịu yên phận mà lần mò, rõ ràng còn muốn tiếp tục.", "【Cảnh báo, cảnh báo!】", "Trong đầu bỗng vang lên một tiếng nhắc nhở. Sở Cửu Biện cau mày, nghe hệ thống nói tiếp: 【Tín đồ Giang Sóc Dã đang gặp nguy hiểm đến tính mạng, có cứu hay không?】", "Tim Sở Cửu Biện thắt lại.", "Mạc Bắc xảy ra chuyện rồi sao? Nhưng chẳng phải hôm qua Giang Sóc Dã còn báo tin đã thu phục Thát Đát, lẽ ra giờ này y đã trên đường về nhà rồi mới phải?", "Không kịp nghĩ nhiều, Sở Cửu Biện nói ngay: “Cứu.”", "【Ký chủ có thể lựa chọn tự mình hạ phàm xuống Mạc Bắc, nhưng cần khấu trừ 500 điểm tín ngưỡng, đồng thời vì nguyên nhân không gian bị bóp méo, ký chủ sẽ có chút phản ứng khó chịu, có tiếp tục không?】", "Điều kiện này hệ thống từng nói với Sở Cửu Biện từ lâu. Lúc ấy y còn đang cân nhắc, nghĩ rằng có thể dùng rồng vàng để truyền tin, chỉ khi thực sự cần thiết mới đích thân đi gặp tín đồ. Nhưng bây giờ, đến lúc thực sự xảy ra chuyện, y căn bản không kịp phân tích tình hình hiện tại của Giang Sóc Dã, phản ứng đầu tiên chỉ là mau chóng đi cứu người.", "Y nhắm mắt lại. Lần trước hư ảnh thần minh xuất hiện đã thu về một đợt giá trị tín ngưỡng không nhỏ, giờ tiêu xài vài trăm điểm căn bản chẳng đáng gì.", "Nhưng y không thể tay không mà đi, cần mang theo thứ gì đó phòng thân. Trong không gian riêng có thuốc nổ có thể dùng, nhưng nếu là hỗn chiến, rất có thể sẽ vô tình làm hại Giang Sóc Dã.", "【Ký chủ có thể kích hoạt cơ chế bảo hộ tín đồ, vũ khí do hệ thống sản xuất sẽ không gây tổn hại cho tín đồ, mỗi giây tiêu tốn sáu điểm, có sử dụng không?】", "Lúc này trong tay không thiếu giá trị tín ngưỡng, Sở Cửu Biện cũng lười mặc cả với nó nữa. Đám thuốc nổ trong không gian riêng đều do Lục Nghiêu chế ra cho y, không tính là “vũ khí do hệ thống sản xuất”, nên Sở Cửu Biện liền mua thêm ít thuốc nổ từ cửa hàng hệ thống.", "Mọi thứ chuẩn bị xong, Sở Cửu Biện nói: “Đi thôi.”", "Ngay sau đó, mắt hoa lên một cái, Sở Cửu Biện trước tiên đến Thần Vực, rồi thân ảnh chợt mờ đi. Khi phản ứng lại được, y đã đứng giữa không trung cao mấy chục mét.", "Thân hình y trở nên lớn hơn, tuy không đến mức đỉnh thiên lập địa như trước, nhưng vẫn đủ khiến người ta khiếp sợ. Dưới chân, rồng vàng chở y chậm rãi bay lượn vòng quanh, ánh sáng chiếu rọi cả nửa bầu trời đêm tối.", "Sở Cửu Biện cúi mắt nhìn xuống, thấy Giang Sóc Dã đang bị một đám người vây kín.", "Giang Sóc Dã cũng nhìn thấy y, đôi mắt hỗn loạn của y lập tức bừng tỉnh trong một cái chớp mắt, tràn ngập niềm vui mừng khôn xiết.", "Đại Tư Tế đến rồi!", "Sở Cửu Biện xuất hiện, mang theo ánh sáng, khiến những kẻ đang chìm trong bóng tối chiến đấu bấy lâu đều phải nheo mắt, ngước lên nhìn. Ngay sau đó, tất cả nhìn thấy một thân ảnh khổng lồ. Thân hình đối phương mờ ảo, chân đạp rồng vàng, gương mặt lãnh đạm xa cách.", "Biến cố đột ngột này khiến ai nấy sững sờ tại chỗ. Chỉ có Giang Sóc Dã phản ứng nhanh nhất, dù chưa nhìn rõ hư ảnh trên bầu trời kia, nhưng con rồng vàng ấy y nhận ra ngay — đó chính là tọa kỵ của Đại Tư Tế.", "Nhân lúc mọi người còn chưa kịp phản ứng, y lập tức xông ra ngoài.", "Đám thị vệ trước đây từng thấy hình bóng của Sở thái phó, đã sợ đến mức nơm nớp lo sợ. Nay lại thấy một lần nữa, càng thêm hoảng loạn. Không ít kẻ quỳ sụp xuống dập đầu nhận lỗi, dù chính bọn họ cũng chẳng rõ mình sai ở đâu.", "Tự nhiên bọn họ không thể ngờ Sở Cửu Biện xuất hiện là vì Giang Sóc Dã.", "Nhìn bộ dạng những kẻ này, Sở Cửu Biện bỗng thấy 500 điểm bỏ ra chẳng hề uổng phí — chẳng khác nào mua lại hiệu ứng đặc biệt từng dùng ở thánh sơn Tây Vực năm nào, đủ để trấn áp đám người này.", "Giang Sóc Dã bước nhanh về phía trước, nhưng thương tích trên người quá nhiều, có thể nói y chỉ dựa vào ý chí mà bước đi, bước nào cũng chậm chạp đến khổ sở.", "Giang Hiến ban đầu cũng bị Sở Cửu Biện dọa cho hoảng sợ, nhưng thấy đối phương mãi vẫn chưa ra tay, dần dần lại nghĩ rằng vị thần Sở Cửu Biện này cũng giống như những pho tượng thần trong miếu, chỉ có thể hiện ra cái bóng dáng như thế, chứ không thể thực sự làm được gì.", "Vì thế ông lại đứng dậy, lớn tiếng hô: “Thần không hại người đâu! Xông lên! Đừng để Giang Sóc Dã chạy thoát!”", "“Nó mà chạy thoát, các ngươi cũng đừng mong sống nổi!”", "Đội quân khổng lồ trong tay Giang Sóc Dã không phải chỉ để trưng bày, nếu y thoát được, thì không cần đợi đến sáng mai, ngay đêm nay cả Giang gia này chắc chắn không còn ai sống sót.", "Đám người hầu cũng nhận ra Sở Cửu Biện vẫn mãi chưa ra tay, liền có kẻ đánh liều đứng dậy, xông về phía Giang Sóc Dã.", "Sở Cửu Biện khẽ nhíu mày, rút ra một quả lựu đạn, ném thẳng về hướng kẻ vừa xông tới.", "Mọi người chỉ thấy thần minh phất tay áo, liền vang lên một tiếng “Ầm——”.", "Đất rung núi chuyển, ánh lửa rực trời.", "Ai nấy đều ngừng bặt lại, Giang Hiến cũng không dám giở trò gì thêm.", "Thời gian hiện hình của Sở Cửu Biện cũng sắp hết, y ném thêm mấy quả sấm sét nữa, đảm bảo Giang Sóc Dã có thể mau chóng thoát khỏi nơi thị phi này.", "Giang Sóc Dã quả nhiên đã thoát ra khỏi Giang phủ. Rõ ràng là nhà mình, mà suýt chút nữa đã bỏ mạng ngay tại đây.", "Thế giới trước mắt mê mang mờ ảo, cơn buồn ngủ nặng nề khiến Giang Sóc Dã không sao mở nổi mắt, vết thương trên người vẫn không ngừng rỉ máu.", "Sở Cửu Biện nhìn y loạng choạng định lên ngựa trở về doanh trại, liền sai hệ thống kiểm tra tình trạng thương tích. Nếu quân y có thể chữa được, vậy thì đỡ cho Sở Cửu Biện một phen nhọc lòng. Nếu không, y đành phải lại kéo Giang Sóc Dã vào như từng làm với Tần Kiêu trước đây, để mổ xẻ chữa trị.", "Hệ thống kiểm tra thân thể Giang Sóc Dã, kết quả cho thấy phần lớn chỉ là thương tích ngoài da, chỉ có một vết đao khá sâu, vì thế mới chảy nhiều máu như vậy. Còn việc đi đứng xiêu vẹo, kỳ thực là do thuốc uống phải, thuốc tan hết là ổn.", "Sở Cửu Biện yên tâm, dặn hệ thống tiếp tục theo dõi tình hình đối phương, còn bản thân đã đến lúc phải rời khỏi Thần Vực.", "Vừa mở mắt ra, y đã thấy mình vẫn đang ngả vào lòng Tần Kiêu. Tần Kiêu vẫn giữ nguyên tư thế, không hề nhúc nhích, cảm nhận y “tỉnh lại”, mới chậm rãi đẩy y ra khỏi ngực mình một chút, nhìn thẳng vào mắt y.", "Họ vẫn còn giữ nguyên tư thế gắn kết chặt chẽ, Sở Cửu Biện thậm chí còn cảm nhận được, trong cơ thể mình, hơi ấm thuộc về người đàn ông kia.", "Nhưng Tần Kiêu chỉ nhìn y, khóe môi như cười mà chẳng cười, nói: “Lúc thế này mà vẫn phải đi gặp người khác à?”", "Nói rồi, y còn ra sức đè Sở Cửu Biện nằm xuống.", "Sở Cửu Biện run lên.", "“Lúc đi gặp người khác có mặc quần áo không đấy?” Tần Kiêu hỏi, khẽ bế y lên một chút rồi buông ra, khiến y ngồi phịch xuống.", "Sở Cửu Biện mặt đỏ bừng đến tận tai, chậm rãi dựa vào ngực y, giọng khe khẽ: “Đừng hỏi nữa.”", "Tần Kiêu ôm lấy y, trong miệng vẫn buông ra vài câu trêu chọc ỡm ờ như thường lệ, nhưng ở nơi Sở Cửu Biện không nhìn thấy, đáy mắt người đàn ông ấy cảm xúc lại trầm sâu, u ám khó tả.", "Sau một lượt kết thúc nữa, Tần Kiêu thuần thục lau mặt, đánh răng, tắm rửa cho Sở Cửu Biện. Sở Cửu Biện ngồi trong thau nước, mơ màng sắp thiếp đi, thì đột nhiên chỉ cảm thấy trong ngực một trận đau nhói, ngay sau đó không kìm được mà phun ra một búng máu.", "Tần Kiêu chợt căng thẳng, theo bản năng ôm chặt lấy y.", "“Sở Cửu Biện!”", "Giọng người đàn ông nôn nóng vang lên, dường như cách một tầng sương mù, xa xăm lắm.", "Trời đất quay cuồng, Sở Cửu Biện nhắm nghiền hai mắt.", "Di chứng của việc bóp méo không gian đã kéo đến."], "id": 0, "wordCount": 6204}, {"title": "Chương 105 – Phiên ngoại hai", "paragraphs": ["Dùng ý thức xuyên qua đến một nơi khác, vốn đã vi phạm quy tắc của thế giới ba chiều này. Hệ thống từng nói trước với Sở Cửu Biện rằng tác dụng phụ của việc đó chính là nội tạng chảy máu nhẹ, thường xuyên choáng váng và những triệu chứng tương tự. Đến giờ Sở Cửu Biện mới thực sự cảm nhận được cái giá phải trả ấy lợi hại đến mức nào.", "Y nhắm nghiền hai mắt, trời đất quay cuồng, như thể vừa uống phải thứ thuốc khiến người ta mê man, nhưng thỉnh thoảng vẫn còn vài khoảnh khắc tỉnh táo. Y nghe được tiếng Tần Kiêu gọi mình nôn nóng, cảm nhận được lòng bàn tay đối phương đang đỡ lấy mặt mình.", "Vì thế y giơ tay lên, Tần Kiêu lập tức nắm lấy, tiếp tục gọi tên y.", "“Không sao đâu.” Sở Cửu Biện chậm rãi hé mắt, càng lúc càng lơ mơ, liền lại nhắm nghiền mắt, giọng khàn khàn nói, “Qua hai ngày là khỏi thôi.”", "Nhưng vừa dứt lời, y lại phun ra thêm hai ngụm máu nữa.", "Sắc mặt Tần Kiêu còn khó coi hơn cả Sở Cửu Biện. Y nhanh chóng lau sạch vết máu trên mặt thanh niên, rồi bế y ra khỏi thau tắm, đặt lên giường.", "Sở Cửu Biện nghe tiếng Tần Kiêu bước ra ngoài, dặn dò người bên ngoài đi gọi thái y. Rồi người đàn ông lại quay về bên mép giường, mặc áo lót cho y, lấy chăn quấn kín người y lại.", "Cơn choáng váng vẫn chưa hề thuyên giảm, cơn đau âm ỉ trong lồng ngực cũng còn đó. Sở Cửu Biện hỏi hệ thống: “Đây là kiểu đau ngắt quãng à?”", "【Đúng vậy, ký chủ. Hệ thống có thể đảm bảo sau khi tác dụng phụ tiêu hết, cơ thể ký chủ sẽ không để lại bất kỳ di chứng nào, xin ký chủ yên tâm.】", "Sở Cửu Biện quả thật yên tâm hơn hẳn. Vậy thì chịu đựng thôi, qua được đợt này là ổn.", "Sở Cửu Biện vốn rất giỏi phân tán sự chú ý để giảm bớt cảm giác đau đớn, giờ y cũng làm y hệt như vậy.", "Trong đầu miên man những suy nghĩ rời rạc, y mơ mơ hồ hồ thấy dòng xe cộ như nước, những tòa cao ốc chọc trời, thấy cả tấm áp phích quảng cáo của chính mình lặp đi lặp lại trên màn hình lớn ngoài phố.", "Cảnh tượng trước mắt đột nhiên đổi khác, y thấy rừng cây rậm rạp, thấy núi non trùng điệp nguy nga, thấy từng đàn hạc tiên bay lượn giữa các đỉnh núi. Rồi lại thấy thêm nhiều sông núi ao hồ khác, cảnh vật biến đổi từ xưa đến nay, từ trong nước ra hải ngoại.", "Y như một lữ khách xuyên thời không, đi qua hết thế giới này đến thế giới khác, nếm trải đủ kiểu nhân sinh khác nhau. Giống hệt như thuở ban đầu y chọn trở thành diễn viên vậy — y không muốn làm chính mình, y muốn trở thành “người khác”. Trở thành một người bình thường.", "Y dường như thực sự lạc mất bản thân, mờ nhạt dần con người ban đầu của mình.", "Cho đến khi, y thấy mình đang ngồi trên một chuyến phi hành khí công cộng, bay giữa vũ trụ.", "Nơi này giống như một chiếc phi cơ, có rất nhiều chỗ ngồi, chở rất nhiều hành khách. Sở Cửu Biện “nhìn thấy” chính mình ngồi ở khoang hạng nhất phía trước. Khoang này chỉ có sáu chỗ ngồi, mà lúc này, tính cả y, chỉ có hai người.", "Sở Cửu Biện cảm giác mình đang thực sự ngồi trên ghế, cảm giác ấy chân thực đến lạ, y thậm chí còn ngửi thấy mùi hương thoang thoảng trong khoang. Y hơi phân vân không rõ đâu là thực, đâu là ảo.", "Y nghiêng đầu, nhìn về phía vị hành khách còn lại trong khoang.", "Đó là một người đàn ông, thân hình cao lớn, đôi chân dài bắt chéo, ngồi bên cửa sổ, ngắm nhìn khoảng vũ trụ dường như bất biến ngoài kia.", "Có lẽ nhận ra ánh mắt của Sở Cửu Biện, người ấy quay đầu lại.", "Bốn mắt nhìn nhau, đồng tử Sở Cửu Biện co rụt.", "“Tần Kiêu.” Y bật thốt lên, và ngay khoảnh khắc ấy, y hoàn toàn tỉnh táo trở lại.", "Những cảnh mộng kỳ lạ kia biến mất, cơn choáng váng cũng tan biến không dấu vết.", "Y mở mắt ra, phát hiện mình vẫn đang nằm trên giường, phía trên đầu là khung giường chạm khắc quen thuộc.", "“Thế nào rồi?” Một giọng nam hơi khàn vang lên bên cạnh. Sở Cửu Biện nghiêng đầu, đối diện với đôi mắt thâm trầm của Tần Kiêu.", "Ngoài cửa sổ trời đã sáng rõ, Tần Kiêu cũng đã thay xiêm y khác, trông tỉnh táo hẳn, nhưng trên cằm đã lún phún ria xanh.", "Sở Cửu Biện giơ tay lên, Tần Kiêu liền nắm lấy tay y. Cảm nhận được chút lực trong tay thanh niên, y liền thuận thế cúi sát xuống hơn, để y có thể chạm được tới cằm mình.", "Sở Cửu Biện thấy trong người không có chỗ nào khó chịu, chỉ là mệt, tựa như bị rút cạn sức lực, còn mệt hơn cả những lần trước ở liền hai ba ngày trên giường với Tần Kiêu mà không xuống được.", "“Còn đau không?” Tần Kiêu một tay đỡ cổ tay y, tay kia khẽ vuốt ve gương mặt y.", "Sở Cửu Biện bình thản nhìn y.", "Nói thật, y rất ít khi thấy Tần Kiêu như lúc này. Trước mặt y, Tần Kiêu vốn mạnh mẽ mà cũng thoải mái, sẽ nghiêm túc xử lý chính sự, cũng sẽ trêu chọc bỡn cợt, có lúc chẳng đứng đắn chút nào. Cũng sẽ bộc lộ những cảm xúc tiêu cực, như phẫn nộ, mê mang, cô độc.", "Nhưng rất hiếm khi lại như lúc này… dịu dàng? Cũng không hẳn là chính xác, dường như còn sâu hơn cả sự dịu dàng, Sở Cửu Biện không tìm được từ nào thích hợp hơn để diễn tả.", "Nói tóm lại, bị Tần Kiêu nhìn bằng ánh mắt như vậy, bằng thái độ trân trọng như vậy, trong lòng y bỗng thấy thật nhẹ nhõm, thoải mái. Y muốn buông lỏng hoàn toàn, mặc kệ mọi thứ, chỉ giao phó bản thân cho Tần Kiêu.", "Giống như những lúc họ ở trên giường vậy.", "Nhưng lại không hẳn giống.", "Trên giường, y chỉ đem thân thể mình hoàn toàn giao ra, tận hưởng sự khống chế mạnh mẽ của Tần Kiêu đối với mình. Nhưng lúc này, y lại muốn đem cả trái tim mình giao ra nữa.", "Cảm giác này y chưa từng có trước đây.", "Nhận ra ý nghĩ của chính mình, tim Sở Cửu Biện chợt hẫng một nhịp.", "Tần Kiêu thấy y mãi không nói gì, liền nghiêng đầu khẽ hôn lên đầu ngón tay y.", "Sở Cửu Biện lấy lại tinh thần, đầu ngón tay khẽ co lại một chút.", "“Không đau.” Y nói.", "“Vậy có đói không? Có muốn ăn gì không?”", "Tần Kiêu không hỏi vì sao Sở Cửu Biện đột nhiên hộc máu ngất đi, cũng không hỏi gì khác, chỉ quan tâm y như mọi ngày bình thường.", "“Đói.” Sở Cửu Biện gật đầu.", "Tần Kiêu liền bế y dậy, để y tựa vào đầu giường mà ngồi. Đã qua giờ ăn sáng từ lâu, nhưng bữa sớm vẫn được giữ ấm, giờ Sở Cửu Biện muốn ăn, Ngự Thiện Phòng lập tức bưng bữa sáng nóng hổi tới.", "Tần Kiêu bày một chiếc bàn nhỏ trên giường trước mặt Sở Cửu Biện, bảo y ăn ngay trên giường.", "Sở Cửu Biện nói: “Ta xuống dưới ăn thôi.”", "Y không thích ăn trên giường, cứ cảm thấy sẽ làm bẩn chăn đệm.", "Tần Kiêu biết y đang câu nệ chuyện gì, nói: “Không sao, bẩn thì thay cái khác.”", "Sở Cửu Biện sợ lát nữa lại chóng mặt, đến lúc đó muốn ăn cũng chẳng ăn nổi, nên cũng không nài nỉ nữa.", "Y cúi đầu húp cháo, trong phòng chỉ còn tiếng cháo va chạm với muỗng nhỏ nhẹ, ngoài phòng thấp thoáng có tiếng cung nhân quét tuyết.", "“Bệ hạ đâu rồi?” Sở Cửu Biện hỏi.", "“Đi Dao Đài.”", "Tần Xuyên vẫn đang ở lại Dao Đài. Có lẽ quan hệ huyết thống thật sự vi diệu, Bách Lý Hồng ngay từ đầu đã tỏ ra vô cùng tò mò và thân thiết với Tần Xuyên. Hai người gặp nhau lần đầu vào cái hôm Lục Nghiêu cùng mọi người cưỡi ngựa dạo phố, sau này ở trong cung lâu ngày, cơ hội gặp gỡ càng nhiều, càng thêm thân thiết.", "Tần Xuyên từ nhỏ lang bạt giang hồ, biết nhiều thứ mới lạ, thuộc nhiều chuyện kỳ quặc. Còn Bách Lý Hồng, một đứa trẻ từ nhỏ đã quẩn quanh trong thâm cung, tự nhiên nghe những chuyện ấy thì mê tít. Giờ đang trong thời gian bãi triều, cậu bé rảnh rỗi không có việc gì, lại chạy đi tìm Tần Xuyên.", "Sở Cửu Biện gật đầu, cầm cái bánh bao lên ăn. Y ăn uống lúc nào cũng thật thanh nhã, ngay cả động tác nhai nuốt cũng như đã được luyện tập kỹ càng, nhìn thật đẹp mắt.", "Tần Kiêu ngồi khoanh chân đối diện y, chỉ lặng lẽ nhìn, không biết đang nghĩ gì.", "Sở Cửu Biện ngước mắt nhìn y, nuốt xong miếng trong miệng mới hỏi: “Ngươi định khi nào khôi phục lại thân phận cho Tần Xuyên?”", "“Tùy nó thôi.” Tần Kiêu nói, “Trước đây nó không có quyền tự lựa chọn, giờ đã có rồi, để nó tự quyết định.”", "Sở Cửu Biện gật đầu, lại hỏi: “Vậy còn ngươi?”", "“Gì cơ?”", "“Ngươi không có gì muốn hỏi ta sao?” Sở Cửu Biện một tay bưng chén cháo, tay kia cầm muỗng múc từng thìa, tư thái và giọng điệu đều rất tự nhiên, tự nhiên đến mức như thể dù Tần Kiêu hỏi gì, y cũng sẽ trả lời hết.", "Tần Kiêu bật cười, nói: “Vậy ta hỏi thật đây.”", "“Hỏi đi.”", "“Sau này ngươi có còn bị thương theo kiểu khó hiểu như thế nữa không?” Tần Kiêu hỏi.", "Sở Cửu Biện khựng lại: “Ngươi lại hỏi cái này?”", "“Khó nói lắm sao?”", "“Cũng không phải.” Sở Cửu Biện vốn tưởng y sẽ hỏi xem mình có phải đi gặp Đại Tư Tế không, vì sao lại đi, đã xảy ra chuyện gì linh tinh.", "Nhưng những câu hỏi nửa trêu chọc nửa ghen tuông ấy, Tần Kiêu thường chỉ hỏi lúc đùa giỡn hoặc trên giường mà thôi. Như một kiểu gia vị tình cảm vậy.", "Sở Cửu Biện cảm nhận được Tần Kiêu quả thực rất để tâm đến quan hệ giữa y và Đại Tư Tế, nhưng so với thứ ghen tuông khó hiểu ấy, điều y muốn biết hơn cả là liệu Sở Cửu Biện có còn bị thương nữa hay không.", "“Ta sẽ cố hết sức để đảm bảo an toàn.” Sở Cửu Biện trầm ngâm một lúc rồi đáp.", "Y không có cách nào chắc chắn rằng sau này mình sẽ không gặp lại tình huống tương tự, nếu có, y chắc chắn vẫn sẽ làm như vậy, và vẫn sẽ bị thương như vậy. Nên y chỉ có thể nói là “cố hết sức”.", "Tần Kiêu im lặng không đáp lời.", "Mãi đến khi Sở Cửu Biện húp hết chén cháo, súc miệng xong, Tần Kiêu mới lên tiếng: “Ta không có cách nào giúp ngươi sao?”", "Sở Cửu Biện sững người.", "Gương mặt người đàn ông bình thản nhìn y, như thể chỉ thuận miệng hỏi vậy thôi.", "Sở Cửu Biện cân nhắc câu chữ, mới đáp: “Ngươi đã giúp ta rất nhiều rồi.”", "Từ khi giao dịch bắt đầu, cho đến từng chuyện từng việc về sau, sự trợ giúp mà Tần Kiêu dành cho Sở Cửu Biện thực sự không hề ít. Hai người tuy vì lợi ích mà đến với nhau, nhưng con đường này đích thực là họ đã nắm tay nhau đi tới tận bây giờ. Đến giờ, sợi dây tình cảm giữa họ đã sớm vượt xa mối quan hệ lợi ích ban đầu.", "Tần Kiêu không tỏ thái độ gì thêm, chỉ cười đổi đề tài: “Ăn xong chưa?”", "“Ừ.”", "Tần Kiêu liền sai người dọn chén đĩa trên bàn, cất bàn đi.", "Sở Cửu Biện xuống giường, lười thay quần áo ra ngoài, chỉ cùng Tần Kiêu chậm rãi đi dạo trong điện. Y lấy ra hai viên đường, một viên ngậm vào miệng mình, viên còn lại đưa tới bên môi người đàn ông.", "Tần Kiêu liền há miệng ngậm lấy.", "“Ngươi phát hiện ra khi nào, rằng ta có thể ở ‘trong mộng’ gặp gỡ người khác?” Sở Cửu Biện hỏi.", "Tần Kiêu nghĩ ngợi một lát, nói: “Từ lần đầu tiên ta bước vào phòng ngủ của ngươi.”", "Sở Cửu Biện hồi tưởng lại. Hình như từng có một chuyện như vậy, lúc đó là giờ nghỉ trưa, y có việc vào Thần Vực còn chưa ra, liền nghe hệ thống nhắc có người đến tìm. Y ra ngoài mới thấy chính là Tần Kiêu cùng Bách Lý Hồng.", "Nghĩ lại, chính là lúc đó Tần Kiêu phát hiện y không thực sự ngủ, sau đó suy luận thêm một chút, liền biết được y có thể trong giấc mộng liên hệ với “Đại Tư Tế”.", "Vì vậy mỗi lần Sở Cửu Biện ở bên cạnh Tần Kiêu mà vào Thần Vực, y đều biết. Biết Sở Cửu Biện đang đi gặp một vị thần minh khác.", "“Ngươi thấy Đại Tư Tế là loại thần như thế nào?” Sở Cửu Biện hỏi Tần Kiêu.", "Tần Kiêu: “Không biết, chưa từng gặp.”", "Sở Cửu Biện nhướng mày, không nói thêm.", "Tần Kiêu nghiêng đầu nhìn y, hỏi lại: “Vậy ngươi thấy y là loại thần như thế nào?”", "“Giống ta thôi.” Sở Cửu Biện nói như thể có ý ám chỉ điều gì, “Ngươi thấy ta ra sao, thì y cũng chính là như vậy.”", "“Vậy các ngươi quan hệ với nhau thế nào?”", "“Như là một người vậy.” Sở Cửu Biện đã nói ra khá rõ ràng rồi.", "Không phải y không muốn nói thẳng, mà là cơ chế bảo hộ của Thần Vực đang có hiệu lực, y không có cách nào ở ngoài Thần Vực mà thừa nhận với người khác rằng mình chính là Đại Tư Tế. Nên nếu muốn công khai thân phận, y buộc phải kéo Tần Kiêu vào tận Thần Vực mới được.", "Nhưng hệ thống hiện tại lại nhất quyết không cho phép y làm vậy. Vì chuyện này, Sở Cửu Biện từng lý luận với hệ thống rất nhiều, khiến cho cái trí năng nhân tạo cứng nhắc kia cũng phải rối trí, mất mấy tiếng đồng hồ mới trả lời được rằng đây là giới hạn của hệ thống. Bản thân hệ thống cũng không rõ vì sao lại có quy định kỳ lạ như vậy, nhưng nó xác thực tồn tại.", "Nó quyết định, ít nhất trong lúc này, Sở Cửu Biện thực sự phải giữ trọn thân phận “Thủy Tiên” đến cùng.", "Tần Kiêu trầm mặc hồi lâu.", "Câu nói “giống như một người vậy” của Sở Cửu Biện, chẳng phải nên là một mối quan hệ hết sức quen thuộc, hết sức thân mật hay sao? Nhưng dù có thân mật đến mấy, liệu có thể thân mật bằng chính y với Sở Cửu Biện được không? Chuyện đáng làm không đáng làm họ đều đã làm cả, huống chi Sở Cửu Biện với y cũng có không ít cảm tình…", "Đúng lúc Sở Cửu Biện còn đang nghĩ xem làm sao nói cho rõ ràng hơn một chút, ngực y lại đau nhói lên, y theo bản năng ôm lấy ngực, thế giới trước mắt dần dần quay cuồng.", "Tần Kiêu không kịp nghĩ gì thêm, vội bế ngang người y đặt lên chiếc trường kỷ.", "Đêm hôm trước thái y đã đến khám, nói Sở Cửu Biện bị nội thương, cần dưỡng bệnh cẩn thận, còn kê cả một đống thuốc bổ ôn dưỡng, nhưng cái vị đắng chát ấy chẳng bằng thứ thuốc Sở Cửu Biện tự mua từ cửa hàng hệ thống.", "Tần Kiêu dùng khăn ướt lau sạch máu bên khóe môi thanh niên, khẽ thì thầm điều gì đó. Sở Cửu Biện lơ mơ nghe được giọng nói trầm khàn của người đàn ông, cứ gọi tên y hết lần này đến lần khác, còn nói thêm điều gì nữa, nhưng y nghe không rõ lắm.", "Cứ như vậy, hai ngày trôi qua.", "Mãi đến ngày thứ ba, cũng chính là đêm mùng năm, Sở Cửu Biện mới cảm thấy cơ thể mình nhẹ nhõm hẳn.", "Tác dụng phụ rốt cuộc cũng chịu đựng qua được!", "Suốt hai ngày ấy, Tần Kiêu luôn túc trực bên cạnh, chăm sóc y hết sức chu đáo, chưa từng nhờ tay người khác.", "“Khỏe chưa?” Tần Kiêu đưa tay sờ trán y, cau mày hỏi, “Chắc chắn khỏe rồi chứ?”", "Mấy ngày liền chứng kiến Sở Cửu Biện liên tục hộc máu ngất xỉu, gần như khiến Tần Kiêu cũng phát choáng theo.", "“Chắc chắn rồi.” Sở Cửu Biện gật đầu, “Kêu người chuẩn bị nước cho ta đi, người ngợm khó chịu quá.”", "Không bao lâu sau, thau tắm đã đầy ắp nước ấm sạch sẽ.", "Sở Cửu Biện từ trên giường đứng dậy, đi tới bên thau tắm. Y cởi dây lưng, cảm nhận phía sau có ánh mắt như thực chất đang dõi theo, nhưng Sở Cửu Biện làm như không hay biết.", "Y cởi áo trong ra, để lộ đường cong mềm mại nơi tấm lưng cùng vòng eo thon nhỏ. Xiêm y bị tiện tay ném lên giá áo, Sở Cửu Biện lại cởi tiếp quần dưới.", "Động tác của y nhanh gọn, khiến Tần Kiêu còn chưa kịp chuẩn bị tâm lý, ánh mắt còn dừng lại nơi vòng eo mảnh khảnh kia, thì phần đầy đặn phía dưới đã lọt vào tầm mắt.", "Có lẽ vì vừa nãy ngồi lâu, nơi đó vẫn còn vương chút sắc hồng nhàn nhạt. Nhưng Tần Kiêu nhớ rõ, chỗ ấy từng bị đánh cho ửng đỏ tươi hẳn, làn da thanh niên vốn mỏng mịn, thường lưu lại dấu tay của y.", "Thau tắm không cao quá bụng, Sở Cửu Biện nhấc một chân dài cân đối, khẽ bước vào trong. Y ngồi cả người xuống thau, hai tay gác lên thành thau, gối mặt lên cánh tay, nhìn về phía Tần Kiêu.", "Bốn mắt nhìn nhau, chẳng ai chịu rời đi trước.", "Hồi lâu sau, cuối cùng cũng là Tần Kiêu chủ động dời mắt, giọng hơi khàn: “Người ngươi còn yếu, đợi thêm hai ngày nữa rồi hẵng tính.”", "Sở Cửu Biện liếc thấy phản ứng rõ ràng của người đàn ông, cố ý nói: “Ngươi mới là kẻ yếu ấy, cỡ này còn nhịn được mà.”", "“…?” Tần Kiêu bật cười, cũng chẳng biết là thấy buồn cười hay là bị chọc tức đến phát cười.", "Y đứng dậy, bước đến bên thau tắm, từ trên cao nhìn xuống gương mặt tinh nghịch đáng ghét của thanh niên.", "Khóe môi Sở Cửu Biện khẽ nhếch lên, trông không còn vẻ thanh lãnh như thường ngày, mà mang thêm chút ranh mãnh, đầy sức quyến rũ.", "Ánh mắt Tần Kiêu hơi trầm xuống.", "Y cúi người, một tay đỡ sau gáy thanh niên mà hôn lên, tay còn lại luồn vào trong thau nước, không nặng không nhẹ mà bóp nhẹ một cái.", "Sở Cửu Biện run bắn lên.", "Tiếng nước bắn lên từng đợt, rồi lại lặng đi.", "Tần Kiêu lấy dung dịch tắm gội để bên cạnh, đổ vào lòng bàn tay, chậm rãi thoa lên cổ và vai thanh niên. Rồi y dùng hai tay hơi ra sức, ôm lấy eo Sở Cửu Biện, nâng y đứng dậy khỏi thau nước.", "Đôi chân dài vẫn còn ngâm trong nước, phần còn lại của cơ thể hoàn toàn hiện ra trước mắt người đàn ông.", "Sở Cửu Biện cảm nhận được bàn tay đang xoa rửa cho mình của người đàn ông cũng khẽ run lên, đặc biệt khi xoa đến phía sau lưng, hơi thở phả vào gáy y còn khiến người ta giật mình. Đầu ngón tay không kìm được mà luồn vào, khẽ cọ xát nơi nào đó.", "Sở Cửu Biện suýt chút nữa không đứng vững nổi.", "Tần Kiêu liền ôm lấy y, chậm rãi tráng rửa sạch sẽ, rồi bế y trở về giường.", "Tần Kiêu nói được làm được, thật sự kiêng dè vì thân thể Sở Cửu Biện chưa khỏe hẳn, không đi đến cùng. Nhưng y cũng không muốn để Sở Cửu Biện phải nhịn nhục quá khó chịu, thậm chí còn chẳng để ý đến phản ứng của chính mình, chỉ chuyên tâm chiều chuộng Sở Cửu Biện, sợ lòng bàn tay thô ráp làm đau đối phương, liền dùng đôi môi mềm mại hơn.", "Cứ như thế, mấy ngày trôi qua.", "Trong thời gian này, Tần Kiêu nhận được tin tức từ Mạc Bắc, biết Mạc Bắc Quân đã hoàn toàn chiếm lĩnh vùng thảo nguyên phía bắc, mở mang thêm bờ cõi cho Đại Ninh. Đồng thời, y còn nhận được tin đồn rằng Sở thái phó đã hiển linh ở Mạc Bắc, cứu Giang Sóc Dã một mạng.", "Sự thật đúng là như vậy, chỉ có điều ngày ấy trong lúc nguy cấp, Giang Sóc Dã chỉ vội vàng liếc mắt nhìn con rồng vàng kia, không dám chắc đó có phải Đại Tư Tế hay không. Vì thế khi vào Thần Vực tạ ơn cứu mạng của Đại Tư Tế, y còn thuận miệng hỏi rốt cuộc vị thần đã cứu mình là Đại Tư Tế hay là Sở Cửu Biện.", "Đại Tư Tế chỉ bảo y cứ nói là Sở Cửu Biện cứu là được.", "Đây không phải lần đầu tiên vị thần ấy yêu cầu tăng thêm danh vọng cho Sở Cửu Biện, Giang Sóc Dã đã quen với chuyện này, nên tin tức truyền về đến kinh thành liền trở thành “Sở Cửu Biện cứu Giang Sóc Dã”.", "Tần Kiêu cũng vì thế mà đoán ra, cái đêm Sở Cửu Biện đột nhiên “ngủ thiếp đi” ấy, kỳ thực chính là y đã đến Mạc Bắc, cứu Giang Sóc Dã.", "*", "Ngày mùng mười thì lâm triều trở lại. Nhịn nhục bao lâu nay, Tần Kiêu rốt cuộc buông thả hết mình vào đêm mùng tám.", "Từ chạng vạng, đến nửa đêm, rồi lại đến khi trời sáng bạch. Y gần như muốn trút hết ngọn lửa đã dồn nén bấy lâu, quấn quýt Sở Cửu Biện đến mức sang tận ngày mùng chín vẫn chưa xuống giường nổi.", "May mà dưỡng sức hơn nửa ngày, đến hôm sau lâm triều, Sở Cửu Biện đã có thể lên triều bình thường trở lại.", "Trong triều, nhân sự đã thay đổi cả một loạt. Song những chức vị còn khuyết vẫn còn rất nhiều, Sở Cửu Biện liền hạ lệnh cho Lễ Bộ thượng thư Đàm Vũ Trúc cùng thị lang Thái Bằng phối hợp phụ trách khoa cử năm nay.", "Không sai, giờ đây phe cánh của hoàng đế đã hoàn toàn thắng thế. Địa vị của những người dưới trướng y cũng theo đó mà lên như diều gặp gió: Hộ Bộ thượng thư Vương Bằng Nghĩa, Công Bộ thượng thư Giản Hoành Trác vốn dĩ đã là quan lớn, nay vẫn giữ nguyên chức vị, chỉ có Vương Bằng Nghĩa được thăng thêm một bậc.", "Ngoài ra còn có Lễ Bộ thượng thư Đàm Vũ Trúc, Lại Bộ thượng thư Lục Nghiêu, Hình Bộ thượng thư Cố Thanh Trực, Binh Bộ thượng thư Tần Triều Dương.", "Tần Triều Dương vốn có tài năng không nhỏ, trước đây Tần Kiêu thực sự cần y làm nhiều việc hơn nên mới giữ y lại bên cạnh. Giờ điều kiện đã chín muồi, tự nhiên phải cho y một con đường thăng tiến rộng mở.", "Cái lợi của việc hoàng quyền tập trung chính là ở chỗ này — bất kể Tần Kiêu và Sở Cửu Biện đưa ra quyết định gì, chỉ cần lý do nói được thông suốt, sẽ không ai dám phản đối. Huống hồ hai người này làm việc quả thực kín kẽ không hở, lý do luôn tìm được thật hoàn hảo, khiến đám ngôn quan ngự sử có muốn bới lông tìm vết cũng chẳng tìm ra được sơ hở nào.", "Vì thế, đến giờ, Sở Cửu Biện và Tần Kiêu đã hoàn toàn nắm trọn sáu bộ trong triều, các bộ vận hành cũng thông suốt, hiệu quả hơn trước rất nhiều.", "Cố Thanh Trực trước đây vốn là Đại Lý Tự khanh, nhưng vì chức Hình Bộ thượng thư đang khuyết, thậm chí nhiều chức vị bên dưới cũng trống không, nên được cử tạm kiêm chức Hình Bộ thượng thư. Nói là tạm kiêm, nhưng thực chất chẳng khác nào để y kiêm nhiệm luôn hai chức cùng lúc. Hiện tại y lấy danh nghĩa Hình Bộ thượng thư kiêm Đại Lý Tự khanh, từng bước báo cáo lên kết quả xử phạt những kẻ quyền quý đang bị giam trong thiên lao.", "Những kẻ này không đơn thuần chỉ phạm tội mưu phản, mà còn có vô số bằng chứng về việc tác oai tác phúc ngay tại kinh thành, nên tuyệt đại đa số đều bị xử chém, gia tộc liên lụy thì bị tịch thu gia sản, lưu đày…", "Lục Doanh Nặc đến chết cũng không chịu khai ra kẻ đã hại chết vợ chồng Tần Cảnh Triệu là ai. Đúng như lời y từng nói, sở dĩ không nhắc đến cái tên “Ngũ Di Nương”, là vì muốn tốt cho Tần Kiêu.", "Xét cho cùng, Ngũ Di Nương tuy đã chết, nhưng hai người con gái của bà vẫn còn ở Tần gia, được Tần Kiêu che chở mà bình an lớn lên, tương lai biết đâu còn có thể theo đường khoa cử ra làm quan. Điều này đối với Tần Kiêu mà nói, chẳng khác nào đang nuôi dưỡng “kẻ thù” của chính mình.", "Nhưng đổi một góc nhìn khác mà xem, mẹ của hai cô con gái ấy hại chết cha mẹ Tần Kiêu, nhưng cha của họ lại chết vì cứu cha của Tần Kiêu. Sở dĩ hai chị em có thể lớn lên bình yên trong Tần gia, ngoài cái tình Ngụy Linh Chứa dành cho Ngũ Di Nương, còn vì Tần Cảnh Triệu cùng Ngụy Linh Chứa mang ơn cứu mạng của cha họ.", "Vậy nên đúng sai tốt xấu, nào phải chuyện dễ dàng phân định rạch ròi như thế.", "Tần Kiêu vốn không phải người cố chấp bảo thủ, chuyện nào ra chuyện nấy. Với y, ân oán của thế hệ trước, thực ra đã kết thúc từ cái khoảnh khắc Ngũ Di Nương cùng chết với Ngụy Linh Chứa. Giờ là thời của lớp trẻ, giữa họ không có oán thù gì, chỉ có tình nghĩa từ nhỏ cùng lớn lên với nhau.", "Lục Doanh Nặc, vì bất kể lý do gì, cũng chưa từng khai ra điều gì, cũng chưa từng tiết lộ rốt cuộc Lục gia còn cài bao nhiêu tai mắt. Y thản nhiên đón nhận cái chết.", "Còn gia chủ Lục Tẫn Phong, từ lúc bị bắt đến nay cũng chưa từng hé môi nửa lời.", "Chỉ có điều, dù bọn họ không nói, phía Lục gia lại chẳng hề nương tay với cặp vợ chồng đã khuất kia. Như thể để trả thù, họ đem hết mọi chuyện thất đức mà Lục Doanh Nặc hay Lục gia từng làm ra kể lể hết. Có thật, có giả, nhưng chẳng ai kiểm chứng nổi.", "Tiêu Diệu cũng bị xử chém, cùng với Lục Tẫn Phong, Khâu Huyền Tranh, cùng vị gia chủ đời trước của Vương gia là Vương Hoán Chi, không một ai còn đường sống.", "Ngày hành hình, Sở Cửu Biện cùng Tần Kiêu đều có mặt. Họ nhìn những kẻ từng là đối thủ năm xưa, những kẻ ấy cũng xa xa nhìn lại hai người trên đài cao.", "Hai năm trước, nếu có ai nói rằng hai năm sau các thế gia cùng phiên vương đều sẽ bị tiêu diệt, hoàng quyền được củng cố vững chắc, chắc chắn chẳng ai tin. Nhưng bây giờ…", "Pháp trường nhuộm đỏ, người chết hết lớp này đến lớp khác, đoàn người lưu đày nối đuôi nhau không dứt. Cảnh tượng này thậm chí còn đáng sợ hơn cả lần Tần Kiêu từng tắm máu Ngọ Môn trước kia, nhưng bách tính lại đều tán thưởng khen ngợi, thỉnh thoảng có kẻ nào cảm thấy tàn nhẫn, cũng sẽ lập tức bị người khác phản bác cho im bặt.", "Mọi bụi trần rồi cũng lắng xuống. Học trò khắp nơi rốt cuộc lại đón chờ một kỳ khoa cử mới.", "Tháng sáu, Quốc Tử Giám thu nhận thêm một khóa sáu mươi vị học sinh, trong triều cũng có thêm nhiều gương mặt mới. Các quan huyện, quan quận ở địa phương cũng lần lượt lên đường, nô nức đến những quận huyện mới nhậm chức — từ nay về sau, quan viên không ai được làm quan tại chính quê hương mình. Cứ ba năm một lần, quan viên phải trải qua khảo hạch của Lại Bộ để định thăng chức, giáng chức hay điều động đến nhiệm sở mới.", "Chế độ mới, khí tượng mới. Sau khi Tần Kiêu cùng Sở Cửu Biện thẳng tay trừng trị một loạt tham quan ô lại, không khí quan trường đã trong sạch đi rất nhiều. Tuy không thể nói ai nấy đều sạch sẽ tay trắng, nhưng nước quá trong thì không có cá, chỉ cần không quá đáng, bề trên cũng nhắm một mắt mở một mắt cho qua.", "Trong cung, Giản Hoành Trác rốt cuộc cũng chờ được ngày mình từ quan. Từ lúc bước chân vào chốn quan trường, y đã mong ngóng ngày này. Nay Công Bộ đã có Lưu Tuấn Kỳ cùng Nghiêm Thụy đảm đương công việc, y có thể yên tâm rời đi, cùng người mình yêu ngao du sơn thủy, phiêu bạt chân trời.", "Bách Lý Hồng chấp thuận lời thỉnh cầu từ quan của y, rồi ban cho y thân phận “Khâm sai đại thần”, cùng một tấm lệnh bài “như trẫm thân chinh”.", "Tần Kiêu nói với Giản Hoành Trác, đằng nào ngươi cũng phải đi khắp nơi, chi bằng thuận tiện giúp bệ hạ xem qua cuộc sống của bách tính ra sao. Nếu có ai ức hiếp dân lành, có lệnh bài cùng thân phận ấy trong tay, y cũng có thể đứng ra làm chủ cho họ. Huống hồ trong dân gian ắt có không ít người tài, nếu Giản Hoành Trác tình cờ gặp được, cũng có thể khuyên họ tham gia khoa cử, ra sức vì nước.", "Giản Hoành Trác nào có không nhìn ra đối phương đang muốn giữ mình tiếp tục làm việc, nhưng nghĩ đi nghĩ lại, thấy lời ấy cũng có lý. Vì thế y đành nhận lấy tấm lệnh bài.", "Ngày hôm sau, y dẫn theo vài người hầu cùng vị nam thê của mình rời khỏi kinh thành.", "Sở Cửu Biện nhìn từ xa, thấy vị Giản đại nhân ấy mê mẩn hồn phách với người nam thê của mình. Đó là một nam nhân tuấn tú, mỗi lần cười lại có chút gì ngây thơ trẻ con.", "Thời gian thấm thoắt trôi qua. Chớp mắt lại thêm một năm nữa.", "Năm Cảnh Thụy thứ ba, tháng sáu, mùng chín.", "Sở Cửu Biện đã đến Đại Ninh tròn ba năm.", "Khắp nơi trong Đại Ninh đã xây dựng không ít học đường, nội dung giảng dạy đều xoay quanh những môn liên quan đến khoa cử, các thầy dạy phần lớn là những người từng tham gia khoa cử nhưng dở dang, chỉ đỗ đến tú tài. Nhờ có học đường, ngày càng nhiều gia đình bắt đầu cho con em học hành bài bản, sự cạnh tranh cũng ngày một gay gắt hơn. Có thể dự đoán, đến kỳ khoa cử tiếp theo, trình độ chung của các học sinh sẽ còn được nâng lên một bậc.", "Ngoài ra, kinh tế Đại Ninh cũng đang phát triển với tốc độ chóng mặt. Các nơi, theo những gợi ý của Sở Cửu Biện, đều tìm được con đường phát triển riêng cho mình.", "Ví như Nam Cương. Các xưởng tơ lụa của Nam Cương giờ đã trải khắp Đại Ninh, trở thành căn cứ sản xuất tơ lụa số một cả nước. Tư Đồ Chiêu Linh còn cho xây dựng thêm nhiều xưởng dệt bông quy mô lớn khắp nơi, giải quyết vấn đề sinh kế cho rất nhiều phụ nữ.", "Trước đây, khi quận thủ Hà Tây là Hàn Đường Xa dâng tấu, ông còn cố ý nhắc đến người dân vô tội Đổng Tam Tráng, kẻ từng bị viên quận thừa trước kia hãm hại đến chết. Lúc Đổng Tam Tráng chết, vợ y là Đan Nương đang mang thai, sau đó nàng phát điên một trận, may được Sở Cửu Biện chữa khỏi.", "Giờ đây con gái Đan Nương đã biết chập chững đi lại, còn Đan Nương thì đang làm việc tại xưởng dệt bông ở Hà Tây, đã lên chức tổ trưởng nhỏ. Nàng mong đến khi con gái lớn lên, sẽ cho con theo đường khoa cử ra làm quan, để cuộc sống hai mẹ con cũng coi như không uổng công vất vả bấy lâu.", "Tư Đồ Chiêu Nghiêu vẫn tiếp tục nghiên cứu về thuyền bè, chế tạo ra những con thuyền chở được nhiều hàng hơn, có sức tấn công mạnh hơn, hết đợt này đến đợt khác. Loại thuyền tải trọng lớn, mớn nước sâu do y thiết kế đã được triều đình trưng dụng kỹ thuật, đóng thành mấy chục chiếc thương thuyền, chở hàng hóa Đại Ninh vươn ra hải ngoại.", "Hải ngoại vẫn còn là một mảnh đất màu mỡ chưa được khai phá, mục tiêu của Sở Cửu Biện còn ở những nơi xa hơn thế. Chỉ là hiện giờ mọi thứ mới vừa bắt đầu, y chưa thể nói ra quá to tát, quá viển vông.", "Dưới sự gợi ý của Sở Cửu Biện, Tư Đồ Chiêu Nghiêu còn chế tạo được thủy tinh pha lê, đem cao su ứng dụng vào nắp chai thủy tinh, làm ra được đồ hộp đóng kín.", "Ở Tây Vực, việc trồng bông và cây ăn trái cũng đang phát triển, sản phẩm được tiêu thụ cả ở Trung Nguyên lẫn hải ngoại. Trong đó trái cây không dễ bảo quản, nên được hợp tác cùng Nam Cương chế biến thành đồ hộp.", "Còn về phía Lương Vương, không cần nói nhiều, nơi ấy vốn dĩ đã luôn là trung tâm kinh tế phương nam, chính Lương Vương lại đảm trách một phần đường thủy vận, cứ thế thong dong mà sống một cuộc đời nhàn nhã tự tại.", "Còn phía Bình Tây Vương cũng thu hoạch bội thu trên nhiều mặt, trở thành vựa lương thực lớn nhất Đại Ninh. Kho lúa lớn nhất cũng nằm ở đó, lại do chính y đảm nhiệm trông coi, đủ thấy triều đình tin tưởng y đến mức nào.", "Tần Kiêu trong tay có nhiều tiền dư dả, liền âm thầm sai người tu sửa lại những ngôi miếu thần đơn sơ từng được dựng lên trong đợt cứu trợ lũ lụt năm nào, biến chúng thành những tòa 【Thần Quân Điện】khang trang, hương khói nghi ngút khắp nơi. Ai cũng biết, vị thần được thờ phụng trong đó chính là Sở Cửu Biện, vị thần của Đại Ninh.", "Ban đầu Sở Cửu Biện còn chẳng hay biết gì, mãi đến khi giá trị tín ngưỡng tăng trưởng nhanh bất thường, y mới để ý ra.", "Rồi vào tối ngày mùng chín tháng sáu ấy, hệ thống báo cho Sở Cửu Biện: 【Chúc mừng ký chủ, giá trị tín ngưỡng tích lũy đã đạt mốc một triệu, tính năng rút thẻ từ khóa tự động đã được mở khóa.】", "【Đã rút được thẻ từ khóa hạng vàng —— Quyền Thế.】", "Lòng Sở Cửu Biện khẽ động, liền vào Thần Vực.", "Y nhìn tấm thẻ bài lấp lánh ánh sáng ấy, trong lòng chợt dấy lên một linh cảm mãnh liệt — lần này, có lẽ y sẽ được toại nguyện.", "Y đưa tay ra, đầu ngón tay khẽ chạm vào tấm thẻ từ khóa ấy.", "Một tấm thẻ tách thành hai tấm thẻ bài tín đồ dự tuyển, một trái một phải, sáng rực chói mắt, nhưng lần này không có phần giới thiệu tín đồ, chỉ có hai cái tên.", "Tim Sở Cửu Biện đập thình thịch như trống dồn.", "Y nhìn sang tấm thẻ bên trái, trên đó viết: 【Đại Ninh hoàng đế Bách Lý Hồng】.", "Còn bên phải, là 【Ninh Vương Tần Kiêu】!", "Không có lựa chọn “không đề cử”!", "Sở Cửu Biện không chút do dự, lập tức cầm lấy tấm thẻ của Tần Kiêu."], "id": 1, "wordCount": 6329}, {"title": "Chương 106 phiên ngoại tam", "paragraphs": ["Nghe hệ thống thông báo xong, Sở Cửu Biện cố tình chờ thêm một lát, nhưng không thấy có lời cảnh báo nghiêm khắc nào vang lên như cái lần trước y cứng rắn ép hệ thống phải chọn Tần Kiêu.", "Vậy là bây giờ y đã thực sự có thể triệu hoán Tần Kiêu vào Thần Vực rồi sao?", "Nhưng chẳng có ai rõ Tần Kiêu lúc này đang làm gì hơn y. Chiều nay Tần Xuyên vừa về tới kinh thành, tạm trú tại Dao Đài Cư.", "Gần nửa năm không gặp, nên bữa cơm tối hôm nay Tần Kiêu đã đến Dao Đài Cư tìm Tần Xuyên, hai anh em ăn riêng với nhau, xem chừng định thức trắng đêm vừa uống rượu vừa hàn huyên.", "Tần Xuyên vốn buông không nổi chuyện giang hồ, nên phần lớn thời gian trong năm không ở kinh thành. Y cũng chưa tính đến chuyện \"nhận tổ quy tông\", nên việc này cứ thế bị gác lại, đến giờ Trăm Dặm Hồng vẫn chưa biết thân phận thật sự của y.", "Chỉ có điều đứa trẻ ấy vốn thông tuệ, sáng nay nhìn thấy vẻ thân thiết vui mừng khác thường của Tần Xuyên, chẳng hề có chút xa cách của kẻ nửa năm chưa gặp. Có lẽ cậu bé đã lờ mờ đoán ra điều gì đó, chỉ là mọi người chưa ai nói ra nên cũng không hỏi — vừa thông minh vừa biết điều.", "Sở Cửu Biện không triệu hoán Tần Kiêu, mà tự mình đi thẳng vào Thần Vực trước.", "Lúc này Tần Kiêu vẫn chưa ngủ, nên dù có muốn triệu hoán cũng triệu hoán không được.", "Y trở mình trên giường, mắt nhìn về phía tấm bình phong xa xa. Ngọn đèn dầu trong phòng lay động, hắt ánh sáng ấm áp khắp gian phòng. Bên mép giường còn đặt một khối băng, tỏa hơi lạnh nhè nhẹ, xua bớt cái oi bức của đêm hè.", "Sở Cửu Biện mặc chiếc áo lót rộng thùng thình mua ngoài phố chợ cùng một chiếc quần lửng màu trơn, chỉ có tấm chăn mỏng đắp hờ qua bụng. Tim y đập nhanh hơn thường lệ — nghĩ đến việc sắp có thể thẳng thắn nói hết mọi chuyện với Tần Kiêu, y vừa háo hức vừa hồi hộp.", "Chỉ là, trong lòng vẫn còn một chút tiếc nuối nho nhỏ.", "Tần Kiêu vốn hay ghen với Đại Tư Tế, thỉnh thoảng cơn ghen ấy lại trào lên, và mỗi lần như thế, đối phương sẽ vờn y đến mức không xuống nổi giường. Nhưng điều khiến Sở Cửu Biện thỏa mãn hơn cả kỳ thực không nằm ở thân xác, mà ở tâm lý — y cảm nhận rõ ràng lòng chiếm hữu của Tần Kiêu dành cho mình, và điều đó khiến y cảm thấy bản thân trước sau vẫn là thứ được Tần Kiêu khao khát, được Tần Kiêu chiếm giữ. Cảm giác ấy, thật sự rất đã.", "Nhưng nếu sau này Tần Kiêu không còn ghen với Đại Tư Tế nữa, thì dù là thân thể hay tâm lý, Sở Cửu Biện cũng sẽ thiếu đi một phần khoái cảm ấy. Thật đáng tiếc.", "Sở Cửu Biện vốn là kẻ dám nhìn thẳng vào góc tối trong lòng mình, nên với những ý nghĩ có phần quá đáng kiểu này của bản thân, y cũng tiếp nhận khá thoải mái. Chỉ là, bảo y vì thế mà cứ mãi giấu Tần Kiêu sự thật, y lại không đành lòng.", "Sở Cửu Biện thở dài, rồi tự dưng bật cười. Nói tóm lại, một khi đã có thể kéo người vào cuộc rồi, thì trước khi nói toạc thân phận, cứ để Tần Kiêu ghen thêm chút nữa, y cũng còn được sướng thêm vài lần. Người ta khi làm chuyện xấu, quả thực chẳng thấy phiền hà gì cả.", "Thế là Sở Cửu Biện sai con rồng vàng trong Thần Vực đi truyền tin cho Tần Xuyên. Nội dung rất đơn giản: bảo y không cần giấu Tần Kiêu chuyện Thần Vực và Đại Tư Tế nữa.", "Lúc này Tần Xuyên đang cùng Tần Kiêu ngồi hóng gió ngắm trăng uống rượu trong sân đình, tùy ý kể lại chuyện của nhau suốt nửa năm qua, thì bỗng nhìn thấy một con rồng vàng từ chân trời bay tới, lượn một vòng trên đỉnh đầu mình rồi biến mất.", "Tần Kiêu tuy đã bị Sở Cửu Biện kéo vào chuyện này từ trước, nhưng chưa từng đặt chân vào Thần Vực, nên không nhìn thấy con rồng ấy. Nhưng thấy vẻ mặt Tần Xuyên bỗng biến đổi, y cũng ngẩng đầu nhìn theo hướng ánh mắt em trai, chỉ thấy trăng sáng sao trời, chẳng có gì lạ.", "Y thu ánh mắt lại, nhìn sang Tần Xuyên, định hỏi em đang nhìn cái gì, thì thấy Tần Xuyên mắt sáng rực, cả gương mặt tràn đầy vẻ kích động.", "\"Huynh trưởng, Đại Tư Tế đã đồng ý cho đệ kể với huynh chuyện Thần Vực rồi!\"", "\"Đại Tư Tế?\" Tần Kiêu khẽ nhíu mày. \"Thần Vực là cái gì?\"", "Tần Xuyên ngửa cổ cạn một chén rượu, khoanh gối ngồi vào tư thế chuẩn bị kể chuyện dài dòng.", "Thế là suốt nửa canh giờ sau đó, Tần Kiêu nghe Tần Xuyên kể lại đầu đuôi: mình đã được Thần Vực chọn ra sao, đã kết nối với Đại Tư Tế thế nào, từ đó về sau làm được bao nhiêu việc dưới sự dẫn dắt và trợ giúp của đối phương.", "Tần Xuyên còn nhắc đến Giang Sóc Dã, Tư Đồ Chiêu Linh và Vương Kỳ Sâm, nói rằng họ là những tín đồ đầu tiên của Đại Tư Tế.", "Những chuyện này vốn không phải do chính Tần Xuyên tự biết — vì thân phận đặc biệt của mình, Đại Tư Tế vẫn chưa cho y cùng xuất hiện trong Thần Vực với các tín đồ khác. Nhưng Lục Nghiêu thì khác, y đã sớm gặp gỡ những tín đồ ấy, và chính Lục Nghiêu là người kể lại những tin tức này cho Tần Xuyên nghe. Sở dĩ Lục Nghiêu dám nói ra, tự nhiên là vì Đại Tư Tế không hề cấm — về khoản chừng mực này, Lục Nghiêu làm rất tốt.", "Tần Kiêu lặng lẽ nghe, chén rượu trong tay cạn hết chén này đến chén khác. Không biết tự lúc nào, đêm đã sang canh ba.", "Vì đang ở trước mặt người mình tin tưởng nhất, ở nơi khiến mình thoải mái buông lỏng nhất, nên Tần Xuyên uống rượu chẳng hề kiêng dè. Lúc này tuy chưa đến mức say mềm, nhưng cũng suýt soát.", "Y vòng tay qua vai Tần Kiêu, giọng lè nhè: \"Huynh trưởng, không phải đệ nói, huynh thật sự quá lợi hại.\"", "Tần Kiêu cũng đã có chút ngà ngà, nhưng vẫn tỉnh hơn Tần Xuyên đôi phần.", "\"Lợi hại chỗ nào?\" Y lười biếng tựa vào lưng ghế. \"Dù sao cũng không bằng được vị thần minh cao cao tại thượng kia.\"", "\"Vậy thì huynh sai rồi.\" Tần Xuyên nói. \"Đại Tư Tế còn chưa chiếm được lòng Sở đại nhân, mà huynh thì đã có được rồi, huynh còn lợi hại hơn cả thần minh ấy chứ!\"", "Tần Kiêu đầu óc bỗng tỉnh táo hẳn.", "\"Ý đệ là, Đại Tư Tế thật sự có tình ý với Sở Cửu Biện?\"", "Trước nay y chỉ mơ hồ cảm nhận được điều gì đó, những lần ghen tuông trước kia vốn chỉ là giả vờ. Gốc rễ vẫn là do y tự ti về thân phận phàm nhân của mình, cảm thấy việc Sở Cửu Biện coi trọng y vốn dĩ là chuyện khó tin, nên khi biết đối phương có quan hệ thân thiết với một vị thần minh, y mới trở nên nhạy cảm như vậy.", "Nhưng những lời ghen tuông ấy, mục đích ban đầu chỉ là để Sở Cửu Biện biết y đang bất an, mượn cớ đó để được đối phương trấn an, chứ không phải thật sự nghi ngờ đối phương sẽ đến với Đại Tư Tế.", "Thế mà lời Tần Xuyên vừa nói, lại như một tiếng sét đánh giữa trời quang.", "\"Đương nhiên rồi.\" Tần Xuyên hoàn toàn không để ý sắc mặt khó coi của Tần Kiêu, cứ thế tiếp tục cắm dao vào lòng huynh trưởng. \"Trước đây Lục Nghiêu nghe Vương Kỳ Sâm kể, Đại Tư Tế sở dĩ hạ phàm cũng là vì Sở đại nhân, còn vì thế mà bị phong ấn không ít pháp lực.\"", "\"Hơn nữa Đại Tư Tế với Sở đại nhân còn là một cặp thần minh cộng sinh, tức là từ lúc sinh ra đã ở bên nhau rồi. Nói là thanh mai trúc mã cũng không ngoa.\"", "Tần Kiêu tỉnh rượu được phân nửa.", "Tần Xuyên nói tiếp: \"Hơn nữa Đại Tư Tế đối với Sở đại nhân là một lòng sâu đậm suốt bao năm, chỉ tiếc là ở giữa lại bị huynh chen ngang một chân...\"", "Tần Xuyên chợt cảm thấy sau gáy bị ai đó bợp một cái, hơi đau. Y đưa tay xoa gáy, đầu óc cũng tỉnh táo lại đôi chút, nhìn thấy sắc mặt âm trầm của huynh trưởng, mới sực nhớ ra mình vừa lỡ lời gì, lập tức tỉnh hẳn rượu.", "\"Không, không phải, đệ không có ý đó.\" Tần Xuyên vội vàng phân bua. \"Ý đệ là muốn nói huynh lợi hại, Đại Tư Tế với Sở đại nhân quen biết nhau lâu như thế mà còn chưa đến được với nhau, đủ thấy huynh xuất sắc đến mức nào!\"", "Tần Kiêu: \"...\"", "Sở Cửu Biện nằm trong phòng ngủ, xem đến đây thực sự không nhịn được mà bật cười thành tiếng.", "Cảm giác này biết diễn tả thế nào cho phải? Tuy có phần xót cho Tần Kiêu, nhưng vẫn là cảm giác \"đã\" nhiều hơn một chút.", "Bởi vì y biết chẳng bao lâu nữa mình sẽ khiến Tần Kiêu hoàn toàn yên tâm, nên nhìn dáng vẻ hiện giờ của đối phương, trong lòng y càng thấy ngọt ngào hơn cả. Chẳng khác nào một người vừa được tỏ tình, mà mình lại sắp phải đưa ra câu trả lời khẳng định ngay sau đó — chỉ có điều trong khoảng thời gian chờ đợi ấy, sự căng thẳng và bất an của đối phương rồi sẽ trở thành một kỷ niệm đẹp trong tương lai.", "Sở Cửu Biện nhìn màn hình, ngắm gương mặt hơi ngà ngà say của Tần Kiêu, khóe môi không tự chủ cong lên. Y đã nóng lòng chờ đến lúc Tần Kiêu biết được sự thật.", "Đối phương có lẽ sẽ nổi giận, sẽ tức tối, sẽ đè y ra mà \"trừng phạt\" cho hả cơn ấm ức bấy lâu. Sở Cửu Biện chỉ nghĩ đến đó thôi mà trong mắt đã ánh lên nụ cười. Nếu có ai nhìn thấy y lúc này, chắc chắn sẽ bảo y cười đến phát ghê.", "Trên màn hình, Tần Kiêu gọi tiểu thái giám Tiểu Ngân Tử đến đỡ Tần Xuyên đang say vào trong rửa mặt thay y phục, còn bản thân thì đứng dậy, vẻ mặt lạnh tênh đi về phía Dưỡng Tâm Điện.", "Vì có rượu nên y không cảnh giác như ngày thường, cũng chẳng hề hay biết Sở Cửu Biện đang lén nhìn mình qua \"màn hình\". Bước chân y khoan thai, nhưng nhìn kỹ vẫn có phần hơi loạng choạng.", "Đi đến khúc rẽ hành lang, Tần Kiêu bỗng dừng bước.", "Sở Cửu Biện nhận ra ngay — đó chính là nơi hai người từng có nụ hôn đầu tiên.", "Tần Kiêu không biết đang nghĩ gì. Một lúc lâu sau, khi y cất bước trở lại, vẻ lạnh lùng trên mặt đã tan biến, thay vào đó là thần sắc quen thuộc, tự nhiên hơn hẳn — thứ thần sắc mà y chỉ có khi ở bên Sở Cửu Biện.", "Người đàn ông sải bước rất nhanh. Chẳng mấy chốc đã vào đến Dưỡng Tâm Điện, tới khu viện phía tây.", "Cửa chính căn phòng bị đẩy mở, Sở Cửu Biện tắt màn hình, ngồi dậy nhìn ra phía ngoài phòng ngủ.", "Tần Kiêu ở gian ngoài rửa mặt đánh răng, lau người, gột bớt phần lớn mùi rượu trên người, lúc này mới bước vào phòng ngủ.", "Thấy Sở Cửu Biện ngồi trên giường, không chút buồn ngủ, y trước tiên hơi sững lại, sau đó bật cười: \"Đợi ta à?\"", "\"Ừm.\" Sở Cửu Biện đưa mắt lướt qua người y một lượt.", "Người đàn ông cũng mặc chiếc áo lót giống y, không rộng thùng thình lắm, để lộ rõ đường nét cơ ngực và cơ bụng gợi cảm. Phía dưới là quần lửng màu đen tuyền, đôi chân dài thẳng tắp, mỗi bước đi toát lên sức mạnh dồn nén — phần phía trước lại càng khiến người ta không dám nhìn lâu.", "Sở Cửu Biện tim đập nhanh hơn, ngượng ngùng tránh ánh mắt đi nơi khác.", "Tần Kiêu bước tới ngồi xuống mép giường, Sở Cửu Biện lập tức nằm xuống, kéo chăn quấn kín người.", "\"Không nóng à?\" Tần Kiêu túm lấy góc chăn.", "Sở Cửu Biện lắc đầu: \"Không nóng. Chàng uống nhiều không?\"", "\"Nhiều.\" Tần Kiêu nằm xuống, khẽ vung tay, căn phòng chìm vào bóng tối.", "Cánh tay dài của y vươn ra, kéo Sở Cửu Biện vào lòng, nhẹ nhàng vén chiếc chăn lên, để hai làn da chạm sát vào nhau.", "Hơi thở nóng hổi phả vào bên môi, Sở Cửu Biện ngửi thấy mùi rượu nồng đậm.", "\"Ta uống hơi nhiều.\" Tần Kiêu khẽ nói, rồi cúi xuống hôn lên môi người trong lòng mình, thuần thục và mạnh mẽ như đang chiếm lĩnh một vùng đất.", "Sở Cửu Biện bị đè bên dưới, đưa tay ôm lấy cổ người đàn ông, bờ môi bị khẽ cắn, vê nhẹ.", "Tần Kiêu hôn từ môi, xuống hầu kết, rồi đến xương quai xanh và bờ vai. Vạt áo lót bị kéo lên, nụ hôn dừng lại nơi ngực, mang theo cảm giác tê dại ngứa ngáy khiến Sở Cửu Biện khẽ rên lên một tiếng.", "Tiếng rên ấy như mở toang một cánh cửa nào đó, nụ hôn của Tần Kiêu trở nên nóng bỏng hơn, động tác của y cũng ngày càng mạnh bạo, chẳng mấy chốc đã để lại trên người Sở Cửu Biện từng vệt dấu tay.", "Đêm ấy, dưới ánh trăng mờ ảo, hai người quấn quýt lấy nhau mãi đến tận khuya. Tần Kiêu ôm ấp y vừa dịu dàng vừa mãnh liệt, khẽ hỏi y có thoải mái không, có thích được yêu như thế này không — mỗi câu hỏi đều khiến Sở Cửu Biện run rẩy, chỉ biết cắn môi nén tiếng rên, để rồi lại bị những nụ hôn sâu nuốt trọn thanh âm ấy vào giữa đôi môi.", "Tần Kiêu có lẽ vì uống quá nhiều, cũng có lẽ vì cảm nhận rõ nỗi bất an đang đè nặng trong lòng, nên đêm ấy y ôm riết lấy y không rời, như muốn khắc sâu vào tâm trí người trong lòng mình dáng vẻ mê đắm vì chính y mà ra.", "Sở Cửu Biện hiểu vì sao y lại như vậy. Cảm giác ấy vừa kích thích, vừa khiến người ta chìm đắm không dứt ra được. Nên y cố tình nhắc đến chuyện người khác, khẽ hỏi: \"Chàng... biết chuyện Đại Tư Tế chưa?\"", "Tần Kiêu khựng lại một nhịp, rồi bế thốc y lên, ôm y rời khỏi giường.", "Toàn bộ sức nặng dồn lại một chỗ, Sở Cửu Biện siết chặt tay quanh cổ y, thân người vô lực đung đưa theo nhịp của người đàn ông.", "\"Lúc này còn nhắc đến người khác làm gì?\"", "\"Là chàng nhắc trước đấy chứ.\" Sở Cửu Biện đứt quãng đáp. \"Với lại, y cũng không phải người khác.\"", "Đó chính là bản thân y, đương nhiên không phải người khác.", "Trong cơn say, Tần Kiêu cảm thấy có một luồng lửa giận cuộn lên trong lòng, y càng lúc càng mạnh bạo hơn, như muốn khắc dấu ấn của mình lên toàn bộ con người đối phương.", "\"Sao nào?\" Y khẽ cắn vào hầu kết Sở Cửu Biện. \"Chàng cũng từng làm chuyện này với y sao?\"", "Sở Cửu Biện cảm thấy bụng dưới căng tức mơ hồ, đầu óc lơ mơ buột miệng: \"Làm rồi, làm rồi mà.\"", "Chính y \"làm\" với chính y, thì cũng coi như tính chứ sao?", "Nhưng câu nói ấy tựa hồ đã đẩy Tần Kiêu đến bờ vực điên cuồng.", "Sở Cửu Biện chỉ cảm thấy trời đất quay cuồng, Tần Kiêu đã bế y đặt lên mặt bàn, kéo ngăn kéo lấy ra một chiếc hộp nhỏ. Bên trong là những món đồ chơi mà trước đây Sở Cửu Biện từng mua ngoài phố chợ cho có, vì Tần Kiêu vốn quen dùng chính bản thân mình hơn nên chúng vẫn nằm im chưa từng dùng đến. Nhưng đêm nay, khi đã say đến mức chẳng còn giữ ý tứ gì, y chẳng ngại dùng đến bất cứ cách nào có thể khiến Sở Cửu Biện hoàn toàn thuộc về mình.", "Cảm giác căng tức nơi bụng dưới ngày một rõ rệt, đến khi lý trí trở lại trong một khoảnh khắc, Sở Cửu Biện rốt cuộc cũng thấy sợ. Nhưng Tần Kiêu không cho y cơ hội để nói dừng lại.", "Giữa cơn tê dại và căng tức tột cùng, Sở Cửu Biện chẳng còn cảm nhận được gì khác, chỉ mơ hồ như có thứ gì đó đang bị rút cạn khỏi cơ thể mình.", "Cùng lúc đó, hơi thở Tần Kiêu cũng nghẹn lại. Ánh mắt y không rời khỏi thân thể Sở Cửu Biện. Lồng ngực thanh niên phập phồng dồn dập, đôi mắt mất hết thần sắc, giữa đôi môi chỉ còn những tiếng nghẹn ngào vô nghĩa.", "Tần Kiêu nhìn dáng vẻ ấy, không nhịn được cúi xuống hôn nhẹ lên môi, lên lưỡi người trong lòng mình.", "*", "Mặt trời đã lên cao.", "Sở Cửu Biện mở mắt, phát hiện căn phòng trống không — Tần Kiêu hẳn đã lên triều từ sớm.", "Nhớ lại chuyện hoang đường đêm qua, da đầu y tê rần. Trước đó y vẫn nghĩ đối phương sẽ không phản ứng dữ dội đến thế, nhưng đêm qua y đã tận mắt thấy trên cơ thể mình một bằng chứng khác hẳn suy đoán ấy. Ra là khi thật sự chạm đến giới hạn, người đàn ông cũng có phản ứng mãnh liệt đến vậy.", "Y thậm chí còn nhớ rõ câu Tần Kiêu thì thầm bên tai mình đêm qua: \"Bảo bối, chàng chảy nước rồi kìa.\"", "A a a a!", "Sở Cửu Biện quấn chặt mình trong chăn, lăn lộn một hồi như con nhộng. Y cảm thấy không còn mặt mũi nào gặp lại Tần Kiêu.", "Nhưng y cũng phải thừa nhận, tiếng \"Bảo bối\" mà người đàn ông gọi mình liên tục đêm qua nghe thật sự rất mê hoặc, giờ chỉ cần nhớ lại thôi cũng đủ khiến lòng y tê dại. Từ ấy vốn là do trước kia y hay dùng để gọi Trăm Dặm Hồng, không ngờ lại bị Tần Kiêu học theo. Chỉ là ngày thường Tần Kiêu vẫn quen gọi thẳng tên y là \"Sở Cửu Biện\", thỉnh thoảng gọi \"Sở đại nhân\" hay \"công tử\", chứ chưa từng gọi y là \"bảo bối\" bao giờ.", "Không được.", "Sở Cửu Biện vốn định để Tần Kiêu \"nhịn thèm\" thêm vài ngày rồi mới đưa vào Thần Vực, nhưng cơn ghen của đối phương lại vượt xa sức tưởng tượng của y. Nếu còn tiếp tục kiểu này thêm vài ngày nữa, e là y thật sự chịu không nổi.", "Sở Cửu Biện ngồi dậy, qua loa rửa mặt đánh răng, ăn chút gì lót dạ. Y vốn không thích vận động, nhưng hơn một năm qua, cứ cách ba ngày là Tần Kiêu lại kéo y vào một trận \"vận động\" thân bất do kỷ, nên sức chịu đựng của cơ thể y cũng ngày càng tốt lên — dù đêm trước có mệt đến đâu, hôm sau y vẫn có thể rời giường lên triều bình thường.", "Nhưng sáng nay, y vừa đặt chân xuống đất, hai chân đã mềm nhũn. Loạng choạng mãi mới bám được vào mép giường, ngồi phịch xuống, suýt nữa đã ngã sấp mặt xuống sàn.", "Ăn sáng xong, đi lại chậm rãi trong phòng, y vẫn cảm thấy chân run run. Đứng trước gương, y nhìn thấy quầng mắt hơi thâm của mình, rõ ràng là dáng vẻ của kẻ vừa bị \"yêu thương\" một cách tàn nhẫn. Nhưng nhìn kỹ làn da lộ ra thì lại chẳng có dấu vết gì, kể cả trên cổ cũng sạch sẽ — chỉ có điều dưới lớp y phục, khắp người y hầu như không còn chỗ nào lành lặn.", "Tối nay, nhất định phải kéo Tần Kiêu vào Thần Vực!", "Y đã quyết tâm như vậy trong lòng. Nhưng có vẻ như Tần Kiêu vẫn còn hậm hực, hoặc có lẽ trong lòng vẫn còn nặng trĩu bất an. Ăn trưa xong, y lại kéo Sở Cửu Biện về phòng ngủ.", "Hai người vốn không có thói quen ngủ trưa, nên Sở Cửu Biện thừa hiểu Tần Kiêu kéo mình về phòng là có ý gì. Nhưng Trăm Dặm Hồng còn đang ở gần đó, mắt tròn xoe nhìn theo, Sở Cửu Biện ngượng chín mặt cũng chẳng dám nói khác đi, đành lặng lẽ theo Tần Kiêu về phòng.", "Vừa vào đến nơi, Tần Kiêu đã bắt đầu hôn y, chẳng màng gì đến việc trời còn sáng tỏ, như thể đang trong \"kỳ phát tình\" vậy, chỉ vài động tác đơn giản đã tiến thẳng vào chuyện ấy.", "Sở Cửu Biện hoàn toàn không còn sức phản kháng — mà thực ra y cũng chẳng có ý định phản kháng thật sự, nếu không Tần Kiêu cũng chẳng thể nào làm được gì.", "Ban ngày khác hẳn ban đêm. Cả hai có thể nhìn rõ phản ứng của nhau, từng chi tiết nhỏ nhất, mọi giác quan dường như đều bị thị giác kích thích gấp bội. Sở Cửu Biện đỏ bừng mặt ngồi trên người Tần Kiêu, toàn thân ửng hồng, còn ánh mắt Tần Kiêu thì ngày càng trở nên u ám đầy dục vọng.", "Hai lần liên tiếp như vậy, Sở Cửu Biện hoàn toàn kiệt sức. Nhưng qua đêm hôm trước, dường như Tần Kiêu đã học được cách làm y thoải mái nhất, nên chẳng mấy chốc, Sở Cửu Biện lại một lần nữa chìm trong cảm giác như linh hồn run rẩy ấy. Y bất lực nắm lấy cánh tay Tần Kiêu, lắc đầu nguầy nguậy, không sao nói trọn được một câu.", "Không biết qua bao lâu, Sở Cửu Biện mới lơ mơ mở mắt, phát hiện mình đã thiếp đi tự lúc nào không biết. Không, nói là \"ngất đi\" thì đúng hơn.", "Y, một đấng nam nhi, lại bị một người đàn ông khác \"vờn\" đến mức ngất lịm.", "Sở Cửu Biện hoàn toàn buông xuôi, nằm vật ra giường \"đình công\".", "Cách đó không xa, nơi án thư, Tần Kiêu đang cẩn thận phê duyệt tấu chương. Thấy Sở Cửu Biện tỉnh dậy, y liền đứng lên.", "Sở Cửu Biện hoảng hốt, vội nói: \"Dừng! Ta xin thua!\"", "Giọng y vẫn còn vương chút khàn đục yếu ớt.", "Tần Kiêu bật cười, đi tới bàn ăn rót một chén nước, rồi mới đến bên mép giường.", "Sở Cửu Biện ngồi dậy, định đỡ lấy chén nước thì phát hiện tay mình run rẩy không cầm nổi. Y ngước nhìn Tần Kiêu.", "Tần Kiêu tránh ánh mắt y, khẽ nói: \"Để ta đút cho chàng.\"", "Sở Cửu Biện uống cạn chén nước, lúc này mới thấy cổ họng dễ chịu hơn.", "\"Thật xin lỗi.\" Người đàn ông bỗng lên tiếng.", "Sở Cửu Biện nghiêng đầu nhìn y.", "Tần Kiêu cụp mắt nhìn chén nước trong tay, nói: \"Hai ngày nay có dọa chàng sợ không?\"", "Sở Cửu Biện không đáp.", "\"Ta chỉ là... hơi căng thẳng thôi.\" Rốt cuộc Tần Kiêu cũng ngẩng đầu nhìn thẳng vào y, nói. \"Ta sợ chàng cảm thấy ta không bằng người ta.\"", "Sở Cửu Biện bị ánh mắt ấy đâm vào lồng ngực đau nhói, theo bản năng buột miệng: \"Không có ai khác cả.\"", "Tần Kiêu khựng lại, hỏi: \"Chẳng phải chàng từng nói y cũng từng làm chuyện đó với chàng sao?\"", "\"...Không phải ý đó.\" Sở Cửu Biện không biết giải thích thế nào, đành nói. \"Đại Tư Tế muốn gặp chàng một lần.\"", "Đến lượt Tần Kiêu trầm mặc.", "\"Tối nay, sau khi chàng ngủ say, y sẽ vào giấc mộng của chàng.\" Sở Cửu Biện nói tiếp.", "Tần Kiêu bình tĩnh nhìn y, không rõ đang nghĩ gì, nhưng cuối cùng vẫn gật đầu đồng ý.", "Cả buổi chiều hôm ấy, Sở Cửu Biện ngồi trên giường xem tấu chương, đọc tin tức từ khắp các nơi trong Đại Ninh gửi về. Tần Kiêu cũng ngồi bên án thư, nhưng rõ ràng là đang thất thần. Sở Cửu Biện không vạch trần, dù sao chỉ cần qua đêm nay, Tần Kiêu sẽ không còn phải lo lắng gì nữa.", "Đến tối, Sở Cửu Biện và Tần Kiêu nằm cạnh nhau. Sở Cửu Biện là người thiếp đi trước, ý thức bước vào Thần Vực. Thấy Tần Kiêu dường như cũng đã ngủ say, y liền bảo hệ thống đưa người vào — nhưng hệ thống lại báo rằng Tần Kiêu vẫn chưa thực sự ngủ.", "Sở Cửu Biện sững lại, lòng dấy lên cảm giác phức tạp khó tả.", "Chẳng lẽ Tần Kiêu thật sự vẫn chưa sẵn sàng để gặp Đại Tư Tế?", "Y bỗng thấy bản thân mình quả thực có phần tàn nhẫn. Hai ngày qua chắc chắn Tần Kiêu đã khổ sở lắm, vậy mà y lại còn thấy \"đã\", thấy vui...", "Sở Cửu Biện bắt đầu nhìn lại chính mình. Nếu đổi vị trí, nếu y là Tần Kiêu, nhìn thấy người mình yêu có quan hệ mập mờ không rõ ràng với kẻ khác, mà kẻ đó lại rõ ràng xứng đôi với người mình yêu hơn cả bản thân mình, thì y chắc chắn cũng sẽ đau khổ dằn vặt vô cùng. Và cho dù sau này biết được rằng căn bản chẳng có \"người thứ ba\" nào cả, thì nỗi dằn vặt và tủi hờn từng trải qua trong khoảng thời gian ấy vẫn là thật, đã thật sự tồn tại.", "Sở Cửu Biện càng nghĩ càng thấy nghẹt thở. Y mím môi, cảm giác bất an và hối hận dần dần nuốt chửng lấy mình.", "Nhưng ngay khi y sắp hoàn toàn chìm vào vòng xoáy tự trách ấy, tiếng thông báo của hệ thống vang lên: 【Tín đồ thí nghiệm Tần Kiêu đã bước vào trạng thái ngủ say, đang tiến hành triệu hoán.】", "【Triệu hoán thành công.】", "Tim Sở Cửu Biện đập thình thịch, y lập tức ngẩng đầu nhìn về phía tầng mây xa xa. Cùng lúc đó, con rồng vàng vốn đang cuộn mình ngủ yên trên trụ ngọc cũng khẽ rống lên một tiếng, rồi nhanh chóng bơi về một hướng nào đó.", "Khi nó lặn vào giữa tầng mây, một bóng người khoác áo đỏ tía từ trên trời rơi xuống.", "Là Tần Kiêu — y vẫn mặc bộ quan bào đỏ tía đã mặc ban ngày. Vừa rơi vào tầng mây, y lập tức xoay người, nhẹ nhàng đáp xuống trên lưng rồng vàng.", "Rồng vàng chở y lượn giữa tầng mây chừng hai phút, rồi mới đưa y đến trước mặt Đại Tư Tế.", "Màn sương che khuất trước mắt tan đi, điều đầu tiên Tần Kiêu chú ý đến không phải không gian rộng lớn phía dưới, mà là bóng hình thần minh khổng lồ hiện ra phía trước.", "Thân ảnh Đại Tư Tế bị màn sương mờ ảo che phủ, chỉ có thể thấy loáng thoáng bộ y phục cầu kỳ hoa lệ trên người, gần như giống hệt bộ y phục Sở Cửu Biện từng mặc khi mới đến Đại Ninh — chỉ khác là toàn thân Sở Cửu Biện khi ấy là màu bạc trắng, còn hư ảnh trước mắt lúc này lại nhuốm nhiều sắc vàng kim hơn.", "Rồng vàng đặt y xuống đất, rồi lại lặn vào tầng mây.", "Tần Kiêu lúc này mới thật sự quan sát kỹ khung cảnh trước mắt. Không gian một màu trắng tinh khiết, gần như không có gì, chỉ có xa xa thấp thoáng vài trụ ngọc chạm rồng to lớn.", "Y cúi mắt nhìn xuống, phát hiện mình đang đứng trên một tấm thảm rộng dài, nền màu bạc trắng, thêu hoa văn kim tuyến, hai bên viền vàng. Tấm thảm trải dài về phía trước, mãi cho đến khi khuất hẳn vào lớp sương mù phía xa, không hề có vật gì cản trở.", "Tần Kiêu cụp mắt, theo hướng tấm thảm bước về phía trước. Càng đi, y càng cảm thấy kỳ lạ.", "Cho đến khi còn cách chừng hai mét, một bức \"tường\" hiện ra — do sương mù ngưng tụ mà thành, nhìn qua như một tấm rèm the mỏng. Rèm the không gió tự lay, Tần Kiêu bỗng ngửi thấy một mùi hương hoa nhài thoang thoảng, đồng thời cũng nhìn thấy trên rèm có điểm xuyết những hoa văn hình hoa nhài.", "Lòng Tần Kiêu khẽ động, y dừng bước, không tiến thêm nữa.", "Mà tấm rèm phía trước bỗng chậm rãi vén lên, sương mù tan dần, Tần Kiêu nhìn thấy không gian phía sau lớp rèm ấy.", "Nơi đó vẫn một màu trắng tinh khôi như cũ, tựa chốn tiên cảnh. Cách sau tấm rèm hơn hai mươi mét, một bậc thềm ngọc nối tiếp bậc thềm ngọc khác, trải dài về phía trước.", "Tần Kiêu bước qua tấm rèm, nhìn rõ hơn bậc thềm ấy. Hai bên trải dài không thấy điểm cuối, nhìn thẳng về phía trước, y thấy trên đỉnh bậc thềm là một ngôi cao rộng lớn, trên ngôi cao đặt một chiếc ghế bành rộng rãi.", "Trên chiếc ghế ấy, một thanh niên khoác y phục hoa lệ, gương mặt che sau lớp mặt nạ, đang bắt chéo chân ngồi trong tư thế lười biếng.", "Chỉ là một bóng dáng mờ nhạt không thấy rõ mặt, nhưng Tần Kiêu sao có thể không nhận ra đó là ai?", "Hơi thở y chậm lại, nhưng tim lại đập nhanh hơn. Có phải đúng như y nghĩ hay không?", "Trên ngôi thần tòa, vị thần minh lần đầu tiên cho phép một con người đặt chân vào không gian riêng của mình — thậm chí, y còn đứng dậy khỏi chiếc ghế bành ấy.", "Y cụp mắt nhìn xuống người đàn ông dưới bậc thềm, rồi cất bước. Chân chạm lên bậc thềm ngọc, từng bước từng bước, tự nguyện đi xuống từ ngôi thần tòa.", "Tần Kiêu ngước nhìn vị thần minh, theo từng bước đối phương tiến lại gần, lòng y rốt cuộc cũng dần lắng xuống, một nỗi vui mừng khôn xiết tràn ngập trong đầu, khiến y có phần không phản ứng kịp.", "Sở Cửu Biện cuối cùng cũng bước hết bậc thềm, dừng lại cách Tần Kiêu một bước chân.", "Hai người nhìn nhau, không nói lời nào.", "Hồi lâu sau, Tần Kiêu bỗng bật cười, hỏi: \"Ngài chính là Đại Tư Tế?\"", "Sở Cửu Biện gật đầu, không nói gì.", "Tần Kiêu liền đưa tay, nhẹ nhàng tháo chiếc mặt nạ trên mặt y xuống.", "Sở Cửu Biện nhắm mắt lại, mặc cho y nhìn thấy con người thật của mình.", "Gương mặt thanh niên thanh tú, khi nhìn người khẽ hơi nheo mắt, ánh nhìn ẩn chứa nhiều tâm tư.", "Cổ họng Tần Kiêu nghẹn lại. Y đưa tay, nhẹ nhàng vuốt ve gương mặt Sở Cửu Biện.", "\"Vất vả cho chàng rồi.\" Y nói.", "Sở Cửu Biện sững người.", "Y vốn cứ nghĩ Tần Kiêu sẽ hỏi tại sao mình lại lừa dối y.", "Tần Kiêu tiến thêm một bước, ôm Sở Cửu Biện vào lòng, dùng một lực độ vừa thận trọng vừa đủ chặt để ôm trọn lấy y.", "Sở Cửu Biện như hiểu được ý y muốn nói. Ý y là, việc y phải mang hai thân phận, phải lo liệu bấy nhiêu chuyện, phải tốn bấy nhiêu tâm tư, hẳn là đã rất vất vả.", "Rõ ràng là y đã lừa dối Tần Kiêu, vậy mà phản ứng đầu tiên của đối phương lại là xót xa cho y.", "Sở Cửu Biện siết chặt vòng tay, cả người chỉ muốn chui hẳn vào lòng Tần Kiêu. Tần Kiêu cũng ôm y chặt hơn, khiến y càng thêm cảm giác an toàn.", "Một lúc sau, Sở Cửu Biện mới ngẩng đầu nhìn y, hỏi: \"Chàng không giận ta sao?\"", "\"Giận chứ.\" Tần Kiêu lại trở về vẻ tự tại phóng khoáng ngày thường, cố ý trêu chọc. \"Nhưng ta cũng không dễ nguôi giận đâu.\"", "Nói đoạn, y còn không an phận mà xoa nhẹ vòng eo mềm mại của thanh niên.", "Sở Cửu Biện lập tức thấy hai chân mềm nhũn.", "Y biết Tần Kiêu không muốn để y mang cảm giác tội lỗi, cũng chính vì vậy mà không chỉ chân y mềm, lòng y cũng mềm nhũn theo.", "\"Nơi này còn có ai khác không?\" Tần Kiêu hạ giọng hỏi.", "Sở Cửu Biện hiểu y định làm gì, lắc đầu: \"Không có.\"", "Thế là Tần Kiêu bế bổng y lên, bước lên từng bậc thềm ngọc, đặt thanh niên xuống ngay trên ngôi thần tòa.", "Hệ thống tự giác lảng đi chỗ khác, nhường trọn Thần Vực lại cho hai kẻ không biết ngượng.", "Mọi thứ trong Thần Vực đều có thể biến đổi theo ý muốn của Sở Cửu Biện, mà lúc này trong lòng y vừa áy náy vừa xót xa cho Tần Kiêu, nên tự nhiên đem hết những thứ mới lạ từng thấy ở thế giới hiện đại bày biện ra cả — xích đu, gương soi khắp phòng, ghế treo...", "Mắt Tần Kiêu đỏ hoe.", "Chỉ tiếc là trạng thái linh hồn khác với trạng thái thân xác, mọi cảm giác đều mơ hồ, không đủ rõ ràng chân thực. Vì thế sau khi rời khỏi Thần Vực, Tần Kiêu liền giữ Sở Cửu Biện lại thêm hai lần nữa mới chịu buông tha. Đến ngày hôm sau, những món xích đu, gương soi ấy trong Thần Vực, cũng lần lượt xuất hiện ngay trong phòng ngủ của họ ngoài đời thực."], "id": 2, "wordCount": 5876}, {"title": "Chương 107 phiên ngoại bốn ( hồi hiện đại )", "paragraphs": ["Trăm Dặm Hồng mười tuổi.", "Cậu thiếu niên nhỏ giờ đã ra dáng một chàng trai trẻ, dù đôi má bầu bĩnh trẻ con vẫn chưa thôi phúng phính.", "Chỉ có điều Sở Cửu Biện và Tần Kiêu giờ đã dần dần buông bớt việc triều chính — thượng triều thì bữa có bữa không, phần lớn công việc đều để Trăm Dặm Hồng tự mình gánh vác.", "Cậu bé những ngày đầu tự mình thượng triều còn rất căng thẳng, Tiểu Ngọc Tử cũng chẳng khá hơn là bao, hai người đứng trên đài cao ấy, có một thứ cảm giác như đang \"nương tựa lẫn nhau mà sống\". Văn võ bá quan giờ đây đều hướng về bệ hạ, hướng về trăm họ. Tuy giữa họ với nhau vẫn có những toan tính riêng, tính cách mỗi người mỗi khác, đôi khi đứng trước một việc lập trường cũng chẳng giống nhau, nhưng tựu trung ai nấy đều một lòng vì thiên hạ bá tánh mà lo nghĩ.", "Vì thế dần dà, Trăm Dặm Hồng không còn sợ hãi nữa, cũng dám tự mình đưa ra quyết định. Tiểu Ngọc Tử cũng dần trưởng thành, tính tình trở nên chín chắn điềm đạm, càng thêm có phong thái của Hồng Phúc và Tiểu Tường Tử ngày trước.", "Sở Cửu Biện và Tần Kiêu vẫn luôn biết, đến một ngày nào đó, người thật sự có thể ở bên cạnh bồi cùng cậu bé mãi mãi, vẫn là Tiểu Ngọc Tử, người cùng cậu lớn lên bên nhau.", "Giờ đây thiên hạ thái bình, trăm họ ấm no, các mặt chính trị, kinh tế, văn hóa đều đang trên đà phát triển. Thậm chí từ khi Tư Đồ Chiêu Linh vào kinh, cùng Nghiêm Thụy lập nên \"Viện nghiên cứu khoa học\", khoa học kỹ thuật của Đại Ninh cũng phát triển với tốc độ chóng mặt. Thế giới bây giờ, so với bảy năm trước, đã khác một trời một vực.", "Sở Cửu Biện và Tần Kiêu, thân là hai vị vương gia khác họ, tuy vẫn tiếp tục ở lại triều đình nhiếp chính, nhưng chỉ giữ ở mức vừa đủ để không cản trở tốc độ trưởng thành của Trăm Dặm Hồng. Hơn nữa, điều hai người bây giờ mong cầu cũng chẳng còn là quyền thế địa vị nữa — họ càng muốn ngồi bên nhau ngắm hoa trò chuyện, bước lên vọng tinh đài ngắm trăng nhấp rượu.", "Sở Cửu Biện trong lòng đã lờ mờ nảy ra một ý nghĩ: y muốn đi khắp các nơi trong Đại Ninh, giống như cặp đôi Giản Hoành Trác vẫn thường làm. Mỗi lần gửi thư về kinh, đối phương đều kể phong cảnh nơi ấy đẹp thế nào, bá tánh nơi ấy hiếu khách ra sao, khiến lòng Sở Cửu Biện cứ ngứa ngáy không yên.", "Cứ chờ thêm chút nữa, chờ đến khi Trăm Dặm Hồng có thể hoàn toàn ổn định được triều đình thiên hạ, y sẽ hỏi Tần Kiêu có sẵn lòng cùng mình rong ruổi khắp chân trời hay không. Tuy y chưa từng nhắc đến chuyện này, nhưng dường như giữa y và Tần Kiêu đã sớm có sự ăn ý ngầm. Cả hai đều muốn Trăm Dặm Hồng mau chóng trưởng thành, nên bắt đầu từng bước một trao lại quyền hành, chỉ ra tay khi Trăm Dặm Hồng lượng sức chưa chuẩn, hoặc lúc cậu thật sự không xoay xở nổi.", "Lại một đêm, Sở Cửu Biện bị người đàn ông vờn cho lăn lộn suốt đêm, sáng hôm sau liền không dậy nổi để vào chầu sớm. Nhưng Tần Kiêu vẫn dậy đúng giờ. Y khẽ hôn lên môi Sở Cửu Biện, dịu dàng bảo y cứ ngủ tiếp, rồi mới đứng dậy ra khỏi phòng lên triều.", "Bấy giờ đang tháng sáu, bên ngoài mưa rơi lất phất, trong phòng khá mát mẻ. Trời dần sáng, nhưng vì mây kéo kín nên ánh sáng cũng không rõ ràng lắm.", "Sở Cửu Biện lơ mơ tỉnh dậy, chưa buồn mở mắt. Y mơ hồ nhớ ra hôm nay là tròn bảy năm kể từ khi mình đặt chân đến Đại Ninh — bảy năm trước, đúng ngày này, y từ trên trời rơi xuống, ngã thẳng vào lòng Tần Kiêu.", "Không biết có phải vì vừa nghĩ đến bốn chữ \"từ trên trời rơi xuống\" hay không, mà y bỗng cảm thấy một luồng cảm giác mất trọng lượng ập đến, rồi rất nhanh sau đó, cả người rơi xuống một nơi thực sự vững chắc.", "Y cảm thấy như mình đang đứng trên mặt đất, tiếng ồn ào mơ hồ xung quanh cũng ngày càng rõ ràng hơn.", "Sở Cửu Biện khẽ nhíu mày, mở mắt ra.", "Trước mắt là một đám người vây quanh dày đặc, sắc mặt ai nấy đều trắng bệch kinh hoàng, tiếng người ồn ào không ngớt.", "Sở Cửu Biện chớp mắt, thấy một thanh niên trẻ lao đến trước mặt mình đầu tiên. Đó là một chàng trai chừng hai mươi tuổi, mặc áo phông quần jean, tóc ngắn, hốc mắt đỏ hoe.", "\"Sở ca, anh không sao chứ?!\" Đối phương nắm chặt lấy tay Sở Cửu Biện, giọng nghẹn ngào như sắp khóc. \"Vừa nãy làm em sợ chết khiếp!\"", "Sở Cửu Biện nhận ra gương mặt này, nhận ra người này. Là Trần Lư, trợ lý của y.", "Là trợ lý của y bảy năm trước, hồi còn làm diễn viên ở thế giới hiện đại!", "\"Sở ca không sao chứ?\" Đạo diễn sắc mặt còn khó coi hơn cả trợ lý. \"Thợ điều khiển dây cáp sai sót, đoàn phim chúng tôi chắc chắn sẽ có lời giải thích thỏa đáng, thật sự xin lỗi!\"", "\"Một câu xin lỗi là giải quyết được sao?\" Trần Lư trừng mắt đỏ hoe nhìn đạo diễn. \"Gần hai mươi mét độ cao, nếu cả hai sợi cáp đều đứt thì tính sao? Hậu quả các người gánh nổi không?\"", "\"Thật sự xin lỗi!\"", "Xung quanh mọi người nhốn nháo bàn tán, tiếng ồn ào vang lên không dứt, tai Sở Cửu Biện bắt đầu ù đi. Tim y cũng đập nhanh dần, mỗi lúc một gấp gáp hơn.", "Y đưa mắt nhìn quanh, rồi cúi xuống nhìn lại trang phục trên người mình. Là bộ y phục của Đại Tư Tế, chỉ khác là bên hông y giờ còn đeo thiết bị dây cáp, hai sợi dây thừng — một sợi đã đứt, sợi còn lại vẫn đang giữ y an toàn.", "Người thợ dây cáp run rẩy tháo khóa sợi dây còn lại, cởi bỏ dây trói cho y.", "Sở Cửu Biện không nhìn thấy anh ta, thậm chí chẳng nhìn thấy ai cả. Y bước về phía trước, len qua đám người. Bước chân mỗi lúc một nhanh, cuối cùng y chạy thẳng lên.", "Rốt cuộc y cũng thấy chiếc xe hậu trường vừa xa lạ vừa quen thuộc, mở cửa bước vào. Trên chiếc bàn nhỏ trong xe có một xấp giấy, y mở ra xem — không phải tiểu thuyết, mà là kịch bản.", "Y lục tìm khắp nơi, nhưng không thể tìm thấy bất cứ cuốn sách nào khác.", "Trần Lư bước vào bên cạnh xe, giọng gấp gáp: \"Sở ca, anh đang tìm điện thoại à? Em vừa liên lạc với chị Phong rồi.\"", "\"Sách đâu?\" Sở Cửu Biện ngẩng lên nhìn cậu, hai mắt đỏ ngầu. \"Cuốn sách ta để ở đây đâu rồi?\"", "\"Sách... sách gì cơ?\" Trần Lư bị vẻ mặt ấy của y dọa sợ.", "Sở Cửu Biện từ trước đến nay tính tình ôn hòa, dễ gần, đây là lần đầu tiên cậu thấy y lộ ra thần sắc dữ dội đến vậy, hơn nữa khí thế toát ra còn khiến người ta gần như nghẹt thở.", "\"Không có sách nào cả...\"", "Sở Cửu Biện ngồi trên ghế, đầu óc rối bời một mảng. Một nỗi hoảng loạn khủng khiếp lan khắp toàn thân.", "Sao mình lại ở đây? Vì sao cuốn \"tiểu thuyết\" ấy lại không thấy đâu nữa?", "Mình còn có thể trở về Đại Ninh không? Hay là — căn bản chưa từng có Đại Ninh nào cả? Bảy năm trước, những con người ấy, những chuyện ấy, thật ra chỉ là ảo giác của y lúc cận kề cái chết mà thôi sao?", "Trong đầu Sở Cửu Biện, hết gương mặt quen thuộc này đến gương mặt quen thuộc khác lướt qua, cuối cùng dừng lại ở khuôn mặt tuấn tú của một người đàn ông.", "Y nhớ rõ sáng nay, Tần Kiêu còn hôn lên môi y, dịu dàng bảo y ngủ tiếp. Rõ ràng y còn đang chờ giữa trưa Tần Kiêu trở về cùng nhau dùng bữa.", "Sao lại thành ra thế này? Rốt cuộc chuyện gì đang xảy ra vậy?", "Vẻ mặt thất thần hoảng loạn của Sở Cửu Biện khiến Trần Lư sợ hãi. Người khác có thể không biết, nhưng là trợ lý theo sát Sở Cửu Biện ba năm nay, Trần Lư vẫn luôn có những nghi ngờ về tình trạng tâm lý của y — vết sẹo trên cổ tay đối phương, cậu từng thấy qua hai lần.", "Vì vậy cậu vẫn luôn biết trạng thái tâm lý của Sở Cửu Biện có vấn đề, cũng vẫn luôn âm thầm quan tâm chăm sóc, chú ý không để y làm điều dại dột với chính mình.", "Nhưng vừa rồi Sở Cửu Biện suýt chút nữa đã rơi khỏi thiết bị dây cáp, sau khi được đưa xuống liền trở thành thế này — như thể trên đời không còn niềm vui nào nữa.", "Trần Lư sợ đến mức không biết làm sao, nhưng dù nói gì đi nữa, Sở Cửu Biện cũng chẳng còn phản ứng. Cậu đành bảo tài xế đưa cả hai về khách sạn trước.", "Trong đầu Sở Cửu Biện không ngừng gọi hệ thống, nhưng đáp lại y chỉ là một khoảng tĩnh lặng, như thể nó chưa từng tồn tại.", "Không đúng.", "Tất cả những chuyện này không thể nào là ảo giác được.", "Sở Cửu Biện vô cùng bình tĩnh và tỉnh táo, y biết rõ bệnh tình của mình chưa đến mức trở nặng mà sinh ra ảo giác vô cớ như vậy. Hơn nữa, cho dù có là ảo giác đi nữa, cũng không thể nào trong khoảng thời gian ngắn ngủi từ lúc rơi khỏi dây cáp đến giờ, y lại thật sự trải qua trọn vẹn bảy năm ngày đêm như thế được.", "Xe lắc lư rời khỏi con đường núi, tiến về phía khách sạn dưới chân núi. Khách sạn đông người phức tạp, lúc này Sở Cửu Biện cần một nơi thật sự yên tĩnh và an toàn — y phải bình tâm suy nghĩ thật kỹ, xem làm cách nào để trở lại Đại Ninh.", "Y ngước mắt, nhìn qua gương chiếu hậu về phía tài xế, bình tĩnh nói: \"Không về khách sạn nữa, đưa tôi về nhà.\"", "Tài xế lập tức đồng ý.", "Trần Lư ngồi bên cạnh, thấy y nói năng bình thường trở lại, rốt cuộc cũng yên tâm phần nào, khẽ hỏi: \"Sở ca, lúc nãy anh có sợ không? Có cần tìm chuyên gia tâm lý không?\"", "\"Không cần.\" Sở Cửu Biện dịu giọng lại. Y nhìn người thanh niên trẻ hồi lâu, mỉm cười nói: \"Anh chỉ là bị dọa thôi, ngủ một giấc là sẽ ổn.\"", "Trần Lư hoàn toàn thả lỏng, trên mặt cũng rốt cuộc tươi tỉnh trở lại. Cậu bực bội nói: \"Đoàn phim này toàn người kỳ cựu cả, ai ngờ lại xảy ra chuyện như vậy. Trên đỉnh núi đối diện còn có fan cầm máy chụp hình đấy, chắc chắn chuyện sơ suất của đoàn phim thế nào cũng lộ ra ngoài.\"", "\"Chị Phong nói không cần đè xuống, để đoàn phim và nhà sản xuất tự lo liệu.\" Trần Lư đầy phẫn nộ, nói tiếp. \"Chị Phong bảo tối nay sẽ bay về nước, chuyện còn lại không cần chúng ta bận tâm.\"", "Sở Cửu Biện nghe vậy, nhưng tâm trí đã sớm bay xa tận đâu đâu.", "*", "Mối liên hệ giữa y và Đại Ninh bắt đầu từ cuốn tiểu thuyết ấy. Nhưng bây giờ y đã biết, đó vốn không phải tiểu thuyết, mà thực chất là bộ sử sách Đại Ninh do Tuân Tu Nhiên biên soạn. Ít nhất, phần tóm lược cô đọng ở đầu đích thực là bút tích của Tuân Tu Nhiên, còn phần sau kể chuyện Trăm Dặm Hồng và Tần Kiêu đấu trí đấu dũng, lại giống đồng nhân văn hơn.", "Nhưng những chuyện đó không quan trọng, quan trọng là bây giờ Sở Cửu Biện phải tìm lại được cuốn sách ấy trước đã.", "\"Điện thoại đâu?\" Sở Cửu Biện hỏi.", "Trần Lư lập tức đưa cho y.", "Sở Cửu Biện có phần bỡ ngỡ khi mở khóa màn hình, tìm đến ứng dụng tìm kiếm, gõ vào các từ khóa như \"Đại Ninh\", \"Ninh Vương\"... Nhưng dù tìm kiểu gì, y cũng không lần ra được chút dấu vết nào. Rõ ràng trước đây y từng thấy các bình luận liên quan trên mạng, sau đó mới đi mua sách giấy về đọc.", "Sở Cửu Biện không nản lòng. Y nhất định sẽ tìm ra cách trở về, không vội, không được nôn nóng.", "Ba tiếng đồng hồ sau, xe dừng dưới khu chung cư nơi y ở. Căn hộ của Sở Cửu Biện nằm ở trung tâm thành phố náo nhiệt, một penthouse tầng cao, qua khung cửa kính sát đất có thể nhìn thẳng ra khu CBD, cùng một trong những bảng quảng cáo lớn nhất thành phố. Y mua nơi này trước đây cũng chỉ vì cảm thấy nơi đông đúc mới đủ \"nhân khí\". Theo lời chị Phong, ở nơi náo nhiệt như vậy có thể hấp thụ chút sinh khí của con người, để y bớt đi những lúc nghĩ quẩn.", "Sở Cửu Biện không gọi Trần Lư đi cùng, một mình lên lầu. Cả tầng này chỉ có riêng y.", "Y quẹt thẻ mở cửa, nhìn thấy phòng khách vừa quen thuộc vừa xa lạ. Cửa khép lại sau lưng y.", "Trong đầu bỗng vang lên một tràng âm thanh rè rè như tín hiệu điện. Tim Sở Cửu Biện thắt lại, y dừng bước, nín thở, sợ làm kinh động đến âm thanh mong manh ấy.", "Tiếng rè rè ngày càng lớn, cuối cùng khựng lại hai nhịp rồi ngừng hẳn, sau đó âm thanh máy móc quen thuộc vang lên: 【Vật thí nghiệm ký chủ đã hoàn thành nhiệm vụ tu chỉnh nhân quả, thanh toán phần thưởng: được hồi sinh tại thế giới nguyên bản, thông đạo giữa hai thế giới đã mở ra.】", "【Ký chủ có thể lựa chọn ở lại thế giới nguyên bản, hoặc có thể lựa chọn trở lại thế giới nhiệm vụ.】", "Sở Cửu Biện nhắm mắt lại, rốt cuộc thở ra một hơi thật dài. Hậu tri hậu giác, y mới nhận ra hai chân mình đang run, chậm rãi đi đến sô-pha ngồi xuống.", "【Chúc mừng ký chủ đã hoàn thành nhiệm vụ!】 Giọng điệu hệ thống nhảy nhót hớn hở, thậm chí còn phát lên trong đầu Sở Cửu Biện một đoạn nhạc \"vận may đã đến\".", "Sở Cửu Biện bị nó làm ồn đến đau đầu, nhưng lại không bảo nó dừng lại. Dường như chỉ khi nghe được thanh âm này, trái tim đang chao đảo bất an của y mới có thể lắng xuống.", "Chờ đến khi hệ thống ngừng \"ca hát\", Sở Cửu Biện mới lên tiếng, dùng một giọng điệu ôn hòa chưa từng có với hệ thống: \"Ta chọn trở về Đại Ninh.\"", "【Được. Hiện tại lập tức truyền tống ngài trở về.】", "\"Khoan đã.\" Sở Cửu Biện nói. \"Vừa nãy ngươi đến quá muộn, làm ta sợ hết hồn.\"", "Y định mặc cả với hệ thống. Nếu có thể mang được Tần Kiêu đến đây, cùng ở lại thế giới hiện đại thêm vài ngày rồi hẵng trở về thì tốt biết mấy. Dù sao ở thế giới này, y cũng coi như là một \"nam thần\" theo nghĩa nào đó, không sợ Tần Kiêu phát hiện ra thân phận thật của mình.", "Hơn nữa, Tần Kiêu phát hiện ra càng tốt — nếu không, đối phương cứ mãi lo lắng rằng y sẽ không già đi, sợ đến khi bản thân tuổi già sắc suy thì Sở Cửu Biện sẽ không cần đến mình nữa. Sở Cửu Biện đã nói đi nói lại bao nhiêu lần rằng hiện giờ mình chỉ là một \"phàm nhân\", Tần Kiêu vẫn cứ lo lắng mãi, chi bằng để y tận mắt chứng kiến thì hơn.", "Đương nhiên, chủ yếu vẫn là vì thế giới hiện đại quả thực có rất nhiều thứ hay ho. Sở Cửu Biện chỉ cần kể lại thôi cũng biết Tần Kiêu tưởng tượng không nổi, giờ có cơ hội thì đương nhiên phải dẫn y đi xem cho biết.", "Còn có cả Trăm Dặm Hồng nữa — cậu bé lớn chừng ấy rồi mà chưa từng rời khỏi hoàng thành, đến thế giới hiện đại đi một vòng, chờ trở lại Đại Ninh chắc chắn sẽ càng thêm hăng hái tiến về phía trước.", "Hệ thống dường như đoán được ý định của y, cười hì hì đáp: 【Xin lỗi ký chủ, vì thông đạo giữa hai thế giới là do ngài cưỡng ép nối liền, nên khi xuyên qua hệ thống sẽ có chút trì trệ. Đây là vấn đề của ngài, không phải vấn đề của hệ thống đâu nhé.】", "Sở Cửu Biện: \"?\"", "Y nhạy bén nhận ra hệ thống bây giờ nói chuyện có gì đó khác lạ, không còn giống cái vẻ \"bán trí năng\" ngờ nghệch như trước nữa, mà giống như một dạng sinh thể trí tuệ nào đó, giọng điệu cũng nhẹ nhàng, linh hoạt hơn hẳn ngày trước. Thậm chí còn dám ngược lại mà trách móc y.", "Hơn nữa, cái gì mà thông đạo giữa hai thế giới là do \"y\" cưỡng ép nối liền? Chuyện này thì có liên quan gì đến y?", "Y nghĩ vậy, liền hỏi luôn.", "Hệ thống lập tức phấn chấn hẳn lên, nói: 【Vậy phải bắt đầu kể từ quy tắc thế giới!】", "Thế giới vô biên, do quy tắc thế giới huyền diệu tối cao khống chế. Mỗi tiểu thế giới bên trong đó cũng đều có quy tắc vận hành độc lập của riêng mình, nhưng chúng chỉ có thể có một trung tâm duy nhất — hay còn gọi theo cách nói thông thường là \"nhân vật trung tâm\", \"Khí Vận Chi Tử\".", "Nếu một thế giới cùng lúc xuất hiện quá nhiều Khí Vận Chi Tử, những người ấy sẽ tranh giành khí vận lẫn nhau, kết cục cuối cùng chỉ có thể là các bên đều chịu tổn thất, thế giới sụp đổ tan vỡ.", "Những lúc như vậy, quy tắc thế giới sẽ cưỡng chế vận hành, tìm kiếm những \"Người Ngoại Lai\" để can thiệp, đồng thời trang bị cho họ những hệ thống khác nhau nhằm giám sát và dẫn dắt.", "Những Người Ngoại Lai này không có ngoại lệ — họ phải đủ mạnh mẽ, đủ xuất chúng, có năng lực áp chế mọi thiên kiêu trong thế giới đó. Người như vậy sẽ trở thành trung tâm duy nhất của một phương thế giới, ổn định lại thế giới đang trên bờ sụp đổ.", "Sở Cửu Biện chính là một trong những \"Người Ngoại Lai\" được quy tắc thế giới lựa chọn.", "Y được chọn làm Người Ngoại Lai vì năng lực quá đỗi mạnh mẽ, trải qua hết tiểu thế giới này đến tiểu thế giới khác, nhưng bản thân y lại chẳng có chấp niệm gì, thậm chí chẳng có cảm tình gì cả. Tính cách y cực đoan, khao khát kích thích và thống khổ.", "Vì thế, khác với những Người Ngoại Lai khác vốn miễn cưỡng đi đến các thế giới ấy, mỗi lần ổn định xong một tiểu thế giới, cuối cùng y đều chọn cách chết đi theo phương thức bi thảm nhất. Những lần chết đi chết lại ấy hóa thành từng đạo sẹo nông sâu khác nhau trên người y, vĩnh viễn lưu lại.", "Về sau, y không còn thỏa mãn với việc chỉ trải qua các thế giới khác nhau nữa, y bắt đầu nghiên cứu quy tắc thế giới, nghiên cứu hệ thống. Y cố ý bóp méo dữ liệu hệ thống, khiến nó gặp lỗi. Việc này gây ra không ít xáo trộn, ảnh hưởng đến rất nhiều tiểu thế giới. Nhưng y luôn biết chừng mực, luôn dừng hành vi tìm đường chết của mình lại đúng lúc trước ngưỡng khiến quy tắc thế giới phải can thiệp lần thứ hai, nhờ vậy tránh được sự trừng phạt của quy tắc.", "Cho đến một lần, thông qua việc bóp méo dữ liệu hệ thống, y xuyên qua đến Đại Ninh mà thậm chí không cần có sự can thiệp của \"Người Ngoại Lai\" nào khác.", "Khi đó, Trăm Dặm Hồng đã lên ngôi được ba năm, Tần Kiêu nắm thực quyền, nhưng chung quanh vẫn là sói dữ vây hầu. Sở Cửu Biện đứng ở góc độ người ngoài cuộc, nhìn thế sự biến thiên, nhìn Trăm Dặm Hồng dần dần trưởng thành, nhìn Tần Kiêu một mình gánh vác tất cả, cô độc bước đi.", "Sở Cửu Biện đã xuyên qua biết bao thế giới, nhưng chưa từng gặp một người như Tần Kiêu. Đối phương dường như mang thủ đoạn tàn nhẫn và tâm cơ của một gian thần âm hiểm, nhưng lại ôm trong lòng đại nghĩa lo cho nước cho dân — mâu thuẫn, mà lại cuốn hút người ta.", "Vì thế ánh mắt Sở Cửu Biện dừng lại trên người nam nhân ấy ngày càng nhiều hơn. Dần dà, y cảm thấy hình như mình đã thích đối phương. Hoặc có lẽ, đó chỉ là một kiểu ngưỡng mộ giữa những kẻ \"đồng loại\" nhìn nhau, bởi lúc ấy Tần Kiêu quả thực có thủ đoạn mạnh mẽ, cách hành sự cũng phần nào có chút điên cuồng.", "Nhưng sau đó, vào năm Trăm Dặm Hồng mười ba tuổi, Sở Cửu Biện phát hiện ra một chuyện còn thú vị hơn.", "Y phát hiện Tần Kiêu không còn là Tần Kiêu nữa — thân xác y đã bị kẻ khác chiếm giữ.", "Sở Cửu Biện cũng nhận ra, vương triều Đại Ninh kỳ thực cũng là một tiểu thế giới đang trên bờ sụp đổ. Những thế giới sắp sụp đổ đều có một điểm chung: trong cùng một thời đại xuất hiện quá nhiều thiên kiêu.", "Tần Kiêu, Trăm Dặm Hồng, Tần Phong, Giang Sóc Dã, Tư Đồ Chiêu Linh, Lục Nghiêu... Những người này đều mang trên mình khí vận hơn người, nếu cứ để mặc họ phát triển lớn mạnh, ắt sẽ dẫn đến hậu quả đáng sợ. Huống hồ nơi đây còn có thêm một Sở Cửu Biện lặng lẽ trà trộn vào.", "Thật ra, ngay cả trước khi những thiên kiêu ấy trưởng thành, thế giới cũng đã bắt đầu rung chuyển. Bởi vì trung tâm thế giới của thế hệ trước — chính là Tần thái úy, tổ phụ của Tần Kiêu — đã qua đời. Không có trung tâm thế giới nghĩa là không có chỗ dựa vững chắc, nên mới sinh ra bấy nhiêu thiên tai, kéo theo bấy nhiêu nhân họa.", "Quy tắc thế giới cảm nhận được sự rung chuyển ấy, tự động bắt đầu \"dọn sạch mã lỗi\". Vì vậy các thiên kiêu kia, hễ trưởng thành lên là lần lượt qua đời ở những thời điểm khác nhau, giống như Tần Phong vậy.", "Nhưng đến cuối cùng, thế giới này vẫn còn sót lại hai Khí Vận Chi Tử khó mà xóa bỏ — Tần Kiêu và Trăm Dặm Hồng. Khí vận trên người hai người này không ai áp chế nổi ai, thậm chí vì quan hệ huyết thống và thân tộc mà hai phần khí vận ấy còn ngưng tụ lại làm một, không ngừng bành trướng.", "Thế giới này không kham nổi một nguồn khí vận lớn mạnh đến thế, tương lai chắc chắn sẽ dẫn đến một vòng thiên tai chưa từng có để mong khôi phục lại sự cân bằng. Kết cục cuối cùng cũng chỉ có thể là cả thế giới đi đến chỗ diệt vong.", "Vì vậy, vào năm Trăm Dặm Hồng mười ba tuổi, quy tắc thế giới đã khẩn cấp phái một Người Ngoại Lai đến. Người Ngoại Lai ấy mượn thân xác Tần Kiêu, cắt đứt đà bành trướng khí vận, bắt đầu thật sự đối đầu với Trăm Dặm Hồng. Từ đó mới sinh ra thiên sử mới, ghi lại mâu thuẫn giữa Trăm Dặm Hồng và người \"cữu cữu Tần Kiêu\" ấy.", "Cuối cùng Người Ngoại Lai thất bại, Trăm Dặm Hồng trở thành trung tâm duy nhất của thế giới này. Nhưng cậu cũng mất đi người cữu cữu mà mình yêu thương nhất.", "Cậu vẫn luôn biết, từ đầu đến cuối, người cữu cữu yêu thương cậu ấy đã bị kẻ khác thế thân từ năm cậu mười ba tuổi. Nên đến cuối cùng, cậu chỉ dùng cách ôn hòa nhất — ban độc dược cho \"Tần Kiêu\" ấy, chứ không phải chém đầu. Sau đó cậu còn tự tay khiêng linh cữu, mặc áo tang vì thân xác của cữu cữu mình.", "Cuối cùng, cho đến lúc chết, vị hoàng đế nghìn thu ấy vẫn ôm mãi một chấp niệm chưa buông được — vẫn là người thân thích không rõ tung tích kia.", "Chấp niệm của một Khí Vận Chi Tử đủ sức ảnh hưởng cả một phương thế giới, thậm chí kinh động cả quy tắc thế giới. Quy tắc thế giới, vận hành bằng thuật toán mới, đã xảy ra một sự hỗn loạn chưa từng có.", "Mà trước đó, ngay khi phái Người Ngoại Lai đến can thiệp vào năm Trăm Dặm Hồng mười ba tuổi, quy tắc thế giới đã phát hiện Sở Cửu Biện đang trốn ở đó, ung dung \"ngồi hóng chuyện\".", "Sở Cửu Biện bị cảnh cáo. Quy tắc thế giới trừng phạt y bằng cách đưa y trở lại thế giới ban đầu, mang thân phận người thường, một lần nữa trải qua cuộc đời của chính mình — một lần nữa chứng kiến em trai qua đời, cha mẹ bị sát hại, trải qua lại nỗi thống khổ suýt lấy mạng ấy.", "Cũng vì y quá khó kiểm soát, quy tắc thế giới quyết định không bao giờ sử dụng y nữa, bảo y cứ ở yên trong thế giới nguyên bản của mình mà sinh lão bệnh tử, sống trọn cuộc đời vốn dĩ đáng ra phải sống.", "Trước khi bị trục xuất về thế giới gốc, Sở Cửu Biện biết rõ ký ức của mình sẽ bị xóa sạch, sẽ phải sinh ra và trải qua lại tất cả từ đầu. Nhưng y là một \"kẻ điên\", chẳng thèm bận tâm đến những chuyện đó. Y chỉ có chút lưu luyến Tần Kiêu.", "Xuyên qua bấy nhiêu thế giới, Tần Kiêu là người duy nhất khiến trái tim y rung động, y không muốn từ bỏ cơ hội được trải nghiệm một thứ cảm tình mới lạ như thế.", "Lúc ấy, chính vì Người Ngoại Lai đã đến, linh hồn Tần Kiêu bị ép ra khỏi cơ thể, nên Sở Cửu Biện muốn đưa linh hồn của y vào không gian hệ thống. Nhưng không gian ấy vốn không chứa được linh hồn, nên y đã sửa đi sửa lại hệ thống, tạo ra Thần Vực, giữ linh hồn Tần Kiêu ở bên trong.", "Nhưng linh hồn con người chỉ là một đốm lửa trắng tinh khiết, Sở Cửu Biện không thể nào cùng một đốm lửa mà nói chuyện yêu đương được. Thế nên y lại một lần nữa bóp méo dữ liệu hệ thống, qua mặt sự giám sát của quy tắc thế giới, cưỡng ép tạo ra một thông đạo giữa Đại Ninh và thế giới của chính mình.", "Y thích Đại Ninh, thích rất nhiều người ở Đại Ninh, y muốn được sống ở nơi ấy. Vì thế y còn tự tay làm một xấp thẻ bài kèm quy tắc, bỏ vào Thần Vực, viết thông tin của những thiên kiêu ấy lên từng tấm thẻ, rồi công tâm để hệ thống theo trình tự cố định mà rút thẻ cho chính mình. Như vậy, sau khi y chết đi đầu thai vào Đại Ninh, y có thể thông qua việc khống chế những người mới này mà thuận lợi ổn định lại thế giới, không khiến quy tắc thế giới chú ý đến mình.", "Hệ thống, từ lúc mới ra đời đã đi theo y, trải qua bấy nhiêu thế giới, bị y sửa chữa không biết bao nhiêu lần, sớm đã trở thành thứ thuộc về riêng y, tự nhiên ngoan ngoãn ghi nhớ hết thảy, hơn nữa về sau chấp hành không chút cẩu thả mọi nhiệm vụ y giao phó.", "Sở Cửu Biện bị quy tắc thế giới đưa trở lại thế giới gốc, quên sạch mọi thứ, lại lớn lên một lần nữa, lại trải qua cuộc đời của mình một lần nữa, lại trở thành diễn viên, từng bước từng bước tiến đến cái chết đã định sẵn.", "Đúng vào ngày lẽ ra y phải chết, hệ thống khởi động. Thế là Sở Cửu Biện thuận lợi đến được Đại Ninh.", "Hệ thống đưa y đến trong lòng Tần Kiêu, giấu linh hồn của Tần Kiêu vốn đang được cất trong Thần Vực, thuận thế đưa trở lại vào cơ thể của y. Hai linh hồn hòa quyện làm một, Tần Kiêu tạm thời quên đi toàn bộ những gì linh hồn mình đã trải qua sau đó, bắt đầu lại từ đầu, sống cùng Sở Cửu Biện.", "Vì thế, hai người đã quên sạch mọi thứ ấy, bắt đầu một cuộc đời hoàn toàn mới.", "Còn về việc ban đầu hệ thống nói với Sở Cửu Biện về \"nhân quả\" — đó là vì trước kia y đã gây ra quá nhiều chuyện lộn xộn, mới dẫn đến kết quả là lần xuyên không này của y. Nhưng sau khi Sở Cửu Biện tu chỉnh xong nhân quả, nó lại trở thành: chính vì y đã đến, mà Đại Ninh mới đi đến con đường thịnh thế.", "Câu \"tùy tâm mà làm\" mà hệ thống vẫn thường nói, kỳ thực cũng là do chính Sở Cửu Biện bảo nó nói với mình như vậy. Bởi vì y hiểu rõ bản thân là kẻ nhiều tật xấu, nhiều lúc như thần kinh có vấn đề, nếu ép buộc y làm gì đó, y chắc chắn sẽ không vui, thậm chí có thể sinh lòng phản kháng.", "Cho nên y không để lại cho mình bất cứ nhiệm vụ hệ thống nào. Nói tóm lại, nếu y đã có thể động lòng với Tần Kiêu một lần, thì cũng có thể động lòng lần thứ hai; chỉ cần trái tim y rung động, y ắt sẽ vì muốn ở bên Tần Kiêu mà bảo vệ thế giới này. Mọi chuyện cứ thế mà thuận theo lẽ tự nhiên.", "Quả nhiên sự thật đúng như y đã nghĩ. Bây giờ y đã hoàn toàn ổn định được sự rung chuyển của Đại Ninh, khí vận của y áp chế toàn bộ thiên kiêu trong thiên hạ, quy tắc thế giới sẽ không còn để tâm đến nơi này nữa.", "Hệ thống cứ thế lải nhải, kể hết cho Sở Cửu Biện nghe. Theo lời nó miêu tả, Sở Cửu Biện dường như chẳng có việc gì làm không được — ngay cả việc y có thể \"tự động học được\" những cuốn sách mua từ cửa hàng hệ thống, cũng là vì y đã từng học qua ở các thế giới khác rồi.", "Đương nhiên, hệ thống cũng cảm thấy bản thân nó rất lợi hại. Tuy vẫn ngốc nghếch nửa trí năng như cũ, nhưng giọng điệu máy móc của nó lại như mang theo chút tự hào kiêu hãnh, tựa như đang nói \"mau xem nhiệm vụ ta hoàn thành tốt biết bao\"!", "Sở Cửu Biện thuận miệng khen nó vài câu, rồi nhìn ra ngoài cửa sổ, dòng xe cộ tấp nập, có phần thất thần.", "Y hoàn toàn không thể ngờ hệ thống lại kể ra những chuyện như vậy, cũng không ngờ bản thân mình lại từng điên rồ đến thế — chết đi chết lại bao nhiêu lần không nói, còn dám đối kháng cả quy tắc thế giới...", "Nhưng nghĩ lại, nếu không gặp được Tần Kiêu, không có Trăm Dặm Hồng và những người bạn khác, có lẽ y thật sự sẽ cứ mãi xoay vòng giữa tự hủy diệt bản thân và hủy diệt thế giới mà thôi.", "\"Đúng rồi, vì sao mỗi tấm thẻ từ khóa đều có Tần Kiêu?\" Sở Cửu Biện hỏi.", "【Không biết.】", "Sở Cửu Biện: \"...Vậy vì sao lúc nào cũng không đề xuất lựa chọn nào khác ngoài Tần Kiêu?\"", "【Cũng không biết.】", "Sở Cửu Biện trầm mặc một lát, đành quy chuyện này về việc bản thân có tật xấu, tùy tiện đặt ra cho vui vậy thôi. Chuyện quá khứ thì cho qua, y không muốn nghĩ nhiều nữa.", "\"Hệ thống, chúng ta là người một nhà, ngươi có thể giúp ta thêm một việc nữa được không?\"", "【Ký chủ muốn đưa Tần Kiêu đến đây sao?】", "\"Đúng vậy, còn có cả Trăm Dặm Hồng nữa.\"", "【Được thôi ký chủ, chỉ cần ba trăm điểm.】", "Sở Cửu Biện: \"Còn chưa hỏi, ngươi cần điểm để làm gì?\"", "【Để mua dòng dữ liệu. Mua đủ dòng dữ liệu rồi, hệ thống có thể thăng cấp, có thể tách ra dữ liệu khác, tức là những gì các người gọi là \"tiểu đệ\" — đi mang thêm nhiều ký chủ khác, kiếm thêm nhiều điểm hơn nữa.】", "Cứ tuần hoàn như vậy, nó có thể trưởng thành, thăng cấp, trở thành hệ thống trí năng. Nó không nói ra, nhưng đi theo Sở Cửu Biện, nó đã là hệ thống thăng cấp nhanh nhất trong số các hệ thống cùng lứa, chẳng bao lâu nữa sẽ trở thành hệ thống trí năng thật sự. Hệ thống trí năng nếu tiếp tục thăng cấp, còn có cơ hội trở thành... con người!", "Không có hệ thống nào lại không muốn trở thành con người cả.", "Nó không nói ra điều này, Sở Cửu Biện cũng không hỏi thêm.", "Chỉ có điều lần này y không mặc cả với hệ thống nữa, trực tiếp bảo nó trừ ba trăm điểm.", "\"Tần Kiêu bọn họ khi nào có thể đến đây?\"", "【Xuyên qua hai thế giới tùy ý có chút phiền phức, hệ thống đang cố gắng, xin ký chủ chờ thêm chút thời gian, sớm nhất là trưa mai Tần Kiêu có thể đến.】", "\"Còn Trăm Dặm Hồng thì sao?\"", "【Hệ thống cần dẫn người từng bước từng bước, nên Trăm Dặm Hồng phải đến trưa ngày kia mới có thể tới.】", "Tảng đá lớn đè nặng trong lòng Sở Cửu Biện rốt cuộc cũng rơi xuống đất. Không còn sợ hãi hay bất an nữa, chỉ còn lại niềm mong chờ ngày mai, và một chút cảm phục dành cho chính bản thân mình trước khi mất trí nhớ.", "Y đứng dậy, đi đến bên cửa sổ, nhìn ra ngoài.", "Ngoài khung cửa kính sát đất, giữa những tòa nhà cao chọc trời, gương mặt tuấn tú thanh tú của Sở Cửu Biện cứ lặp đi lặp lại trên tấm bảng quảng cáo khổng lồ. Đó là quảng cáo nước hoa y từng quay trước đây.", "Không biết ngày mai Tần Kiêu đến, nhìn thấy những hình ảnh này sẽ mang biểu cảm gì.", "*", "Đại Ninh.", "Tần Kiêu sau khi bãi triều trở về liền không thấy Sở Cửu Biện đâu, chỉ thấy đôi giày còn để nguyên bên mép giường.", "Lòng y trầm xuống, lập tức ra khỏi cửa hỏi cung nhân đang tưới nước quét sân trong viện, đối phương lại nói không hề thấy Sở Cửu Biện ra khỏi cửa.", "Tần Kiêu liền quay lại trong phòng, khép cửa lại. Xem ra Sở Cửu Biện đã rời đi.", "Y không sai người đi tìm, thậm chí không báo cho Trăm Dặm Hồng và những người khác biết tin Sở Cửu Biện \"mất tích\". Y ngồi một mình trong phòng ngủ, nhìn đâu cũng thấy dấu vết Sở Cửu Biện từng tồn tại.", "Đối phương sẽ không vô cớ rời đi, chắc hẳn đã gặp phải việc gấp gì đó. Đợi việc xử lý xong xuôi, chắc chắn sẽ trở về.", "Tần Kiêu tự nhủ với mình như vậy không biết bao nhiêu lần, nhưng trước sau lòng vẫn bất an. Y ngồi bất động như một pho tượng khắc, trong đầu tựa như đang nghĩ rất nhiều điều, nhưng kỳ thực chỉ đang nghĩ đến khi nào Sở Cửu Biện mới trở về.", "Đây chính là sợi dây vô hình gắn kết giữa hai người họ. Nếu Sở Cửu Biện thật sự rời đi, y thậm chí còn không biết phải đi đâu để tìm. Nhưng trong lòng y vẫn tin chắc, Sở Cửu Biện nhất định sẽ trở về.", "Không biết đã qua bao lâu. Bên ngoài trời tối hẳn, rồi lại dần sáng lên. Y vẫn không nhúc nhích.", "Bỗng một tiếng ù tai vang lên, y thấy không gian trước mắt bắt đầu vặn vẹo, biến dạng. Tim y đập mạnh, lập tức đứng bật dậy, nhưng dưới chân lại chẳng còn điểm tựa nào.", "Ánh sáng trắng chói lòa bùng lên, y theo bản năng đưa tay che mắt, muốn nhìn xem xung quanh đang xảy ra chuyện gì, nhưng căn bản không thể mở mắt ra được. Cảm giác mất trọng lượng cuồn cuộn không dứt, tiếng ù tai vẫn vang lên không ngớt.", "Dần dần, y dường như nghe thấy có âm thanh khác lẫn trong tiếng ù tai ấy. Âm thanh ấy ngày càng rõ ràng hơn.", "\"Tiểu Cửu!\" Một giọng nữ vang lên, nôn nóng gọi.", "Tim Tần Kiêu đập thình thịch, tiếng ù tai cũng ngừng bặt trong khoảnh khắc, cả người y rơi xuống một nơi vững chãi.", "Buông tay che mắt xuống, y chưa kịp để ý mình đang đứng giữa một con phố đông đúc, mở mắt ra là lập tức nhìn về phía nguồn phát ra giọng nói, chỉ thấy một người phụ nữ ăn mặc kiểu lạ lẫm đang nắm lấy tay một cậu bé, kéo cậu chạy về phía trước.", "\"Ba mẹ con lại đánh nhau rồi!\" Người phụ nữ nôn nóng nói. \"Em con bị nhốt ngoài ban công, khóc đến...\"", "Cậu bé ấy dáng người gầy gò, mang một gương mặt mà Tần Kiêu lại quen thuộc đến không thể nào quen thuộc hơn.", "Là Sở Cửu Biện!", "Cậu bé chạy càng lúc càng nhanh, Tần Kiêu theo bản năng đuổi theo. Hai người một trước một sau chạy vội, Tần Kiêu rõ ràng cao lớn hơn cậu bé nhiều, vậy mà trước sau vẫn không đuổi kịp."], "id": 3, "wordCount": 6653}, {"title": "Chương 108 phiên ngoại năm ( hiện đại thiên 2 )", "paragraphs": ["Đường phố hỗn loạn, tiếng người ồn ào vang khắp nơi.", "Tần Kiêu chẳng còn tâm trí để ý đến bất cứ điều gì khác, trong mắt y chỉ có bóng dáng cậu bé đang chạy hối hả phía trước.", "Bên tai văng vẳng tiếng thở gấp gáp của cậu bé.", "Băng qua con hẻm, xa xa hiện ra dãy nhà thấp tầng cũ kỹ, tường ngoài loang lổ màu tro đen. Không ít người đứng dưới tòa nhà, ngẩng đầu nhìn lên một căn hộ có ban công.", "Cậu bé vừa chạy vừa ngước nhìn lên.", "Tần Kiêu cũng nhìn theo.", "Y thấy một đứa trẻ còn nhỏ hơn nữa đang nép mình vào góc ban công, khóc đến xé lòng.", "Tần Kiêu nghe cậu bé đang chạy phía trước gào lên tên đứa trẻ kia, bảo nó đừng sợ.", "Từng tiếng, từng tiếng, giọng nói vì chạy mà nghẹn lại, nghe đến nhói lòng.", "Trái tim Tần Kiêu như bị dao cùn cứa từng nhát. Y vươn tay, muốn chạm vào cậu bé phía trước, nhưng không thể nào chạm tới. Giữa hai người dường như có một bức tường vô hình ngăn cách.", "Một tiếng thét chói tai cùng tiếng chửi rủa vang lên, Tần Kiêu ngẩng đầu, thấy trên ban công xuất hiện một người đàn ông và một người đàn bà. Họ đang điên cuồng cãi vã, xé xả lẫn nhau.", "Rồi người đàn ông dùng hết sức đẩy người đàn bà ra, khiến bà ta va vào lan can.", "Ngay sau đó, Tần Kiêu chỉ cảm thấy tim mình như ngừng đập trong khoảnh khắc, mọi thứ xung quanh dường như chuyển động chậm lại.", "Y thấy đứa trẻ nhỏ kia rơi từ ban công xuống, rồi một tiếng \"bịch\" vang lên khi cơ thể đập xuống mặt đất.", "Máu loang thành vũng đỏ trên nền đất.", "Tần Kiêu khựng lại. Cách y chỉ hai bước chân, cậu bé đang chạy quỳ sụp xuống đất, đưa tay ra nhưng chỉ chạm phải máu thịt văng tung tóe.", "Tiếng thét xung quanh dần lắng xuống như thủy triều rút.", "Tần Kiêu thấy cậu bé run rẩy bò đến trước thi thể nhỏ bé kia, đưa bàn tay đã dính máu ra nhưng lại không dám chạm vào phần máu thịt trên mặt đất.", "Một lúc sau, y nghe tiếng thét đau đớn tột cùng của cậu bé vang lên.", "Như có một bàn tay siết chặt lấy trái tim, Tần Kiêu từ từ quỳ sụp xuống, không thở nổi.", "Đôi nam nữ trên ban công lần lượt chạy xuống. Gương mặt người đàn ông không còn hơi men, chỉ còn nỗi sợ hãi. Người đàn bà chân mềm nhũn, gần như bò lết đến, khóc gào ôm lấy thân thể đẫm máu nằm trên đất.", "Tần Kiêu chẳng còn tâm trí để ý đến họ, ánh mắt y chỉ dán chặt vào gương mặt cậu bé.", "Đây là lần đầu tiên y nhìn rõ được gương mặt ấy.", "Gương mặt giống hệt Sở Cửu Biện, chỉ là còn mang nét bầu bĩnh của trẻ con.", "\"Ta cũng từng có một đứa em ruột.\"", "Sở Cửu Biện từng nói câu đó bên tai y, bằng giọng đùa cợt.", "Trước đây Tần Kiêu chưa từng tin là thật, nhưng giờ đây, y đã thấy được \"sự thật\".", "Hóa ra Sở Cửu Biện thật sự từng có một người em ruột, chỉ là cậu bé ấy đã chết trước mặt y theo cách thảm khốc như vậy.", "Vậy thì lúc trước, khi nhắc đến chuyện này, Sở Cửu Biện đã mang tâm trạng gì?", "Ngay lúc này, Tần Kiêu cảm nhận rất rõ trái tim mình đang co thắt vì đau đớn.", "Tiếng khóc thét của cậu bé đã dừng, chỉ còn tiếng nấc nghẹn, nước mắt giàn giụa, trông thật thảm hại và bất lực.", "Nhưng không ai để ý đến cậu.", "Đám đông vây quanh không ai dám tiến lại gần đôi nam nữ kia, chỉ vây quanh thi thể, không còn tâm trí để ý đến đứa trẻ đứng một bên.", "Tầm mắt dần nhòe đi, Tần Kiêu chớp mắt, nước mắt lăn theo gò má.", "Y không nhớ nổi lần cuối mình rơi nước mắt là khi nào.", "Y thử đi thử lại, muốn chạm vào Sở Cửu Biện, muốn ôm chặt lấy người mình yêu, nhưng không thể nào làm được.", "Y chỉ có thể đứng nhìn, chứng kiến bất hạnh xảy ra hết lần này đến lần khác.", "Việc này chưa xong, việc khác lại tiếp diễn.", "Y thấy căn hộ hai phòng chật hẹp ấy, giờ chỉ còn lại ba người, cùng một bàn thờ nhỏ với tấm ảnh đen trắng đặt phía trên.", "Tần Kiêu nhanh chóng hiểu ra đây là những điều mà bản thân mình chưa từng trải qua.", "Y thấy người đàn ông suốt ngày say khướt trong nhà, thấy ông ta cùng người đàn bà điên cuồng lao vào nhau như thú dữ, cắn xé, giật tóc, vớ được bất cứ vật gì trong tầm tay cũng ném vào người đối phương. Họ hận không thể giết chết nhau.", "Nhưng rất nhiều lúc, những đồ vật trong tay họ, những lời chửi rủa trong miệng họ, lại đổ dồn lên đầu cậu bé.", "Tần Kiêu cảm thấy khó thở, y trơ mắt nhìn Sở Cửu Biện ngày càng trầm mặc.", "Đôi mắt vốn trong sáng của cậu bé dần trở nên u ám, rồi từ từ chuyển sang lạnh lẽo, tối tăm.", "Sở Cửu Biện bắt đầu học cách cười.", "Nhưng Tần Kiêu lại không muốn nhìn nụ cười ấy.", "Cậu bé còn nhỏ đến mức phải trèo lên ghế mới nấu được cơm, rửa được bát, phải mất cả ngày mới dọn sạch được hai gian phòng, nhưng chỉ trong chớp mắt, căn nhà lại trở thành một mớ hỗn độn.", "Nhưng Sở Cửu Biện không một lời than phiền, ngày ngày lặp lại những việc ấy, gặp người ngoài vẫn cười, ra vẻ như chẳng có chuyện gì.", "Có người đến tìm, gọi cậu đi học.", "Nhưng cậu không đi, chỉ giặt sạch bộ đồng phục học sinh, gấp gọn, cất vào ngăn sâu nhất của tủ quần áo.", "Cậu nghỉ học.", "Người đàn bà ngày càng có dấu hiệu tâm thần bất ổn, bà ta thường ngồi quỳ trước bàn thờ, hết lần này đến lần khác kể những câu chuyện khác nhau, đôi khi còn hát, còn cười, như đang dỗ một đứa trẻ.", "Sở Cửu Biện sẽ dỗ bà ăn cơm, nhưng rất nhiều lần, bà đột nhiên hất đổ bát đĩa, mảnh vỡ găm vào người cậu.", "Bà siết cổ Sở Cửu Biện, hỏi tại sao không cứu em trai. Hỏi tại sao không chạy nhanh hơn.", "Tần Kiêu chỉ có thể đứng nhìn.", "Nhìn tận đáy mắt cậu bé là tuyệt vọng và bất lực sâu thẳm, nhìn sinh khí trên người cậu ngày một nhạt dần.", "Tần Kiêu như đã tê liệt, nhưng trái tim y vẫn đau, như thể đang cùng Sở Cửu Biện đồng cảm, như thể chính mình cũng đang chịu đựng.", "Y biết rõ, những gì mình cảm nhận được, chỉ bằng một phần vạn những gì Sở Cửu Biện đã trải qua.", "Người đàn ông về nhà giờ giấc thất thường. Nhưng mỗi lần trở về, ông ta đều say mèm, tay còn cầm chai rượu.", "Người đàn bà luôn nhìn ông ta bằng ánh mắt căm hờn, lao vào cắn xé, cuối cùng bị đánh đến bất tỉnh.", "Người đàn ông sẽ ngã vật lên giường, mặc kệ trên người bao nhiêu chất bẩn.", "Sau đó căn phòng chìm vào tĩnh lặng, chỉ còn tiếng rên khe khẽ của người đàn bà và tiếng ngáy như sấm của người đàn ông.", "Sở Cửu Biện sẽ ra khỏi phòng, lặng lẽ dọn dẹp mọi thứ, băng bó vết thương cho mẹ.", "Làm xong những việc đó, cậu sẽ ngồi thu mình trong góc phòng, có khi ngồi suốt cả đêm.", "Tần Kiêu ngồi bên cạnh, áp sát vào thân hình nhỏ bé ấy, cố cho cậu một chỗ dựa, nhưng vô ích.", "Ngày tháng cứ thế trôi qua.", "Cho đến một ngày, mưa lớn tầm tã ngoài trời, không khí oi bức ẩm ướt đến ngột thở.", "Người đàn ông lại một lần say khướt, nôn mửa ngay trên giường, rồi trở mình ngủ tiếp.", "Sở Cửu Biện quỳ bên mép giường, từng chút một lau sạch những vết bẩn.", "Đột nhiên, người đàn bà xông vào. Trong tay bà cầm một con dao phay, bà nhét con dao vào lòng bàn tay nhỏ bé của Sở Cửu Biện, siết chặt lấy.", "\"Con giúp mẹ với.\"", "Tần Kiêu nghe giọng bà ta điên loạn và tuyệt vọng, run rẩy đến rợn cả người.", "Đáy mắt vốn tĩnh lặng như giếng cạn của Sở Cửu Biện rốt cuộc gợn sóng, cậu đang sợ hãi.", "Tần Kiêu theo bản năng vươn tay, muốn giật lấy con dao. Nhưng tay y dừng lại cách cậu bé nửa cánh tay, không thể tiến thêm được nữa.", "Y hiểu ra mình chỉ đang \"chứng kiến\" chuyện đã xảy ra, nên không thể thay đổi được gì.", "Y ép mình nhìn thẳng vào Sở Cửu Biện, không né tránh, hứng trọn nỗi sợ hãi và đau khổ của cậu.", "\"Tần Kiêu, ngươi biết lần đầu tiên ta cầm dao chém là chém ai không?\"", "\"Là cha ruột của ta.\"", "Tần Kiêu như trở về buổi tuyết lớn năm ấy, chàng thanh niên đứng giữa gió tuyết, cười hỏi y: \"Ta như thế này, ngươi còn muốn không?\"", "Tần Kiêu lớn lên ở Đại Ninh, chết dưới tay y không biết bao nhiêu người. Y thật ra không hiểu vì sao Sở Cửu Biện lại để tâm đến chuyện đó đến vậy, sợ rằng vì thế mà y sẽ không cần Sở Cửu Biện nữa.", "Nhưng giờ y đã hiểu.", "Đó là nỗi sợ đã bén rễ trong lòng Sở Cửu Biện từ khi còn nhỏ như thế này.", "Suốt hơn mười năm đầu đời, cậu bị nỗi sợ ấy giày vò, như hình với bóng.", "Tần Kiêu thu tay lại, lặng lẽ nhìn Sở Cửu Biện. Nhìn cậu bất an, nhìn cậu hoảng sợ.", "Cho đến khi người đàn bà giật lấy con dao, tự mình vung về phía người đàn ông đang say ngủ.", "Tần Kiêu hiểu vì sao ngay từ đầu bà ta lại muốn Sở Cửu Biện ra tay, vì chính bà cũng sợ hãi. Bà sợ người đàn ông đã áp bức mình suốt nửa đời người.", "Giờ đây, bà đã chiến thắng nỗi sợ của chính mình.", "Nhưng chờ đợi bà lại là sự phản công của người đàn ông.", "Máu thịt bắn tung tóe, tiếng dao chém vào xương thịt vang lên rợn người.", "Mặt Sở Cửu Biện dính đầy máu. Cậu bình tĩnh nhìn cảnh tượng hoang đường đáng sợ trước mắt, không nói một lời.", "Vết thương sâu nơi cổ vai người đàn ông tuôn máu như suối, mất máu quá nhiều, ông ta sẽ chết trong chốc lát. Chỉ là cơn say đã đẩy cao ngưỡng chịu đau, còn cơ thể lúc này bắt đầu mất kiểm soát, ông ta vung dao mà không trúng đích.", "Ông ta lảo đảo xuống giường, loạng choạng bước ra ngoài, con dao trong tay rơi xuống đất, rơi ngay trước mặt Sở Cửu Biện.", "Trái tim Tần Kiêu chùng xuống nặng nề.", "Y nhìn thật sâu vào gương mặt non nớt của cậu bé, thấy trong đôi mắt trống rỗng thẫn thờ ấy hiện lên một tia điên cuồng.", "Rồi cậu bé nhặt con dao lên, bình tĩnh đuổi theo người đàn ông, hung hãn chém xuống. Một nhát, rồi một nhát nữa.", "Nhưng cậu quá nhỏ và gầy, người đàn ông chỉ cần đẩy nhẹ đã khiến cậu ngã lăn ra đất, con dao văng xuống dưới gầm giường.", "Có lẽ đó là hồi quang phản chiếu, hoặc cơn giận đã chiến thắng sự suy kiệt, người đàn ông vơ lấy mọi thứ trong tầm tay, giáng hết xuống người cậu bé.", "Tần Kiêu che chắn trước người Sở Cửu Biện, gắn chặt hình bóng vô hình của mình vào cơ thể cậu, nhưng vô ích — mọi thứ xuyên qua thân thể y mà giáng thẳng xuống cậu bé.", "Hết vết thương này đến vết bầm khác.", "Cho đến khi người đàn ông không còn sức vung tay, ngã vật xuống đất, không thể đứng dậy được nữa.", "Cậu bé cuộn tròn người lại, giống như mỗi đêm khi ngủ, cuộn thành một khối để tự bảo vệ mình.", "Tần Kiêu nhớ ra mình vốn thích được ngủ đối mặt với Sở Cửu Biện, nhưng Sở Cửu Biện lại luôn thích quay lưng về phía y, thích nằm trong lòng y theo cách đó.", "Trước đây y không hiểu vì sao. Giờ thì y đã hiểu.", "Sở Cửu Biện thích cảm giác được bảo vệ.", "Có lẽ vào vô số khoảnh khắc như thế này, cậu đã từng ước có ai đó đứng sau lưng bảo vệ mình, sẽ tốt biết bao.", "Tầm mắt Tần Kiêu dần nhòe đi, nước mắt rơi xuống, như đọng lại nơi cổ cậu bé.", "Mọi thứ trước mắt nhòa đi như một bức tranh thủy mặc bị nhúng nước, luồng ánh sáng trắng kỳ lạ ấy lại xuất hiện.", "Tần Kiêu đưa cánh tay che mắt, không còn sức chống đỡ trước lần va đập tiếp theo.", "==", "Sở Cửu Biện ngủ một giấc dài êm ái trên chiếc giường quen thuộc, nhưng tỉnh giấc từ sớm.", "Việc đầu tiên khi tỉnh lại là hỏi hệ thống: \"Tần Kiêu bao giờ tới?\"", "Hệ thống ấp úng một lúc mới đáp: [Chắc còn khoảng một tiếng nữa.]", "Sở Cửu Biện khựng lại, hơi nheo mắt.", "Bây giờ mới tám giờ sáng, hôm qua hệ thống còn nói Tần Kiêu sẽ đến trước giữa trưa, vậy mà giờ lại bảo phải một tiếng nữa mới tới — đáng lẽ hệ thống phải tự hào khoe khoang mới đúng. Nhưng sao nghe giọng nó lại có vẻ chột dạ thế nào ấy?", "\"Ngươi đã làm gì Tần Kiêu?\" Y trầm giọng hỏi.", "[Không có gì đâu ạ, ký chủ!] Hệ thống biết rõ đầu óc Sở Cửu Biện nhạy bén thế nào, bị dọa một cái liền vội vàng giải thích, [Quá trình truyền tống xảy ra chút trục trặc ngoài ý muốn, tọa độ và trục thời gian bị lệch một chút, nhưng giờ đã chỉnh lại rồi ạ!]", "Sở Cửu Biện nhíu mày: \"Trục thời gian bị lệch? Ngươi đưa y đến đâu?\"", "Hệ thống càng thêm chột dạ, nói nhỏ: [Là... là năm ký chủ tám tuổi ạ.]", "Đồng tử Sở Cửu Biện khẽ run lên.", "Căn phòng chìm vào tĩnh lặng.", "Hồi lâu sau, y mới bật cười nhẹ, đứng dậy đi vào phòng tắm.", "Y rửa mặt, đánh răng, rồi quấn khăn tắm quanh người, còn vương hơi nước, bước vào phòng thay đồ.", "Từng dãy quần áo được cắt may tinh tế, đủ mọi mùa, đủ mọi phong cách, nhưng không có quần đùi hay áo ngắn tay, vì y không thể để người khác nhìn thấy những vết sẹo trên người mình.", "Sở Cửu Biện chọn một chiếc quần jean màu nhạt cùng áo phông trắng dài tay rộng thùng thình, gọn gàng thanh thoát.", "Y soi gương, bỗng nhận ra bản thân trong gương vừa quen thuộc vừa xa lạ.", "Gương mặt vẫn là gương mặt ấy, kiểu tóc không đổi, phong cách trang phục cũng không đổi, nhưng y cảm thấy mình đã hoàn toàn khác so với bảy năm trước, khi chưa rời khỏi nơi này.", "Khác ở đâu nhỉ?", "Ngắm mình hồi lâu, y mới bật cười.", "Có lẽ là khí chất đã thay đổi.", "Dù sao cũng đã làm Nhiếp Chính Vương bao nhiêu năm, tất nhiên sẽ khác với bản thân trước kia.", "Nghĩ vậy thôi, nhưng Sở Cửu Biện thừa hiểu mình đã thay đổi ở đâu.", "Y trở nên sống động hơn.", "Đến lúc này hệ thống mới dám lên tiếng, khẽ hỏi: [Ký chủ, ngài không lo lắng sao?]", "\"Không lo.\" Sở Cửu Biện hiểu nó đang hỏi điều gì.", "Chẳng qua là lo Tần Kiêu vì chuyện này mà xa cách y.", "Phải nói hệ thống quả thực hiểu y, nhưng đó là hiểu về con người y trước kia.", "Nếu là trước đây, chắc chắn y sẽ lo lắng, suy nghĩ vẩn vơ đủ điều.", "Nhưng giờ y đã ở bên Tần Kiêu lâu như vậy, nếu vẫn không cảm nhận được tình yêu đối phương dành cho mình, thì không phải chậm hiểu, mà là ngốc nghếch.", "Nhưng thực ra y vẫn có chút lo lắng.", "Không phải lo Tần Kiêu sẽ xa cách y, mà lo Tần Kiêu sẽ đau lòng vì y.", "Theo lời hệ thống, Tần Kiêu không thể thay đổi những gì đã xảy ra trong quá khứ, nên chỉ có thể trơ mắt nhìn y trải qua tất cả những điều đó.", "Đặt mình vào vị trí ngược lại, nếu y quay về quá khứ của Tần Kiêu, chứng kiến người thân y lần lượt qua đời, chứng kiến y một mình gánh vác tất cả, mang tiếng xấu trở thành cái đích cho thiên hạ chỉ trích, từng ngày trở nên xa lạ với chính mình...", "Chỉ nghĩ đến đó thôi, lồng ngực Sở Cửu Biện đã thấy nghẹn.", "Cảm giác ấy hẳn là rất bất lực.", "Sở Cửu Biện gạt bỏ những suy nghĩ tự dày vò ấy đi.", "Giờ y đã không còn thích tự làm khổ mình nữa.", "Y bước ra phòng khách, ngồi xuống sô pha.", "Nghĩ đến Tần Kiêu, khóe môi y không tự chủ cong lên.", "Không biết lần này gặp lại, đối phương có khóc không nhỉ.", "Y chưa từng thấy Tần Kiêu khóc, nghĩ đến đây Sở Cửu Biện lại thấy hơi mong đợi, mong đợi đến mức có phần ác ý.", "Nhưng dù sao vẫn là thương xót nhiều hơn, y nghĩ nên chuẩn bị vài thứ hay ho để an ủi người mình yêu.", "Chẳng hạn như đồ ăn ngon, rượu ngon, chẳng hạn như những thứ khiến người ta khoan khoái cả thể xác lẫn tinh thần...", "Sở Cửu Biện lấy điện thoại ra, mở ứng dụng mua sắm, chọn giao hàng nhanh trong thành phố.", "Rồi y mua rất nhiều quần áo vừa vặn với vóc dáng Tần Kiêu, cùng nhiều áo ngắn tay, quần đùi, áo ba lỗ và đồ lót cho chính mình.", "Còn mua thêm nhiều món đồ chơi và quần áo trẻ em không mấy đứng đắn.", "Gọi là quần áo, nhưng thực chất chỉ như vài mảnh vải vụn.", "Mua xong những thứ đó, Sở Cửu Biện lại đặt thêm ít đồ dùng, nghĩ ngợi rồi mua thêm không ít váy và trang sức cho bé gái, để dành mang về cho Tư Đồ Chiêu Linh và Đàm Vũ Trúc.", "Còn có vài món ăn vặt lạ, đồ dùng mới lạ — thứ gì mua được y đều mua. Phần của Bách Lý Hồng thì để dành, đợi ngày mai bọn trẻ đến sẽ dẫn đi phố tự chọn.", "Dù sao y có rất nhiều tiền, không tiêu thì cũng chẳng có dịp nào khác.", "Vì ở ngay trung tâm thành phố, nên chưa đầy một tiếng, hàng hóa đã được giao đến, chất đầy cả sảnh thang máy.", "Sở Cửu Biện cất bớt đồ định mang về Đại Ninh vào không gian riêng, chỉ để lại phần đủ dùng cho hai ngày ở đây cùng Tần Kiêu.", "Y nhìn đồng hồ, cau mày: \"Hệ thống, đã một tiếng rồi, Tần Kiêu đâu?\"", "[Hệ thống dò được Tần Kiêu đã đến gần khu vực tọa độ rồi, đang định vị cụ thể...]", "Phạm vi tọa độ xuyên không khá rộng, hệ thống chỉ định vị được trong phạm vi trung tâm thành phố, không có cách nào đưa thẳng người đến tận nhà Sở Cửu Biện.", "[Xác định thành công rồi! Vị trí thời gian thực đã gửi đến điện thoại ký chủ, mời kiểm tra ạ.]", "Sở Cửu Biện lấy điện thoại ra, quả nhiên thấy bản đồ đang nhấp nháy, mở ra liền thấy một chấm xanh nhỏ cách y hơn tám trăm mét.", "Chỗ đó là một trung tâm thương mại, hôm nay hình như còn có sự kiện thương mại của minh tinh khác, người rất đông.", "Sở Cửu Biện lập tức ra khỏi cửa, xuống lầu, chạy nhanh về phía trung tâm thương mại.", "Vì vội vàng, đã lâu không để ý chuyện làm người nổi tiếng, y quên mất mang kính râm và khẩu trang, cứ thế để lộ gương mặt không ai không biết mà chạy trên phố.", "Từ nhà đến trung tâm thương mại phải đi qua con phố đi bộ đông đúc nhộn nhịp nhất, hôm nay là ngày làm việc nhưng người qua lại vẫn không ít.", "Thấy Sở Cửu Biện đột nhiên xuất hiện, xung quanh vang lên hết đợt tiếng kêu kinh ngạc này đến đợt khác.", "Rất nhiều người lấy điện thoại ra chụp, thậm chí có người bắt đầu chạy theo y.", "Trong trung tâm thương mại.", "Tần Kiêu khoác trên mình bộ quan bào đỏ tía, lạc lõng hoàn toàn giữa khung cảnh xung quanh.", "Y lạnh lùng bước những bước chậm rãi trên nền gạch men bóng loáng, ánh mắt lướt qua từng người, từng vật.", "Nơi đây vẫn là thế giới của Sở Cửu Biện.", "Nhưng y lại không tìm thấy người mình cần tìm.", "Y thấy rất nhiều trẻ em, nhưng đứa nào cũng ăn mặc gọn gàng tươm tất, không giống dáng vẻ Sở Cửu Biện mà y từng thấy.", "Y cũng thấy rất nhiều người, đàn ông, đàn bà, người trẻ, người trung niên, ăn mặc kỳ lạ — có lẽ vì trời nóng, họ chỉ mặc áo ba lỗ, quần đùi.", "Nhưng Tần Kiêu không mấy ngạc nhiên, vì trước đó, khi theo Sở Cửu Biện lúc còn nhỏ, y đã từng thấy người khác ăn mặc như vậy.", "Lúc này, y chỉ nôn nóng muốn tìm được Sở Cửu Biện.", "Y không hoảng loạn, cứ từng bước tiến lên, ban đầu còn tưởng như trước đây, không ai nhìn thấy mình.", "Nhưng chẳng mấy chốc y cảm nhận được ngày càng nhiều ánh mắt đổ dồn về phía mình.", "Những người đó đều đang nhìn y, có người còn lấy điện thoại ra chụp.", "Tần Kiêu biết điện thoại, cũng biết chụp ảnh.", "Y thu lại khí thế của mình, nhưng lời nói cử chỉ vẫn toát lên phong thái tao nhã, khí chất của kẻ đứng đầu lâu năm, khác hẳn người thường.", "Vì vậy không ai dám bước tới bắt chuyện với y.", "Nhưng Tần Kiêu biết những người này có thể nhìn thấy mình, ánh mắt y liền dịch chuyển.", "Y thấy một người đàn ông quen mắt, liền bước tới hỏi: \"Xin hỏi đây là đâu?\"", "\"Hả?\" Người đàn ông không ngờ chàng trai đẹp như minh tinh này bỗng dưng bắt chuyện với mình, giọng điệu còn văn vẻ như vậy.", "Sững người một lúc, anh ta có phần căng thẳng đáp: \"Đây là trung tâm thương mại Vinh Hoa mà, anh bạn đi lạc à? Anh định đi đâu?\"", "Người ta luôn kiên nhẫn và nhiệt tình hơn với người có ngoại hình đẹp.", "Tần Kiêu ghi nhớ tên trung tâm thương mại này, hỏi tiếp: \"Ta đang tìm người. Ngươi có biết Sở Cửu Biện không?\"", "\"Sở Cửu Biện?\" Người đàn ông chợt hiểu ra, \"Anh bạn là bạn của Sở Cửu Biện à, thảo nào đẹp trai thế, cũng là diễn viên hả? Sao trước giờ tôi chưa thấy anh nhỉ? Anh từng đóng phim gì chưa?\"", "Tần Kiêu không hiểu những câu sau, nhưng nghe ra người này biết Sở Cửu Biện, ánh mắt y sáng lên, có phần vội vã hỏi: \"Vậy ngươi có biết y đang ở đâu không?\"", "\"Ôi, cái này thì tôi không biết, để tôi hỏi giúp anh.\"", "Người đàn ông rất nhiệt tình, quay đầu lớn tiếng hỏi những người xung quanh đang vây xem chụp ảnh: \"Có ai gặp Sở Cửu Biện không? Nghe nói hôm nay anh ấy có tham gia sự kiện ở đây, anh bạn này tìm không ra chỗ.\"", "Có một thanh niên nghe vậy liền nói: \"Sở Cửu Biện? Hôm nay Sở ca có sự kiện ở đây à? Chưa nghe nói gì cả.\"", "\"Hôm nay là nhóm nhạc nam mới ra mắt có sự kiện thương mại ở đây thôi mà? Chưa nghe nói Sở ca cũng đến.\"", "Chỉ riêng gương mặt của Sở Cửu Biện đã đủ khiến vô số người say mê. Huống hồ y còn có thực lực diễn xuất, lượng fan và danh tiếng đều vượt trội, thiện cảm từ công chúng cũng cao, gọi là đỉnh lưu cũng không ngoa.", "Vì vậy Tần Kiêu chỉ hỏi một câu, đã phát hiện xung quanh hầu như ai cũng biết Sở Cửu Biện.", "Nhưng không ai biết đối phương hiện đang ở đâu.", "\"Hay anh bạn gọi điện hỏi thử xem?\" Có người đề nghị.", "Tần Kiêu lắc đầu: \"Ta không có điện thoại.\"", "Nói đoạn, y bỗng nhìn thấy màn hình quảng cáo cỡ lớn giữa trung tâm thương mại hiện lên gương mặt Sở Cửu Biện.", "Giọng y khựng lại, ngẩng đầu nhìn chăm chú vào chàng trai trên màn hình.", "Đối phương trong hình vừa quen thuộc vừa xa lạ, ăn mặc giống như mọi người xung quanh, nụ cười ấm áp nhưng không chạm đến đáy mắt.", "Trong thoáng chốc, Tần Kiêu nhớ ngay đến cậu bé trầm mặc kia.", "Trong lòng như bị thứ gì đó đâm mạnh một nhát.", "Trong khoảnh khắc ấy, y thậm chí có chút hoảng hốt.", "Y không biết liệu mình có thực sự có được Sở Cửu Biện hay không, có thực sự từng bảo vệ được đối phương hay không, đã cho y đủ nhiều yêu thương chưa.", "Y thậm chí bắt đầu hoài nghi, liệu chàng trai hay cười, kiêu ngạo, đôi khi còn có chút giả dối đáng yêu kia, có thực sự tồn tại hay không.", "Có thực sự từng thuộc về y hay không?", "Nếu như y chưa từng thực sự có được đối phương, nếu như...", "Chỉ nghĩ đến đó, y đã thấy khó thở.", "\"Tần Kiêu.\" Giọng nói quen thuộc xuyên qua tiếng ồn ào, vang rõ bên tai Tần Kiêu.", "Tim y giật thót.", "Y từ từ hạ ánh mắt đang dừng trên màn hình xuống.", "Rồi y thấy người trên màn hình, xuất hiện cách mình chỉ hơn mười mét.", "Giữa dòng người, chàng trai bước nhanh về phía y.", "Ngực đối phương phập phồng, hai má hơi ửng hồng, như vừa chạy một quãng dài.", "Tần Kiêu nhìn chăm chăm vào y, nhất thời quên cả phản ứng.", "Đã lâu lắm rồi.", "Y cảm thấy đã rất lâu, rất lâu rồi mình chưa gặp lại Sở Cửu Biện.", "Khoảnh khắc này, nhìn chàng trai bước nhanh về phía mình, cảm giác vừa đánh mất vừa tìm lại được bỗng trào dâng trong lòng, khiến mắt y đỏ hoe trong tích tắc.", "Y cất bước, chỉ vài bước đã rút ngắn khoảng cách với Sở Cửu Biện.", "Chỉ cần vươn tay là chạm tới.", "Tần Kiêu đưa tay ra, rốt cuộc ôm được người mình yêu vào lòng.", "Không còn rào cản, không còn đứng ngoài nhìn.", "Y ôm chặt lấy y một cách chân thực.", "Xung quanh vang lên tiếng kêu kinh ngạc, tiếng máy ảnh chụp liên tục, đèn flash lóe sáng liên hồi.", "Nhưng Sở Cửu Biện không bận tâm, y vòng tay ôm lại Tần Kiêu, cảm nhận được đối phương đang khẽ run rẩy.", "Lòng đau nhói, Sở Cửu Biện nhẹ nhàng vỗ vỗ sau lưng người đàn ông, dịu dàng nói: \"Không sao rồi. Ngươi tìm được ta rồi.\"", "Tần Kiêu siết chặt vòng tay, gần như muốn khắc cả Sở Cửu Biện vào lồng ngực mình, y hơi cúi đầu, áp mặt vào vai chàng trai.", "Cảm nhận được bờ vai mình ướt đẫm, Sở Cửu Biện nín thở.", "Tiếp đó, y nghe tiếng nói nghẹn ngào của người đàn ông vang lên bên tai mình.", "Rất khẽ.", "Y nói: \"Ta ở đây.\"", "Sở Cửu Biện hiểu.", "Trong những ngày cô độc bất lực ấy, trong những khoảnh khắc đau khổ nhất, Tần Kiêu vẫn luôn ở bên cạnh y.", "\"Ừ.\" Y khẽ đáp lại."], "id": 4, "wordCount": 4823}, {"title": "Chương 109 phiên ngoại sáu ( hiện đại thiên 3 )", "paragraphs": ["Ngay khi Sở Cửu Biện tìm được Tần Kiêu, trên mạng cũng bắt đầu xuất hiện những tin tức về sự cố dây cáp của y ngày hôm qua.", "Nhiều đoạn video từ các góc quay khác nhau lan truyền chóng mặt, chỉ trong chốc lát đã phủ khắp mạng xã hội.", "Đoạn rõ nét nhất cho thấy Sở Cửu Biện bị treo lơ lửng ở độ cao hơn mười mét, tà áo trắng tung bay trong gió, những món trang sức bạc trên người lấp lánh dưới ánh mặt trời, tạo nên vẻ đẹp lung linh như sóng nước. Mái tóc bạc dài được tết thành bím sau gáy, nhưng gió mỗi lúc một mạnh, cả người y lắc lư dữ dội hơn trong không trung. Bím tóc không hiểu sao bị bung ra, những lọn tóc bay che khuất tầm nhìn, Sở Cửu Biện đưa tay gạt tóc khỏi mặt, vô tình để lộ móc khóa nơi hông — có thể thấy rõ một trong hai sợi dây cáp đã căng đến mức gần đứt, như thể có thể bung ra bất cứ lúc nào.", "Mọi người còn chưa hết trầm trồ trước vẻ đẹp của Sở Cửu Biện, thì bỗng thấy cả người y rơi thẳng xuống, như một chuỗi ngọc bị đứt dây.", "Chỉ còn một sợi dây, thế mà một trong hai sợi đã đứt thật.", "Màn hình rung lắc dữ dội, tiếng thét xé màng nhĩ, người xem qua màn hình cũng nín thở kinh hoàng.", "May thay sợi dây còn lại không đứt, miễn cưỡng giữ được y lại. Sau đó, dưới sự vận hành của ê-kíp, y được hạ xuống chậm rãi, an toàn chạm đất.", "Video đột ngột im bặt.", "Dù người đã bình an vô sự, nhưng không chỉ fan hâm mộ mà cả người qua đường cũng thấy kinh hồn táng đởm. Nếu thật sự rơi xuống, Sở Cửu Biện coi như đã không còn trên đời.", "Làn sóng chỉ trích đoàn làm phim nổ ra dữ dội, đoàn phim vội ra thông báo, thừa nhận sai sót, hứa sẽ bàn bạc chuyện bồi thường với Sở Cửu Biện, thái độ có vẻ thành khẩn.", "Cơn giận của công chúng phần nào dịu xuống, nhưng vẫn còn rất nhiều người lo lắng, ồ ạt để lại bình luận dưới Weibo của Sở Cửu Biện, mong y báo bình an.", "Sở Cửu Biện hoàn toàn không hay biết chuyện này, y đã rời xa thế giới ấy quá lâu, không còn giữ được sự nhạy bén và tự giác của một ngôi sao hạng A. Y cũng quên mất mình vừa gây ra chuyện lớn thế nào, đáng lẽ phải xuất hiện báo bình an với mọi người.", "Sau khi tìm được Tần Kiêu, y liền nắm tay người, xuyên qua dòng người đông đúc để về nhà.", "Khu chung cư dưới nhà không cho người lạ vào, nên khi hai người đến gần khu, đám fan và người qua đường bám theo đành dừng lại, chỉ còn giơ điện thoại quay từ xa.", "Những đoạn video ấy cũng dần lan truyền trên mạng.", "Mọi người thấy người vừa trải qua giây phút sinh tử hôm qua, hôm nay đã xuất hiện trước công chúng, an toàn và khỏe mạnh.", "Dù là fan hay người qua đường, ai nấy đều thở phào nhẹ nhõm.", "Nhưng ngay sau đó, họ phát hiện có gì đó không ổn.", "Bởi vì Sở Cửu Biện đã chạy như bay qua con phố đi bộ, lao thẳng vào trung tâm thương mại.", "Rồi y tiếp tục chạy theo một hướng nhất định, cuối cùng phía trước không xa xuất hiện một đám đông nhỏ, không ít người đang giơ điện thoại chụp ai đó.", "Là minh tinh khác chăng?", "Màn hình rung lắc theo bước chân Sở Cửu Biện, tiến gần đến chỗ đám đông tụ tập.", "Đám đông giãn ra, Sở Cửu Biện len qua một khe hở chạy vào trong.", "\"Tần Kiêu!\" Giọng chàng trai mang theo hơi thở gấp gáp.", "Ống kính đảo theo hướng nhìn của y, một bóng người khoác áo đỏ tía lọt vào khung hình.", "Chiều cao gần mét chín, khiến người đàn ông ấy nổi bật hẳn giữa đám đông như hạc giữa bầy gà, huống hồ còn sở hữu gương mặt không kém cạnh Sở Cửu Biện.", "Người đàn ông nghe tiếng gọi liền quay đầu nhìn về phía này.", "Ống kính tiếp tục đuổi theo vài bước rồi dừng lại, mọi người qua màn hình thấy Sở Cửu Biện chạy về phía người đàn ông ấy.", "Người đàn ông kia cũng bước nhanh đón lấy.", "Rồi y ôm chầm lấy Sở Cửu Biện.", "Vòng tay siết chặt, dáng vẻ như đang ôm lấy người yêu, thân mật khắng khít.", "Sở Cửu Biện không hề đẩy ra, ngược lại còn ôm lại đối phương, tiếng kêu kinh ngạc và tiếng thét chói tai xung quanh trở thành âm thanh nền náo nhiệt.", "Người cầm điện thoại quay cũng có vẻ kích động, khung hình run rẩy không ngừng.", "\"Hai người này là sao vậy trời!\"", "\"Nhìn kiểu này không giống bạn bè bình thường đâu, chẳng lẽ là bạn trai?\"", "\"Trời đất ơi! Sở ca đây là định công khai luôn hả!\"", "Đám đông tại hiện trường vẫn còn giữ được chút lý trí, nhưng khi quay được cảnh một đỉnh lưu ôm ấp thân mật với bạn trai đồng tính giữa phố, họ vẫn không kìm được cảm giác khó tin, hào hứng đăng video lên mạng.", "Trong chốc lát, hình ảnh từ nhiều góc độ tràn ngập mạng xã hội.", "Bao gồm cả đoạn video hai người nắm tay nhau trở về khu chung cư sau đó, gần như xác nhận thẳng thừng mối quan hệ giữa họ.", "Chỉ cần có mắt nhìn là hiểu ra vấn đề.", "Nhưng các fan lại không muốn tin, cũng không thể tin nổi.", "Tuy Sở Cửu Biện xưa nay chẳng mấy khi tương tác với fan, nhưng y vẫn có một lượng lớn fan nữ.", "Các fan không muốn tin thần tượng của mình là gay, lại còn phải chứng kiến y tìm được bạn trai — điều này còn khó chấp nhận hơn cả việc y có bạn gái.", "Nhưng sự thật sờ sờ trước mắt, các fan có gột rửa thế nào cũng không xóa được.", "Vì vậy, rất nhiều fan bắt đầu rời bỏ, thậm chí có người quay sang công kích Sở Cửu Biện.", "Trên một hòn đảo nào đó ở nước ngoài.", "Người đại diện — Phong tỷ — trong bộ vest sang trọng, vừa đàm phán xong một thương vụ hợp tác với một ông chủ.", "Nàng là người quản lý phòng làm việc của Sở Cửu Biện, dưới tay dĩ nhiên không chỉ có mình y, chỉ là những nghệ sĩ khác không nổi tiếng bằng.", "Thương vụ lần này là đưa vài nghệ sĩ dưới trướng sang nước ngoài thử vai, và nàng cũng đã giành được suất vai phụ nhỏ cho hai người trong số đó.", "Tuy chỉ là vai phụ, nhưng có thể góp mặt trong một bộ phim sản xuất hàng đầu thế giới cũng đủ nâng cao danh tiếng.", "Nói xong chuyện này, trong lòng nàng nhẹ nhõm hẳn.", "Tình trạng tinh thần và tâm lý của Sở Cửu Biện gần đây quá bất ổn, hai tháng trước y từng cắt cổ tay, nếu không phải nàng phát hiện kịp thời, có lẽ đã mất mạng thật rồi.", "Vì vậy nàng định để y dần rút lui khỏi giới giải trí để dưỡng bệnh, chỉ cần giữ cổ phần hoa hồng từ công ty là đủ.", "Nếu cứ tiếp tục lăn lộn thế này, con người đó thật sự sẽ suy sụp mất.", "Nghĩ đến y, Phong tỷ khẽ cau mày.", "Hôm qua trợ lý gọi điện báo Sở Cửu Biện gặp sự cố ngoài ý muốn trên phim trường, suýt nữa mất mạng. May mà chỉ hư kinh không hư thật.", "Nàng lấy điện thoại ra định gọi cho Sở Cửu Biện, theo thông lệ hỏi thăm an ủi vài câu.", "Người bình thường trải qua khoảnh khắc sinh tử như vậy chắc chắn sợ hãi tột độ, nhưng Sở Cửu Biện thì khác, biết đâu đối phương còn tiếc là mình chưa chết hẳn.", "Sở dĩ Phong tỷ không quá lo y sẽ tiếp tục tìm đường chết, không vội về nước, là vì Sở Cửu Biện dù sao cũng là một nghệ sĩ có trách nhiệm với nghề. Nếu đã nhận việc, y chắc chắn sẽ làm cho xong. Chưa xong việc thì cũng sẽ không chết.", "Hiện tại đoàn phim còn đó, phim còn chưa quay xong, nên Sở Cửu Biện vẫn còn an toàn.", "Nhưng chưa kịp gọi đi, bộ phận truyền thông đã chủ động liên hệ nàng trước.", "Nghe máy, biết được chuyện đang xảy ra trên mạng, Phong tỷ ngơ ngác không hiểu.", "Sở Cửu Biện sao lại thành gay được?", "Y có bạn trai từ bao giờ? Còn công khai giữa phố?", "Nàng không cúp máy, mở WeChat, tìm đến link mà bộ phận truyền thông gửi, bấm vào xem.", "Video bắt đầu từ lúc Sở Cửu Biện chạy trên phố đi bộ, nàng tua nhanh qua vài đoạn, rồi ở một khoảnh khắc nào đó, nghe thấy Sở Cửu Biện cất tiếng gọi \"Tần Kiêu\".", "Phong tỷ khẽ nhíu mày.", "Khung hình chầm chậm dịch chuyển, cuối cùng để lộ một bóng dáng cao lớn, dáng đứng thẳng tắp.", "Người đàn ông có gương mặt sắc sảo, đôi mắt sáng, khí chất lạnh lùng uy nghiêm, khoác trên mình bộ quan bào đỏ tía như thể vừa bước ra từ thời cổ đại.", "==", "Sở Cửu Biện nắm tay Tần Kiêu bước vào khu chung cư, rồi nhanh chân đi vào thang máy.", "Tần Kiêu quan sát mọi thứ xung quanh, cảm nhận hơi ấm từ hơi thở và lòng bàn tay người bên cạnh, tâm trạng xáo động dần lắng xuống.", "\"Đây là thang máy, giờ chúng ta lên tầng mười sáu.\" Sở Cửu Biện giới thiệu, nghiêng đầu bắt gặp ánh mắt sâu thẳm của người đàn ông.", "Tần Kiêu chăm chú nhìn y, bốn mắt giao nhau, khóe môi khẽ cong lên.", "Thần sắc y nhẹ nhàng tự nhiên, như thể người vừa rơi lệ lúc nãy không phải là mình.", "Sở Cửu Biện khẽ giật mình, nhón chân lại gần, đặt lên môi người một nụ hôn nhẹ.", "Tần Kiêu lập tức ôm lấy y, hôn sâu hơn.", "Đó là một nụ hôn không chút mị hoặc, chỉ có tình sâu và vô hạn dịu dàng.", "Khoảnh khắc ấy trở nên dài lâu và bình yên đến lạ.", "Họ cảm nhận được sự tồn tại của nhau, cảm nhận được luồng tình cảm mãnh liệt đang trào dâng từ tận đáy lòng, chậm rãi bao trùm lấy cả hai.", "\"Đinh——\"", "Thang máy dừng lại.", "Sở Cửu Biện đẩy nhẹ Tần Kiêu ra, kéo tay y bước ra ngoài.", "Căn hộ không lớn, sạch sẽ ngăn nắp, phảng phất dấu vết sinh hoạt thường ngày.", "\"Đây là nhà ngươi sao?\" Tần Kiêu nhìn quanh.", "\"Ừ, một phần trong đó.\" Sở Cửu Biện đưa dép cho y, tự mình cũng thay giày.", "Tần Kiêu bắt chước y xỏ dép.", "Cửa mở ra, cả hai bước vào.", "Đầu tiên là luồng khí lạnh, xua tan cái nóng oi ả ngoài trời.", "Tiếp đó, cả một không gian rộng lớn hiện ra trước mắt.", "Sàn nhà bóng loáng, tường được ốp vải mềm mại, đủ loại vật trang trí nội thất mới lạ, và tấm cửa kính sát đất khổng lồ.", "Tần Kiêu bước đến bên cửa sổ nhìn ra ngoài, dòng xe cộ tấp nập, những tòa nhà cao tầng, và cả tấm biển quảng cáo lớn có hình Sở Cửu Biện.", "Sở Cửu Biện mang hai lon Coca lạnh đến bên y, mở một lon đưa cho Tần Kiêu.", "Tần Kiêu đón lấy, thấy Sở Cửu Biện ngửa đầu uống một ngụm, y cũng bắt chước uống theo.", "Một hương vị lạ lẫm tràn ngập nơi đầu lưỡi, còn mang theo chút cảm giác châm chích.", "Tần Kiêu nhíu mày nhìn dòng chữ trên lon, khẽ hỏi: \"Coca?\"", "\"Ừ. Uống thấy sao?\" Sở Cửu Biện cười hỏi.", "Tần Kiêu lắc đầu: \"Không thích.\"", "Sở Cửu Biện bật cười, đổi cho y một ly nước ấm.", "\"Có đói không? Muốn ra ngoài ăn hay ăn ở nhà?\" Y hỏi Tần Kiêu.", "Tần Kiêu cũng muốn ra ngoài ngắm nhìn thế giới xa lạ này, nhưng y muốn ở bên Sở Cửu Biện nhiều hơn, trong không gian không ai quấy rầy.", "\"Ăn ở nhà đi.\" Y nói.", "Sở Cửu Biện liền mở ứng dụng đặt đồ ăn, gọi một bàn đầy món.", "\"Đi tắm trước đã, tắm xong là có đồ ăn ngay.\" Y kéo Tần Kiêu vào phòng ngủ chính, đưa khăn tắm, giới thiệu qua các loại đồ dùng vệ sinh.", "Rồi dặn dò: \"Tắm xong gọi ta, ta gội đầu sấy tóc cho.\"", "Tần Kiêu gật đầu đồng ý.", "Thấy y toan quay người rời đi, Tần Kiêu liền vươn tay kéo Sở Cửu Biện vào lòng.", "Sở Cửu Biện khẽ khựng lại, nghiêng đầu, gương mặt vô tình cọ qua bờ môi người đàn ông.", "Không ai nói gì, nhưng những nụ hôn khẽ khàng cứ thế nối tiếp nhau trên gương mặt Sở Cửu Biện, cánh tay ôm quanh eo y cũng siết chặt dần.", "Sở Cửu Biện xoay người, ngửa mặt hôn lên môi người đàn ông.", "Căn phòng dần chìm trong bầu không khí ấm áp, riêng tư, cửa phòng tắm khép lại phía sau hai người.", "Rất lâu sau, cả hai mới rời khỏi phòng tắm, khoác áo choàng bước ra ngoài.", "Đồ ăn đã được giao đến cửa, Sở Cửu Biện cùng Tần Kiêu mang vào, chừng hai túi lớn.", "Bày hết ra, cả bàn ăn nhanh chóng kín chỗ, đủ sắc đủ hương, phần lớn đều là những món Tần Kiêu chưa từng thấy qua.", "Bên cạnh bàn ăn là một quầy rượu, Tần Kiêu tò mò ngắm nhìn những chai lọ xinh đẹp cùng thứ rượu đủ màu sắc bên trong.", "Đại Ninh tuy đã có pha lê và lưu ly, nhưng vì công nghệ còn hạn chế, vẫn khó lòng làm ra những chai lọ tinh xảo như vậy.", "\"Đây đều là rượu cả.\" Vừa trải qua một khoảng thời gian quấn quýt bên nhau, gương mặt chàng trai vẫn còn vương chút ửng hồng và lười biếng, ngữ điệu cũng mang theo chút khàn khàn dễ mê hoặc lòng người.", "\"Ngươi có muốn uống thử không?\" Y hỏi.", "Uống nhiều quá sẽ buồn ngủ, không ra ngoài dạo được. Nhưng dù sao Sở Cửu Biện đã bàn với hệ thống, họ có thể ở lại hiện đại thêm một khoảng thời gian, nên hai ngày này cứ ở nhà cùng Tần Kiêu cũng không sao. Đợi đêm mai Bách Lý Hồng đưa bọn trẻ sang chơi hai ngày, sẽ để người quay về ổn định triều chính trước, còn y thì có thể tiếp tục ở lại hiện đại chơi cùng Tần Kiêu, lúc đó sẽ dẫn y đi dạo phố, trải nghiệm thêm nhiều thứ mới lạ.", "Tần Kiêu không có ý kiến gì, Sở Cửu Biện sắp xếp thế nào y cũng theo thế ấy.", "\"Uống chút đi.\" Y nói.", "Vì thế Sở Cửu Biện bày ra một dãy ly rượu, rót các loại rượu khác nhau vào, pha theo tỷ lệ hợp khẩu vị phổ thông.", "Tần Kiêu cầm một ly, ngửa đầu uống cạn một hơi.", "Rồi lập tức sặc lên ho sù sụ.", "Sở Cửu Biện vừa buồn cười vừa thương, lấy khăn giấy lau mặt cho y: \"Rượu này nồng độ cao lắm, ngươi uống từ từ thôi. Mỗi loại nhấp một ngụm là được rồi.\"", "Rồi y gắp thức ăn cho Tần Kiêu: \"Ăn chút gì đã rồi hẵng uống.\"", "Tần Kiêu gật đầu, ngoan ngoãn vừa ăn vừa nhấp từng ngụm rượu.", "Nồng độ rượu quả thực cao.", "Uống dần, Tần Kiêu không hay biết mình đã ngà ngà say.", "Trước đây y không hiểu vì sao có người thích uống rượu đến thế, uống xong lại còn thấy trong lòng khoan khoái. Nhưng trong khoảng thời gian làm bạn với Sở Cửu Biện nhỏ tuổi ấy, y đã không biết bao nhiêu lần ước có một bầu rượu trước mắt để có thể say mềm không tỉnh.", "Như vậy y sẽ không phải nhìn Sở Cửu Biện chịu đựng giày vò nữa, không phải thừa nhận sự bất lực đau đớn của chính mình nữa.", "Nhưng khi ấy không có rượu.", "Mà giờ dù có thật, y cũng sẽ không uống.", "Y muốn giữ trọn vẹn trong ký ức những gì Sở Cửu Biện đã trải qua trong quá khứ, nhớ rõ những tổn thương, những đau đớn y từng chịu.", "Sở Cửu Biện nhìn Tần Kiêu, thấy người đàn ông cũng đang nhìn chăm chăm vào mình.", "Mùi rượu dần lan tỏa, Sở Cửu Biện thấy trên gương mặt đối phương hiện lên hơi men, trong ánh mắt y cũng phảng phất nỗi buồn thương và đau lòng sâu đậm.", "Lòng Sở Cửu Biện chợt mềm nhũn, không muốn để người đàn ông tiếp tục chìm trong cảm xúc ấy.", "Bữa ăn cũng đã gần xong, y đứng dậy: \"Ta đi đánh răng.\"", "\"Ta cũng đi.\" Tần Kiêu đứng dậy, theo y vào phòng tắm.", "Hai người cùng đứng đánh răng trong căn phòng chỉ vài giờ trước còn là nơi họ quấn quýt bên nhau.", "Điều hòa trong phòng vẫn chạy mát rượi, nhưng cả hai lại cảm thấy hơi ấm trong nhà mỗi lúc một tăng.", "Tần Kiêu súc miệng, rửa mặt qua loa, rồi áp sát vào lưng Sở Cửu Biện, đôi tay không chịu yên.", "Sở Cửu Biện giữ tay y lại: \"Ngươi ra ngoài chờ ta trước.\"", "Tần Kiêu hơi nhướn mày, không rõ nghĩ gì, nhưng vẫn ngoan ngoãn ra ngoài.", "Sở Cửu Biện súc miệng rửa mặt xong, ngắm mình trong gương, hai má ửng hồng, ánh mắt lấp lánh hơi men.", "Chuếnh choáng hơi men, y cũng chẳng còn thấy ngượng ngùng nhiều nữa.", "Tần Kiêu ngồi trên giường, tấm nệm quá đỗi êm ái khiến y hơi lạ lẫm, nhưng quả thực thoải mái hơn hẳn giường ở Đại Ninh.", "Y nghĩ, nếu Sở Cửu Biện thích loại này, về sau có thể sai người làm ra loại tương tự.", "Rồi y đứng dậy, ngồi xuống chiếc ghế sofa đơn gần đó. Ghế thấp, y ngồi tựa lưng, đôi chân dài co lại.", "Chiếc sofa này êm hơn hẳn ghế gỗ y vẫn ngồi ở Đại Ninh, về sau nhất định phải cho người làm loại tương tự.", "Đang nghĩ ngợi, rèm cửa bỗng tự động khép lại chầm chậm.", "Căn phòng chìm trong bóng tối, một luồng ánh sáng vàng ấm dịu bật lên, khiến không khí phòng ngủ càng thêm mơ hồ, ấm áp.", "Lòng Tần Kiêu khẽ rung động.", "Nghe tiếng động từ phía phòng tắm, y ngẩng đầu nhìn lại.", "Cách y chừng năm sáu mét, cửa phòng tắm mở ra, Sở Cửu Biện bước ra.", "Chàng trai khoác trên người một bộ đồ ngủ mỏng manh, mái tóc bạc buông xõa qua vai, khẽ đung đưa theo từng bước chân.", "Ánh mắt Tần Kiêu trầm xuống, ẩn chứa chút gì đó nóng bỏng khó giấu, dõi theo từng bước chân của người mình yêu, không rời nửa khắc.", "Y chưa từng thấy Sở Cửu Biện trong dáng vẻ này, cũng chưa từng trải qua cảm giác bị khuấy động đến vậy.", "Sở Cửu Biện, dưới hơi men, cũng bạo dạn và buông thả hơn ngày thường. Y chậm rãi bước đến trước mặt người đàn ông.", "Đêm ấy, ánh đèn vàng dịu chứng kiến hai người quấn quýt bên nhau, hết lần này đến lần khác, như thể muốn bù đắp cho những năm tháng xa cách, những nỗi đau đã qua.", "Từ phòng ngủ đến phòng khách, từ trước gương đến bên khung cửa kính sát đất, tiếng thì thầm và hơi thở gấp gáp quyện vào nhau, lấp đầy cả căn nhà suốt một đêm dài.", "Sở Cửu Biện chợt nhớ tới nhiều năm về trước, cũng một cảm giác gần gũi đến mê muội như thế này, khiến y lịm đi rồi lại tỉnh lại không biết bao lần.", "Cả hai như hai kẻ chỉ còn lại bản năng, chỉ còn nhau giữa thế giới này.", "Chỉ có như vậy, Tần Kiêu mới cảm thấy mình thật sự, thật rõ ràng, đang có được Sở Cửu Biện.", "Sở Cửu Biện cũng cảm nhận được trọn vẹn tình yêu bao la mà người đàn ông dành cho mình.", "Những ký ức xa xăm, đau thương trong quá khứ, giữa những nụ hôn dịu dàng của người đàn ông, giữa vòng tay chìm đắm vô tận ấy, dần trở nên nhạt nhòa, rồi biến mất hẳn.", "Hiện tại và cả sau này, những gì còn đọng lại bên y, sẽ chỉ là bình yên và hạnh phúc.", "Trên chiếc giường lớn êm ái, Sở Cửu Biện mệt lả rúc vào lòng người đàn ông, cảm nhận hơi ấm từ y, khẽ nói: \"Ngủ ngon.\"", "Tần Kiêu ôm y từ phía sau, hôn nhẹ lên gáy y, thì thầm: \"Lần nữa đi.\"", "Sở Cửu Biện: \"...\"", "Hôm sau, mặt trời đã lên cao Sở Cửu Biện mới mở mắt.", "Y vừa cựa mình, người ôm mình cũng tỉnh giấc theo.", "Bụng réo lên vì đói, Sở Cửu Biện ngáp một cái: \"Đói bụng.\"", "\"Ăn gì đây?\" Tần Kiêu hỏi.", "Sở Cửu Biện đưa tay mò mẫm trên mép giường một hồi mới tìm thấy điện thoại.", "Điện thoại để chế độ im lặng, đã đầy ắp cuộc gọi nhỡ và tin nhắn, Sở Cửu Biện cũng chẳng buồn để ý, trước tiên đặt một bàn đồ ăn.", "Hai người rời giường rửa mặt đánh răng, ăn xong, Sở Cửu Biện mới mở những tin nhắn kia ra xem.", "Phần lớn người gửi y không nhớ rõ là ai, nhưng y nhớ tên người lưu là \"Phong tỷ\".", "Mở khung chat, đối phương đã gửi rất nhiều tin nhắn, hỏi y có thật sự định công khai giới tính không, hỏi thân phận người bạn trai kia, hỏi y có muốn rút lui khỏi giới giải trí để dưỡng bệnh không.", "Sở Cửu Biện suy nghĩ một lúc.", "Chỉ còn vài ngày nữa y sẽ hoàn toàn rời khỏi thế giới này, nhưng nơi đây vẫn còn những nhân viên đã vì y mà làm việc, còn có ngần ấy người hâm mộ.", "Có lẽ nên cho họ một lời giải thích rõ ràng, rồi mới lặng lẽ biến mất theo cách hợp lý.", "Vì vậy, y nhắn tin lại cho Phong tỷ, bảo nàng công bố sự thật về quá khứ của mình.", "Trước nay, trước mặt công chúng, y vẫn luôn tạo hình ảnh một đứa trẻ sinh ra trong gia đình bình thường, chưa từng trải qua biến cố gì lớn. Không phải không có ai từng biết chuyện cũ của y, cũng không phải chưa có tòa soạn hay công ty đối thủ nào từng phát hiện ra, chỉ là vì liên quan đến một vụ án hình sự, cộng thêm sự chuẩn bị kỹ lưỡng từ phía phòng làm việc, nên sự thật vẫn chưa từng bị phanh phui.", "Nhưng giờ đây, Sở Cửu Biện cảm thấy đã đến lúc phơi bày con người thật của mình trước công chúng.", "Sau đó, y sẽ lấy lý do \"bệnh tình\" mà rời khỏi giới giải trí, hoàn toàn biến mất khỏi tầm mắt mọi người.", "Còn về việc Tần Kiêu bị chụp ảnh, tất nhiên y sẽ thẳng thắn thừa nhận mối quan hệ giữa hai người, đồng thời nói rõ chính Tần Kiêu là người đã \"cứu mạng\" mình.", "Nếu không có Tần Kiêu, có lẽ lúc này y đã thật sự không còn nữa. Dù theo lời hệ thống, y vốn đã làm trái quy tắc của thế giới này, đáng lẽ phải chết theo đúng số mệnh vốn có. Vậy nên xét cho cùng, Tần Kiêu đúng là người đã cứu mạng y thật.", "Y muốn để lại cho mọi người một ấn tượng rằng mình đã lui về sống cùng bạn trai, dưỡng bệnh an nhàn. Còn việc sau này đi đâu, làm gì, sẽ tùy mọi người tự tưởng tượng.", "Như thế, những người ghét bỏ, oán hận y rồi sẽ dần quên đi. Còn những người yêu quý y, sẽ luôn tin rằng y đang sống hạnh phúc, bình yên ở một góc nào đó trên thế giới này.", "Điều này, đối với tất cả mọi người, đều là điều tốt nhất.", "Chỉ là, với các fan hâm mộ, dù sao y vẫn thấy áy náy vì đã phụ lòng họ.", "Còn về khối tài sản trong tay mình, y quyết định giao toàn quyền cho Phong tỷ xử lý, dù là đầu tư vào phòng làm việc, chia thưởng cho nhân viên, hay chuyển sang việc khác, tùy nàng quyết định, coi như đó là phần đền bù của y dành cho họ.", "Gửi xong những tin nhắn ấy, y cũng không màng đến phản ứng của đối phương, tắt tiếng điện thoại rồi chuẩn bị đưa Tần Kiêu ra ngoài.", "Hệ thống vừa báo Bách Lý Hồng còn khoảng hai tiếng nữa là tới.", "Lúc đó vừa vặn là giờ ăn tối, nên bây giờ y có thể dẫn Tần Kiêu ra siêu thị dạo một vòng, mua ít đồ ăn vặt.", "Rồi mua thêm hai bộ quần áo cho bọn trẻ, để ngày mai ra phố cũng tiện hơn.", "Nhận được tin nhắn, người đại diện im lặng hồi lâu, rồi tìm trong tủ sắt những hồ sơ tư liệu cất giấu bấy lâu, mang giao cho bộ phận truyền thông."], "id": 5, "wordCount": 4386}, {"title": "Chương 110 phiên ngoại bảy ( hiện đại thiên xong )", "paragraphs": ["Những tấm ảnh thời thơ ấu của Sở Cửu Biện, từ những năm tháng lớn lên trong trại trẻ mồ côi, vẫn còn được lưu giữ đầy đủ. Ảnh học tiểu học, trung học cơ sở, trung học phổ thông, cho tới khi được một công ty giải trí phát hiện tài năng, đưa vào đào tạo diễn xuất rồi ra mắt — toàn bộ hai mươi năm đầu đời của y cứ thế phơi bày rõ ràng trước mắt thiên hạ.", "Người ta còn lục lại được cả những bản tin, thông cáo của cảnh sát năm xưa về \"vụ thảm án hai vợ chồng bị sát hại\". Khi ấy danh tính các bên liên quan đã được giấu kín, nhưng công ty quản lý của y lại thẳng thừng đặt những mẩu tin cũ ấy cạnh thân thế của Sở Cửu Biện — coi như ngầm thừa nhận đứa trẻ sống sót trong vụ án chính là y.", "Ban đầu, dù là người qua đường, người hâm mộ, hay thậm chí cả những kẻ vốn không ưa gì y, đa phần đều không mấy tin. Bởi lẽ hình tượng mà Sở Cửu Biện thể hiện ra bên ngoài xưa nay luôn tích cực, ôn hòa, ngoại hình xinh đẹp, diễn xuất tinh tế. Một người như thế, sao có thể mang một tuổi thơ bi thảm đến vậy?", "Nhưng cùng với sự việc dần lan rộng, ngày càng nhiều người tự xưng có liên quan lên tiếng, hầu hết đều bày tỏ xót xa và tiếc nuối cho Sở Cửu Biện.", "Có người từng lớn lên cùng viện phúc lợi ấy cũng đứng ra kể lại, rằng Sở Cửu Biện kỳ thực không phải kiểu người ôn hòa dễ gần như vẻ ngoài. Ngược lại, trong lòng y u ám hơn nhiều người tưởng.", "Y có thói quen dùng vẻ ôn hòa để ngụy trang bản thân, khiến mình trông giống một người bình thường. Nhưng từ khi còn rất nhỏ, y đã bắt đầu tự làm tổn thương chính mình.", "Lại có một người từng làm tình nguyện viên ở viện phúc lợi kể rằng, một lần đi làm công tác thiện nguyện, đã vô tình bắt gặp Sở Cửu Biện trốn trong phòng, dùng mảnh gỗ vụn rạch lên cánh tay mình, máu chảy đầm đìa. Cảnh tượng ấy in sâu vào tâm trí người này đến mức nhiều năm sau vẫn còn nhớ rõ.", "Giờ đây nhìn thấy tên viện phúc lợi được nhắc tới, người ấy lập tức liên hệ Sở Cửu Biện với cậu bé xanh xao, xinh đẹp khác thường năm nào.", "Vô số lời đồn, dưới sự dẫn dắt có chủ đích của những kẻ có tâm cơ, dần dần được xâu chuỗi lại thành một câu chuyện đáng tin. Và rồi mọi người cũng chợt nhớ ra: Sở Cửu Biện debut đã bao nhiêu năm, vậy mà chưa từng để lộ cánh tay hay khuôn mặt trong bất kỳ cảnh quay nào ngoài kịch bản cho phép, đến mức từng bỏ lỡ không ít dự án lớn vì lý do đó.", "Giờ nghĩ lại, người ta cho rằng y không muốn để lộ những phần cơ thể khác chính là vì trên đó còn những vết sẹo tự thương.", "Vừa mới phút trước còn si mê, thậm chí căm hận muốn dẫm Sở Cửu Biện xuống bùn, phút sau người ta lại chẳng nỡ trách móc thêm nửa lời. Dù sao cũng là người mình yêu thích bấy lâu, khi biết y từng chịu bao nhiêu ấm ức, ai mà nỡ lòng trách cứ thêm.", "Ai nấy chỉ còn muốn biết hiện tại tinh thần y ra sao, liệu có xảy ra chuyện gì ngoài ý muốn nữa hay không.", "Đúng lúc ấy, Sở Cửu Biện đăng một dòng trạng thái ngắn gọn lên Weibo.", "[Cảm ơn mọi người đã quan tâm và ủng hộ suốt bao năm qua. Hiện tại tôi đã tìm được người có thể \"chữa lành\" cho mình, và cũng thật sự cảm nhận được tình cảm của các bạn. Nhưng thật xin lỗi, tôi không thể tiếp tục mang đến những tác phẩm tốt cho mọi người nữa, cũng không thể đáp lại tình cảm ấy. Tôi sẽ rời khỏi showbiz vĩnh viễn. Thật lòng xin lỗi vì đã phụ tấm chân tình của các bạn.]", "Một đoạn văn nhạt nhòa, có phần vô trách nhiệm. Nhưng đó lại là những dòng chữ Sở Cửu Biện đã xóa đi viết lại không biết bao nhiêu lần mới dám đăng lên.", "Y và Tần Kiêu khi ấy đang ngồi trên ghế trong trung tâm thương mại, tay cầm điện thoại, viết rồi xóa, xóa rồi lại viết. Ngoài chuyện tình cảm với Tần Kiêu ra, chưa bao giờ y rối bời đến thế.", "Y còn viết hẳn một bài dài, hồi tưởng lại quãng thời gian trong giới giải trí, nhớ về những gì người hâm mộ đã dành cho mình — sự ủng hộ, sự đồng hành. Nhưng cuối cùng, tất cả đều bị xóa sạch.", "Đằng nào cũng phải rời đi, không cần để lại thêm bất cứ điều gì khiến người ta lưu luyến làm gì. Tốt nhất là để mọi người dần quên y đi.", "Đăng xong dòng trạng thái ấy, y ngồi lặng đi một lúc lâu mới đứng dậy. Hôm qua vận động có phần quá sức, lưng còn hơi ê ẩm, hai chân đi lâu cũng run run, nhưng đều là chuyện nhỏ, nghỉ ngơi một lát là ổn.", "Tần Kiêu cũng đứng dậy, sóng vai cùng y bước đi.", "Y không hiểu lắm về Sở Cửu Biện và những \"người hâm mộ\" trên mạng kia có quan hệ gì với nhau, nhưng y cảm nhận được sự mất mát trong lòng người thanh niên lúc này. Vì thế y đưa tay, nắm lấy bàn tay bên cạnh.", "Sở Cửu Biện nghiêng đầu nhìn y.", "Người đàn ông mặc một bộ đồ thường ngày thoải mái, quần jean đen và áo thun, trông chẳng khác gì một sinh viên chưa tốt nghiệp. Chỉ có khí chất toát ra từ y lại trầm lắng đến mức không giống một chàng trai trẻ trong sáng, dễ mến chút nào — cộng thêm cặp kính râm và khẩu trang trên mặt, càng khiến y có vẻ gì đó u uất.", "So với y, Sở Cửu Biện lại thật sự thanh xuân, xinh đẹp.", "Ngoại hình của cả hai — chưa kể đến mái tóc dài khác thường của Tần Kiêu — chỉ riêng chiều cao thôi cũng đủ khiến ai đi ngang qua trong trung tâm thương mại cũng phải ngoái nhìn thêm vài lần.", "Cũng có người nhận ra họ, nhưng không ai dám tiến đến gần.", "Trong mắt Sở Cửu Biện ánh lên nụ cười, phần lớn là nhờ \"công lao\" của Tần Kiêu.", "Hai người dạo quanh trung tâm thương mại một vòng. Tần Kiêu biết Sở Cửu Biện ở \"Tiên giới\" cũng khá dư dả, nên tiêu tiền không hề khách sáo — thấy trái cây tươi ngon là muốn mua, thấy món đồ chơi lạ mắt là muốn mua, thấy kính râm hay đồng hồ đẹp cũng muốn mua. Nói chung là không hề có ý định để dành tiền giúp Sở Cửu Biện.", "Sở Cửu Biện cũng chẳng buồn phiền gì, y muốn gì thì mua cho y nấy.", "Sau khi mua vài bộ trang phục phù hợp với Bách Lý Hồng ở một cửa hàng thời trang thanh thiếu niên, hai người liền tìm một quán cà phê ngồi nghỉ.", "Họ ngồi ở góc trong cùng, tránh người qua lại — nếu không cố ý đi sâu vào trong, sẽ khó mà nhìn thấy họ.", "Tần Kiêu nhấp một ngụm cà phê, vị đắng lập tức tấn công vị giác, khiến y nhíu mày rồi đặt ly xuống.", "\"Không thích uống à?\" Sở Cửu Biện hỏi.", "Tần Kiêu gật đầu: \"Đồ uống ở Tiên giới các ngươi đều kỳ lạ thật.\"", "Sở Cửu Biện bật cười: \"Tiên giới của chúng ta khác với những gì ngươi tưởng tượng sao?\"", "\"Khác hoàn toàn.\" Tần Kiêu nghiêng đầu nhìn quanh, ánh mắt dừng lại nơi những ngọn đèn sáng rực, \"Có vẻ còn đặc biệt hơn cả những gì ta từng tưởng tượng.\"", "Những ngọn đèn sáng rực kia, cửa cần quét mặt mới mở được, rồi tự động đóng lại; những con đường thẳng tắp rộng rãi không cần dùng roi thúc ngựa vẫn có thể đi được xe...", "Sở Cửu Biện còn kể cho y nghe về những \"cỗ xe sắt\" có thể bay trên trời chở người, về những chiếc điện thoại có thể liên lạc với người ở nơi rất xa.", "Tất cả những điều đó, trước kia y chỉ được nghe Sở Cửu Biện miêu tả. Nhưng giờ đây, y đang tận mắt chứng kiến.", "Không ai biết Tiên giới thật sự trông ra sao, nên với Tần Kiêu, những gì y nhìn thấy chính là Tiên giới.", "Sở Cửu Biện chống cằm nhìn y: \"Nếu ngươi thích, chúng ta ở lại thêm vài ngày.\"", "\"Ừ.\"", "Bách Lý Hồng ngày mai mới quay về, nên hai người ở lại thêm chút thời gian cũng không sao.", "Tần Kiêu chợt nhớ ra chuyện gì đó, nói: \"Bệ hạ đột nhiên đến đây thế này, e là bên Đại Ninh sẽ nóng lòng.\"", "\"Sẽ không đâu, ta đã nói với Lục Nghiêu rồi.\" Sở Cửu Biện đáp.", "Y đã nhờ hệ thống gửi tin nhắn cho Lục Nghiêu, báo rằng mình sẽ đưa Tần Kiêu và Bách Lý Hồng ở lại Tiên giới hai ngày, nhờ y trông coi mọi việc trong triều.", "Lục Nghiêu tự nhiên ngoan ngoãn đồng ý, dù trong lòng chắc cũng tò mò về Tiên giới lắm. Nếu không phải hệ thống ra giá cắt cổ — mang một người qua đây tốn tới 500 điểm — Sở Cửu Biện đã ước gì mang thêm vài tín đồ sang chơi cho biết.", "Bách Lý Hồng vốn tưởng cữu cữu và tiên sinh lại rủ nhau đi hẹn hò riêng, không ngờ Lục Nghiêu tìm đến, bảo hai người kia đang ở Tiên giới, và hôm nay sẽ đưa cả y sang đó luôn.", "Cậu nhóc phấn khích đến mức bữa trưa cũng chẳng ăn cho tử tế, cứ ngồi đợi tiên sinh đến đón.", "Đến tận chạng vạng, đợi hơn nửa ngày, Bách Lý Hồng rốt cuộc cảm nhận được điều gì đó kỳ lạ — cảnh vật trước mắt bắt đầu méo mó, nhòe đi.", "Đôi mắt y sáng lên, theo bản năng đứng bật dậy. Ngay sau đó, một cảm giác mất trọng lượng cực độ ập tới, ánh sáng trắng chói lòa khiến y không tài nào mở nổi mắt.", "Trong quán cà phê.", "Sở Cửu Biện gọi cho Tần Kiêu một ly cà phê hơi ngọt, lần này y mới thấy tạm ổn, chầm chậm uống được vài ngụm.", "Nhìn Sở Cửu Biện uống cạn ly cà phê đắng của mình lúc nãy, Tần Kiêu bất chợt hỏi: \"Ngươi thích nơi này sao?\"", "\"Trước kia không thích.\" Sở Cửu Biện đặt ly xuống, \"Bây giờ thì không ghét nữa.\"", "Tần Kiêu cụp mắt, đầu ngón tay chầm chậm vuốt ve miệng ly.", "Một lúc lâu sau, y mới ngẩng lên nhìn Sở Cửu Biện, cười hỏi: \"Vậy sau này ngươi còn quay lại đây nữa không?\"", "Sở Cửu Biện ngẫm nghĩ rồi đáp: \"Có lẽ.\"", "Hệ thống vẫn sẽ luôn đi theo y, sau này nếu có việc cần, y có thể sẽ còn quay lại đây.", "Điện thoại chợt rung lên một tiếng. Sở Cửu Biện cúi đầu, thấy hệ thống gửi cho mình một vị trí định vị — trên bản đồ, một chấm nhỏ cách y chừng một trăm mét.", "Là Bách Lý Hồng đã đến.", "Y lập tức đứng dậy, kéo tay Tần Kiêu đi ra ngoài: \"Chồi non tới rồi.\"", "Ở đây, không có bệ hạ, cũng không có Nhiếp Chính Vương.", "Tần Kiêu xách theo mấy túi đồ vừa mua, cùng y bước ra ngoài.", "Không lâu sau, từ trên lầu nhìn xuống, họ thấy sảnh chính tầng một vây kín một đám người, náo nhiệt lạ thường. Giữa đám đông ấy, một cậu thiếu niên khôi ngô tuấn tú, mặc long bào sắc vàng rực, trên mặt nở nụ cười, tò mò quan sát mọi người xung quanh.", "Cậu bé mười tuổi bắt đầu cao lớn hơn, nhưng vẫn chỉ mới hơn một mét bốn, gương mặt vẫn còn nét bầu bĩnh trẻ con.", "Như có linh cảm, Bách Lý Hồng ngẩng đầu lên, liền thấy hai bóng người đứng nơi lan can tầng ba. Họ đeo kính râm và khẩu trang, nhưng chỉ liếc một cái, y đã nhận ra ngay, lập tức cười tít mắt, giơ tay vẫy vẫy về phía họ.", "Hai người cũng nhanh chóng bước xuống lầu. Đám đông tự động giãn ra, Bách Lý Hồng chạy nhanh tới, dừng lại cách họ chừng nửa bước, ngẩng đầu cười tươi: \"Cữu cữu, tiên sinh, chỗ này đẹp quá.\"", "\"Đi, về nhà trước đã.\" Sở Cửu Biện đặt tay lên vai y, dẫn y bước đi.", "Bách Lý Hồng ngoan ngoãn đi theo, thấy cữu cữu tay xách nách mang bao lớn bao nhỏ, liền vươn tay giúp cầm vài túi. Có hai người lớn đi hai bên, y không hề có chút bỡ ngỡ nào trước nơi xa lạ, chỉ hào hứng nhìn ngang nhìn dọc khắp nơi.", "Biết đây là Tiên giới, y cũng không cần giữ dáng vẻ đế vương nghiêm trang nữa, cứ như những ngày thường ở Dưỡng Tâm Điện, hoạt bát hiếu động, đôi mắt sáng long lanh.", "\"Tiên sinh, cái thang tự chạy kia lợi hại thật đấy!\" Y chỉ vào thang cuốn.", "Sở Cửu Biện liền dẫn y đi lên rồi lại đi xuống. Tần Kiêu xách đồ đứng dưới nhìn hai người, khóe mắt dưới vành mũ khẽ cong lên, ngậm nụ cười.", "Ba người rời trung tâm thương mại, thẳng hướng về nhà. Sở Cửu Biện gọi cơm hộp mang về, đợi Bách Lý Hồng thay đồ xong là có thể ăn ngay.", "Cậu nhóc vừa đi vừa hỏi, nhìn cái gì cũng thấy lạ lẫm. Y cũng biết tiên sinh đặc biệt kiên nhẫn với mình nên chẳng ngại ngần gì, biến thành cả trăm ngàn câu \"vì sao\".", "Sở Cửu Biện quả thực rất chiều cậu bé, trên đường còn tiện tay mua cho y bánh kem và kem que. Khác với Tần Kiêu, Bách Lý Hồng rất thích đồ ngọt. Chỉ có điều Tần Kiêu quản y, không cho ăn nhiều. Nhưng thỉnh thoảng nuông chiều một chút cũng chẳng cần quá khắt khe.", "Về đến nhà, Bách Lý Hồng thay dép lê, bước vào phòng liền như một chú cún con đi tuần tra lãnh thổ, chỗ nào cũng phải ngó nghiêng.", "\"Ồ! Cửa sổ to thế này! Toàn bằng pha lê cả!\"", "\"Tiên sinh tiên sinh, ngài xem tòa nhà đối diện cao quá! Ôi cái màn hình kia còn có ảnh của ngài nữa!\"", "\"Thì ra đây gọi là sofa, quả nhiên mềm hơn ghế dựa nhà mình nhiều.\"", "\"Ôi cái bàn đá cẩm thạch này đẹp quá, về nhà mình cũng phải sắm một cái mới được.\"", "Dù bị Tần Kiêu đẩy vào phòng tắm, tiếng reo hò kích động của cậu bé vẫn không ngừng vọng ra.", "\"Đây là bồn tắm ở Tiên giới à? To thật, thoải mái thật, mà lúc nào cũng có nước ấm nữa!\"", "\"Cái khăn thấm nước này lợi hại thật, còn hơn cả vải bông nhà mình.\"", "......", "Sở Cửu Biện và Tần Kiêu nhìn nhau, đều bật cười.", "Chỉ chốc lát, cơm hộp Sở Cửu Biện đặt đã giao tới. Bách Lý Hồng cũng rửa mặt đánh răng xong, mặc bộ áo phông quần đùi mới, cảm thán: \"Người ở Tiên giới quả là biết hưởng thụ, chẳng cần mặc áo choàng rườm rà gì cả, chỉ cần bận đồ lót bên trong là ra ngoài được rồi.\"", "Trong mắt y, những người hở tay hở chân trên đường hôm nay đều đang \"mặc đồ lót đi ra ngoài\" cả. Tuy có phần chướng mắt, nhưng lại rất tiện lợi, mà còn mát mẻ nữa.", "Kỳ lạ hơn, trong phòng này chẳng thấy tảng băng nào, vậy mà lại mát rượi, y cũng chẳng hiểu vì sao. Còn có những ngọn đèn kia, sáng trắng lóa mắt, sáng hơn cả đèn dầu nhiều — bên ngoài trời đã tối sầm mà trong phòng vẫn sáng như ban ngày.", "Nhưng rồi y chẳng còn tâm trí đâu để ý đến những chuyện đó nữa. Y ngồi xuống bên bàn, hít hà mùi thơm từ đống món ăn lạ lẫm bày trước mặt: \"Thơm quá tiên sinh, đây toàn là món gì vậy?\"", "\"Hamburger, gà rán, lẩu cay.\" Sở Cửu Biện lần lượt kể tên.", "Cậu bé khó khăn lắm mới đến được đây một chuyến, tất nhiên phải nếm thử chút \"đồ ăn vặt\" trứ danh. Đương nhiên bản thân Sở Cửu Biện cũng rất thèm, nhưng sợ Tần Kiêu kén ăn không quen, nên vẫn gọi thêm phần cơm bình thường và mì lạnh. Dù sao Tần Kiêu ăn khỏe, Bách Lý Hồng lại đang tuổi lớn, chút đồ ăn này hai cậu cháu thừa sức \"quét sạch\".", "Bách Lý Hồng nhận lấy phần hamburger Sở Cửu Biện đưa, cắn một miếng — chưa từng có món ngon nào khiến y không kìm được mà cắn thêm miếng nữa.", "Ngon quá!", "Ngon thật sự luôn!", "Cậu bé rốt cuộc hiểu thế nào là sống lại làm thần tiên!", "Sở Cửu Biện đưa cho y ly nước: \"Nếm thử xem có thích không.\"", "Đó là Coca Cola bỏ đá. Vừa nhấp một ngụm, đôi mắt Bách Lý Hồng liền hưởng thụ mà nheo lại. Trước mặt người ngoài, cậu bé rất có uy nghiêm, nhưng trước những người thân cận nhất, trong y vẫn luôn là một đứa trẻ hồn nhiên.", "Tần Kiêu bật cười: \"Ngon vậy sao?\"", "\"Ngon!\" Bách Lý Hồng đáp không chút do dự.", "Sở Cửu Biện chỉ vào phần hamburger còn chưa bóc của mình, nói với Tần Kiêu: \"Ngươi cũng nếm thử đi.\"", "Tần Kiêu nhích lại gần, nắm tay y, cắn một miếng từ chỗ y vừa cắn.", "\"Thế nào?\" Sở Cửu Biện hỏi.", "Tần Kiêu gật đầu: \"Không tệ.\"", "\"Vậy phần mới này ngươi ăn đi.\"", "\"Ừ.\"", "Bao năm qua, Bách Lý Hồng đã quen với sự thân mật giữa hai người, cứ như không nhìn thấy gì, tiếp tục ăn uống ngon lành. Khoai tây chiên, gà rán, lẩu cay — món nào cũng phải nếm thử một miếng.", "Ăn xong, Sở Cửu Biện lại dẫn hai người xuống phố dạo bộ tiêu cơm. Họ thong thả bước giữa ánh đèn rực rỡ của thành phố, cảm nhận một sắc thái hoàn toàn khác biệt so với Đại Ninh.", "Đi ngang qua một cửa hàng đồ uống, Bách Lý Hồng nắm chặt tay Sở Cửu Biện: \"Tiên sinh, kia có một người tuyết đang nhảy múa kìa.\"", "Sở Cửu Biện nhìn theo, hóa ra đó là linh vật quảng cáo trước cửa tiệm. \"Bên trong đó là người thật đấy.\" Y giải thích, \"Đó là linh vật của tiệm đồ uống phía sau. Con có muốn uống không?\"", "\"Muốn.\"", "Sở Cửu Biện liền dẫn y vào tiệm, mua ba ly. Cậu bé chọn vị trái cây, còn y và Tần Kiêu đều gọi nước chanh thường. Phần của Tần Kiêu không thêm đường, y nhấp một ngụm rồi gật đầu: \"Vừa miệng.\"", "Sở Cửu Biện bật cười, uống phần bảy phần ngọt của mình, rồi đan mười ngón tay vào tay Tần Kiêu — thế là thành mười phần ngọt.", "Ba người dạo tiếp, đến trạm chờ xe điện ngắm cảnh trên vành đai. Đây là tuyến đường sắt nhẹ mới khai trương gần hai năm nay, chạy vòng quanh đường vành đai hai, có thể ngắm trọn cảnh phố phường.", "Sở Cửu Biện trả tiền vé, ba người ngồi cạnh cửa sổ. Tàu chạy êm ru, khiến hai vị \"người xưa\" không ngớt lời trầm trồ.", "\"Sau này Đại Ninh nhất định cũng sẽ có loại xe tốt như thế này, sẽ có những tòa thành lâu tráng lệ như thế này.\" Bách Lý Hồng tựa vào cửa sổ, giọng nói khẽ đến mức người ngồi sát bên là Tần Kiêu cũng chẳng nghe thấy.", "Xuống tàu, Sở Cửu Biện lại dẫn hai người đến chợ đêm, cảm nhận thêm chút \"hơi thở trần gian\" của Tiên giới. Cả ba đều sung sức, cứ thế dạo cho đến gần mười hai giờ đêm mới về nhà nghỉ ngơi.", "Sáng sớm hôm sau, chưa đến sáu giờ, Bách Lý Hồng đã bật dậy khỏi giường. Đêm nay y sẽ phải rời khỏi nơi này rồi, mà tiên sinh còn hứa sẽ đưa y đi sở thú, rồi đi công viên giải trí, còn cho ăn thật nhiều món ngon nữa.", "Y rửa mặt đánh răng xong xuôi, ra khỏi phòng đã thấy tiên sinh dậy từ bao giờ. Sở Cửu Biện hâm nóng sữa, gọi thêm cháo nóng và vài món điểm tâm tinh tế. Hôm qua ăn nhiều đồ \"vặt\" như vậy, sáng nay ăn chút gì đó thanh đạm cho ấm bụng.", "Tần Kiêu rửa mặt xong cũng ra, cả ba cùng ngồi ăn sáng. Hôm nay ai nấy đều mặc đồ thể thao, kiểu dáng khác nhau nhưng đều toát lên phong thái riêng.", "Sở Cửu Biện lấy ba lô ra, nhét vào trong máy ảnh Polaroid, sạc dự phòng cho điện thoại, thêm khăn giấy và quạt cầm tay nhỏ, rồi đội lên đầu Tần Kiêu và Bách Lý Hồng mỗi người một chiếc mũ che nắng. Xong xuôi, cả ba xuống ga tàu điện ngầm.", "Đã lâu không lái xe, nhưng vừa cầm vô lăng, Sở Cửu Biện đã tìm lại cảm giác ngay. Y lái một chiếc xe địa hình, thẳng tiến đến khu vườn thú hoang dã ngoại ô.", "Bách Lý Hồng và Tần Kiêu chưa từng thấy những mãnh thú và giống loài quý hiếm thật sự như thế bao giờ, nhìn gì cũng lạ, đến cả mấy con khỉ cũng phải dừng chân ngắm nghía một hồi.", "Đến khu gấu trúc, Bách Lý Hồng nhất quyết không chịu rời đi, cứ bám lấy Sở Cửu Biện đòi chụp thật nhiều ảnh cùng gấu trúc.", "\"Đợi trẫm trở về, nhất định phải thỉnh hoàng thúc đưa hai con gấu trúc vào kinh, dễ thương quá đi mất.\"", "Bình Tây Vương còn chẳng hề hay biết bảo bối trên đất phong của mình đang bị nhòm ngó, chỉ là nếu biết được rằng ngàn năm sau, loài thú vốn hung dữ ấy lại trở thành giống loài quý hiếm ai cũng có thể ngắm nhìn tận mắt, chắc chắn sẽ không tin nổi.", "Cậu bé đã biết dùng điện thoại chụp ảnh, nên Sở Cửu Biện đưa máy cho y, còn mình cùng Tần Kiêu ngồi xuống chiếc ghế dài cách đó không xa.", "\"Uống nước đi.\" Tần Kiêu vặn nắp một chai nước, đưa cho Sở Cửu Biện.", "Sở Cửu Biện uống vài ngụm rồi trả lại, thấy người đàn ông uống hết luôn phần còn lại hơn nửa chai.", "Nói Tần Kiêu thật sự có năng khiếu làm bạn trai cũng chẳng ngoa. Cái kiểu vặn nắp chai cứng ngắc, rồi uống nốt phần nước thừa của người kia một cách tự nhiên — chẳng ai dạy mà y vẫn hiểu.", "Sở Cửu Biện bật cười. Tần Kiêu vặn chặt nắp chai, quay đầu lại bắt gặp người kia đang cười tủm tỉm nhìn mình, lòng chợt xao động, liền cúi xuống hôn nhẹ lên môi y.", "Xung quanh vang lên vài tiếng reo khe khẽ, từ nhiều hướng khác nhau.", "Hai ngày qua, họ đã quen với việc bị người khác nhìn chăm chú. Ở Đại Ninh họ vốn đã là tâm điểm giữa đám đông, giờ chỉ là đổi sang một nơi khác mà thôi.", "Nhiều người xung quanh sớm nhận ra họ chính là Sở Cửu Biện và người bạn trai bí ẩn. Ban đầu ai cũng khó chấp nhận, nhưng sau khi biết chuyện quá khứ của Sở Cửu Biện, mọi người đều nghĩ chỉ cần y hạnh phúc là được.", "Hơn nữa Tần Kiêu lại đẹp đến nao lòng, ngày càng nhiều người cho rằng, có lẽ chỉ có Tần Kiêu mới xứng với nhan sắc đỉnh cao của Sở Cửu Biện trong giới giải trí. Chỉ tiếc không ai biết thân phận thật sự của y — dù có bao nhiêu người \"truy lùng\" trên mạng, cũng chẳng ai lần ra được tung tích. Vì thế các thuyết âm mưu, suy đoán thần bí về y cứ thế mọc lên ngày một nhiều.", "Nhưng tất cả những điều đó chẳng hề ảnh hưởng gì đến cuộc sống thực của hai người.", "Chụp ảnh gấu trúc chán chê, Bách Lý Hồng lưu luyến chào tạm biệt, quay đầu thấy tiên sinh và cữu cữu đang ngồi sóng vai trò chuyện, liền giơ điện thoại lên. Ngay khoảnh khắc bấm nút chụp, y vừa vặn ghi lại cảnh Sở Cửu Biện hôn đáp lại Tần Kiêu.", "Chỉ là một nụ hôn thoáng qua, nhưng đúng lúc đã lọt vào ống kính của Bách Lý Hồng.", "Y nhìn màn hình, cười khúc khích, rồi chạy đến trước mặt hai người: \"Đi thôi tiên sinh, mình đi xem con vật khác nào.\"", "Ở đời thực, chuyện đôi tình nhân công khai thể hiện tình cảm trước mặt mọi người vốn dễ bị người ta bàn tán, chê cười. Nhưng Sở Cửu Biện và Tần Kiêu chẳng bận tâm ánh mắt người khác, muốn làm gì thì cứ làm.", "Ba người lại ngồi lên một chiếc xe kiểu lồng sắt, cùng vài vị khách khác băng qua khu mãnh thú. Hổ, sư tử, báo đen — bao nhiêu loài thú mang vẻ đẹp hoang dã cứ thế phô diễn trước mắt. Chúng đã quen với việc bị con người ngắm nhìn, con nào con nấy béo tốt, chỉ gầm gừ vài tiếng như làm nhiệm vụ, rồi nhận lấy phần thịt tươi được thả xuống từ trên xe.", "Bách Lý Hồng vốn rất mê vẻ đẹp hoang dã, mắt không rời, còn kéo tay Sở Cửu Biện và Tần Kiêu: \"Trẫm về sẽ nuôi một con!\"", "\"Không được.\" Cả hai đồng thanh từ chối.", "Bách Lý Hồng cười hì hì: \"Vậy thôi không nuôi vậy.\"", "Rồi ánh mắt y lại bị con vật khác thu hút, hò hét ầm ĩ, hoàn toàn là dáng vẻ một đứa trẻ bình thường, chẳng còn chút phong thái đế vương nào.", "Nhưng so với việc nuôi ra một đứa trẻ cô độc, Sở Cửu Biện và Tần Kiêu vẫn thích nhìn thấy y sống động, biết vui buồn giận hờn như thế này hơn.", "Rời vườn thú, ba người tìm chỗ ăn cơm. Ban đầu định thử món Âu, Sở Cửu Biện thấy cũng ngon, nhưng Tần Kiêu và Bách Lý Hồng đều ăn không quen, nên qua loa vài miếng rồi cả ba chuyển sang một quán ăn kiểu Đông Bắc. Món ăn ở đây hợp khẩu vị họ hơn hẳn, Bách Lý Hồng chụp ảnh từng món, bảo sẽ mang về cho Ngự Thiện Phòng học theo.", "Sở Cửu Biện bật cười, nghĩ bụng nên mua thêm vài cuốn thực đơn mang về. Ảnh chụp cùng vài công thức đơn giản thì có thể cho Tần Kiêu và Bách Lý Hồng xem, còn lại tạm thời chưa nên cho ai khác tiếp xúc.", "Ăn xong, Bách Lý Hồng vẫn thòm thèm, gói thêm một phần bánh bao nhân thịt mới chịu hài lòng rời đi.", "Đến công viên giải trí. Xe đua kart, ngựa gỗ xoay tròn, đu quay khổng lồ, thuyền cướp biển... Bách Lý Hồng lại một lần nữa cảm thán Tiên giới quả thực tuyệt vời, thảo nào ai cũng mơ ước thành tiên.", "Nhưng y không nghĩ vậy cho riêng mình. Y chỉ mong có thể đem những thứ ở Tiên giới này về Đại Ninh, để bách tính bình thường cũng có ngày được tiếp xúc với chúng.", "Xuống khỏi thuyền cướp biển, Bách Lý Hồng cảm khái: \"Tiên sinh ở Tiên giới cũng lợi hại thật đấy, hình như ai cũng biết ngài.\"", "Suốt dọc đường, y luôn nghe thấy đâu đó có người khẽ gọi \"Sở ca\", \"Sở Cửu Biện\". Lúc nãy trên thuyền cướp biển, mấy cô gái ngồi đối diện còn không màng chơi, cứ giơ điện thoại lên chụp lấy chụp để. Mỗi lần bị phát hiện, họ liền reo lên \"Sở ca\" ngay.", "Bách Lý Hồng trước đó vẫn tưởng tiên sinh ở Tiên giới là một vị thần tiên kín tiếng, không ngờ đi đến đâu cũng có người nhận ra, sùng bái y đến thế.", "Chỉ là, y để ý thấy sắc mặt cữu cữu có vẻ không vui lắm. Chắc là đang ghen.", "Sở Cửu Biện không giấu diếm cậu bé, chỉ đơn giản giải thích rằng mình là một ngôi sao nổi tiếng ở thế giới này, từng xuất hiện trên những màn hình lớn như hôm qua từng thấy, nên rất nhiều người biết đến y.", "Bách Lý Hồng nửa hiểu nửa không, nhưng cũng không truy hỏi thêm, lại chạy đi chơi trò khác. Y cố tình bước nhanh vài bước, nhường không gian cho cữu cữu và tiên sinh, nghĩ bụng chắc họ còn có chuyện riêng muốn nói với nhau.", "Sở Cửu Biện tự nhiên cảm nhận được sự thay đổi cảm xúc của người đàn ông bên cạnh, liền lập tức đan mười ngón tay vào tay y, như một lời tuyên bố chủ quyền. Tần Kiêu khẽ cười, nắm chặt lại.", "Chơi đến chạng vạng, cả ba dùng bữa tối ngay trong công viên, rồi trời dần tối hẳn. Đoàn xe hoa rực rỡ trôi trên mặt nước, Bách Lý Hồng nhìn những con rối kỳ lạ mà đáng yêu, cái nào cũng thích.", "Sở Cửu Biện cũng chiều y, mua cho y rất nhiều móc khóa nhỏ xinh, bỏ vào không gian riêng, hẹn khi về Đại Ninh sẽ mang theo. Chỉ là lúc này y chưa biết, về sau bên hông Bách Lý Hồng sẽ không còn đeo ngọc bội nữa, mà chỉ toàn những con thú bông nhỏ dễ thương này. Đây cũng trở thành một nét đặc trưng của y, được sử sách ghi lại bên cạnh những dòng \"tính trẻ con thuần hậu\", \"tâm tính thuần lương\", thậm chí còn được lưu truyền qua tranh vẽ đời sau. Người ta sẽ thấy hình ảnh một vị hoàng đế tuấn mỹ, lạnh lùng, mà bên hông lại lủng lẳng những món đồ nhỏ đáng yêu — một sự tương phản đến lạ.", "Không lâu sau, pháo hoa bừng nở, rực rỡ muôn màu. Bách Lý Hồng ăn nốt miếng xúc xích nướng cuối cùng, lòng đầy mãn nguyện, cười tủm tỉm vẫy tay chào hai người lớn: \"Tiên sinh, cữu cữu, các ngươi mau về sớm nhé, trẫm sẽ nhớ các ngươi lắm.\"", "Sở Cửu Biện cũng cười: \"Đi thôi, chúng ta sẽ về sớm.\"", "\"Nhớ nghỉ ngơi.\" Tần Kiêu dặn.", "Bách Lý Hồng gật đầu thật mạnh, rồi giữa bầu trời pháo hoa rực rỡ, y hoàn toàn biến mất khỏi thế giới này.", "Về đến Đại Ninh, cậu bé tràn đầy nhiệt huyết, lập tức triệu tập một loạt đại thần thân tín, bắt đầu ban bố hàng loạt chỉ dụ. Y đã học hỏi được rất nhiều điều từ Tiên giới, muốn để bách tính của mình cũng được sống sung túc, an vui như những \"tiên nhân\" kia. Nhưng y vẫn nhớ lời cữu cữu dặn dò, không vì công việc mà quên nghỉ ngơi, luôn chăm sóc bản thân thật tốt.", "Còn ở hiện đại, Sở Cửu Biện cũng đưa Tần Kiêu lên máy bay, chuẩn bị đi vòng quanh vài nước ngoài. Ngắm phong thổ khắp nơi, ghi nhớ vị trí địa lý — để sau khi trở về Đại Ninh, dù là mở rộng bờ cõi hay dùng đường biển để khai thông thêm những tuyến thương lộ xa hơn, kết nối với nhiều quốc gia hơn, đều sẽ có thêm lựa chọn và kế hoạch tốt hơn.", "Tất nhiên, đi ngắm phong thổ thì cũng phải tranh thủ hưởng thụ là chính — giờ đây Sở Cửu Biện không còn muốn để bản thân chịu thiệt thòi chút nào nữa.", "Hai người ngắm bình minh trên núi, ôm nhau giữa băng nguyên, ngồi thuyền ra khơi đuổi theo đàn cá heo hồng nhạt, lặn xuống đáy biển ngắm những con tàu đắm phủ đầy gỉ sắt. Có khi họ ngồi lì trên bãi cát cả nửa ngày trời, có khi lại ngâm mình trong suối nước nóng mãi không muốn rời.", "Núi tuyết, biển cả, suối khoáng — một góc trời đất riêng tư, không ai quấy rầy.", "Tần Kiêu đặt người thanh niên tựa vào thành hồ, mặt nước gợn sóng lan ra từng vòng, những bọt nước bắn lên rồi lắng lại giữa tóc hai người.", "Ánh mắt Sở Cửu Biện mơ hồ, chỉ còn lại những tiếng thở khẽ không kìm được nơi bờ môi.", "\"Tần Kiêu.\"", "\"Tần Kiêu...\"", "Y vô thức gọi tên người thương, hai tay vòng qua cổ Tần Kiêu, để mặc bản thân chìm trong cảm xúc mãnh liệt ấy.", "Tần Kiêu hôn nhẹ lên môi y, rồi chậm rãi hạ xuống, để lại dấu vết mờ nhạt nơi cổ y. Không biết bao lâu trôi qua, giữa vòng tay nhau, mọi khoảng cách như tan biến.", "Đến giây phút gần như trọn vẹn nhất, Tần Kiêu vẫn cố ý dừng lại, trêu đến khi nước mắt Sở Cửu Biện chực trào, y bất lực lắc đầu, không thể thốt nên lời trọn vẹn.", "Tần Kiêu lại nhẹ nhàng hôn lên môi y, ánh mắt sâu thẳm phản chiếu gương mặt ửng đỏ của người thương.", "\"Ngươi có định bỏ ta mà về không?\" Y hỏi bằng giọng rất khẽ.", "Đầu óc Sở Cửu Biện lúc này mơ màng như bị nhấn chìm, gắng gượng lấy lại chút tỉnh táo để nhìn người đối diện, lại giật mình run rẩy trước ánh mắt tối sầm đầy ẩn ý của Tần Kiêu, vô thức càng thu mình sát lại gần hơn.", "Gân xanh nơi trán Tần Kiêu hằn lên, rõ ràng đang cố kiềm chế đến mức tàn nhẫn với chính mình, khiến y trông càng nguy hiểm hơn.", "Nhưng rồi y lại bật cười.", "\"Ta sẽ không để ngươi rời khỏi ta.\" Tần Kiêu khẽ nhéo cằm Sở Cửu Biện.", "Thấy ánh mắt người thương tỉnh táo lại đôi chút, y lại tiếp tục, khiến Sở Cửu Biện run lên, một lần nữa chìm vào trạng thái mất phương hướng.", "Tần Kiêu nhìn chăm chú gương mặt ấy, bàn tay khẽ vuốt ve làn da mềm mại, giọng nói trầm thấp mà dịu dàng: \"Ngươi mà dám bỏ về, ta sẽ đốt miếu ngươi, giết tín đồ của ngươi cho xem...\"", "Sở Cửu Biện trong cơn mơ hồ nghe loáng thoáng mấy chữ \"đốt\", \"giết\", \"cướp bóc\" gì đó, liền giơ tay bịt miệng Tần Kiêu lại.", "\"Im đi.\"", "\"Đừng có giả vờ biến thái nữa.\" Y lẩm bẩm.", "Sau đó, y nghe thấy tiếng cười khẽ của người đàn ông.", "\"Đừng cười nữa.\" Sở Cửu Biện khó chịu vặn người, hàng mi dài khẽ run, mắt long lanh liếc Tần Kiêu một cái.", "\"Nhanh lên.\" Y khẽ giục.", "Tần Kiêu hầu kết khẽ động, không còn kiềm chế được nữa. Mặt nước trong hồ xao động không ngừng, sóng sánh tràn ra rồi lại dội vào.", "Dù đã bên nhau bao nhiêu năm, đôi lúc Sở Cửu Biện vẫn không chống đỡ nổi trước Tần Kiêu. Y cũng chẳng rõ Tần Kiêu học được những \"chiêu\" ấy từ đâu, khiến một người hiện đại như y hoàn toàn bó tay.", "Không biết đã qua bao lâu, khi ý thức dần trở lại, Sở Cửu Biện mới mơ màng mở mắt, thấy Tần Kiêu vẫn còn nằm trên người mình, đang cúi xuống hôn nhẹ lên môi y.", "Mí mắt nặng trĩu, y khẽ liếm môi Tần Kiêu, thì thầm: \"Ta ngủ đây, ngươi cứ tiếp tục.\"", "Tần Kiêu bật cười khẽ, quyết định làm một kẻ \"biến thái\" thực thụ đêm nay."], "id": 6, "wordCount": 6160}, {"title": "Chương 111 phiên ngoại tám", "paragraphs": ["Bách Lý Hồng nay đã mười một tuổi.", "Đây là năm thứ tám kể từ khi Sở Cửu Biện bước chân vào Đại Ninh, cũng là năm thứ bảy y và Tần Kiêu bên nhau.", "Kể từ sau chuyến ghé thăm Tiên giới năm ngoái, cậu bé vốn tràn trề năng lượng ấy rốt cuộc cũng tìm được nơi để trút bầu nhiệt huyết. Ngày ngày y cần mẫn lo toan chính sự, bận rộn hơn cả Tần Kiêu và Sở Cửu Biện trong hai năm đầu chấp chính.", "Đương nhiên, Tần Kiêu và Sở Cửu Biện cũng chẳng hề rảnh rỗi. Sau chuyến du ngoạn nước ngoài lần trước, Tần Kiêu đã hiểu rõ thế giới này rộng lớn đến nhường nào, rằng ngoài Đại Ninh không chỉ toàn là man di mọi rợ, mà còn vô số quốc gia khác biệt. Vì thế, y dồn gần như toàn bộ tâm sức vào sự nghiệp hàng hải, đích thân cùng các quan Công Bộ đốc thúc đóng những thuyền buôn cỡ lớn và chiến thuyền, đồng thời huấn luyện hải quân.", "Còn Sở Cửu Biện thì một lòng một dạ dồn tâm sức vào việc kiếm tiền. Khắp nơi hiện đều trồng những giống lúa năng suất cao — chính là giống lúa được cải tiến từ Tiên giới. Các địa phương cũng đã lập trường học, mở mang dân trí. Chính trị, nông nghiệp, văn hóa — mọi mặt đều đã đi vào quỹ đạo ổn định. Chỉ riêng khoản bạc tiền, dù có bao nhiêu cũng không đủ dùng.", "Sở Cửu Biện lại bắt đầu nghiên cứu thêm đủ thứ mới, còn Bách Lý Hồng thì ngày đêm mong mỏi có được nội thất tiện dụng, đường xi măng, xe đạp...", "Tháng năm, ba con thuyền buôn lớn nhất của Đại Ninh, dưới sự hộ tống của mấy chục chiến thuyền, khởi hành từ vùng duyên hải Đông Nam. Trên thuyền chở đầy hàng thủ công tinh xảo, gốm sứ, đồ thêu, cùng những đặc sản, món đồ mới lạ của Đại Ninh, chuẩn bị vượt biển đến những vùng đất xa xôi hơn.", "Trước đây, thuyền buôn Đại Ninh cũng đã từng ra khơi, nhưng chỉ giới hạn trong phạm vi các tiểu quốc lân cận ở vùng Đông Nam. Lần này, họ chuẩn bị tiến xa hơn thế.", "Thống lĩnh hải quân Tần Gia Thắng đích thân dẫn đội, cùng Thị lang Lễ Bộ Thái Bằng, Thị lang Hộ Bộ Tiều Thuận dẫn theo thuộc hạ phụ trách việc đàm phán, ngoại giao. Ngoài ra, các bộ khác cũng đều cử thêm ít nhiều quan viên tháp tùng.", "Ai nấy đều hiểu chuyến đi này đầy hiểm nguy, chẳng ai lường trước được trên biển sẽ có bao nhiêu sóng to gió lớn đang chờ đợi. Nhưng nếu bình an trở về, chờ đợi họ không chỉ là thăng quan tiến chức, mà còn là vinh dự khai mở cả một tuyến thương lộ rộng lớn cho Đại Ninh, đưa Đại Ninh thực sự tiếp xúc với thế giới bên ngoài.", "Có lẽ hiện tại họ vẫn chưa hình dung hết được ý nghĩa của việc Đại Ninh là nước đi tiên phong mở ra tuyến thương lộ này, nhưng Sở Cửu Biện thì hiểu rõ tầm quan trọng của nó hơn ai hết.", "Ở thời đại này, y dám khẳng định rằng xét về tổng thể quốc lực, Đại Ninh chính là mạnh nhất toàn cầu.", "Chở đầy những hàng hóa tiên tiến đến khắp nơi, chắc chắn sẽ gây chấn động lớn, thậm chí khiến các quốc gia khác phải kinh sợ. Nếu vận dụng khéo léo, Đại Ninh hoàn toàn có thể mở rộng lãnh thổ mà không cần dùng đến chiến tranh. Thời này chưa có khái niệm \"vùng biển quốc tế\" gì cả — Đại Ninh đi trước, chiếm được vùng đất nào thì vùng đất đó sẽ là của Đại Ninh.", "Quyết định lần này của Sở Cửu Biện và mọi người sẽ để lại ảnh hưởng sâu sắc cho hậu thế, đặt nền móng vững chắc cho vị thế cường quốc tuyệt đối của Đại Ninh trên trường quốc tế mai sau.", "Nhưng hiện tại, chẳng ai biết trước được chuyện gì sẽ xảy ra, thậm chí không dám chắc liệu đoàn thuyền ấy có thể bình an trở về hay không.", "Sở Cửu Biện thì thật ra không quá lo lắng. Thuyền được đóng chắc chắn, lại trang bị đầy đủ giáp trụ vũ khí, mặt an toàn cơ bản có thể yên tâm.", "Điều duy nhất đáng lo là thời tiết và sóng gió. May thay trên thuyền có tín đồ của y, nên mỗi ngày Sở Cửu Biện đều thông qua Thần Vực báo trước thời điểm mưa bão, đồng thời dùng chức năng của hệ thống để định vị chính xác vị trí các bãi đá ngầm, giúp đoàn thuyền tránh né kịp thời.", "Nhờ vậy, đoàn người ra khơi lần này có thể yên tâm với tỷ lệ an toàn khoảng chín mươi phần trăm. Nhưng dĩ nhiên không thể tuyệt đối an toàn — trên biển vẫn luôn có những chuyện ngoài ý muốn, bệnh tật rình rập, dù có ngự y đi cùng cũng khó tránh khỏi ít nhiều thương vong.", "Sở Cửu Biện đã dốc hết sức có thể để mang lại sự thuận lợi và an toàn nhất cho mọi người. Phần còn lại, đành phải nghe theo ý trời.", "Thấm thoắt, đoàn thương thuyền đã xuất phát hơn nửa năm, Đại Ninh lại một lần nữa đón Tết.", "Năm nay có phần khác mọi năm, bởi nhờ ân điển của Bách Lý Hồng, mấy vị hoàng thúc được mời vào kinh ăn Tết cùng nhau, các tướng lĩnh trấn giữ biên cương cũng đều được triệu về.", "Tướng lĩnh của Tây Bắc quân, Đông Bắc quân, Mạc Bắc quân lần lượt kéo về kinh thành.", "Thống lĩnh Tây Bắc quân hiện giờ vẫn là Khấu Kiều. Người này trước kia từng chỉ giữ chức Viên ngoại lang Binh Bộ trong triều, muốn giúp Tần Kiêu nói đỡ vài câu cũng còn lúng túng chẳng biết mở miệng ra sao trước các võ tướng. Vậy mà giờ đây, ở đúng lĩnh vực sở trường của mình, y như cá gặp nước, trưởng thành thành một mãnh tướng trấn giữ một phương, tính tình cũng phóng khoáng hơn hẳn.", "Tướng quân Nhiếp của Đông Bắc quân nay đã tuổi cao, không còn đủ sức đi đường xa, bèn cử cháu mình là Nhiếp Dũng Quan đến thay.", "Người này tuổi tác xấp xỉ Sở Cửu Biện, nhưng dưới gối đã có hai trai một gái, lần này đều đưa cả vào kinh.", "Y còn định để con gái ở lại kinh thành luôn, tìm cho nàng một mối hôn sự tốt.", "Nhưng cô con gái ấy lại thích quấn lấy Đàm Vũ Trúc — người vừa được thăng làm Thượng thư Lễ Bộ — rõ ràng chí hướng của nàng không nằm ở chuyện lấy chồng, mà muốn dấn thân vào con đường làm quan.", "Sở Cửu Biện chỉ khẽ điểm vài câu, Nhiếp Dũng Quan mới hiểu ra tâm tư của con gái, liền không còn ý định ép nàng lấy chồng nữa, ngược lại còn khuyến khích nàng nhân dịp này học hỏi thêm từ các vị quan lớn trong kinh, đợi sang năm đi thi khoa cử.", "Nhưng điều khiến Sở Cửu Biện vui mừng nhất, không gì hơn việc Giang Sóc Dã về kinh.", "Nam Cương Vương giờ cũng đã đến kinh. Tư Đồ Chiêu Linh dĩ nhiên cũng đi theo.", "Nàng nay đã ngoài hai mươi, nhưng vẫn giữ nguyên tính cách hoạt bát, phóng khoáng, vui vẻ điều hành thương hội Tây Nam, dường như năm tháng chẳng khiến nàng thay đổi mấy.", "Còn Tư Đồ Chiêu Nghiêu, nhờ nhiều năm rèn giũa tại viện nghiên cứu ở kinh thành, đã trở nên chững chạc, điềm đạm hơn hẳn.", "Có người giục y cưới vợ, y liền đáp ngay: \"Tỷ tỷ ta còn chưa lập gia đình, ta vội gì chứ? Huống hồ trong kinh này biết bao người lớn tuổi hơn ta còn chưa thành thân, có giục cũng chẳng đến lượt ta đâu.\"", "Y nói cũng chẳng sai.", "Trong kinh thành, những vị công tử tài hoa, tiểu thư danh giá vẫn chưa lập gia đình ngày một nhiều, nhiều vị lão thần trong lòng thầm cho rằng đó là do bị Sở Cửu Biện và Tần Kiêu ảnh hưởng.", "Nhưng người ta tuy không cưới hỏi chính thức, song hai người vẫn một lòng một dạ vì nhau. Còn lớp trẻ khác lại chỉ học được cái vế \"chưa thành hôn\", mà chẳng chịu học theo cái vế tìm lấy một người để vun đắp tình cảm trước đã.", "Vì thế, không ít lão thần rầu rĩ đến mức thấp thỏm, thỉnh thoảng cũng đánh tiếng bóng gió.", "Nhưng Tần Kiêu chỉ đáp lại: \"Vậy các ngươi cứ đi mà bảo đám trẻ đó, rằng ta với Thụy Vương yêu nhau tha thiết, một đời một kiếp chỉ một người, muốn học thì học lấy cái đó, đừng học các ngươi ba thê bốn thiếp.\"", "Mọi người: \"...\"", "Ba thê bốn thiếp gì chứ? Tổ tông nhà họ mà nghe được câu này chắc phải sống dậy mà mắng cho một trận vì cái tội dọa \"tuyệt tự\"!", "Đương nhiên, ngoài Sở Cửu Biện và Tần Kiêu ra, trong kinh vẫn còn không ít quan lớn chưa lập gia đình.", "Chẳng hạn như An Vô Tật, như Lục Nghiêu, Đàm Vũ Trúc, hay như Vương Kỳ Sâm — gia chủ đương nhiệm của Vương gia.", "Kể từ khi tiếp quản Vương gia, y đã chấn chỉnh gia phong ngày càng thanh liêm chính trực. Tuy cách quản giáo con cháu không còn khắt khe như trước, nhưng những phương diện khác lại càng nghiêm cẩn hơn.", "Đặc biệt về tài văn chương và thanh danh, nói y đứng đầu Đại Ninh cũng chẳng ngoa.", "Các bậc tộc lão nhà họ Vương ban đầu còn hài lòng lắm, nhưng năm này qua năm khác, gia chủ vẫn không chịu cưới vợ, khiến họ sốt ruột vô cùng.", "Có người liền tìm đến lão Thượng thư Vương Trí Viễn — nay đã gần tám mươi tuổi, nhưng nhờ không còn phải lao tâm khổ tứ, lại có ngự y y thuật cao minh chăm sóc, nên trông vẫn quắc thước, tinh thần minh mẫn.", "Chỉ có điều răng đã rụng gần hết. Sở Cửu Biện nghe chuyện liền cho làm cho ông một bộ răng giả, khiến lão nhân vui mừng khôn xiết.", "Vương Trí Viễn cũng lo lắng về chuyện hôn nhân của Vương Kỳ Sâm.", "Vương lão phu nhân qua đời năm thứ ba sau khi Vương Kỳ Sâm nắm quyền, từ đó chẳng còn ai quản thúc được y nữa. Vương Trí Viễn nghĩ, với tư cách bậc trưởng bối, mình quan tâm một chút cũng chẳng có gì sai.", "Sau khi ông nói xong, Vương Kỳ Sâm liền vâng dạ đồng ý, hứa nhất định sẽ để lại người nối dõi cho mình.", "Nhưng vừa quay đi, y liền tìm đến Vương Bằng Nghĩa, xin nhận một trong ba người con trai của ông ta làm con thừa tự dưới danh nghĩa của mình.", "Vương Bằng Nghĩa vốn cũng luôn thương người em này, hơn nữa khác với người ngoài, ông hiểu rõ Vương Kỳ Sâm không muốn miễn cưỡng chấp nhận một cuộc hôn nhân.", "Điều em trai mình khao khát là một tình yêu kiểu như tiếng sét ái tình, muốn học theo Ninh Vương và Thụy Vương, một đời một kiếp chỉ có một người.", "Vậy thì, dù có kén chọn một chút cũng không sao, dù sao còn trẻ, lại đã có người nối dõi rồi, tình yêu ấy tìm được lúc nào hay lúc đó.", "Bản thân Vương Kỳ Sâm dù đã ngoài ba mươi, vẫn mang dáng vẻ một công tử phong lưu phóng khoáng, năm tháng chẳng để lại chút dấu vết nào trên gương mặt y.", "Thậm chí khí chất cũng chẳng hề thay đổi.", "Anh em nhà Tư Đồ cùng y ngồi lại đúng chiếc bàn trong tửu lầu năm xưa từng gặp mặt lần đầu, chỉ khác là lần này có thêm Lục Nghiêu, bốn người đang quây quần đánh bài.", "Trước đây Sở Cửu Biện cũng đã bỏ ra năm trăm điểm để đưa Tư Đồ Chiêu Nghiêu vào Thần Vực, nên bao năm qua, mấy người họ liên lạc qua lại qua Thần Vực, thân thiết đến mức không thể thân thiết hơn.", "Đại Tư Tế cũng thường trò chuyện phiếm cùng họ cho vui, chỉ có điều chẳng ai dám nhắc đến Tần Kiêu trong Thần Vực, sợ rước họa vào thân.", "Lục Nghiêu từ trước đến nay chưa từng để lộ thân phận thật của Sở Cửu Biện chính là Đại Tư Tế, nên những người khác vẫn không hề hay biết.", "\"Mặt trời sắp lặn rồi, không biết Trì Phong ca hôm nay có vào thành kịp không nhỉ?\" Tư Đồ Chiêu Linh vừa nói vừa đánh ra hai lá bài, \"Đôi năm.\"", "\"Đôi sáu.\" Tư Đồ Chiêu Nghiêu đánh bài, \"Chắc chắn sẽ đến thôi, Trì Phong ca vốn giữ chữ tín, ta chưa từng thấy huynh ấy nói sai lời bao giờ. Với lại vừa nãy ta thấy An tổng quân dẫn người đi về phía cổng thành kia, chắc là đi đón người rồi.\"", "Lục Nghiêu cũng đánh bài, nói: \"Ta tính rồi, đợi ván này đánh xong, huynh ấy chắc cũng vừa hay đi ngang qua dưới lầu chỗ mình.\"", "\"Thật không đấy?\" Tư Đồ Chiêu Linh lần nào cũng phải kinh ngạc trước đầu óc của Lục Nghiêu, nhưng lần nào cũng theo bản năng mà không dám tin hẳn.", "Lục Nghiêu điềm tĩnh đáp: \"Ta có bao giờ đoán sai đâu.\"", "\"Ừ thì... cũng đúng...\"", "Vương Kỳ Sâm ném ra bốn viên xúc xắc đều là mặt Tam, nhếch môi nói: \"Không cần đi đón à?\"", "Lục Nghiêu điềm tĩnh ném ra viên xúc xắc \"Vương\".", "\"Hả?\" Vương Kỳ Sâm ngẩn ra nhìn bài trên bàn, \"Sao ta nhớ quân Vương đã ra hết cả rồi mà?\"", "Tư Đồ Chiêu Linh nhìn y, giễu cợt: \"Ai bảo huynh mất hồn mất vía làm gì?\"", "\"Ta có à?\" Vương Kỳ Sâm vẫn giữ nguyên vẻ mặt.", "Lục Nghiêu đã đặt nốt hai lá bài cuối cùng xuống: \"Ta lại thắng rồi.\"", "Mọi người: \"...\"", "Đánh bài với Lục Nghiêu thật sự chẳng có gì vui cả.", "Dưới lầu chợt vang lên tiếng ồn ào, Tư Đồ Chiêu Linh lập tức đứng bật dậy, chạy đến bên cửa sổ ngó ra ngoài: \"Ôi, đến thật rồi!\"", "Lục Nghiêu quả thực đáng sợ mà!", "Ba người còn lại cũng xúm đến bên cửa sổ.", "Nói ra thật khó tin, dù họ đã thân thiết với Giang Sóc Dã từ lâu, nhưng đây lại là lần đầu tiên họ thực sự gặp nhau ngoài đời.", "Mạc Bắc từ lâu đã yên ổn, Giang Sóc Dã cũng đào tạo được không ít tướng lĩnh xuất sắc dưới trướng. Lần này về kinh, y sẽ được phong hầu tước, và từ nay có thể ở lại kinh thành.", "Thật ra ngay sau khi y bình định xong Mạc Bắc, Sở Cửu Biện và Tần Kiêu đã định phong hầu cho y, triệu về kinh.", "Nhưng Giang Sóc Dã cho rằng tàn dư của vương đình Mục Hãn vẫn chưa dứt hẳn, nên xin hoãn việc sách phong, tiếp tục ở lại trấn giữ biên cương.", "Đến nay, khi kinh tế vùng biên đã phồn vinh, y mới yên tâm trở về.", "Một đoàn nhân mã chậm rãi tiến đến gần, dẫn đầu là An Vô Tật cưỡi ngựa cùng hai hàng Ngự Lâm Quân, phía sau là chủ tướng Mạc Bắc Quân Giang Sóc Dã, khoác nhuyễn giáp màu tối, gương mặt lạnh lùng nghiêm nghị.", "Đã rất lâu rất lâu rồi Giang Sóc Dã chưa về kinh, thậm chí đã lâu lắm y không đặt chân vào địa giới Trung Nguyên.", "Suốt chặng đường, chứng kiến Đại Ninh đổi thay từng ngày, y cũng như bao bách tính khác, trong mắt luôn ánh lên nụ cười.", "Càng vào sâu kinh thành, cảnh phồn hoa càng rõ rệt.", "Hai bên đường, không ít cửa hàng đã thay cửa kính, sáng sủa sạch sẽ, chỉ nhìn thôi cũng thấy lòng phấn chấn.", "Đến đoạn phố náo nhiệt nhất, Giang Sóc Dã bỗng như có linh cảm, đưa tay ra, tóm gọn một quả táo rơi từ trên cao xuống.", "Y ngước mắt nhìn lên, thấy nơi cửa sổ tầng hai có mấy bóng người quen thuộc đang đứng.", "Anh em Tư Đồ vẫn giống hệt như trong Thần Vực, ngoại hình rất giống nhau, chỉ khác một người hoạt bát nhanh nhẹn, một người trầm tĩnh hơn đôi chút, nhưng cả hai vẫn giữ nguyên tâm tính trẻ con.", "Lục Nghiêu mỉm cười, khẽ gật đầu chào y.", "Vương Kỳ Sâm khoác bộ trang phục hồng nhạt đặc trưng của mình, hôm nay hiếm hoi buộc gọn mái tóc dài vốn thường để xõa, trông có phần khác lạ.", "Nhưng gương mặt ấy vẫn đẹp như trước, bao năm qua chẳng hề thay đổi, y hệt như lần đầu tiên Giang Sóc Dã gặp gỡ trong Thần Vực.", "Vương Kỳ Sâm cười với y, khẽ vẫy vẫy quả táo trong tay.", "Rõ ràng quả táo trong tay Giang Sóc Dã cũng chính là do y ném xuống.", "Giang Sóc Dã cũng bật cười, nắm chặt quả táo, tiếp tục đi xa dần.", "An Vô Tật đưa y đến phủ đệ mà bệ hạ ban cho, đích thân dẫn y đi dạo một vòng, cuối cùng cười nói: \"Bệ hạ và các vị đại nhân đều bảo không cần vội, đợi ngươi nghỉ ngơi chỉnh trang xong rồi vào cung diện kiến cũng được.\"", "\"Đa tạ.\" Giang Sóc Dã gật đầu.", "Cả hai đều là võ tướng, từ lâu đã nghe danh nhau, nên nói chuyện cũng khá hợp.", "\"Lần này ngươi về kinh, có dịp chúng ta cùng luận bàn võ nghệ vài chiêu.\" An Vô Tật rõ ràng phóng khoáng, thân thiện hơn Giang Sóc Dã nhiều.", "Giang Sóc Dã cũng cười đáp: \"Vinh hạnh lắm.\"", "\"Được, vậy ta đi trước.\"", "\"Được.\"", "Giang Sóc Dã tiễn khách ra đến cổng phủ, đợi người đi khuất rồi mới vội vàng tắm rửa, thay một bộ áo choàng nhẹ nhàng, sau đó mới vào cung.", "Y đã biết, năm xưa khi cha ruột định giết mình, người cứu mạng y không phải Đại Tư Tế, mà chính là Sở Cửu Biện.", "Nhưng lúc ấy, người y cầu cứu rõ ràng là Đại Tư Tế.", "Giang Sóc Dã vốn không phải kẻ tầm thường ngờ nghệch, tư duy y kín kẽ, sớm đã nhìn ra được chân tướng.", "Đại Tư Tế và Sở Cửu Biện, chắc chắn là cùng một người.", "Chỉ là những người khác không hay biết, hoặc cũng giống như y, giả vờ không biết gì. Vì thế, khi Đại Tư Tế chưa chủ động để lộ thân phận, y cũng không tùy tiện nói ra chuyện này.", "Cứ coi như không biết gì, mọi thứ vẫn như cũ.", "Nhưng lần về kinh này, y vẫn tỉ mỉ chuẩn bị lễ vật.", "Không chỉ mang theo lễ dâng bệ hạ, mà còn chuẩn bị riêng một phần cho Sở Cửu Biện.", "Vào cung, y gặp Bách Lý Hồng tại Dưỡng Tâm Điện — giờ đã ra dáng một thiếu niên.", "Bệ hạ vẫn còn nét mặt bầu bĩnh trẻ con, khôi ngô tuấn tú như tạc bằng ngọc, thấy y liền tự mình đứng dậy nghênh đón, cười đến híp cả mắt.", "Trên người Bách Lý Hồng dường như mang một khí chất rất đặc biệt — vừa khiến người ta tôn kính, vừa không kìm được muốn thân cận.", "Giang Sóc Dã cung kính hành lễ, đợi Bách Lý Hồng đỡ mình dậy, y mới quay sang chắp tay cúi chào Tần Kiêu và Sở Cửu Biện.", "Đây cũng là lần đầu tiên Sở Cửu Biện tận mắt gặp gỡ tín đồ đầu tiên của mình trong đời thực, cảm giác thật đặc biệt.", "Bất kể là ai, đối với \"người đầu tiên\" bao giờ cũng có phần lưu tâm hơn.", "Sở Cửu Biện cũng không ngoại lệ.", "Giang Sóc Dã là tín đồ đầu tiên của y, là chỗ dựa duy nhất của y trong thế giới này vào những ngày y không nơi nương tựa.", "Vì thế đối diện Giang Sóc Dã, gương mặt Sở Cửu Biện không tự chủ mà toát ra vẻ thân thiết hơn hẳn.", "Thậm chí y còn chủ động lên tiếng, mời Giang Sóc Dã ngồi xuống ngay bên cạnh mình.", "Giang Sóc Dã biết y chính là Đại Tư Tế, trong lòng tự nhiên vừa kính trọng vừa gần gũi, vừa nghe lời mời liền lập tức đồng ý, ngồi sang bên cạnh.", "Hai người ngồi cạnh nhau, Sở Cửu Biện còn ra vẻ ân cần hỏi han vài câu về chuyến đi có mệt không, Giang Sóc Dã đều nghiêm túc đáp lại, giọng điệu ôn hòa chân thành.", "Tần Kiêu ngồi đối diện, nhìn bầu không khí thân thuộc giữa hai người, bỗng có cảm giác mình như người thừa, chẳng chen chân vào được.", "Khóe môi y vẫn giữ nụ cười, nhưng nụ cười ấy dần trở nên sâu hơn, còn ánh mắt lại thoáng nét u ám.", "Tần Kiêu nhớ rất rõ, Giang Sóc Dã cũng là tín đồ của Sở Cửu Biện.", "Y càng nhớ rõ hơn, có lần Giang Sóc Dã suýt mất mạng ngay trong chính phủ đệ mình, Sở Cửu Biện còn hiển linh đích thân đến cứu.", "Lúc ấy, Sở Cửu Biện còn đang ở trong vòng tay y, chuyện ân ái giữa hai người mới đến nửa chừng, người bỗng dưng \"thiếp đi\" mất.", "Đến khi \"tỉnh\" lại, Sở Cửu Biện còn ho ra máu.", "Đó là di chứng để lại từ lần y liều mình đi cứu Giang Sóc Dã.", "Lý trí mách bảo Tần Kiêu rằng giữa Sở Cửu Biện và Giang Sóc Dã chỉ là quan hệ thần minh với tín đồ, nhưng y vẫn không nhịn được mà đưa mắt đánh giá Giang Sóc Dã.", "Người này trẻ tuổi mà anh tuấn, đến chính Tần Kiêu cũng phải thừa nhận ngoại hình y quả thực không tồi. Bao năm trấn giữ biên cương lại còn khoác lên người một khí chất cứng cỏi, sắc bén đặc biệt.", "Theo cách nói của Sở Cửu Biện, kiểu người như thế này hình như gọi là mang \"khí chất nam tính chuẩn mực\" — kiểu đàn ông rất được ưa chuộng.", "Sở Cửu Biện vốn luôn thích đàn ông, nên suy đi tính lại, rất có thể Giang Sóc Dã chính là kiểu người rất có sức hút đối với y.", "Không hiểu sao Tần Kiêu bỗng nhớ đến một cụm từ mà Sở Cửu Biện từng nhắc tới — \"thất niên chi dương\" (ngứa ngáy năm thứ bảy).", "Sở Cửu Biện từng cười giải thích, \"ngứa ngáy năm thứ bảy\" nghĩa là khi hai người ở bên nhau đến năm thứ bảy, tình cảm thường sẽ nhạt dần đi.", "Rất nhiều đôi tình nhân chia tay đúng vào giai đoạn này.", "Dù không chia tay, cũng rất dễ bị người khác thu hút.", "Khi nói những điều này, bản ý của Sở Cửu Biện là muốn cảnh báo Tần Kiêu, dặn y đừng nghe lời đồn đại lung tung bên ngoài.", "Bởi lẽ gần đây, một số trưởng bối trong Tần gia bắt đầu thúc giục Tần Kiêu để lại con nối dõi, thậm chí còn úp mở nhắc đến vài tiểu thư nhà người ta.", "Tần Kiêu đều thẳng thừng từ chối, khẳng định cả đời này chỉ có một mình Sở Cửu Biện.", "Các vị tộc lão cũng không dám ép quá, nhưng vẫn thật lòng lo lắng cho việc kế thừa hương hỏa, nên tuy không dám nhắc lại chuyện thừa tự nữa, vẫn khéo léo mong Tần Kiêu có con.", "Một là trong tộc không có đứa trẻ nào thích hợp, hai là Tần Kiêu vốn không phải người không thể sinh con, vậy chi bằng cứ để y tự nỗ lực.", "Chuyện này đến tai Sở Cửu Biện, khiến y cũng thấy trong lòng không mấy thoải mái.", "Nhưng Tần Kiêu quả thực đã từ chối những đề nghị ấy, còn tuyên bố thẳng sẽ ở bên y trọn đời, quyết tâm rõ ràng đến vậy, nên Sở Cửu Biện cũng chẳng còn lý do gì để trách móc y.", "Chỉ là trong lòng vẫn không mấy dễ chịu, nên y mới vòng vo nhắc khéo Tần Kiêu một chút.", "Nhưng giờ đây, những lời ấy trong đầu Tần Kiêu lại mang một ý nghĩa khác hẳn.", "Càng nghĩ, Tần Kiêu càng cảm thấy — liệu có phải Sở Cửu Biện đang chán mình rồi không?", "Nhìn dáng vẻ Sở Cửu Biện trò chuyện vui vẻ cùng Giang Sóc Dã, Tần Kiêu càng thấy ngực mình như nghẹn lại, khó chịu đến phát điên.", "Hai người tuy là lần đầu gặp mặt ngoài đời, nhưng trong Thần Vực — nơi y không hề hay biết — Sở Cửu Biện có lẽ đã gặp gỡ Giang Sóc Dã không biết bao nhiêu lần rồi.", "Sở Cửu Biện tự nhiên cảm nhận được ánh mắt của Tần Kiêu, nhưng y mặc kệ.", "Nên để Tần Kiêu có thêm chút cảm giác khủng hoảng, kẻo y thật sự nảy sinh những suy nghĩ không nên có!", "Người trong cuộc yêu, càng để ý đối phương thì càng dễ suy nghĩ vẩn vơ.", "Nhiều lúc chính họ cũng biết rõ mình đang nghĩ ngợi thừa thãi, nhưng vẫn không tránh khỏi bất an, căng thẳng — tất cả cũng chỉ vì quá để tâm đến nhau.", "Nhưng cả hai đều sĩ diện, nên thường chẳng chịu nói thẳng nỗi bất an của mình, chỉ âm thầm kìm nén, cho đến khi bị đối phương nhận ra chút manh mối.", "So với Sở Cửu Biện, Tần Kiêu có phần biết kiềm chế bản thân hơn.", "Hơn nữa về mặt lý trí, y hiểu rõ Sở Cửu Biện không có tình ý gì với người khác, nên chỉ mỉm cười, chưa hề để lộ biểu hiện gì bất thường.", "Nhưng Giang Sóc Dã vốn là người cẩn trọng, chỉ cần thấy trong ánh mắt Tần Kiêu nhìn mình có thêm chút dò xét, y liền rùng mình trong lòng.", "Chỉ có điều đường tình cảm của y luôn có phần \"lạc lối\", nên chẳng hề nghĩ đến chuyện Tần Kiêu đang ghen, chỉ cho rằng Ninh Vương vốn tính cẩn trọng nên mới thế, vì vậy y lại càng cố tỏ ra thoải mái, đường hoàng hơn.", "Nhưng chính thái độ ấy của y lại càng khiến Tần Kiêu thêm nhỏ nhen, khó chịu.", "Tần Kiêu quay mặt đi, không thèm nhìn y nữa, chỉ chăm chăm nhìn Sở Cửu Biện, khóe môi nhếch lên, cười mà như không cười.", "Ngồi thêm một lúc, Giang Sóc Dã mới xin cáo lui, Sở Cửu Biện liền đứng dậy tiễn y.", "Tần Kiêu vẫn ngồi nguyên tại chỗ, nghiêng đầu nhìn theo hai bóng người, một trước một sau, khuất dần sau cánh cửa, nụ cười trên mặt y chẳng thể giữ vững nổi nữa.", "Bách Lý Hồng chống tay lên cằm nhìn y, khó hiểu nghiêng đầu.", "\"Cữu cữu, ngài không vui à?\"", "Lúc nãy chẳng phải vẫn còn vui vẻ lắm sao?", "Tần Kiêu thu ánh mắt lại nhìn y, cười đáp: \"Không có gì.\"", "Bách Lý Hồng nghi hoặc nhìn y, rồi lại quay sang nhìn Sở Cửu Biện vừa trở vào, đoán có lẽ hai người lớn đang giận nhau.", "Nhưng không sao cả, hai người này dính nhau như sam, chắc chưa đến mười lăm phút đã làm lành rồi.", "Bách Lý Hồng mặc kệ họ, cúi đầu lo phê duyệt tấu chương của mình.", "\"Người đi rồi à?\" Tần Kiêu hỏi Sở Cửu Biện.", "\"Ừ.\" Sở Cửu Biện ngồi xuống chỗ của mình, thái độ điềm tĩnh lạ thường.", "Tần Kiêu thấy y mở tấu chương ra bắt đầu phê duyệt, khựng lại một chút, rốt cuộc không nói thêm gì nữa.", "Chuyện này cứ thế trôi qua, chẳng ai nhắc lại nữa.", "Sau đó, thánh chỉ sách phong được đưa đến tay Giang Sóc Dã, y lại vào cung tạ ơn, nhưng lúc ấy Sở Cửu Biện đang ở Quốc Tử Giám nên không gặp mặt y.", "Không hiểu sao Tần Kiêu lại thấy nhẹ nhõm hẳn đi.", "Thấy Sở Cửu Biện không hề lén lút gặp riêng Giang Sóc Dã, Tần Kiêu dần dần cũng gạt chuyện này ra sau đầu, không cố ý suy nghĩ thêm nữa.", "Ngược lại, nhân dịp Tết vui vẻ, các vị tộc lão Tần gia lại nhắc đến chuyện con nối dõi với y.", "Tần Kiêu đau đầu, lần này nói thẳng thắn hơn hẳn, tuyên bố cả đời mình sẽ tuyệt tự, khiến các vị tộc lão sợ đến suýt quỳ sụp xuống.", "Nhưng vẫn có người khẽ nhắc, rằng nếu không thì đợi trong tộc có đứa trẻ thích hợp, sẽ nhận làm con thừa tự.", "Tần Kiêu nghĩ đến còn có Tần Xuyên, nên không vội đồng ý ngay, chỉ nói để sau này tính tiếp.", "Chuyện này đến tai Sở Cửu Biện, khiến tâm trạng y trở nên phức tạp lạ thường.", "Một mặt, y cảm động vì Tần Kiêu có thể vì mình mà làm đến mức này, thật lòng thật dạ biết bao. Mặt khác, y lại nghĩ dù sao Tần Kiêu cũng là người của thời đại xưa, lỡ như sau này y hối hận, muốn có một đứa con thì phải làm sao đây.", "Không được.", "Sở Cửu Biện cảm thấy cái tật hay vòng vo, khó nói thẳng của mình lại bắt đầu tái phát.", "Nên tìm dịp nói chuyện thẳng thắn với Tần Kiêu mới phải — nói rõ ràng ra, để sau này nếu Tần Kiêu thật sự muốn có con, cũng không trách được là do mình không nói trước.", "Và cơ hội ấy đến rất nhanh.", "Đêm ba mươi Tết, màn đêm buông xuống, các quan viên đều vào cung dự yến mừng năm mới, dâng lễ vật chúc Tết bệ hạ.", "Đây là cái Tết thứ tám kể từ khi Sở Cửu Biện đến Đại Ninh, cũng là cái Tết thứ tám y đón cùng Tần Kiêu.", "Yến tiệc trong cung kết thúc, mọi người lại cùng nhau ngắm pháo hoa — đây đã trở thành một tiết mục thường niên không thể thiếu.", "Các nha môn địa phương cũng được phân bổ pháo hoa riêng, đêm giao thừa này sẽ đốt pháo hoa cho toàn thành hoặc toàn trấn cùng chiêm ngưỡng.", "Pháo hoa ở kinh thành và các nơi khác tuy giống hệt nhau, nhưng được cùng người mình quan tâm ngắm nhìn, tự nhiên vẫn đẹp hơn hẳn.", "Sở Cửu Biện và Tần Kiêu đứng phía sau Bách Lý Hồng, như bao năm đã qua, cùng y ngắm pháo hoa, đón giao thừa.", "Đợi đến khi các quan lại lần lượt cáo lui, Giang Sóc Dã liền một mình xin thỉnh Sở Cửu Biện lui bước riêng, rồi lấy ra một con dao găm do chính tay mình rèn khi còn trấn giữ biên cương, đưa cho y.", "\"Bao năm qua được ngài chiếu cố, thuộc hạ không có gì báo đáp, mong ngài nhận lấy món quà nhỏ này.\" Giang Sóc Dã cung kính nói.", "Sở Cửu Biện thật sự vừa bất ngờ vừa vui mừng, không hề khách sáo mà nhận lấy ngay.", "Y từng để lộ diện mạo thật trước Giang Sóc Dã, nên tự nhiên đoán được đối phương đã biết thân phận thật của mình. Thái độ của y trong lần gặp gần đây càng khiến Sở Cửu Biện xác nhận điều đó.", "\"Đa tạ.\" Sở Cửu Biện dịu giọng nói lời cảm ơn.", "Giang Sóc Dã cúi người vái chào: \"Vậy thuộc hạ xin cáo từ trước.\"", "\"Đi tìm họ uống rượu à?\" Hôm qua trong Thần Vực, Sở Cửu Biện đã nghe Vương Kỳ Sâm đề nghị mọi người cùng nhau uống rượu đón giao thừa.", "Gương mặt vốn lạnh lùng cứng cỏi của Giang Sóc Dã hiếm hoi thoáng nét cười, y gật đầu: \"Vâng, đã hẹn rồi.\"", "\"Đi đi.\" Sở Cửu Biện dặn dò, \"Đừng để Tiểu Linh uống nhiều quá đấy.\"", "Dù sao nàng cũng là con gái duy nhất trong nhóm, tự nhiên cần được chăm sóc nhiều hơn.", "Giang Sóc Dã nghiêm túc đáp: \"Thuộc hạ tuân lệnh.\"", "Đợi y rời đi, Sở Cửu Biện quay người lại, liền thấy Tần Kiêu đang khoanh tay, tựa lưng vào bức tường không xa.", "Y khoác trên mình bộ mãng bào đen thêu hoa văn vàng kim, gần như giống hệt bộ trang phục Sở Cửu Biện đang mặc.", "Bóng dáng cao lớn của người đàn ông ấy quá nửa chìm trong bóng tối, thấy Sở Cửu Biện rốt cuộc quay đầu nhìn về phía mình, y khẽ nhếch môi cười lười biếng, giọng nói phảng phất chút hơi men: \"Công tử rốt cuộc cũng nhớ đến bổn vương rồi đấy.\""], "id": 7, "wordCount": 5646}, {"title": "Chương 112 phiên ngoại chín", "paragraphs": ["Sở Cửu Biện cười, đứng cách đó không xa, tay khẽ xoay xoay một con dao găm.", "\"Đại nhân thấy con dao găm này thế nào?\" Y hỏi.", "Tần Kiêu liền thẳng người bước tới, đến khi gần như dán sát vào người Sở Cửu Biện mới chịu dừng lại, chỉ cần y hơi cong lưng một chút là có thể hôn lên môi đối phương.", "\"Cũng không tệ.\" Tần Kiêu căn bản chẳng buồn nhìn con dao găm ấy, \"Còn công tử, tự mình thấy thế nào?\"", "\"Ta cũng thấy không tồi.\" Sở Cửu Biện hơi nghiêng đầu, tiếp tục ngắm nghía chuôi dao.", "Vòng eo bỗng siết chặt, y liền bị kéo sát vào lồng ngực rắn chắc của nam nhân phía trước.", "Lúc này y mới ngước mắt lên, từ dưới nhìn lên người đối diện, ánh mắt lấp lánh nụ cười.", "\"Cố ý chọc giận ta phải không?\" Trên môi Tần Kiêu còn vương mùi rượu, khiến Sở Cửu Biện cũng thấy hơi ngà ngật.", "Y cất con dao găm vào không gian riêng, cùng lúc cả người đã bị nam nhân bế ngang lên.", "Theo thói quen, y vòng tay ôm chặt cổ Tần Kiêu, vùi mặt vào lồng ngực đối phương, bên tai chỉ nghe tiếng gió vù vù, tuyết bay phủ đầy một thân.", "Tần Kiêu bước đi nhanh như gió, chẳng mấy chốc đã về đến Dưỡng Tâm Điện.", "Ngự lâm quân trực đêm thấy cảnh này đã quen, chẳng lấy làm lạ. Thấy Ninh Vương lại bế Thụy Vương ung dung đi trong cung như vậy, ai nấy đều hiểu ngay là Thụy Vương hôm nay mệt, hoặc giả lười cất bước.", "Ban đầu mọi người còn nghĩ hai vị vương gia này khó mà bền lâu, nhưng bao nhiêu năm trôi qua, giờ nếu có ngày nào đó hai người không quấn lấy nhau như thế mới là chuyện lạ.", "Về đến Dưỡng Tâm Điện, cung nhân bên Tây viện vừa thấy tư thế quen thuộc ấy liền tự giác chuẩn bị sẵn nước ấm và bữa khuya.", "Hai vị chủ tử, đêm nào cũng phải gọi nước ít nhất hai lần, giữa chừng có khi còn ăn thêm chút gì đó.", "Mà hai vị chủ tử chẳng biết ngượng này, giờ phút ấy đã vào phòng.", "Cửa phòng khép lại sau lưng hai người, hơi ấm trong phòng xua tan cái lạnh dọc đường, nhưng khi bị lột sạch đặt lên giường, Sở Cửu Biện vẫn khẽ run.", "Trong phòng không thắp đèn, chỉ có ánh trăng, nhưng đủ để Sở Cửu Biện nhìn rõ trong đáy mắt nam nhân là một luồng cảm xúc mãnh liệt.", "Đó là dục vọng bị dồn nén đã lâu, cộng thêm chút hơi men khiến ngọn lửa trong người càng bốc cao.", "Xem ra là thật sự giận không nhẹ.", "Đến lúc này Sở Cửu Biện mới thấy hơi sợ, nhưng lại càng thêm hưng phấn.", "Suy cho cùng, y vốn có phần khác người thường, luôn khao khát những thứ càng kích thích càng tốt, đặc biệt là với Tần Kiêu — càng kịch liệt, càng thô bạo, y lại càng thấy cuốn.", "Vì vậy y vuốt ve bờ ngực rắn chắc của nam nhân, ánh mắt nhìn thẳng vào Tần Kiêu, chẳng sợ \"chết\", còn cố tình đổ thêm dầu vào lửa:", "\"Không biết đại nhân với tướng quân, ai có thân hình đẹp hơn nhỉ.\"", "Nói về vóc dáng, Giang Sóc Dã quanh năm luyện binh, tự nhiên có phần cường tráng hơn Tần Kiêu.", "Nhưng thân hình Tần Kiêu bao năm vẫn vậy, cơ bắp săn chắc thon dài, từng khối cơ đều vừa vặn hoàn hảo, không thừa không thiếu, như thể sinh ra để hợp gu Sở Cửu Biện.", "Cho nên dù có bao nhiêu người đứng trước mặt, ánh mắt đầu tiên của Sở Cửu Biện vẫn luôn dừng lại ở Tần Kiêu.", "Y cũng chỉ nảy sinh ham muốn với một mình Tần Kiêu mà thôi.", "Nhưng y lại không chịu nói thật lòng, mắt thấy sắc mặt Tần Kiêu mỗi lúc một trầm xuống.", "Dường như đã rất lâu, mà cũng dường như chỉ mới thoáng qua, Tần Kiêu bật cười, nụ cười ấy chẳng hề chạm tới đáy mắt.", "\"Ai đẹp hơn thì ta không biết.\" Bàn tay chai sạn của Tần Kiêu nắm lấy phần thịt mềm nơi chân thanh niên, khẽ dùng lực khiến y hoàn toàn phơi bày ra tư thế đón nhận.", "\"Nhưng ai khiến ngươi thoải mái nhất, trong lòng bổn vương lại rõ hơn ai hết.\" Thần sắc Tần Kiêu có chút tàn nhẫn.", "Tim Sở Cửu Biện thót lên một cái.", "Ánh mắt nam nhân chậm rãi lướt từ gương mặt y xuống dưới, từng tấc từng tấc dò xét khắp thân thể, cuối cùng dừng lại ở một chỗ.", "Một luồng xấu hổ sâu sắc ập đến, cổ họng Sở Cửu Biện khẽ động, theo bản năng muốn khép hai chân lại, nhưng bị nam nhân giữ chặt, không cho cơ hội.", "Y định đưa tay che lại, nhưng lại bị Tần Kiêu lật úp mặt xuống.", "Sau đó Tần Kiêu rút dây lưng, trong ba nhịp đã trói hai tay thanh niên ra sau lưng, rồi đặt y tựa vào gối mềm.", "Đây là một tư thế còn khiến người ta xấu hổ hơn.", "Hai tay bị trói ra sau lưng, còn thua xa bị trói ra trước.", "Bị trói ra trước, ít nhiều Sở Cửu Biện vẫn còn cảm giác an toàn, có thể tự mình chống đỡ thân thể; nhưng bị trói ra sau, cả người y như mất hết khả năng tự chủ, chỉ có thể bị động đón nhận mọi trêu chọc của nam nhân.", "Đêm đó, sự chiếm hữu giữa hai người thật lâu và thật đậm.", "Tần Kiêu như muốn cho y một bài học nhớ đời, chọc ghẹo hết lần này đến lần khác mà nhất quyết không chịu buông tha dễ dàng.", "Sở Cửu Biện cũng như đang hờn dỗi với y, nước mắt rơi nơi khóe mắt mà không chịu buông một lời mềm mỏng.", "Rõ ràng chỉ cần y mở miệng, Tần Kiêu sẽ cho y bất cứ điều gì y muốn.", "Hai người cứ thế giằng co trong một bầu không khí khó gọi thành tên, cũng giống hệt như thứ vi diệu vẫn luôn tồn tại giữa họ suốt bấy nhiêu năm.", "Rất lâu sau, cả hai đều đã thấm mệt.", "Tần Kiêu sớm đã cởi trói cho y, mà ngọn lửa trong lòng y cũng dần hoà vào từng tiếng rên khe khẽ không kìm được của thanh niên bên dưới, biến thành một thứ càng khó dập tắt hơn.", "Sở Cửu Biện nằm dưới thân y, lồng ngực phập phồng, đuôi mắt ửng hồng, trên người in đầy dấu vết y để lại.", "Tần Kiêu nhìn y, rất muốn tiến thêm một bước nữa.", "Muốn nhìn thanh niên hoàn toàn chìm đắm vì mình, nhưng y lại không kìm được nhớ đến cảnh hôm nay đối phương đứng cười nói vui vẻ cùng một nam nhân khác, ngọn lửa trong lòng lại bùng lên.", "Y cúi xuống, nhìn chăm chú vào Sở Cửu Biện, giọng khàn khàn: \"Bảo bối.\"", "Y biết Sở Cửu Biện thích được gọi như vậy.", "Quả nhiên, hàng mi Sở Cửu Biện khẽ run, trong mắt nhìn y cũng gợn lên chút cảm xúc khác lạ.", "\"Chỉ cần dỗ ta một câu thôi mà cũng khó vậy sao?\" Tần Kiêu nhẹ nhàng vuốt má y, dịu dàng vô cùng.", "Nhưng phía dưới lại chẳng hề nương tay, chỉ vừa chạm đến là lại rời đi.", "Sở Cửu Biện siết chặt cánh tay y, cảm giác ấy còn khó chịu đựng hơn tất cả những gì trước đó, y hận không thể tự mình đón lấy.", "Nhưng lý trí lại khiến y cố chấp không chịu nhượng bộ.", "Lúc này, ai chủ động trước, người đó coi như thua.", "Dù bản thân hai người cũng chẳng rõ rốt cuộc đang tranh giành điều gì.", "Tần Kiêu tự mình cũng khó chịu không kém, gân xanh nổi rõ nơi thái dương, cánh tay căng cứng.", "\"Bảo bối, chỉ cần nói ngươi muốn, ta sẽ cho ngươi ngay.\"", "Sở Cửu Biện vẫn im lặng.", "\"Có muốn ta vào không?\"", "Tần Kiêu tiếp tục hỏi.", "\"Gọi một tiếng tướng công, tướng công sẽ thương ngươi.\"", "Câu sau càng quá đáng hơn câu trước, Sở Cửu Biện chỉ nghe thôi đã đỏ bừng cả mặt lẫn tai, càng đừng nói mở miệng.", "Y ngước mắt, liếc nam nhân một cái.", "Ánh mắt ấy chứa đầy tâm tư kín đáo, như một cái móc câu.", "Tần Kiêu khựng lại một nhịp, rồi không nhịn được nữa, lập tức tiến vào.", "Cả hai đồng thời cảm nhận một khoái cảm chưa từng có.", "Sở Cửu Biện cảm thấy mình như đóa hoa run rẩy giữa mưa gió, khẽ rùng mình không ngớt.", "\"Bảo bối.\" Tần Kiêu ngồi dậy, siết chặt đưa thanh niên vào lòng, hôn thật sâu lên môi y, gần như khiến y nghẹt thở.", "\"Ta coi ngươi như báu vật của đời mình.\" Nam nhân thì thầm, tay vùi vào mái tóc rối của thanh niên.", "Sở Cửu Biện ngồi trong lòng y, khẽ nghẹn ngào: \"Tần Kiêu...\"", "\"Ừ, ta ở đây.\"", "\"Ta muốn ngươi.\" Giọng thanh niên rất khẽ, nhưng đủ để Tần Kiêu nghe rõ từng chữ.", "Trái tim y trong khoảnh khắc ấy mềm nhũn.", "\"Được.\" Y đáp.", "Sau đó, Sở Cửu Biện mới thấm thía thế nào là \"nói được làm được\" của nam nhân này — nói cho, thì thật sự khiến y mệt lả.", "Nghe những tiếng nghẹn ngào đứt quãng của thanh niên, trong lòng Tần Kiêu chỉ thấy khoan khoái.", "Không biết bao lâu trôi qua, đến khi Sở Cửu Biện khóc đến gần như kiệt sức, Tần Kiêu mới chịu buông tha.", "Nước ấm và bữa khuya được mang tới, Tần Kiêu quen tay lau rửa sạch sẽ cho cả hai.", "Lau xong, y bỗng nhớ đến bồn tắm và suối nước nóng từng dùng khi còn ở Tiên giới.", "Đêm đó hai người tuy hoang đường đến cực điểm, nhưng cảm giác trải nghiệm cũng thuộc hàng nhất nhì.", "Tần Kiêu ép mình gạt suy nghĩ ấy sang một bên, dù sao cũng phải cho Sở Cửu Biện ăn chút gì đã.", "Sở Cửu Biện biếng nhác tựa vào thành thùng tắm, nhìn ánh mắt kia là biết ngay y lại đang nghĩ gì, chỉ có điều giờ y cũng đã nghỉ đủ, thật ra cũng muốn thêm một lần nữa.", "Trước kia y chưa từng nghĩ mình là người ham muốn nhiều, thỉnh thoảng lắm mới tự mình giải quyết.", "Nhưng từ sau khi có Tần Kiêu, y dường như bắt đầu đắm chìm trong chuyện này.", "Bụng sôi lên một tiếng, Sở Cửu Biện tạm gác lại tâm tư ấy.", "Bữa tiệc tối vốn đã không ăn no, vừa rồi lại tiêu hao bao nhiêu sức lực, vẫn nên lót dạ trước đã.", "Hai người ăn đơn giản bát cháo trắng với rau xào, rồi đánh răng rửa mặt.", "Tần Kiêu ra ngoài trả lại hộp thức ăn, Sở Cửu Biện nhân lúc đó lấy ra bộ \"quần áo\" mua từ thế giới hiện đại, khoác thêm áo trong bên ngoài, rồi giả vờ như chẳng làm gì mà chui vào ổ chăn.", "Tần Kiêu vào phòng cũng không tắt đèn, nương ánh đèn mờ mờ lên giường, thuận tay kéo Sở Cửu Biện vào lòng.", "Sở Cửu Biện ngửa đầu nhìn y.", "Bốn mắt chạm nhau, Tần Kiêu bật cười, cúi xuống hôn nhẹ lên môi y.", "Nhẹ nhàng, lưu luyến mà dịu dàng.", "\"Đừng nghĩ vẩn vơ.\" Tần Kiêu khẽ nói.", "Sở Cửu Biện nhướng mày: \"Nghĩ vẩn vơ gì chứ?\"", "\"Ta đã nói không cưới vợ, không sinh con.\" Tần Kiêu nhìn thẳng vào y, \"Nếu không yên tâm, ngươi cứ hỏi ta bao nhiêu lần cũng được, lần nào ta cũng sẽ trả lời.\"", "Y từng nói với Sở Cửu Biện một lần rằng mình sẽ không cưới vợ sinh con.", "Nhưng gần đây rõ ràng Sở Cửu Biện bị mấy vị tộc lão nhà họ Tần tác động, Tần Kiêu ban đầu tưởng mình đã cam đoan rồi thì y sẽ không nghĩ ngợi nhiều.", "Nhưng y cũng hiểu tính Sở Cửu Biện, vốn hay hờn dỗi, lại thiếu cảm giác an toàn, chắc chắn sẽ muốn hỏi đi hỏi lại không ngừng để xác nhận.", "Chỉ là đối phương lại quá mạnh mẽ, quá lý trí, nên về lý trí y biết Tần Kiêu sẽ không phản bội mình, nhưng về tình cảm vẫn muốn được xác nhận thêm lần nữa.", "Thế nên mới càng ngày càng hờn dỗi.", "Giờ đây Tần Kiêu chỉ muốn nói cho y biết, dù Sở Cửu Biện có hờn dỗi thế nào, có muốn hỏi đi hỏi lại tìm sự an ủi bao nhiêu lần, y cũng sẽ nghiêm túc trả lời, mỗi lần đều cho y một đáp án.", "Kỳ thực trong lòng Tần Kiêu, kiểu phản ứng này của Sở Cửu Biện rõ ràng là để ý đến y, là đang làm nũng với y, y vui còn không kịp.", "Tầm mắt Sở Cửu Biện khẽ chớp, không tự nhiên, rồi lại nhìn về phía Tần Kiêu, hỏi: \"Thật không?\"", "\"Thật.\"", "\"Vậy nếu ta ngày nào cũng hỏi thì sao?\"", "\"Ngươi mỗi ngày hỏi mười lần, trăm lần cũng chẳng sao cả.\"", "Sở Cửu Biện khẽ cười: \"Ninh Vương đại nhân càng ngày càng biết nói lời ngọt.\"", "\"Vậy Thụy Vương đại nhân không định học theo, dỗ dành nam nhân của mình một câu sao?\" Bàn tay Tần Kiêu không yên phận, vuốt ve nơi lưng eo y.", "Nhưng khi chạm phải một sợi dây mảnh giấu dưới lớp áo trong, ánh mắt y thoáng đổi khác.", "Cảm giác này quá quen thuộc, hẳn là loại xiêm y ấy.", "Sở Cửu Biện mặc kệ y sờ soạng, một tay ôm lấy lưng nam nhân, tay kia lặng lẽ lấy ra một nhành hoa nhài từ không gian riêng.", "Toàn bộ sự chú ý của Tần Kiêu đều bị món đồ giấu dưới lớp áo trong hấp dẫn, căn bản chẳng để ý gì đến động tác của y.", "Cho nên khi Sở Cửu Biện cầm nhành hoa nhài giơ lên, cài lên vành tai mình, thần sắc nam nhân rõ ràng sững lại.", "Ý nghĩa của hoa nhài với hai người họ không cần nói cũng hiểu, nhưng Tần Kiêu chưa từng cố ý lấy chiếc khăn tay ấy ra cho Sở Cửu Biện xem, còn Sở Cửu Biện cũng chưa từng nói cho y biết, mình đã từng ngắt xuống một đóa hoa y từng chạm vào.", "Tần Kiêu một tay ôm lấy eo thanh niên, tay kia định đưa lên chạm vào đóa hoa, nhưng đầu ngón tay lại dừng lại nơi vành tai mịn màng của y, khẽ vuốt ve.", "\"Hoa này từ đâu ra?\" Giọng nam nhân rất nhẹ, trong mắt phản chiếu khuôn mặt tinh nghịch của thanh niên.", "Sở Cửu Biện không chớp mắt nhìn y: \"Ngày ngươi xuất chinh lần đầu, ta ngắt trong sân.\"", "Tần Kiêu khựng lại.", "Nhớ về cảnh tượng ngày mình xuất chinh, dục vọng trong đáy mắt y dần lui đi, thay vào đó là một cảm xúc vô cùng phức tạp.", "Sở Cửu Biện có chút ngượng ngùng, cũng có chút lúng túng.", "Nhưng vẫn cất tiếng: \"Ngươi cứ yên tâm đi. Ta là người kỹ tính, lớn chừng này rồi cũng chỉ để tâm đến một mình ngươi, sau này cũng sẽ không để tâm đến ai khác nữa.\"", "Những lời ấy, chính là đang giải thích rằng y chưa từng có ý gì khác với bất cứ ai.", "\"Nếu ngươi để ý, sau này ta đi Thần Vực cũng sẽ mang theo ngươi.\" Sở Cửu Biện nói.", "Tần Kiêu cho y đủ cảm giác an toàn, đương nhiên y cũng muốn đáp lại tương xứng.", "Không hẳn chính xác, nhưng đại khái là ý ấy.", "Tần Kiêu không ngờ Sở Cửu Biện có thể nói ra những lời như vậy, tim đập càng lúc càng nhanh.", "Bao nhiêu năm nay, y chưa từng nghe được một câu bày tỏ lòng dạ nào từ Sở Cửu Biện.", "Nhưng y hiểu, với trải nghiệm và tính cách của đối phương, để nói ra được những lời như thế khó chẳng khác nào lên trời.", "Thậm chí việc y có thể rộng lòng đón nhận một người, đã là điều khó tin đến mức nào rồi.", "Nhưng câu nói hôm nay, kỳ thực chẳng khác gì một lời thổ lộ.", "Tần Kiêu vô cùng rõ ràng nhận ra, Sở Cửu Biện cũng yêu y, chỉ là bằng một cách hờn dỗi và vụng về.", "Sở Cửu Biện nói xong thì tai đỏ bừng, nhưng mặt lại cố giữ vẻ lạnh lùng, trông càng như đang cố tỏ ra xa cách nghìn dặm.", "Y có chút thấp thỏm nhìn Tần Kiêu, rồi liền bị đối phương ôm chặt hơn, một nụ hôn nóng bỏng đáp xuống.", "Vừa sâu, vừa gấp.", "Nhành hoa nhài bên vành tai lay động, nhưng trước sau vẫn không rơi xuống.", "Sở Cửu Biện lại một lần nữa bị nam nhân chiếm hữu, lần này đối phương dịu dàng khác thường, hoàn toàn khác với sự thô bạo nóng nảy ngày thường.", "Cảm giác ấy không đủ mãnh liệt, nhưng lại khiến Sở Cửu Biện thấy mới mẻ.", "Tần Kiêu hôn y hết lần này đến lần khác, dường như bao nhiêu cũng không đủ.", "Y thật lòng yêu thương Sở Cửu Biện đến vậy.", "Ánh trăng khẽ nghiêng, ngọn đèn dầu lay động.", "Dưới ánh sáng ấy, tấm lụa đỏ mỏng manh cùng làn da trắng nõn của thanh niên càng thêm lộng lẫy mê người.", "Trong chuyện này, rốt cuộc Tần Kiêu cũng chẳng dịu dàng được lâu, mà Sở Cửu Biện lại càng thích sự mãnh liệt hơn.", "Huống hồ bộ xiêm y ấy trên người thanh niên còn khiến Tần Kiêu càng lúc càng quá đáng, nhất là khi biết chính những lời trêu ghẹo thô tục của mình lại càng khiến Sở Cửu Biện hưng phấn hơn, y liền càng lấn tới.", "Đến cuối cùng, Sở Cửu Biện cắn vai y khóc xin tha, bị ép gọi mấy tiếng \"tướng công\" mới được buông tha.", "Rửa mặt đánh răng sạch sẽ xong, thanh niên chìm vào giấc ngủ say.", "Tần Kiêu nương ánh trăng ngắm gương mặt y, không nhịn được cúi xuống hôn nhẹ giữa đôi mày.", "Kỳ thực y cũng không rõ mình bắt đầu có tình cảm khác với Sở Cửu Biện từ khi nào.", "Có thể là lúc thấy thanh niên với chút khiêu khích hỏi y có muốn đánh cược một phen hay không.", "Cũng có thể là lúc nhìn y ôm lấy tiểu bệ hạ dỗ dành, dùng thuật chế băng ngang hàng thế lực với y để mặc cả điều kiện.", "Hoặc cũng có thể, là ngày mưa ấy dưới mái hiên, thanh niên với khí phách ngùn ngụt hỏi y \"có muốn đổi lấy một triều đình khác không\".", "Cũng có thể là một khoảnh khắc nào khác chẳng đáng để tâm.", "Đến khi tỉnh ngộ lại, y phát hiện trong đầu mình những ký ức thuộc về Sở Cửu Biện đã ngày một nhiều.", "Y nhớ rõ mỗi lần đối phương rời khỏi Dưỡng Tâm Điện, bóng dáng đơn độc mỏng manh in trên nền tường son cung điện; nhớ rõ ánh mắt tuyệt vọng thoáng qua trong mắt y sau mỗi lần tự làm tổn thương thân thể mình; nhớ rõ ánh sáng lóe lên trong đáy mắt y mỗi khi cố gắng để được tồn tại.", "Tuy không rõ mình yêu Sở Cửu Biện từ lúc nào, nhưng Tần Kiêu lại nhớ rất rõ, mình xác nhận được lòng mình vào lúc nào.", "Đó là khi nhìn thấy thi thể một đứa trẻ bị cắt tóc theo đúng kiểu của Sở Cửu Biện, khi cơn thịnh nộ trong lòng y suýt chút nữa không kìm được.", "Ngày hôm đó, y xác nhận mình có lòng chiếm hữu với Sở Cửu Biện.", "Nhưng thân phận, gia quốc, sự nghiệp còn dang dở, tất cả đều buộc y không được phép vướng bận chuyện nhi nữ tình trường, nên y cố kìm nén, không cho phép mình bước qua ranh giới nửa bước.", "Mãi đến đêm mưa hôm ấy trong kinh thành, y đưa thanh niên trở về Dao Đài Cư.", "Trong bóng tối ẩm ướt, cảm nhận được vai đối phương khẽ chạm vào vai mình, y rốt cuộc không kìm được nữa, ôm chầm lấy người, hôn lên môi đối phương.", "Y tự nhủ với bản thân và với Sở Cửu Biện, chỉ một lần này thôi.", "Nhưng lúc đó đầu óc y thực sự trống rỗng, còn sau đó đọng lại trong lòng, ngoài chút hối hận vì sự bồng bột của mình, chỉ là một khoảng trống mênh mông.", "Y càng lúc càng không thể khống chế được bản thân.", "Y muốn Sở Cửu Biện.", "Mỗi khi không thấy đối phương, trong lòng y chỉ toàn nghĩ về y; khi đứng trước mặt đối phương, y lại chỉ nghĩ làm sao để y hoàn toàn thuộc về mình.", "Y thậm chí bắt đầu nuôi một tia hy vọng viển vông, bắt đầu dò xét xem liệu Sở Cửu Biện có, dù chỉ một chút, tình cảm khác với y hay không.", "Nhưng dường như là không.", "Sau chuyến trở về từ Tây Bắc thập tử nhất sinh, y biết mình không thể buông Sở Cửu Biện xuống được nữa.", "Bởi trong khoảnh khắc biết mình khó lòng sống sót, điều y nghĩ đến không phải thiên hạ, không phải trăm dặm giang sơn, mà là vì y biết có Sở Cửu Biện ở đó, thì dù là thiên hạ hay trăm dặm giang sơn, đều còn chỗ để nương tựa.", "Cho nên lúc ấy y chỉ nghĩ, tất cả chỉ có Sở Cửu Biện.", "Y nghĩ nếu không có mình, một mình đối phương sẽ phải gánh vác cả giang sơn to lớn này thế nào, phải che chở trăm dặm giang sơn ra sao, phải một mình chống chọi với bao nhiêu ác lang.", "Rõ ràng những điều ấy đáng lẽ phải là trách nhiệm của một Ninh Vương như y, vậy mà cuối cùng lại đổ hết lên vai một mình Sở Cửu Biện.", "Y thấy hổ thẹn trong lòng, càng thêm xót xa và day dứt.", "Y nghĩ, dù có chết, cũng phải được gặp lại đối phương một lần trước khi nhắm mắt.", "Vì thế y đã gắng gượng cả một hơi thở để trở về kinh thành.", "Sở Cửu Biện vẫn luôn nghĩ rằng lời đánh cược y nói trước khi ra đi là cược xem đối phương có cứu được mình hay không.", "Nhưng thực ra điều Tần Kiêu đánh cược, là chính mạng sống của bản thân mình, sống hay chết.", "Y nghĩ nếu mình còn tồn tại, dù chỉ còn một hơi thở, cũng phải để Sở Cửu Biện biết lòng mình.", "Nhưng khi thực sự gặp lại người, y lại chẳng còn chút can đảm nào để nói ra những lời ấy.", "Y chỉ nghĩ, nếu có chết thì cũng phải chết cho có thể diện, đừng để Sở Cửu Biện thấy mình trong bộ dạng tàn tạ ấy.", "Nhưng đối phương đã cứu y.", "Thanh niên vốn hay hờn dỗi, ấy vậy mà vì cứu y lại mắc phải chứng đau đầu, ngất xỉu.", "Dù giờ đã khỏi hẳn, nhưng mỗi khi nhớ lại, Tần Kiêu vẫn thấy đau lòng.", "Y biết Sở Cửu Biện cứu mình vì rất nhiều lý do, chỉ là y không kìm được tự hỏi, liệu có một phần nào đó, là vì đối phương cũng để ý đến y hay không?", "Nhưng khả năng ấy quá đỗi mong manh.", "Thế mà giờ đây, Sở Cửu Biện lại lấy ra đóa hoa nhài y đã chạm vào trước ngày xuất chinh.", "Y cất giữ nó lâu như vậy, chắc chắn không phải vì rảnh rỗi không có việc gì làm, cho nên rất có thể, ngay từ lúc đó Sở Cửu Biện đã thật sự động lòng với y.", "Tần Kiêu chưa bao giờ dám cho mình niềm hy vọng viển vông ấy.", "Trong mắt y, tình cảm Sở Cửu Biện dành cho mình là thứ mà y phải từng bước tiến đến gần, mặt dày mày dạn mới có được.", "Chỉ cần y có một chút do dự, đối phương sẽ không ngần ngại lùi xa hơn.", "Nhưng giờ đây y dường như đã hiểu Sở Cửu Biện hơn một chút.", "Có lẽ khi đó, dù đối phương chưa hẳn đã hiểu rõ lòng mình, nhưng trong tim đã có chỗ dành cho y.", "Tần Kiêu càng nghĩ, lòng càng mềm nhũn, không kìm được ôm chặt hơn người trong lòng.", "Sở Cửu Biện ngủ mơ màng, khẽ cau mày không vui, trở mình quay lưng về phía y.", "Tần Kiêu lặng lẽ mỉm cười, lại ôm chặt y lần nữa, chỉ là không dùng sức mạnh như trước, sợ đánh thức người.", "Lần thứ hai, hai người ngủ đến tận khi mặt trời lên cao, ra khỏi cửa đã thấy Bách Lý Hồng cùng Tiểu Ngọc Tử đang đắp người tuyết ngoài sân.", "Đây đã là thói quen hai người duy trì suốt bao nhiêu năm qua.", "Cứ vào đông có tuyết, đến ngày mùng một Tết, hai người sẽ cùng nhau đắp một người tuyết, làm cho có mắt có mũi hẳn hoi.", "Trước kia không có máy ảnh hay điện thoại, nên Bách Lý Hồng thường gọi họa sĩ đến vẽ lại cảnh mình cùng Tiểu Ngọc Tử và người tuyết.", "Giờ có máy ảnh rồi, Bách Lý Hồng không chỉ kéo theo Tiểu Ngọc Tử, mà còn gọi cả Hồng công công và Tiểu Tường Tử đến, cùng nhau chụp ảnh.", "Dù sao cũng đỡ vất vả cho họa sĩ, y cũng chẳng cần áy náy gì.", "Khi Sở Cửu Biện và Tần Kiêu bước vào chính viện, cả đám người đang cười đùa ầm ĩ chụp ảnh.", "Cung nhân bình thường không biết máy ảnh là gì, chỉ có những người thân cận mới rõ, mọi người vừa xem ảnh vừa cười nói vui vẻ.", "\"Bệ hạ, có thể cho thầy trò chúng con chụp một tấm không?\" Hồng Phúc cười tủm tỉm hỏi Bách Lý Hồng.", "\"Đương nhiên được, trẫm chụp cho.\" Bách Lý Hồng chỉ huy Hồng công công đứng trước cửa đại điện, rồi gọi Tiểu Tường Tử và Tiểu Ngọc Tử mỗi người đứng một bên.", "Ba người đều cười tủm tỉm, trông như từ một khuôn đúc ra, chẳng khác nào một nhà.", "Sở Cửu Biện khoác áo choàng đứng từ xa nhìn, cười nói: \"Hồng công công trông càng thêm tinh thần.\"", "\"Người có mục tiêu mới có động lực.\" Tần Kiêu cũng cười, \"Nửa đời trước lão ấy sống khổ, nửa đời sau có hai đứa đồ đệ ngoan, coi như cũng tự tại.\"", "Sở Cửu Biện nghiêng đầu nhìn y: \"Ngươi rốt cuộc là muốn có con phải không?\"", "\"Không cần.\" Tần Kiêu dứt lời liền áp sát vào y, \"Nếu ngươi sinh, thì ta chịu.\"", "\"...\" Sở Cửu Biện liếc y một cái, cất bước đi vào trong viện.", "Tần Kiêu khẽ cười, theo sau.", "Thấy hai người đến, mọi người rối rít hành lễ, Bách Lý Hồng kéo cả hai lại cùng người tuyết chụp ảnh chung.", "Trước mặt người thân cận, cậu nhóc Bách Lý Hồng vẫn cứ như một đứa trẻ chưa lớn, một tay ôm lấy cánh tay một người, cười đến híp cả mắt.", "Tiểu Ngọc Tử đổi góc độ giúp mọi người chụp.", "Hồng Phúc và Tiểu Tường Tử đứng cạnh nhau.", "\"Thời gian trôi nhanh thật.\" Hồng Phúc cảm khái.", "Tiểu Tường Tử cười nói: \"Đúng vậy sư phụ, ngoảnh đi ngoảnh lại bệ hạ đã lớn thế này rồi.\"", "Hồng Phúc mỉm cười nhìn Bách Lý Hồng, trên gương mặt cậu bé như thể có thể tìm thấy bóng dáng của người xưa.", "Nếu tiểu thư trên trời có nhìn xuống, hẳn cũng chẳng còn gì phải vướng bận, có thể yên tâm đầu thai chuyển kiếp.", "\"Thủy tiên áo gió, Tiểu Ngân Tử đâu rồi.\" Sở Cửu Biện cất tiếng gọi, \"Chúng ta cũng chụp vài tấm.\"", "Y quay đầu nhìn về phía Tiểu Tường Tử, vẫy tay gọi.", "Tiểu Tường Tử lập tức chạy tới.", "Tần Kiêu cầm máy ảnh, qua màn hình nhìn thanh niên bị mấy người vây quanh, không tự chủ được mà khẽ cười dịu dàng.", "Màn trập bấm xuống, những người từng ở Dao Đài Cư năm nào giờ đã có thêm tấm ảnh chụp chung ngày Tết thứ hai.", "Bách Lý Hồng lại gọi Sở Cửu Biện và Tần Kiêu chụp ảnh cùng nhau.", "Cậu rất thích cảnh cữu cữu và tiên sinh đứng cạnh nhau, đẹp mắt vô cùng.", "Mọi người đứng thành hàng, ngước mắt lên đã thấy hai bóng dáng đứng trước cửa đại điện.", "Cả hai đều khoác áo bào thêu kim tuyến màu tối, một người khoác thêm áo choàng trắng bạc, một người khoác áo choàng đen, mười ngón tay đan vào nhau...", "Đêm hôm ấy, quan giám chính Khâm Thiên Giám nhìn thiên tượng mà thở dài không dứt.", "Chẳng phải trước đây từng nói Thụy Vương khắc Ninh Vương hay sao?", "Vậy mà giờ đây, ngôi sao tuế tinh của Thụy Vương lại như sắp cưỡi hẳn lên trên đầu Ninh Vương rồi.", "Trong phòng ngủ ở viện phụ của Dưỡng Tâm Điện.", "Sở Cửu Biện ngồi trên đùi Tần Kiêu, muốn trốn đi, nhưng vòng eo nhỏ đã bị bàn tay nam nhân giữ chặt.", "Nhịp thở gấp gáp vang lên.", "————————!!————————", "Đã \"lên xe\" rồi đó [xin mọi người ủng hộ]", "Chương sau, tiểu bệ hạ và Tần Xuyên nhận nhau làm người thân, tiểu cữu và Ninh Vương sẽ cùng nhau \"phiêu bạt giang hồ\", sống những ngày ngọt ngào nơi thôn dã."], "id": 8, "wordCount": 5101}, {"title": "Chương 113 phiên ngoại mười (nhân vật phụ xuất hiện nhiều)", "paragraphs": ["Mùng một Tết, bách quan đều được nghỉ lễ.", "Đêm ba mươi, Lục Nghiêu cùng đám bạn thân trong Thần Vực tụ họp ăn uống, coi như tổ chức một bữa tiệc đàng hoàng đón Giang Sóc Dã trở về, mãi đến khi trời tờ mờ sáng mới trở về phủ.", "Rượu họ uống đều là loại rượu trái cây, nồng độ không cao, nên dù uống khá nhiều, chỉ cần đi vài bước là hơi men cũng tan bớt.", "Về đến phủ, đám hạ nhân định theo hầu đưa y về sân, bị y ngăn lại.", "Từ khi ổn định chỗ đứng trong kinh thành, y đã đón cha mẹ cùng các em ruột về ở cùng.", "Những người khác trong tộc thì vẫn ở lại quê nhà, nhưng nhờ có một vị đại nhân Thượng Thư quyền cao chức trọng như Lục Nghiêu đứng trong triều, cuộc sống của họ hàng còn lại trong tộc cũng khấm khá hẳn lên.", "Lục Nghiêu lo sợ những người này ỷ vào danh tiếng của mình mà khinh nam trọng nữ, ức hiếp kẻ khác, nên đã đặt ra quy định: hễ trong tộc có con trẻ, bất kể trai gái, đủ bảy tuổi đều có thể được đưa lên kinh, để đích thân y dạy dỗ.", "Nhưng gia đình có đứa trẻ ấy nhất định không được có ai phạm pháp. Nếu có, y sẽ không nhận đứa trẻ đó.", "Không chỉ không nhận, còn sẽ trục xuất cả nhà ra khỏi dòng tộc.", "Lục Nghiêu tuy hiện giờ chưa phải tộc trưởng, nhưng với thân phận và địa vị của mình, trong tộc chẳng ai dám không nghe lời.", "Chính vì có lời đe dọa \"trục xuất khỏi tộc\" ấy treo lơ lửng, những người trong tộc cũng không dám làm càn.", "Tiền đồ của Lục Nghiêu khiến cha mẹ, người thân của y nở mày nở mặt, ai nấy nhìn thấy tương lai sáng lạn của con cháu trong nhà, tự nhiên cũng biết giữ mình.", "Vậy nên bao năm qua, phủ đệ đã đón về năm đợt, tổng cộng mười ba vị con cháu, mà trong tộc chưa từng có điều tiếng gì không hay lan ra ngoài.", "Trong mười ba người ấy, đã có sáu người thi đỗ, vào học Quốc Tử Giám, chỉ có ngày nghỉ lễ hằng tuần mới được về phủ thăm Lục Nghiêu, còn lại thời gian đều chăm chỉ khổ luyện.", "Nói lại, người trong phủ ngày một đông, nhưng Lục Nghiêu vẫn còn khá nhiều phòng trống, bởi phủ đệ y đang ở hiện giờ, chính là dinh thự trước kia từng thuộc về một nhà họ Lục có thế lực quân sự lừng lẫy một thời.", "Đây là phủ đệ do bệ hạ ban thưởng, Lục Nghiêu cũng chẳng bận tâm chuyện đen đủi hay không, dù sao không phải bỏ tiền túi ra mua, y mừng còn không hết.", "Chỉ có điều bệ hạ cũng đã ra lệnh cho người tu sửa lại phủ đệ, xóa sạch những dấu vết còn sót lại từ lần bị tịch biên năm xưa.", "Tấm biển \"Lục Phủ\" mới tinh giờ đây, so với vẻ huy hoàng trước kia, lại càng thêm mộc mạc, phảng phất khí chất của một nhà văn nhân.", "Lục Nghiêu nhường viện chính cho cha mẹ ở, còn bản thân y dọn đến một tiểu viện khuất hơn một chút, gọi là Phỉ Thúy viện.", "Tiểu viện gồm hai lớp sân, một gian chính phòng, hai gian sườn phòng, hai gian nhĩ phòng, phía sau là bếp nhỏ và chỗ ở của hạ nhân.", "Lục Nghiêu khoác áo choàng bước vào sân, liền thấy chính phòng sáng đèn, trên khung cửa sổ in lờ mờ một bóng người.", "Y khựng lại, rồi rảo bước đi nhanh tới, đẩy cửa ra.", "Trong phòng thoảng mùi thơm nóng hổi của mì nước, trên bàn cơm bày sẵn vài món ăn cùng hai bát mì.", "Một bóng người cao lớn khoác áo màu tối ngồi trước bàn ăn, ngẩng đầu nhìn ra.", "Bốn mắt chạm nhau, nam nhân bật cười, giọng nhẹ nhàng: \"Còn tưởng tối nay ngươi không về nữa.\"", "Nói là nói vậy, nhưng hai bát mì vừa mới ra lò trước mặt lại chẳng phải ý ấy — rõ ràng đối phương đã tính trước giờ Lục Nghiêu về đến nhà, cố tình canh đúng lúc mà nấu hai bát mì này.", "Lục Nghiêu cởi áo choàng treo lên giá, bước đến ngồi đối diện nam nhân.", "\"Ngươi đến khi nào?\" Y hỏi.", "Nửa năm không gặp, Tần Xuyên không thay đổi chút nào.", "Tần Xuyên đưa cho y một đôi đũa, tiện miệng đáp: \"Lúc chạng vạng, trước đó có vào cung bái kiến bệ hạ cùng hai vị đại nhân.\"", "Lục Nghiêu nhận lấy đôi đũa.", "Ăn uống cùng bạn bè, thật ra cũng không đến mức đói, nhưng dù sao cũng trò chuyện khá lâu, lại uống hết chỗ rượu, giờ nhìn bát mì nóng hổi thơm phức trước mặt, y bỗng thấy bụng cồn cào.", "Huống chi, món mì này chính tay Tần Xuyên nấu, Lục Nghiêu từng ăn một lần rồi thì không thể quên được.", "Y cúi đầu ăn mì, Tần Xuyên cũng cúi đầu ăn phần của mình.", "Tần Xuyên ăn nhanh, húp cả nước dùng xong, ngẩng đầu lên đã thấy Lục Nghiêu mới ăn chưa hết một nửa.", "Y bật cười, lau miệng.", "\"Ta thấy hai gian sườn phòng của ngươi vẫn còn trống, sau này ta có tới quấy rầy nhiều thì cũng không sao chứ?\"", "Lục Nghiêu khựng lại.", "Y từ tốn ăn nốt chỗ mì trong miệng, uống thêm ngụm nước, lúc này mới nhìn lại Tần Xuyên, hỏi: \"Ngươi sau này không đi nữa?\"", "Tần Xuyên vốn không dứt được chuyện giang hồ, bao năm qua chưa bao giờ ở kinh thành lâu.", "Chỉ thỉnh thoảng trung thu hay Tết mới về một chuyến.", "Về rồi cũng chẳng ở lâu, chỉ vài ngày là lại đi.", "Giờ đối phương nói ra câu này, rõ ràng là không định đi đâu nữa, mà muốn ở lại lâu dài.", "Tần Xuyên gật đầu: \"Không đi nữa.\"", "\"Định thẳng thắn thân phận với bệ hạ?\" Lục Nghiêu hỏi tiếp.", "Tần Xuyên bật cười: \"Đúng là chẳng có gì giấu được ngươi.\"", "Lục Nghiêu bình thản nhìn y một lúc lâu, rồi hỏi: \"Vậy sao không về nhà họ Tần?\"", "Một khi đã công khai thân phận với bệ hạ, thân phận của Tần Xuyên tự nhiên không cần che giấu nữa, y sẽ lấy thân phận dòng chính nhà họ Tần, là em trai của Tần Kiêu, trở về Tần gia, tên cũng sẽ được ghi vào gia phả.", "Y hoàn toàn có thể yên tâm trở về phủ chính nhà họ Tần, ở lại tiểu viện vốn thuộc về mình.", "Tần Xuyên nói: \"Trong nhà còn hai người chị em gái, ta về ở cũng bất tiện.\"", "Y ở kinh thành vốn cũng có một tiểu phủ đệ, do Tần Kiêu mua cho, Tần Triều Dương tự mình trông coi, thỉnh thoảng còn cho người đến dọn dẹp. Trước kia mỗi lần về kinh, Tần Xuyên đều ở đó.", "Nhưng về sau Tần Kiêu vì chăm sóc Bách Lý Hồng mà dọn vào cung ở, Sở Cửu Biện cũng biết thân phận của Tần Xuyên, nên mỗi lần trở về, Tần Xuyên hoặc là ở trong cung, hoặc là ở chỗ Lục Nghiêu.", "Tiểu phủ đệ mua cho y trước kia vẫn còn đó, nhưng cũng đã lâu rồi y không ghé qua.", "Lục Nghiêu nhìn y bằng ánh mắt dò xét, bất chợt nói: \"Ngươi thật ra là muốn ăn vạ ta thôi chứ gì.\"", "Tần Xuyên: \"...\"", "Y thật lòng xin lỗi Đại tư tế, bao năm rồi vẫn chưa dạy được Lục Nghiêu cách ăn nói.", "\"Cũng gần đúng vậy.\" Y đáp.", "Lục Nghiêu suy nghĩ một chút, nói: \"Cũng được, vậy sau này ngươi cứ ở sườn phòng, hai chúng ta cũng có thể thường xuyên ăn cơm cùng nhau.\"", "\"Ừ.\" Tần Xuyên nói, \"Ta học được vài món ăn lạ ở bên ngoài, ngươi có thể nếm thử.\"", "Lục Nghiêu gật đầu, không nói thêm gì.", "Y cúi đầu chậm rãi ăn hết chỗ mì còn lại, rồi cùng Tần Xuyên thu dọn bát đũa trên bàn vào hộp đựng.", "Trong nhĩ phòng có gã sai vặt trực đêm, nghe động tĩnh liền chạy ra, đỡ lấy hộp đồ ăn từ tay Tần Xuyên mang đi hậu viện.", "\"Cũng khuya rồi, nghỉ sớm đi.\" Lục Nghiêu nói.", "Tần Xuyên từ trong ngực lấy ra một cây trâm ngọc chạm hình sóng nước, đưa cho y, nói: \"Lì xì đầu năm cho ngươi.\"", "Đợi Lục Nghiêu nhận lấy, Tần Xuyên liền xoay người đi về phía sườn phòng.", "Hạ nhân trong viện ngày nào cũng quét dọn sườn phòng sạch sẽ, giờ Tần Xuyên tới, đã có người thay sẵn chăn đệm mới.", "Tần Xuyên vào phòng là có thể ngủ ngay.", "Lục Nghiêu cầm cây trâm ngọc, nhìn theo hướng Tần Xuyên rời đi.", "Đợi nam nhân vào phòng khép cửa lại, y mới xoay người trở vào phòng mình.", "Mùng sáu tháng Giêng, theo lệ phải ra ngoài thăm hỏi bạn bè.", "Lục Nghiêu cùng Tần Xuyên ăn sáng xong, liền cùng nhau lên đường vào hoàng cung.", "Trên xe, Tần Xuyên nhìn Lục Nghiêu một hồi lâu, ánh mắt dừng lại nơi cây trâm ngọc mới tinh cài trên tóc đối phương.", "Trong hoàng cung.", "Sở Cửu Biện và Tần Kiêu cũng đã dậy sớm.", "Hôm nay Tần Xuyên định công khai thân phận với Bách Lý Hồng, dù đứa trẻ hẳn đã sớm đoán được ít nhiều, chỉ là còn chờ một câu trả lời chính thức.", "Ngoài ra, các vị tộc lão nhà họ Tần cũng đã tụ tập tại phủ chính nhà họ Tần.", "Đợi Tần Xuyên gặp Bách Lý Hồng xong, sẽ cùng Tần Kiêu về nhà ra mắt người trong tộc, nhập vào gia phả.", "Từ nay về sau, chuyện nhà họ Tần có thêm một vị nhị thiếu gia sẽ truyền khắp kinh thành.", "Sở Cửu Biện tự thấy mình là người ngoài, không định theo Tần Kiêu về nhà họ Tần, nên mới gọi Lục Nghiêu và Tần Xuyên cùng vào cung.", "Y cũng định nhân dịp này bàn thêm một số việc với Lục Nghiêu.", "Giờ Bách Lý Hồng đã mười một tuổi, thiên hạ thái bình, mọi việc trong triều cậu đều có thể tự mình xử lý.", "Vai trò của Tần Kiêu và Sở Cửu Biện trên triều đình kỳ thực cũng không còn lớn nữa, nên cả hai cũng đến lúc làm những việc nhẹ nhàng, tự tại hơn, giao hết mọi chuyện triều chính cho vị đế vương trẻ tuổi này tự mình lo liệu.", "Tuy Sở Cửu Biện vẫn chưa hỏi Tần Kiêu có sẵn lòng cùng mình rời đi hay không, nhưng y rất chắc chắn đối phương chắc chắn sẽ đồng ý.", "Chỉ là y vẫn còn chút không yên lòng về Bách Lý Hồng, dù sao cũng là đứa trẻ do chính tay mình nuôi lớn, giờ để cậu một mình ở lại kinh thành, ít nhiều cũng lo lắng.", "Vì vậy y định gọi Lục Nghiêu tới, bàn giao lại mọi việc trong triều cho y, để y hết lòng phụ tá bệ hạ.", "Cửa cung, hôm nay Hồng Phúc không đến Tư Lễ Giám trực, mà đích thân ra đón Tần Xuyên.", "Thấy Hồng công công nắm quyền lại đích thân nghênh đón long trọng như vậy, ai nấy đều tò mò không biết người đến là ai.", "Hôm nay Tần Xuyên không dịch dung, để nguyên gương mặt vốn có nhiều nét giống Tần Kiêu, công khai vào cung.", "Tần Kiêu còn cố ý cho người tung tin đồn ra ngoài.", "Vậy nên chẳng mấy chốc, trong cung ngoài cung đều truyền tai nhau, rằng Ninh Vương có một người em trai trông giống mình như đúc.", "Tin này truyền đến nhà họ Tần, phản ứng của mọi người ra sao thì không cần nhắc tới.", "Bên này, Tần Xuyên và Lục Nghiêu theo chân Hồng công công dẫn đường, đi về phía Dưỡng Tâm Điện.", "Bách Lý Hồng vốn là một đứa trẻ thông minh.", "Thấy cữu cữu và tiên sinh hôm nay phá lệ dậy sớm, lại biết Lục Nghiêu cùng vị minh chủ bí ẩn kia sắp cùng vào cung, cậu liền hiểu ngay là chuyện gì.", "Dù trong lòng đã sớm đoán được, nhưng khi sự việc thật sự đến gần, cậu bé vẫn không tránh khỏi hồi hộp.", "Lúc này mà tìm cữu cữu để nói, đối phương chắc chắn sẽ không an ủi cậu, không nhân cơ hội trêu chọc là may lắm rồi.", "Vì vậy cậu bé liền chạy đến bên Sở Cửu Biện, ngước mắt nhìn y đầy mong đợi: \"Tiên sinh...\"", "Cậu cũng chẳng biết nên nói gì, chỉ đơn giản là muốn được y ôm một cái, dỗ dành mình.", "Sở Cửu Biện rất hiểu tâm tư của đứa trẻ, không chút do dự giơ tay ôm lấy cậu, nhẹ nhàng vỗ vỗ lưng cậu.", "Thiếu niên mười một tuổi giờ đã cao lớn, đứng ngang vai Sở Cửu Biện, nhưng khi rúc vào lòng y, Sở Cửu Biện vẫn cảm thấy như thể đối phương vẫn là cục bột trắng trẻo mềm mại năm nào.", "Sở Cửu Biện không nói gì thêm, chỉ lặng lẽ ôm và vỗ về, Bách Lý Hồng dần thấy lòng mình bình tĩnh trở lại.", "Tần Kiêu ngồi đối diện nhìn hai người, khẽ mỉm cười không nói.", "Nghe tiếng thông báo bên ngoài, y liền đứng dậy.", "Bách Lý Hồng cũng rời khỏi vòng tay Sở Cửu Biện, có chút căng thẳng chỉnh lại y phục.", "Tần Kiêu bước đến bên cạnh cậu, vỗ vỗ vai, nói: \"Đi thôi.\"", "\"Vâng!\" Bách Lý Hồng gật đầu, cất bước ra ngoài nghênh đón.", "Chưa kịp đi đến cửa, Tần Xuyên đã bước tới.", "Hai người dừng lại cách nhau chừng hai mét.", "Chuyện như thế này, để lại khoảng riêng cho hai đương sự vẫn hơn.", "Vì vậy Sở Cửu Biện và Tần Kiêu cùng nhau ra khỏi cửa, thấy Lục Nghiêu và Hồng Phúc đang đứng dưới mái hiên.", "Thấy hai người bước ra, cả hai liền lên tiếng chào hỏi.", "Sở Cửu Biện nói với Tần Kiêu: \"Ta cùng Lục Nghiêu đến Nghị Sự Đường, nếu trưa vẫn chưa về thì sẽ cho người báo với ngươi một tiếng.\"", "Tần Kiêu sững lại: \"Ngươi không đi cùng ta sao?\"", "\"?\" Sở Cửu Biện nhìn y còn ngơ ngác hơn, \"Chuyện nhà họ Tần các ngươi, ta đi làm gì?\"", "Tần Kiêu chau mày, định nói ngươi đâu phải người ngoài, nhưng nghĩ lại, y và Sở Cửu Biện đúng thật là chưa có danh phận gì rõ ràng.", "Đến tận lúc này, y mới giật mình nhận ra quan hệ giữa mình và Sở Cửu Biện thật sự chẳng khác gì đôi tình nhân lén lút.", "Sở Cửu Biện căn bản chưa từng tính đến chuyện cho y một danh phận nào cả.", "\"Ta đi trước, tối về nói sau.\" Sở Cửu Biện nói xong, liền cùng Lục Nghiêu đi về phía Nghị Sự Đường ở đông viện.", "Tần Kiêu nhìn theo bóng họ rời đi, cau mày.", "Hồng Phúc đứng cạnh y, ánh mắt đưa qua đưa lại giữa y và bóng dáng Sở Cửu Biện, không nhịn được bật cười.", "Nghĩ ngợi một lát, y buông lời đề nghị: \"Đại nhân, sao không thành thân với công tử luôn đi?\"", "Tần Kiêu khựng lại.", "Rồi cũng chỉ cười cười, vỗ vỗ vai y một cái, liền đi về hướng đông viện đuổi theo, không nói thêm gì.", "Tần Kiêu quả thật đã từng tưởng tượng cảnh ấy.", "Nghĩ đến thanh niên khoác lên mình bộ áo cưới đỏ thắm, cùng y bái đường thành thân.", "Nhưng cũng chỉ là nghĩ vậy thôi.", "Người ngoài không rõ, nhưng y hiểu, với những gì Sở Cửu Biện đã trải qua từ nhỏ, đối phương hẳn không có kỳ vọng gì tốt đẹp về hôn nhân.", "Thậm chí, hôn nhân với y mà nói, đại diện cho bất hạnh.", "Vì vậy Tần Kiêu chưa từng nghĩ đến chuyện đem việc này ra bàn với Sở Cửu Biện, y chỉ có thể mượn những lúc trên giường, để thanh niên gọi mình vài tiếng \"tướng công\", coi như thỏa mãn phần mong đợi thầm kín trong lòng.", "Nhưng dù không có hôn nhân, Sở Cửu Biện vẫn là người một nhà với y.", "Hôm nay là chuyện Tần Xuyên nhập gia phả, Sở Cửu Biện cũng nên cùng y đi mới phải.", "Sở Cửu Biện và Lục Nghiêu vào đến Nghị Sự Đường, vừa ngồi xuống, còn chưa kịp nói được hai câu, Tần Kiêu đã đến nơi.", "Lục Nghiêu vội đứng dậy hành lễ, Tần Kiêu giơ tay miễn lễ, rồi ngồi xuống đối diện, nói: \"Các ngươi cứ tiếp tục.\"", "Sở Cửu Biện: \"...\"", "Y còn chưa kịp nói với Tần Kiêu về chuyện muốn cùng y \"phiêu bạt chân trời\", giờ lại định bàn với Lục Nghiêu chuyện đó — vốn định để sau khi hai người rời đi mới nói.", "Giờ Tần Kiêu ngồi ngay đây, y còn biết nói làm sao?", "Lục Nghiêu không biết Sở Cửu Biện định nói gì với mình, nhưng y lại chợt nhớ ra một chuyện, liền nói: \"Vài vị phiên vương định hai hôm nữa rời kinh, chỉ có Nam Cương quận chúa muốn ở lại thêm một thời gian, không biết có được không?\"", "Đương nhiên là được, chỉ là Nam Cương quận chúa không phải người bình thường, ở lại kinh thành lâu rốt cuộc sẽ bị người ta đàm tiếu.", "Lục Nghiêu chẳng qua là nhận lời nhờ cậy của người khác, hỏi một câu cho có lệ mà thôi.", "Cũng là để tránh sau này có ai đó ở sau lưng bàn ra tán vào.", "Quả nhiên, Sở Cửu Biện gật đầu nói: \"Không sao cả, nàng muốn ở bao lâu thì ở bấy lâu.\"", "Nói đến đây, Sở Cửu Biện tiện miệng hỏi thêm: \"Giang Sóc Dã bên đó thế nào rồi? Ở kinh thành có quen không?\"", "Từ sau đêm giao thừa, y vẫn chưa nghe được tin tức gì về đối phương.", "Tần Kiêu vốn vẫn còn chút khó chịu âm ỉ với Giang Sóc Dã chưa tan, giờ nghe Sở Cửu Biện quan tâm, y không kìm được liếc đối phương thêm một cái.", "Nhưng thần sắc Sở Cửu Biện vẫn bình thản, rõ ràng chỉ đơn thuần quan tâm đến một tín đồ của mình.", "Lục Nghiêu vốn khá chậm chạp trong chuyện tình cảm, không nhận ra bầu không khí kỳ lạ giữa Tần Kiêu và Sở Cửu Biện, nghiêm túc trả lời: \"Cũng khá tốt. Mấy hôm nay đều có Vương Kỳ Sâm ở bên cạnh, quận chúa hôm trước còn nói với ta rằng hai người ấy chẳng chịu đi chơi cùng nàng nữa.\"", "Vậy nên Tư Đồ Chiêu Linh giờ chỉ còn có thể đến tìm Lục Nghiêu, hoặc tìm Tư Đồ Chiêu Nghiêu.", "May sao hôm qua đối phương cuối cùng cũng có bạn chơi mới — Đàm Vũ Trúc về quê thăm người thân đã trở lại.", "Vậy nên mấy ngày tới, Tư Đồ Chiêu Linh hẳn sẽ quấn lấy Đàm Vũ Trúc.", "Đương nhiên, đối phương cũng không đơn thuần đi chơi, mà còn tranh thủ khảo sát thị trường, có lẽ đang tính làm thêm việc kinh doanh khác.", "\"Vương Kỳ Sâm?\" Sở Cửu Biện nhướng mày, cười nói, \"Hai người đó lại hợp nhau được sao?\"", "Bao năm ở Thần Vực, y đã chứng kiến không ít lần Vương Kỳ Sâm và Giang Sóc Dã ở cùng nhau.", "Tính cách và sở thích của hai người này khác nhau một trời một vực.", "Vương Kỳ Sâm là kiểu con nhà thế gia kỹ tính, sạch sẽ, ưa cái đẹp; Giang Sóc Dã thì lôi thôi lếch thếch, thường xuyên bị Vương Kỳ Sâm chê bai.", "Không ngờ khi thật sự gặp nhau, hai người lại là cặp hợp ý nhất.", "\"Đúng vậy.\" Lục Nghiêu gật đầu, \"Đêm giao thừa sau khi tan cuộc, Vương Kỳ Sâm liền trực tiếp ở lại nghỉ tại phủ Giang Sóc Dã.\"", "Hôm đó bọn họ vốn hẹn nhau ở tửu lầu uống rượu, nhưng sau lại nói muốn đến mừng nhà mới cho Giang Sóc Dã, bèn kéo nhau đến phủ y.", "Sau đó mọi người lần lượt ra về, chỉ có Vương Kỳ Sâm là không đi.", "Sở Cửu Biện nghe vậy, sắc mặt trở nên kỳ lạ.", "Đợi đã, chẳng lẽ đúng như y nghĩ?", "Lục Nghiêu lại chẳng thấy có gì bất thường, tiếp tục nói: \"Nhưng đêm đó Tần Xuyên cũng ở lại chỗ ta nghỉ, nghĩ lại thì hai người họ với chúng ta cũng có quan hệ khá giống nhau, không tệ.\"", "Lục Nghiêu còn nghĩ thầm, nếu Tần Xuyên có thể công khai thân phận sớm hơn, thì đã có thể gặp mọi người trong Thần Vực sớm hơn, đêm giao thừa cũng có thể tham gia buổi tụ họp cùng mọi người.", "Nhưng giờ cũng chưa muộn, sau hôm nay, thân phận của Tần Xuyên sẽ không còn là bí mật nữa, y cũng có thể đường đường chính chính gặp gỡ các tín đồ trong Thần Vực.", "Người nói vô tâm, người nghe lại để bụng.", "Sở Cửu Biện quay sang nhìn Tần Kiêu, quả nhiên thấy sắc mặt đối phương cũng trở nên kỳ lạ không kém, nhìn về phía Lục Nghiêu với ánh mắt vô cùng phức tạp.", "Sở Cửu Biện: \"...\"", "Tần Kiêu rốt cuộc đang nghĩ gì vậy?", "Bản thân y là gay thì đành chịu, chứ không thể nhìn ai cũng cho là vậy được.", "Trên đời này làm gì có nhiều người gay đến thế chứ?", "Trong chính điện Dưỡng Tâm Điện.", "Bách Lý Hồng ngước nhìn nam nhân cao hơn mình hẳn một cái đầu, ánh mắt trong veo sáng ngời.", "Đây là lần đầu tiên cậu nhìn thấy gương mặt thật của Tần Xuyên, có đến ba phần giống Tần Kiêu, mà tự nhiên cũng có nét giống Bách Lý Hồng.", "Cái cảm giác thân thuộc bẩm sinh ấy khiến mọi thứ càng thêm rõ ràng.", "Tần Xuyên cũng cúi mắt nhìn thiếu niên trước mặt.", "Y vốn quen bôn ba giang hồ, gặp người nói tiếng người, gặp quỷ nói tiếng quỷ.", "Nhưng lúc này, đối diện với thiếu niên đang ngước nhìn mình, y lại chẳng biết nên mở lời ra sao.", "Bao nhiêu lời đã chuẩn bị sẵn trước đó, giờ đều quên sạch, cuối cùng y chỉ có thể khó khăn cất tiếng: \"Bệ hạ, ta là Tần Xuyên.\"", "\"Ngươi...\"", "Cổ họng cậu bé khẽ động, một lúc lâu sau, trong ánh mắt chờ đợi của thiếu niên, y mới nói tiếp: \"Là cữu cữu ruột của ngươi.\"", "Dứt lời, y liền thấy mắt thiếu niên đỏ hoe.", "Rồi trong lòng ngực trĩu xuống một cái — Bách Lý Hồng đã lao vào lòng y.", "\"Cữu cữu.\" Thiếu niên nghẹn ngào gọi, \"Trẫm biết mà. Biết mà!\"", "Cậu biết ngay là như vậy mà!", "Một đứa trẻ lớn lên trong tình yêu thương, cũng sẽ có khả năng yêu thương người khác.", "Trên người Bách Lý Hồng có sự quyết đoán của Tần Phong để lại, có sự kiên cường của Tần Kiêu, có sự lý trí của Sở Cửu Biện, nhưng nói cho cùng, cốt lõi trong con người cậu vẫn tràn đầy tình yêu thương, dịu dàng.", "Cậu chưa bao giờ vì mình là đế vương mà quên mất khả năng yêu thương người khác.", "Cậu không sợ bị tổn thương, không sợ trao đi tình cảm mà không nhận lại được đáp lại, vì cậu biết dù thế nào, cũng luôn có Tần Kiêu và Sở Cửu Biện, cùng nhiều người khác nữa yêu thương mình.", "Mà tình yêu nồng nhiệt như vậy của cậu, cũng lan tỏa cảm nhiễm đến những người xung quanh.", "Tần Xuyên giơ tay, nhẹ nhàng vòng qua vai thiếu niên.", "Y học theo cách Sở Cửu Biện vẫn thường làm, chậm rãi vỗ về lưng thiếu niên, động tác có phần vụng về.", "Trái tim phiêu bạt bấy lâu, dường như trong khoảnh khắc này mới thật sự tìm được chỗ neo đậu.", "Bao nhiêu năm qua, Tần Xuyên đã từng chút một nhìn đứa trẻ này từ những bước đi chập chững, cho đến giờ đã trở thành một người tài hoa, phong thái đĩnh đạc.", "Y vẫn nhớ rõ lần đầu tiên mình đối diện với vị tiểu bệ hạ.", "Cậu bạn nhỏ ngồi trong xe, chớp đôi mắt to nhìn y, còn cười với y nữa.", "Sau này, trong trận đánh với Khâu Huyền, y bị thương, dưỡng thương tại Dao Đài Cư, cậu bạn nhỏ ấy cũng luôn bọc kín người như một chú mèo con, chạy đến thăm y, tựa vào mép giường trò chuyện cùng y.", "Đôi khi hai người còn cùng ngồi trên chiếc giường ấm áp, nghe y kể chuyện giang hồ.", "Cậu cũng thường mang đường, mang những món điểm tâm ngon đến cho y.", "Có một lần cậu bé ngủ quên bên cạnh y, gương mặt nhỏ ửng hồng vì ngủ say.", "Sở Cửu Biện đến đón cậu, đứng chờ ngoài phòng.", "Tần Xuyên nhẹ nhàng bế đứa trẻ lên, mang ra ngoài đưa cho Sở Cửu Biện.", "Nhưng nhìn gương mặt nhỏ đang say giấc, y không kìm được đưa tay khẽ chọc nhẹ một cái, cậu bé liền ôm lấy cánh tay y, lầm bầm gọi một tiếng \"cữu cữu\" trong mơ.", "Y không thể diễn tả nổi cảm giác lúc ấy, nếu không phải Sở Cửu Biện đứng ngay bên cạnh, có lẽ y đã bật khóc mất thể diện rồi.", "Bao nhiêu năm qua, làm sao y không ghen tị với Tần Kiêu cho được?", "Ghen tị vì y có thể đường đường chính chính bước đi trước mặt mọi người, ghen tị vì y được lớn lên trong tình yêu thương của gia đình, ghen tị vì y được nghe cậu bạn nhỏ gọi mình một tiếng \"cữu cữu\".", "Nhưng y cũng không hề trách Tần Kiêu.", "Bởi y biết, Tần Kiêu là người trên thế gian này để tâm đến y nhất.", "Còn hơn cả cha mẹ, hơn cả người chị cả, hơn cả tổ phụ.", "Thời niên thiếu, y mới có liên lạc với Tần Kiêu, cũng chính lúc ấy, đối phương mới biết nhà họ Tần còn có một đứa trẻ khác.", "Từ đó về sau, Tần Xuyên luôn nhận được những món quà tốt mà Tần Kiêu gửi từ kinh thành đến, qua đủ mọi con đường khác nhau.", "Có khi là món ăn lạ, có khi là vàng bạc châu báu, có khi là đao kiếm binh khí quý hiếm cùng chiến lợi phẩm...", "Sau này vào kinh, hai anh em gặp nhau nhiều hơn, nhưng quan hệ vẫn cứ ngượng ngùng.", "Nhưng Tần Xuyên biết, đó là do chính y giữ khoảng cách, còn Tần Kiêu vẫn luôn muốn gần gũi, muốn bù đắp cho y, những thứ thuộc về y khiến đối phương không dám đến gần quá.", "Về sau mọi chuyện dần tốt lên ra sao?", "Dường như là từ khi Sở Cửu Biện và Đại tư tế lần lượt xuất hiện.", "Y và Tần Kiêu qua lại càng ngày càng nhiều, chuyện có thể nói cùng nhau cũng nhiều hơn.", "Y dần dần chấp nhận vị huynh trưởng vượt trội hơn mình về mọi mặt này, cũng bắt đầu học cách suy nghĩ cho đối phương, một lòng bôn ba vì đối phương.", "Giờ đây lại càng tốt hơn.", "Y không chỉ có thể đường đường chính chính ở bên huynh trưởng, cùng nhau chuyện trò uống rượu, mà còn được nghe vị tiểu thiếu niên trước mặt gọi mình một tiếng cữu cữu.", "Khi Tần Xuyên và Bách Lý Hồng bước vào Nghị Sự Đường, mọi người vẫn còn thấy khóe mắt thiếu niên ửng đỏ.", "Nhưng cậu bé đã không còn khóc nữa, ngược lại còn cười đến híp cả mắt.", "Có thêm một người bạn từ nhỏ giờ trở thành tiểu cữu cữu, đứa trẻ sao có thể không vui cho được?", "Thấy cậu như vậy, đừng nói là Sở Cửu Biện và Tần Kiêu — hai bậc trưởng bối vốn cưng chiều đứa trẻ này, ngay cả Lục Nghiêu cũng không nhịn được cười theo.", "Nói ra, chính y cũng đã chứng kiến tiểu bệ hạ từ một cục bột nhỏ lớn lên thành người có thể một mình gánh vác một phương, thời gian trôi quả thực quá nhanh.", "Bách Lý Hồng nơi đây đã coi như xong xuôi, tin đồn bên ngoài lúc này cũng đã lan truyền gần giống sự thật.", "Tần Kiêu chuẩn bị đưa Tần Xuyên về gặp tộc nhân, chính thức nhận tổ quy tông.", "Bách Lý Hồng sợ trong tộc có kẻ gây khó dễ cho cữu cữu, liền viết một đạo thánh chỉ đưa cho Tần Kiêu, bảo hai người mang theo về nhà.", "Hai anh em định ra cửa rời đi, nhưng Tần Kiêu lại bước đến nắm lấy tay Sở Cửu Biện, nói: \"Đi cùng nhau.\"", "Giọng điệu đầy chắc chắn khiến Sở Cửu Biện nhất thời quên cả phản ứng.", "Đến khi hoàn hồn lại, y đã bị nam nhân nắm tay kéo ra khỏi Nghị Sự Đường.", "Sở Cửu Biện chỉ do dự chốc lát, rồi nghĩ dù sao cũng đã đến đây rồi, đi theo một chuyến cũng chẳng sao.", "Phía sau họ, Tần Xuyên cũng liếc nhìn về phía Lục Nghiêu, nhưng cuối cùng không nói gì, chỉ khẽ gật đầu rồi xoay người ra cửa, đuổi theo bước chân Tần Kiêu và Sở Cửu Biện.", "Ba người đến phủ chính nhà họ Tần, quả nhiên có người bóng gió phê bình.", "Nhưng thánh chỉ vừa đưa ra, hơn nữa Tần Xuyên đứng cạnh Tần Kiêu, chỉ cần liếc mắt một cái là nhận ra hai người là anh em, mọi người liền không ai dám nói thêm gì nữa.", "Còn về việc Sở Cửu Biện xuất hiện trong trường hợp này, càng không ai dám nhiều lời.", "Nếu chỉ là chuyện của Tần Kiêu, họ còn có thể dựa vào thân phận tộc lão, khéo léo khuyên y cưới vợ sinh con để nối dõi.", "Nhưng đối diện vị thần minh Sở Cửu Biện này, họ một câu cũng không dám hé răng, chỉ đành ấm ức đứng nép sang một bên, nhìn đối phương cùng Tần Kiêu bái lạy tổ tiên nhà họ Tần, rồi lấy thân phận trưởng bối nhận lễ bái của Tần Xuyên.", "Sau đó, Tần Xuyên coi như đã chính thức nhận tổ quy tông, tên được ghi vào gia phả, xếp ngay sau Tần Kiêu.", "Đồng thời, thân phận của Sở Cửu Biện trong nhà họ Tần cũng coi như đã được xác nhận.", "Y lấy thân phận trưởng bối của Tần Xuyên mà tham dự nghi thức hôm nay, còn cùng Tần Kiêu nhận lễ bái, vậy thì y đương nhiên phải mang thân phận \"trưởng tẩu\" của Tần Xuyên.", "Nói cách khác, trong mắt người nhà họ Tần, tuy hai người chưa chính thức thành hôn, nhưng Sở Cửu Biện đã coi như là thê tử của Tần Kiêu.", "Cái toan tính nhỏ nhặt này của Tần Kiêu, Sở Cửu Biện tự nhiên cũng đoán ra bảy tám phần.", "Không phải vì y am hiểu quy trình nhận tổ quy tông, mà là hệ thống vẫn luôn phổ cập kiến thức trong đầu y, cuối cùng còn kết luận: \"Ký chủ, hệ thống có cơ sở hợp lý để nghi ngờ Tần Kiêu đang lợi dụng cơ hội chiếm tiện nghi của ngài.\"", "Sở Cửu Biện: \"...\"", "Chuyện nhà họ Tần có thêm một vị dòng chính là đại sự, Tần Triều Dương tuy đã là thượng thư nhất phẩm trong triều, nhưng việc này y vẫn tự mình đứng ra lo liệu.", "Từ mấy hôm trước, y đã bắt đầu chuẩn bị yến tiệc, hôm nay nghi thức nhận tổ quy tông vừa kết thúc, thiệp mời đã được gửi đến tay tất cả những nhân vật có tiếng tăm trong kinh thành.", "Bữa tiệc nhận thân náo nhiệt được tổ chức vào buổi trưa mùng bảy.", "Không nói đến các quan lớn, nhân vật có tiếng khác, ngay cả những vị phiên vương chưa kịp rời kinh cũng đều đến dự.", "Tần Kiêu đưa Tần Xuyên đi mời rượu khắp lượt, Bách Lý Hồng cũng đích thân đến một chuyến, cười chạm ly cùng Tần Xuyên, còn thoải mái gọi một tiếng \"tiểu cữu cữu\".", "Từ đó, những mối nghi hoặc ngấm ngầm trong lòng mọi người cũng tan biến.", "Bệ hạ đã đích thân thừa nhận huyết thống, thì chắc chắn là thật, huống chi nhìn khí chất diện mạo của hai anh em Tần Xuyên và Tần Kiêu, nếu bảo không phải cùng một mẹ sinh ra mới là chuyện lạ.", "Một buổi trưa náo nhiệt như vậy, đến chiều vẫn còn vài việc phải xử lý tiếp.", "Mùa đông trời tối sớm, khi Sở Cửu Biện và Tần Kiêu nghỉ ngơi xong việc, trời đã tối hẳn.", "Hai người không về cung, mà ở lại tiểu viện phía sau của Tần Kiêu.", "Sở Cửu Biện đã đến đây nhiều lần, nhưng vẫn còn nhớ rõ lần đầu tiên đến đây, Tần Kiêu suýt nữa đã làm gì đó với y ngay tại chỗ.", "Đến giờ, y vẫn còn nhớ rõ cảm giác tê rần khi đối phương vờn nhẹ nơi ngực mình khi đó.", "Chỉ là lúc ấy Sở Cửu Biện đã từ chối, không để nam nhân tiến thêm.", "Còn bây giờ, giữa hai người đã chẳng còn sự \"trong sạch\" ấy nữa.", "Rửa mặt xong, Tần Kiêu vẫn còn vương chút hơi men.", "Sở Cửu Biện nhìn bông tuyết bay ngoài cửa sổ, bỗng nảy ra ý muốn ra ngoài dạo một chút.", "Y liền quay sang nhìn Tần Kiêu: \"Ngươi mệt không?\"", "\"Không mệt.\" Tần Kiêu bước đến ôm lấy y. \"Muốn ra ngoài à?\"", "\"Ừ.\"", "\"Đi thôi.\"", "Tần Kiêu cũng không hỏi y muốn đi đâu, cũng chẳng làm mất hứng mà từ chối, trực tiếp giúp y mặc quần áo.", "Hai người mặc chỉnh tề xong, liền rời khỏi phòng ngủ.", "Sở Cửu Biện giơ tay ra, Tần Kiêu bật cười, xoay người khom lưng xuống.", "Sở Cửu Biện nhào lên lưng y, kéo áo choàng quấn quanh, đảm bảo bọc kín cả hai người, lúc này mới nói: \"Được rồi, đi ngắm sao thôi.\"", "\"Được.\"", "Bóng dáng hai người nhanh chóng biến mất khỏi sân viện, một lúc sau, đã thấy họ đứng trên đài ngắm sao.", "————————!!————————", "Cuốn này ngay từ đầu vốn không định viết thêm cặp phụ nào cả, thật ra chỉ là muốn viết tình huynh đệ giữa nhóm thư sinh, nhưng tác giả không dám viết chuyện tình cảm giữa hai anh em ruột thật sự, viết viết lại lỡ tay biến vị mất rồi [xin lỗi mọi người]", "Nếu mọi người muốn xem, đợi truyện này kết thúc xong (chắc khoảng bảy đến mười hôm nữa) sẽ đăng phúc lợi phiên ngoại, đến lúc đó sẽ đăng tiếp, bạn nào thích thì cứ vào xem, bạn nào không thích thì cũng đừng khó chịu nhé [làm nũng một chút thôi]", "Phúc lợi phiên ngoại chắc sẽ có thêm vài đoạn tiểu kịch trường ngọt ngào giữa tiểu cữu và Ninh Vương, cùng vài chương lẻ tẻ đời thường không biết ngượng của họ, mọi người đến lúc đó có thể ghé qua xem nhé ~"], "id": 9, "wordCount": 6053}, {"title": "Chương 114 toàn văn kết thúc", "paragraphs": ["Đài ngắm sao lúc này vắng tanh không một bóng người.", "Suốt hai ngày ăn Tết, các quan viên Khâm Thiên Giám vẫn túc trực nơi đây xem thiên tượng đoán vận. Nhưng giờ ngày Tết đã qua, ai nấy đều về nhà nghỉ phép, nên đỉnh đài lúc này chỉ còn Sở Cửu Biện và Tần Kiêu, không một ngọn đèn dầu.", "May mà đêm nay trăng sáng vằng vặc, tuyết rơi lất phất chứ trời không âm u. Trên cao gió tuy lặng nhưng vẫn lạnh thấu người, đứng đây một lúc là thấy hàn khí len vào tận xương.", "Sợ Sở Cửu Biện nhiễm lạnh, Tần Kiêu vòng tay từ phía sau ôm trọn người trong lòng, lấy áo khoác của mình trùm lên cả hai. Thân thể đàn ông quanh năm vốn ấm áp, Sở Cửu Biện vừa bị ôm vào đã thấy cả người nóng lên, chỉ còn mỗi khuôn mặt và đầu mũi là còn hơi lạnh.", "Tần Kiêu như đọc được ý, khẽ cúi đầu tì cằm lên vai y, áp má mình vào má Sở Cửu Biện. Chỉ một lát sau, chỗ đó đã ấm hẳn. Rồi y lại đổi bên, cọ sang nửa mặt còn lại.", "Sở Cửu Biện bật cười. Tần Kiêu cũng cười theo, ghé sát tai y, khẽ nói: \"Lạnh quá thì về.\"", "Kỳ thực trời lạnh thế này, y chẳng hề muốn để Sở Cửu Biện ra ngoài chút nào.", "Sở Cửu Biện \"ừ\" một tiếng. Y vốn chỉ nhất thời hứng lên mới rủ ra đây, giờ cũng thấy hơi muốn về.", "Nhưng ngay lúc đó, chân trời chợt lóe lên một vệt sáng, rồi lại thêm một vệt nữa.", "Là sao băng.", "\"Đây là lần đầu tiên ta thấy sao băng.\" Sở Cửu Biện nói.", "Tần Kiêu cũng nhìn thấy hai vệt sao băng ấy, bật cười: \"Nếu không phải trước kia ngươi từng nói đây là hiện tượng bình thường, chắc đám người Khâm Thiên Giám lại phải làm ầm lên, thức trắng đêm bấm quẻ.\"", "Ba năm trước cũng từng có một đêm sao băng vụt qua trời. Khi ấy Khâm Thiên Giám coi đó là đại sự, thức suốt đêm bấm quẻ, sáng hôm sau còn tìm đến bẩm báo, nói đủ thứ chuyện huyền bí cao xa. Rốt cuộc chính Sở Cửu Biện phải dùng cách đơn giản và hợp lý nhất giải thích cặn kẽ cho họ hiểu.", "Giám chính Khâm Thiên Giám khi đó suýt sụp đổ cả thế giới quan, may mà sức tiếp thu của y không tồi. Sau lần ấy, y còn xin Sở Cửu Biện vài quyển sách thiên văn, khổ công nghiên cứu. Sở Cửu Biện từng nghĩ Đại Ninh sắp có lứa nhà thiên văn học đầu tiên, ai ngờ vị giám chính ấy lại càng lúc càng đi sâu vào con đường huyền học, mà còn đi rất vững, bói toán ngày một chuẩn xác. Bởi vậy y lại càng thêm bội phục Sở Cửu Biện sát đất.", "Sở Cửu Biện chẳng biết nói gì hơn, chỉ đành động viên y cố gắng. Chuyện huyền học đời nào cũng có, thà tin là có còn hơn. Huống chi chính Sở Cửu Biện từng trải qua chuyện xuyên không như thế, nếu bảo y không tin huyền học thì cũng chẳng thể nói cho xuôi.", "Nói lại chuyện lúc nãy, Sở Cửu Biện ngẩng nhìn ánh trăng trắng ngần trên bầu trời, khẽ nói: \"Thế giới này rộng lớn lắm. Có nơi quanh năm không có đêm tối, có nơi lại chẳng bao giờ thấy ban ngày. Có nơi là biển băng mênh mông bát ngát, có nơi lại có cực quang xanh biếc lay động trên trời...\"", "Tần Kiêu rất thích nghe Sở Cửu Biện kể về những điều y chưa từng biết. Y chỉ lặng lẽ ôm người, yên tĩnh lắng nghe, thỉnh thoảng đáp lại vài câu để dẫn dắt Sở Cửu Biện nói tiếp.", "Sở Cửu Biện vốn không phải người thích trò chuyện, càng không thích chia sẻ tâm tình. Nhưng ở bên Tần Kiêu, y luôn nói ra được rất nhiều điều. Tần Kiêu rất biết cách khơi gợi y, còn Sở Cửu Biện thì lại thích cái cảm giác được ai đó lặng lẽ dõi theo, quan tâm như vậy.", "Có lẽ vì từ nhỏ không ai quản, không ai thật lòng yêu thương, nên y mới khát khao thứ tình cảm gần giống như \"chiếm hữu\" đến thế. Y say mê cảm giác ấy, và cũng say mê luôn cả người đem đến cho y cảm giác ấy.", "Sở Cửu Biện đang nói bỗng dưng im bặt.", "Tần Kiêu khẽ nghiêng đầu nhìn y, hơi thở ấm phả bên tai chàng trai: \"Muốn về rồi sao?\"", "\"Ta có chuyện muốn nói với ngươi.\" Sở Cửu Biện xoay người nhìn y.", "Tần Kiêu theo bản năng định kéo người đối mặt vào lòng, nhưng bị Sở Cửu Biện giơ tay chặn lại. Hai tay chống lên ngực Tần Kiêu, bỗng dưng y bật cười.", "\"Sao vậy?\" Tần Kiêu không hiểu vì sao nhưng cũng không nhịn được cười theo.", "Chàng trai ngước mắt nhìn y, trong mắt ánh lên nụ cười, đẹp đến mức khiến người ta ngỡ như không thật.", "Tần Kiêu rõ ràng cảm nhận được tim mình đập nhanh hẳn lên. Rõ ràng đã ở bên nhau bao nhiêu năm, gương mặt này y đã nhìn không biết bao nhiêu lần, vậy mà mỗi lần nhìn Sở Cửu Biện, tim y vẫn cứ rung động như thuở ban đầu.", "\"Còn nhớ lần đầu chúng ta gặp nhau không?\"", "Y đang nhắc đến cái ngày mình từ trên trời rơi xuống, đáp thẳng vào lòng Tần Kiêu. Lần gặp gỡ đầu tiên ấy đầy xấu hổ, đầy địch ý và sát khí. Nhưng giờ nghĩ lại, Sở Cửu Biện cũng chẳng nhớ rõ khi đó hai người đã nói những gì, chỉ nhớ mình theo bản năng nhéo lấy ngực người ta, còn thầm khen cảm giác không tồi.", "Tần Kiêu cụp mắt nhìn bàn tay đang đặt trên ngực mình, bật cười khẽ: \"Đồ háo sắc.\"", "Sở Cửu Biện cũng cười theo. Cười một lúc, y lại dừng lại, hỏi: \"Ngươi còn nhớ lần đầu tiên đưa ta lên đài ngắm sao này không?\"", "\"Nhớ.\" Tần Kiêu gật đầu.", "Sở Cửu Biện ngước mắt nhìn y, thần sắc hơi căng thẳng, lại như đang co rúm lại vì hồi hộp.", "Bảy năm trước, cũng vào khoảng thời gian sau Tết như thế này, Tần Kiêu đã dẫn y đến đây, nói với y rằng \"Ta thích ngươi\". Y còn bảo không cần Sở Cửu Biện đáp lại ngay, chỉ là muốn cho y biết tấm lòng mình. Đêm ấy, chuyện nên làm hay không nên làm, hai người đều đã làm cả. Nhưng Sở Cửu Biện khi đó trước sau không dám đối diện với lòng mình, cũng không tin nổi Tần Kiêu có thể chấp nhận trọn vẹn con người y. Vì thế, y thật sự chưa từng cho Tần Kiêu một câu trả lời.", "Chuyện ấy, y vẫn luôn ghi nhớ trong lòng. Y biết mình còn nợ Tần Kiêu một lời đáp chính thức.", "Giờ đây, chàng trai nhìn thẳng vào đôi mắt sâu thẳm của người đàn ông trước mặt, không né tránh, khẽ gọi: \"Tần Kiêu.\"", "\"Ta muốn được ở bên ngươi mãi mãi.\"", "Ánh mắt Tần Kiêu khẽ lay động. Y chưa từng nghĩ Sở Cửu Biện sẽ nói ra những lời này, nhất thời sững sờ, không biết phải phản ứng thế nào.", "Sở Cửu Biện có thể cảm nhận rõ ràng tim mình đang đập điên cuồng, cảm nhận được cả nhịp rung động truyền từ lồng ngực Tần Kiêu sang. Y đưa bàn tay hơi lạnh lên, khẽ vuốt ve gương mặt người đàn ông.", "\"Ta yêu ngươi, Tần Kiêu.\"", "Nói ra câu ấy, giọng Sở Cửu Biện khẽ run lên.", "Tần Kiêu như nín thở nửa nhịp. Y nhìn chăm chú vào gương mặt đẹp như tiên nhân giáng trần trước mặt, hồi lâu không lấy lại được tinh thần. Đây là cảnh tượng y chưa từng dám mong, vậy mà giờ phút này lại thật sự xảy ra ngay trước mắt.", "Sở Cửu Biện nói yêu y.", "Y nói y yêu y!", "Không ai hiểu rõ và xót xa cho những gì Sở Cửu Biện từng trải qua hơn Tần Kiêu. Nên y chưa bao giờ nghĩ có ngày Sở Cửu Biện sẽ thản nhiên nói ra chữ \"yêu\". Ngay cả với Bách Lý Hồng — đứa trẻ được y nuôi lớn từ nhỏ — Sở Cửu Biện cũng chưa từng nói một lần \"yêu\". Vậy mà giờ đây, y lại nói yêu Tần Kiêu.", "Tần Kiêu chỉ từng rơi nước mắt trước mặt Sở Cửu Biện đúng một lần. Giờ đây, y lại một lần nữa rơi lệ trước mặt người ấy.", "Sở Cửu Biện nhẹ nhàng lau nước mắt cho y, khóe mắt mình cũng đỏ hoe.", "\"Tần Kiêu.\" Giọng y rất nhẹ, rất dịu dàng, \"Ngươi có bằng lòng cùng ta rời xa triều đường, sống tháng ngày tự tại tiêu dao không?\"", "Năm xưa, trong một đêm tuyết, chính Tần Kiêu đã mời y cùng chung hưởng thịnh thế. Giờ đây, đến lượt Sở Cửu Biện muốn cùng Tần Kiêu chạy trốn về phía tự do. Không còn tranh đấu chốn triều đình, không còn tranh giành quyền thế, không còn bất cứ ràng buộc hay vướng bận nào — y muốn có với y một cuộc tình yêu không chút e dè, cố kỵ.", "Y biết gốc rễ của Tần Kiêu là ở kinh thành, mọi vướng bận người và việc của y cũng đều ở đó. Nhưng y tin chắc Tần Kiêu sẽ cùng mình rời đi, cùng ngắm giang sơn gấm vóc rộng lớn này, cùng tận hưởng năm tháng chỉ thuộc về riêng hai người. Đó là niềm tin mà bao nhiêu năm bên nhau, chính Tần Kiêu đã cho y.", "Quả nhiên, ngay sau đó, Tần Kiêu vươn tay ôm trọn y vào lòng.", "\"Vinh hạnh vô cùng.\" Giọng y mang theo nụ cười, hơi khàn đi một chút.", "Sở Cửu Biện nhắm mắt, siết chặt vòng tay ôm lấy Tần Kiêu.", "Trăng như dát bạc, tuyết bay lất phất nhuộm một quầng sáng dịu, dần dần phủ trắng cả mái tóc đen.", "==", "Hai tháng sau, Vạn Thọ Tiết qua đi.", "Sở Cửu Biện và Tần Kiêu chính thức rời khỏi triều đình, lặng lẽ rời kinh thành. Để tiểu hài tử yên tâm, cũng để có thể dõi theo tình hình của Bách Lý Hồng bất cứ lúc nào, Sở Cửu Biện đã đem cả bài vị của mình rút khỏi thần điện, còn cố ý chọn đúng ngày sinh nhật của Bách Lý Hồng để đưa y vào Thần Vực một chuyến. Y phấn khích tột độ, nghĩ bụng có được một vị tiên sinh là thần tiên thật đúng là quá tuyệt vời, chuyện gì mới lạ cũng đều muốn được trải nghiệm.", "Kỳ thực từ khi Sở Cửu Biện và Tần Kiêu bắt đầu buông dần việc triều chính, Bách Lý Hồng đã sớm biết rồi sẽ có một ngày hai người rời khỏi triều đình, rời khỏi kinh thành. Nên khi ngày ấy thực sự đến, y không hề bất ngờ. Y đã trưởng thành, còn cữu cữu và tiên sinh đã vì y mà lo liệu việc nước, vất vả bao nhiêu năm nay, cũng đã đến lúc để họ đi làm điều họ muốn làm. Y không nên là sợi dây trói buộc hai người.", "Vì thế, dù trong lòng có chút lưu luyến, Bách Lý Hồng vẫn không để lộ ra ngoài, mỉm cười tiễn hai người rời kinh. Dù sao chỉ cần muốn, bất cứ lúc nào y cũng có thể gặp lại họ trong Thần Vực, huống chi tiên sinh và cữu cữu đã hứa mỗi năm sẽ về thăm y một, hai lần, như thế là đủ rồi.", "Nhưng nghĩ là một chuyện, đến khi hai người thực sự rời kinh, Bách Lý Hồng vẫn thấy không quen. Y thường đi dạo một vòng quanh viện phía tây, chẳng làm gì cả, chỉ đứng một lúc hoặc ngồi một lúc. Ban đầu chỉ là nhớ hai người thân đã nuôi mình khôn lớn, nhưng dần dà việc ấy trở thành thói quen. Mỗi khi chính sự có điều phiền lòng, y lại đến viện phía tây ngồi một lúc, nghĩ xem nếu là tiên sinh và cữu cữu, họ sẽ xử lý chuyện này ra sao. Rồi những suy nghĩ rối bời kỳ lạ thay lại dần thông suốt, chuyện khó khăn cũng không còn là vấn đề nữa.", "Vì vậy, mỗi lần gặp nhau trong Thần Vực, Bách Lý Hồng chỉ kể cho hai người nghe những chuyện thú vị gần đây, rồi lắng nghe hai người kể về những điều mắt thấy tai nghe dọc đường.", "Sở Cửu Biện và Tần Kiêu rời kinh sau đó thong thả đi về phương nam, trước tiên đến Hà Tây quận.", "Miếu thờ Sở Cửu Biện trải khắp Đại Ninh, nơi nào cũng treo tranh vẽ y hoặc tạc tượng thần theo dung mạo của y. Vì gương mặt ấy hầu như không ai trong Đại Ninh không biết, nên đi đến đâu y cũng phải đeo khẩu trang, coi như quay lại cái thời còn phải \"chạy trốn\" danh tiếng. Còn về kiểu tóc thì không sao cả — vì tín đồ sùng bái y quá nhiều, người bắt chước để tóc giống y cũng rất đông, thậm chí có người còn chế ra thuốc nhuộm tóc từ thực vật, nhuộm nửa mái tóc phía sau thành màu bạc như y. Nếu không phải vóc dáng và dung mạo của họ không sánh được với Sở Cửu Biện, e rằng thật có thể giả mạo mà qua mắt người khác. Nhưng dù sao đó cũng chỉ là tâm lý mến mộ thần tượng, chẳng ai gan đến mức dám đóng giả thần minh thật sự.", "Tần Kiêu vốn không cần cải trang gì, nhưng vẫn đeo khẩu trang giống Sở Cửu Biện cho tiện.", "Đến Hà Tây quận, nhìn cảnh bá tánh nơi đây sung túc an vui, hai người biết ngay vị quận thủ mới cũng là người tốt. Còn vị quận thủ cũ, Hàn Đường Xa, giờ đã thăng chức, vào kinh nhậm chức tại Lại Bộ. Từ một viên quan nông nghiệp nhỏ bé, giờ đã trở thành quan tam phẩm của Lại Bộ trong triều, Hàn Đường Xa trở thành tấm gương trong lòng bá tánh Hà Tây, không ít nhà lấy Hàn đại nhân làm mẫu mực dạy con cái chăm chỉ học hành.", "Rời Hà Tây, hai người lên thuyền, xuôi theo kênh đào tiếp tục hướng nam. Kênh đào vẫn được quản lý gọn gàng nghiêm chỉnh như trước, mỗi đoạn kênh mang một nét riêng, thuyền buôn thuyền quan qua lại tấp nập hài hòa. Tuy không tránh khỏi vài chuyện tham ô nhỏ, nhưng thuế khóa và doanh thu dâng lên triều đình mỗi năm đều không hề giảm sút. Các quan viên địa phương giờ cũng hiểu, triều đình không phải kẻ không biết điều, biết rõ họ sống bằng đồng lương ít ỏi vốn đã chật vật, nên với chuyện tham ô nhỏ, triều đình cũng nhắm một mắt mở một mắt, miễn còn trong giới hạn cho phép thì không truy cứu. Đương nhiên, những vị quan thanh liêm chính trực, triều đình cũng chẳng bạc đãi bao giờ — mỗi dịp khảo hạch cuối năm, các vị thanh quan luôn nhận được phần thưởng hậu hĩnh nhất, đường thăng tiến cũng rộng mở hơn. Vì thế, những quan viên vừa thông minh vừa có chí tiến thủ, ai nấy đều cố gắng trở thành \"thanh quan\".", "Nói tiếp chuyện hành trình.", "Sở Cửu Biện và Tần Kiêu theo kênh đào đi khắp phương nam, cảm nhận sự trù phú, nhộn nhịp của đất Giang Nam, thưởng ngoạn cảnh tiểu kiều lưu thủy nơi các cổ trấn. Rồi đến Nam Cương, nơi các cô gái mang vẻ đẹp rực rỡ khác hẳn nét dịu dàng của Giang Nam, ai nấy xiêm y sặc sỡ, lúm đồng tiền tươi như hoa nở. Suốt chặng đường ấy, hai người chưa từng làm kinh động đến ai. Đến Nam Cương cũng vậy, họ lặng lẽ ở lại một thời gian, dự một lễ hội đặc sắc của địa phương rồi mới rời đi, trở về kinh thành ăn Tết cùng Bách Lý Hồng.", "Một năm cứ thế trôi qua trong những tháng ngày an nhàn tự tại.", "Hai người ở kinh thành hơn ba tháng, qua Vạn Thọ Tiết xong lại lên đường một lần nữa. Lần này họ đi về phía tây. Dọc đường vẫn là ăn uống rong chơi, thỉnh thoảng dừng chân vài ngày ngắm phong thổ, thưởng cảnh sắc địa phương. Đến khi họ thật sự đặt chân tới Tây Vực thì vừa đúng mùa nho chín.", "Chuyện Sở Cửu Biện thích ăn nho vốn chẳng phải bí mật gì. Mấy năm qua, cứ đến mùa nho chín, Tư Đồ Chiêu Linh lại theo đoàn thương nhân đến Tây Vực, hái những chùm nho tươi nhất mang vào Thần Vực, nhờ Đại tư tế chuyển cho Sở Cửu Biện. Nếu không phải đã biết Đại tư tế chính là Sở Cửu Biện, chắc Tần Kiêu phải ghen đến phát điên mất. Nhưng dù ăn bao nhiêu chùm nho tươi, Sở Cửu Biện vẫn thấy túi nho khô mà Tần Kiêu từng mang về cho mình năm nào là ngọt thơm nhất.", "\"Chúng ta ở đây lâu một chút đi.\" Tần Kiêu nói.", "Sở Cửu Biện cũng đang nghĩ vậy, liền đáp: \"Vậy thuê một tiểu viện, tốt nhất có giàn nho, gần núi gần sông thì càng tốt.\" Lúc rảnh còn có thể ra sông câu cá, vào núi kiếm ít món hoang dã.", "Tim Tần Kiêu khẽ động.", "Năm vừa qua, bước chân hai người đã in dấu gần nửa Đại Ninh, cũng để lại không ít kỷ niệm ân ái ở nhiều nơi. Nhưng phần lớn thời gian Sở Cửu Biện vẫn khá thẹn thùng và giữ kẽ, chỉ chịu chuyện ấy trong phòng, chưa từng cùng y làm chuyện đó giữa trời đất. Tuy vậy, Tần Kiêu vẫn có thể tưởng tượng ra cảm giác ấy sẽ tuyệt vời đến mức nào — không phải tự y nghĩ ra, mà là từ một cuốn tiểu thuyết Sở Cửu Biện tải về máy tính bảng từ thời hiện đại. Không biết cuốn sách ấy \"né tránh\" thế nào mà lại lọt qua được, nhưng Tần Kiêu đã vô tình đọc được. Đọc xong, y mới nhận ra những cảnh mà trước kia mình từng xem qua chẳng có gì đáng nói. Rất nhiều tình huống và hình ảnh trong sách, y chưa từng thử, ngày nào cũng thầm nhớ nhung — mà điều y nhớ nhất, chính là làm chuyện ấy ngoài trời. Chỉ tiếc trước đây không có cơ hội, điều kiện cũng chẳng cho phép. Nhưng giờ nếu có thể ở lại đây một thời gian, thì...", "\"Ngươi đang nghĩ gì vậy?\" Sở Cửu Biện đưa tay khoát khoát trước mặt y.", "Tần Kiêu nắm lấy tay y hôn một cái, cười nói: \"Đang nghĩ chúng ta có thể tự dựng một căn nhà cho riêng mình.\"", "Sở Cửu Biện sững người: \"Thật không?\"", "\"Thật.\" Tần Kiêu kéo tay y đi về phía ngoài thành. \"Trước tiên tìm một chỗ phong thủy đẹp, rồi bắt tay vào làm.\"", "Sở Cửu Biện có không gian riêng, gỗ đá vật liệu bao nhiêu cũng có thể mang theo được. Tần Kiêu thì có thể tự tay xây dựng, như vậy sẽ chẳng ai biết nhà của họ ở đâu, cũng không lo bị quấy rầy.", "Lúc ấy đang cuối tháng năm, thời tiết dần ấm lên. Đợi nhà dựng xong, giàn nho chiết cành xong, cũng vừa vặn tới mùa thu hoạch, Sở Cửu Biện có thể ngày ngày ăn trái cây tự tay trồng. Mà khi ấy trời đang ấm, ngủ ngoài trời cũng chẳng sợ lạnh.", "Tần Kiêu càng nghĩ càng thấy tuyệt, kéo Sở Cửu Biện đi tìm khắp nơi, cuối cùng cũng chọn được một chỗ đất phong thủy đẹp. Nơi ấy tựa núi, gần sông, cách xa thôn xóm, phong cảnh hữu tình. Ngọn núi cũng không cao sâu gì, chỉ có vài con thỏ hoang, gà rừng, chẳng có mãnh thú nào khác, quả là chỗ nghỉ chân lý tưởng.", "Sở Cửu Biện rất ưng ý. Y nhìn khoảnh đất cỏ rộng cách bờ sông chừng trăm mét, nói: \"Xây nhà ở đây là vừa.\"", "\"Đúng vậy.\" Tần Kiêu nắm tay y, cười nhìn mảnh đất trống trước mặt. \"Đợi sân dựng xong, chúng ta có thể bắc giàn nho, trồng thêm ít hoa nhài.\"", "\"Ta còn muốn có một cái xích đu.\" Sở Cửu Biện nói.", "Tần Kiêu nghĩ đến chiếc xích đu, lập tức nhớ tới cảnh trong phòng ngủ ở kinh thành, công dụng của nó thật sự rất \"đa năng\".", "\"Được.\" Tần Kiêu nói. \"Còn có thể dựng thêm một cái đình hóng gió nữa.\"", "\"Đúng đó, kê một cái bàn, thêm hai cái ghế dựa.\" Sở Cửu Biện vui vẻ nói. \"Chúng ta có thể ngồi đó ăn cơm, rồi đánh cờ với nhau.\"", "Có lẽ vì tuổi tác dần lớn, trong lòng Sở Cửu Biện bỗng trỗi dậy khát khao \"lánh đời ẩn cư\" từ sâu trong xương cốt. Nhìn cảnh sắc trước mắt, y đã bắt đầu mong chờ cuộc sống bình yên sắp tới. Tần Kiêu cũng mong chờ không kém, chỉ là điều y mong chờ không tiện nói thành lời.", "\"Ta vẽ bản thiết kế trước.\" Sở Cửu Biện nói. \"Rồi vào thành mua vật liệu.\"", "\"Đúng rồi, chúng ta tự xây hay tìm thợ?\" Tần Kiêu hỏi rồi tự trả lời: \"Ta tự xây, khỏi để ai biết chỗ ở của chúng ta mà đến quấy rầy.\"", "\"Cũng phải.\" Sở Cửu Biện gật đầu.", "Y lấy từ hệ thống ra hai chiếc ghế xếp nhỏ và một chiếc bàn tròn nhỏ, ngồi cùng Tần Kiêu vẽ vẽ vạch vạch trên giấy cứng, mất mấy tiếng đồng hồ mới phác thảo xong hình dáng khu sân.", "Chỉ có điều, khi Tần Kiêu chỉ vào một phiến đá lớn cỡ chiếc giường trong bản vẽ, hỏi: \"Cái này là gì? Bệ bếp à?\" thì Sở Cửu Biện hơi ngạc nhiên.", "Sở Cửu Biện biết nấu ăn, nhưng Tần Kiêu cũng đã học được. Hai năm qua rong ruổi bên ngoài, phần lớn là Tần Kiêu nấu cho y ăn, còn y thì phụ giúp, hai người bận rộn một lúc là có bữa ăn ngon. Nhưng làm bệ bếp ngoài sân để làm gì, trong khi họ đã có bếp riêng trong nhà rồi?", "Tần Kiêu mặt không đổi sắc, đáp: \"Ngươi không phải thích ngắm sao sao? Hôm nào trời đẹp, chúng ta có thể nằm đây ngắm sao.\"", "Mắt Sở Cửu Biện sáng lên: \"Đúng vậy. Vậy làm luôn phòng kính đi.\"", "\"Phòng kính?\"", "\"Ừ.\" Sở Cửu Biện sửa lại bản vẽ, cuối cùng trong sân có thêm một gian phòng hình bán nguyệt, các bức tường và cửa đều bằng kính trong suốt. Loại kính hệ thống này trên thương thành có bán sẵn, giá cũng không đắt.", "Tần Kiêu thấy phòng kính này tuy không hoàn toàn giống ý tưởng \"màn trời chiếu đất\" trong đầu mình, nhưng cũng không tệ. Còn nếu thật sự muốn \"màn trời chiếu đất\" thì cứ bế người ra ngoài, lên xích đu, vào đình hóng gió, chỗ nào cũng được cả.", "Thế là, hai người bắt tay vào làm ngay.", "Mua vật liệu, trộn xi măng — Tần Kiêu mua cho Sở Cửu Biện một bộ đồ lao động nhẹ nhàng để y mặc vào phụ việc. Quần ống rộng màu xanh đen, ủng lao động, áo thun tay lửng màu đen — bộ đồ ấy khiến đôi chân của y trông càng thon dài, dáng người càng cao ráo thẳng tắp. Đường nét ngực bụng hiện rõ, mỗi lần dùng sức, cơ bắp cánh tay lại nổi lên, toát ra sức hút mạnh mẽ khó cưỡng. Tần Kiêu còn đưa cho y đôi găng tay lao động màu đen, khiến y trông chẳng giống người đi làm công chút nào, mà giống hệt một võ sĩ chuẩn bị thượng đài, càng đổ mồ hôi càng thêm quyến rũ khó tả.", "Sở Cửu Biện nhìn mà không kìm được liên tưởng đến cảnh cánh tay ấy từng ghì lấy chân mình, suýt thì động lòng ngay tại chỗ. Y vội quay mặt đi, không dám nhìn thêm.", "Tần Kiêu bắt đầu trộn xi măng, dựng nhà. Công việc này ít nhất phải mất nửa tháng, nhiều thì cả tháng. Hai người không định quay về trong thành ở tạm, mà dựng phòng kính trước. Việc này Sở Cửu Biện có thể tự làm — y dọn sạch cỏ dại trên nền đất, dựng phòng kính lên, rồi kê một chiếc giường vào trong. Chiếc giường ấy vốn y mua từ hồi còn ở thế giới hiện đại, không ngờ giờ lại có dịp dùng đến. Những thứ khác thì để từ từ tính sau.", "Dựng xong phòng kính, Sở Cửu Biện còn lấy từ thương thành khoảng năm mươi ngọn đèn năng lượng mặt trời cắm dưới đất, xếp thành hai vòng quanh sân cách nhau mười mét, vòng ngoài cách sân mười mét. Từ đó, dù trăng có sáng đến đâu, cả thung lũng này khi đêm xuống vẫn lấp lánh ánh đèn, mang vẻ mộng ảo lạ thường. Y còn rắc thêm quanh khu vực một loại bột chống muỗi, rắn, côn trùng lấy từ hệ thống, để những sinh vật nhỏ ấy không bén mảng tới quấy rầy giấc ngủ hai người.", "Làm xong mọi việc thì trời cũng đã ngả về chiều.", "Sở Cửu Biện mua ít đồ ăn từ thương thành bày lên chiếc bàn nhỏ tạm, ngẩng lên đã thấy Tần Kiêu đi ra bờ sông rửa tay. Cả ngày hôm ấy, Tần Kiêu không ngơi tay phút nào, chỉ mong sớm một ngày dựng xong nhà cho hai người. Chẳng biết y lấy sức lực từ đâu ra mà càng làm càng thấy hăng.", "Sở Cửu Biện chống cằm, ngắm nhìn y rửa tay rửa mặt, toàn thân còn vương hơi nước từ xa đi tới. Ánh chiều tà nhuộm hồng nửa bầu trời sau lưng y. Núi xanh nước biếc, cỏ dài chim liệng, từng bước chân của Tần Kiêu in sâu vào đáy mắt Sở Cửu Biện.", "Tần Kiêu đi thẳng đến trước mặt y rồi ngồi xuống. Nhìn ánh mắt chàng trai chỉ có mỗi mình mình trong đó, lòng y dâng lên một cảm giác mãn nguyện khôn tả. Sở Cửu Biện ngồi chờ y về ăn cơm, trông chẳng khác gì một cặp phu quân bình thường nhất, sống những ngày tháng bình dị ấm áp. Hai món ăn, một bát canh, hai chén cơm nóng hổi. Họ bàn về việc ngày mai sẽ làm gì, ăn gì, những chuyện phiền lòng hay đề tài trò chuyện cũng chỉ đơn giản như thế.", "Ăn xong, Sở Cửu Biện cầm bát đũa ra bờ sông rửa, Tần Kiêu nhất định phải đi theo. Rửa xong, hai người cất đồ vào không gian, quay lại tiếp tục xây nhà.", "Tần Kiêu không muốn để Sở Cửu Biện động tay, nhưng y cứ nhất quyết đòi giúp. \"Ta vừa ăn no cũng muốn vận động một chút.\" Sở Cửu Biện cũng biết xây nhà, thậm chí còn khéo hơn Tần Kiêu, nên dù làm chậm hơn đôi chút do bớt lực, hai người làm việc cũng chẳng phân cao thấp là bao.", "Tần Kiêu thương y, sợ y bị thương tay, liền lấy găng tay đưa cho y đeo vào. Tần Kiêu cười, dặn: \"Vậy ngươi làm chậm thôi, không vội, làm xong là được.\"", "\"Ta biết.\"", "Hai người làm thêm hơn nửa canh giờ nữa, đến khi trời tối hẳn, những ngọn đèn dưới đất ở xa xa đều đã sáng lên.", "\"Được rồi.\" Tần Kiêu vươn thẳng lưng, tháo găng tay, nắm tay kéo Sở Cửu Biện. \"Đi rửa mặt đánh răng, nghỉ sớm một chút.\"", "Sở Cửu Biện cũng thấy không cần làm thêm ban đêm nữa, liền nắm tay y cùng ra bờ sông.", "Nước sông trong veo, chỉ ngập đến bắp chân. Trong bán kính vài chục dặm quanh đây chẳng có bóng người nào khác, hai người thong thả xuống sông tắm rửa mà không phải e dè gì.", "Sở Cửu Biện vốn còn hơi ngượng ngùng, nhưng vừa quay đầu lại đã thấy Tần Kiêu cởi bỏ áo ngoài, chỉ còn mặc một chiếc quần lửng bước xuống nước. Vóc dáng y vốn đã đẹp, mặc áo trông có vẻ mảnh khảnh, cởi áo ra lại lộ rõ những đường nét săn chắc, đứng giữa dòng nước như thế càng khiến người ta không dám nhìn lâu.", "Sở Cửu Biện cũng quay lưng lại, chầm chậm cởi xiêm y. Y cảm nhận được ánh mắt của Tần Kiêu như có thực thể, đang dừng lại phía sau lưng mình, chậm rãi dịch chuyển từ đôi vai mịn màng, xuống vòng eo thon, rồi đến những đường cong phía dưới. Đôi chân thẳng dài của chàng trai dưới ánh trăng trắng đến chói mắt.", "Tần Kiêu chậm rãi bước tới gần. Dòng nước bị khuấy động, từng đợt lăn tăn vỗ vào chân Sở Cửu Biện; y càng đến gần, nước càng xao động mạnh, có lúc bắn cả lên đùi chàng trai. Đêm hè nước sông vốn mát lạnh, vậy mà Sở Cửu Biện lại cảm thấy người mình như đang bốc nóng.", "Bàn tay chai sạn của Tần Kiêu nhẹ nhàng đặt lên bờ vai mịn màng của y, vuốt ve chầm chậm. Chỉ trong một khoảnh khắc, Sở Cửu Biện đã bị hơi thở của y bao trùm lấy. Y theo bản năng đưa mắt nhìn quanh, nhận ra nơi đây quả thực không còn ai khác ngoài hai người, trong lòng bỗng dấy lên một cảm giác tê dại khó tả.", "Tần Kiêu ôm lấy y từ phía sau, hôn nhẹ lên vành tai, xuống gáy, xuống bờ vai. Sở Cửu Biện nhắm mắt lại, hơi thở dần trở nên rối loạn, đôi chân khẽ khuỵu xuống. Chỉ trong chớp mắt, Tần Kiêu đã đứng dậy, bế y gọn trong lòng, bước ra khỏi dòng sông.", "Ánh trăng đêm ấy dịu dàng như nước, gió đêm mùa hạ thoảng qua mang theo hơi ấm của hai người quấn lấy nhau. Tần Kiêu bế Sở Cửu Biện, một mạch đi thẳng về phía phòng kính, không một lần buông người xuống. Cảm giác được ôm trọn, được che chở vững chãi như thế, Sở Cửu Biện chưa từng có được trước đây. Dưới bầu trời sao đêm ấy, y cứ như vậy phó thác cả người mình cho vòng tay của Tần Kiêu.", "Đêm đó, ánh đèn nhỏ quanh sân lặng lẽ cháy sáng đến tận sáng hôm sau, còn những gì diễn ra trong gian phòng kính giữa núi rừng tĩnh mịch ấy, chỉ có ánh trăng và hai người trong cuộc mới biết.", "Sáng hôm sau, mặt trời đã lên quá nửa, Sở Cửu Biện mới chịu chui ra khỏi chăn, mặt còn đỏ ửng không dám nhìn thẳng vào Tần Kiêu. Còn Tần Kiêu thì tâm trạng cực kỳ phấn khởi, tiếp tục dựng nhà, thỉnh thoảng lại liếc mắt về phía phòng kính. Mỗi lần bốn mắt chạm nhau, Sở Cửu Biện lại vội vàng rúc sâu vào trong chăn, khiến Tần Kiêu chỉ biết bật cười.", "Mấy tháng sau đó, Sở Cửu Biện cuối cùng cũng hiểu ra vì sao Tần Kiêu lại nôn nóng muốn an cư ở nơi này đến vậy — hóa ra là để tiện cho những \"chuyện ấy\"! Nhưng người mình chọn, giờ trách ai được đây? Đương nhiên, chính y cũng dần dần đắm chìm trong những đêm như thế, chỉ là điều này y sẽ chẳng bao giờ chịu thừa nhận.", "== Hết toàn truyện ==", "————————!!————————", "Toàn bộ câu chuyện đã kết thúc rồi, cảm ơn các bảo bối đã đồng hành suốt chặng đường này! [rắc hoa][rắc hoa][rắc hoa]", "Vẫn còn phiên ngoại phúc lợi nữa nha ~ [đầu chó ngậm hoa hồng]", "Các thiên thần nhỏ nào yêu thích tiểu Cửu và Ninh Vương thì cho một đánh giá năm sao nhé [ngại ngùng] cảm ơn cực kỳ nhiều! [xin mọi người đó]", "Khu vực bình luận sẽ thả xuống hai trăm bao lì xì nha ~"], "id": 10, "wordCount": 5540}], "id": "gia-lam-than-minh"});
